fn without_first_text_code_delta_x(source: &str) -> String {
    let start = source.find("<ofd:TextCode").unwrap();
    let end = start + source[start..].find('>').unwrap();
    let start = start + source[start..end].find(" DeltaX=\"").unwrap();
    let end = start + 9 + source[start + 9..end].find('"').unwrap() + 1;
    let mut result = source.to_owned();
    result.replace_range(start..end, "");
    result
}

#[test]
fn removes_raw_package_entry_and_preserves_remaining_document() {
    let mut document = OfdDocument::new();
    document.add_text_page("remain", 40.0, 30.0).unwrap();
    document
        .set_entry("Extra/./scratch.bin", vec![0, 255])
        .unwrap();
    assert_eq!(
        document.entry("Extra/scratch.bin").unwrap(),
        Some(&[0, 255][..])
    );
    assert!(document.remove_entry("Extra/scratch.bin").unwrap());
    assert!(!document.remove_entry("Extra/scratch.bin").unwrap());
    assert!(document.remove_entry("../outside").is_err());
    assert_eq!(document.page_text(0).unwrap(), ["remain"]);
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert!(reopened.entry("Extra/scratch.bin").unwrap().is_none());
    assert_eq!(reopened.page_text(0).unwrap(), ["remain"]);
}

#[test]
fn annotation_references_use_unique_archive_case_for_reading_and_editing() {
    let mut document = OfdDocument::new();
    document.add_blank_page(30.0, 20.0).unwrap();
    let first = document
        .add_shape_annotation(0, "Square", [2.0, 3.0, 8.0, 5.0], &Default::default())
        .unwrap();
    let annotation_path = document.annotations().unwrap()[0].source_path.clone();
    let list_path = "Doc_0/Annots/Annotations.xml";
    let document_path = "Doc_0/Document.xml";
    let list = String::from_utf8(document.entry(list_path).unwrap().unwrap().to_vec()).unwrap();
    let root = String::from_utf8(document.entry(document_path).unwrap().unwrap().to_vec()).unwrap();
    assert!(list.contains("Page_0/Annotation.xml"));
    assert!(root.contains("Annots/Annotations.xml"));
    document
        .set_entry(
            document_path,
            root.replace("Annots/Annotations.xml", "annots/annotations.xml")
                .into_bytes(),
        )
        .unwrap();
    document
        .set_entry(
            list_path,
            list.replace("Page_0/Annotation.xml", "page_0/annotation.xml")
                .into_bytes(),
        )
        .unwrap();
    assert_eq!(document.annotations().unwrap()[0].id, first);
    assert!(document
        .page_svg(0)
        .unwrap()
        .contains("data-ofd-annotation"));
    assert!(document.validate_references().unwrap().is_empty());

    let second = document
        .add_shape_annotation(0, "Circle", [12.0, 3.0, 5.0, 5.0], &Default::default())
        .unwrap();
    let annotations = document.annotations().unwrap();
    assert_eq!(annotations.len(), 2);
    assert_eq!(annotations[1].id, second);
    assert_eq!(annotations[1].source_path, annotation_path);
    assert!(document.validate_references().unwrap().is_empty());

    document
        .set_entry("Doc_0/ANNOTS/ANNOTATIONS.XML", list.into_bytes())
        .unwrap();
    let ambiguous = root.replace("Annots/Annotations.xml", "ANNOTS/annotations.xml");
    document
        .set_entry(document_path, ambiguous.into_bytes())
        .unwrap();
    let before = document.to_bytes().unwrap();
    assert!(document.annotations().is_err());
    assert!(document
        .add_shape_annotation(0, "Square", [1.0, 1.0, 3.0, 3.0], &Default::default())
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    assert!(document
        .validate_references()
        .unwrap()
        .iter()
        .any(|issue| issue.code == "annotation_reference"));
}

#[test]
fn creates_editable_square_and_circle_with_atomic_validation() {
    let mut document = OfdDocument::new();
    document.add_blank_page(30.0, 20.0).unwrap();
    let square = document
        .add_shape_annotation(
            0,
            "Square",
            [2.0, 3.0, 10.0, 5.0],
            &ofdrw::ShapeAnnotationStyle {
                stroke_color: Some([0, 0, 255]),
                fill_color: Some([255, 0, 0]),
                line_width: 0.5,
                dash_sequence: Some(vec![1.0, 2.0]),
                opacity: 128,
                insets: [0.1; 4],
            },
        )
        .unwrap();
    let circle = document
        .add_shape_annotation(
            0,
            "Circle",
            [15.0, 3.0, 8.0, 8.0],
            &ofdrw::ShapeAnnotationStyle {
                stroke_color: None,
                fill_color: Some([0, 255, 0]),
                ..Default::default()
            },
        )
        .unwrap();
    let annotations = document.annotations().unwrap();
    assert_eq!(annotations[0].id, square);
    assert_eq!(annotations[0].parameters["PDFShapeDash"], "1 2");
    assert_eq!(annotations[1].id, circle);
    assert!(!annotations[1].parameters.contains_key("PDFShapeStroke"));
    assert!(document.page_svg(0).unwrap().contains("#0000ff"));
    assert!(document.validate_references().unwrap().is_empty());
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.annotations().unwrap().len(), 2);
    let from_pdf = OfdDocument::from_pdf_bytes(&reopened.to_pdf().unwrap()).unwrap();
    assert_eq!(
        from_pdf
            .annotations()
            .unwrap()
            .iter()
            .map(|a| (a.annotation_type.as_str(), a.subtype.as_deref()))
            .collect::<Vec<_>>(),
        [("Path", Some("Square")), ("Path", Some("Circle"))]
    );
    let mut legacy = reopened.clone();
    let annotation_path = &annotations[0].source_path;
    let xml = String::from_utf8(legacy.entry(annotation_path).unwrap().unwrap().to_vec()).unwrap();
    let old_xml = xml
        .replacen("Type=\"Path\"", "Type=\"Square\"", 1)
        .replacen(" Subtype=\"Square\"", "", 1);
    assert_ne!(old_xml, xml);
    assert!(!old_xml.contains("Subtype=\"Square\""));
    legacy
        .set_entry(annotation_path, old_xml.into_bytes())
        .unwrap();
    assert!(legacy.to_pdf().unwrap().starts_with(b"%PDF"));
    let before = document.to_bytes().unwrap();
    assert!(document
        .add_shape_annotation(0, "Triangle", [2.0, 3.0, 10.0, 5.0], &Default::default())
        .is_err());
    assert!(document
        .add_shape_annotation(
            0,
            "Square",
            [2.0, 3.0, 10.0, 5.0],
            &ofdrw::ShapeAnnotationStyle {
                insets: [0.6; 4],
                ..Default::default()
            }
        )
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
}

#[test]
fn creates_multi_path_annotation_and_rejects_partial_edits() {
    let mut document = OfdDocument::new();
    document.add_blank_page(40.0, 30.0).unwrap();
    let paths = [
        ofdrw::AnnotationPath {
            commands: "M 0 0 L 10 10".into(),
            boundary: [0.0, 0.0, 10.0, 10.0],
            style: PathStyle {
                stroke_color: Some([255, 0, 0]),
                ..Default::default()
            },
        },
        ofdrw::AnnotationPath {
            commands: "M 0 10 L 10 0".into(),
            boundary: [10.0, 0.0, 10.0, 10.0],
            style: PathStyle {
                stroke_color: Some([0, 0, 255]),
                dash_sequence: Some(vec![2.0, 1.0]),
                ..Default::default()
            },
        },
    ];
    let id = document
        .add_multi_path_annotation(0, [3.0, 4.0, 25.0, 15.0], &paths)
        .unwrap();
    let annotations = document.annotations().unwrap();
    assert_eq!(annotations.len(), 1);
    assert_eq!(annotations[0].id, id);
    assert_eq!(annotations[0].annotation_type, "Path");
    let xml = std::str::from_utf8(
        document
            .entry(&annotations[0].source_path)
            .unwrap()
            .unwrap(),
    )
    .unwrap();
    let tree = roxmltree::Document::parse(xml).unwrap();
    let objects = tree
        .descendants()
        .filter(|node| node.tag_name().name() == "PathObject")
        .collect::<Vec<_>>();
    assert_eq!(objects.len(), 2);
    assert_ne!(objects[0].attribute("ID"), objects[1].attribute("ID"));
    assert_eq!(objects[1].attribute("DashPattern"), Some("2 1"));
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    let svg = reopened.page_svg(0).unwrap();
    assert!(svg.contains("#ff0000") && svg.contains("#0000ff"));
    assert!(reopened.to_pdf().unwrap().starts_with(b"%PDF"));
    assert!(reopened.validate_references().unwrap().is_empty());
    let before = document.to_bytes().unwrap();
    for invalid in [
        Vec::new(),
        vec![
            paths[0].clone(),
            ofdrw::AnnotationPath {
                commands: "bad".into(),
                ..paths[1].clone()
            },
        ],
        vec![
            paths[0].clone(),
            ofdrw::AnnotationPath {
                boundary: [10.0, 0.0, 0.0, 10.0],
                ..paths[1].clone()
            },
        ],
    ] {
        assert!(document
            .add_multi_path_annotation(0, [3.0, 4.0, 25.0, 15.0], &invalid)
            .is_err());
        assert_eq!(document.to_bytes().unwrap(), before);
    }
}

#[test]
fn creates_mixed_annotation_and_rejects_invalid_resources_atomically() {
    use ofdrw::{AnnotationGraphic, AnnotationPath};

    let mut document = OfdDocument::new();
    document.add_blank_page(40.0, 30.0).unwrap();
    let png = document.page_png(0, 25.4).unwrap();
    let image_id = document
        .add_multimedia_resource(0, "Image", "PNG", &png)
        .unwrap();
    let objects = vec![
        AnnotationGraphic::Path(AnnotationPath {
            commands: "M 0 0 L 9 9".into(),
            boundary: [0.0, 0.0, 10.0, 10.0],
            style: PathStyle {
                stroke_color: Some([255, 0, 0]),
                ..Default::default()
            },
        }),
        AnnotationGraphic::Text {
            text: "Mixed {prefix} {id}".into(),
            boundary: [10.0, 0.0, 12.0, 10.0],
            size: 4.0,
            font_id: None,
            color: Some([0, 0, 255]),
            opacity: 180,
        },
        AnnotationGraphic::Image {
            resource_id: image_id,
            boundary: [22.0, 0.0, 8.0, 8.0],
            opacity: 200,
        },
    ];
    let id = document
        .add_mixed_annotation(0, [2.0, 3.0, 32.0, 12.0], &objects)
        .unwrap();
    let annotation = &document.annotations().unwrap()[0];
    assert_eq!(annotation.id, id);
    let appearance_objects = document.annotation_objects(0, &id).unwrap();
    assert_eq!(
        appearance_objects
            .iter()
            .map(|object| object.kind.as_str())
            .collect::<Vec<_>>(),
        ["PathObject", "TextObject", "ImageObject"]
    );
    assert_eq!(
        appearance_objects[0].commands.as_deref(),
        Some("M 0 0 L 9 9")
    );
    assert_eq!(appearance_objects[1].text, ["Mixed {prefix} {id}"]);
    assert_eq!(appearance_objects[1].size, Some(4.0));
    assert_eq!(
        appearance_objects[2].resource_id.as_deref(),
        Some(
            objects
                .last()
                .and_then(|object| match object {
                    AnnotationGraphic::Image { resource_id, .. } => Some(resource_id.as_str()),
                    _ => None,
                })
                .unwrap()
        )
    );
    let xml =
        std::str::from_utf8(document.entry(&annotation.source_path).unwrap().unwrap()).unwrap();
    let tree = roxmltree::Document::parse(xml).unwrap();
    let graphics = tree
        .descendants()
        .filter(|node| {
            matches!(
                node.tag_name().name(),
                "PathObject" | "TextObject" | "ImageObject"
            )
        })
        .collect::<Vec<_>>();
    assert_eq!(
        graphics
            .iter()
            .map(|node| node.tag_name().name())
            .collect::<Vec<_>>(),
        ["PathObject", "TextObject", "ImageObject"]
    );
    assert_eq!(graphics[1].attribute("Boundary"), Some("10 0 12 10"));
    assert_eq!(graphics[2].attribute("Boundary"), Some("22 0 8 8"));
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(
        reopened.annotation_objects(0, &id).unwrap(),
        appearance_objects
    );
    let svg = reopened.page_svg(0).unwrap();
    assert!(svg.contains("Mixed {prefix} {id}") && svg.contains("#ff0000"));
    assert!(!reopened.page_png(0, 50.8).unwrap().is_empty());
    assert!(reopened.to_pdf().unwrap().starts_with(b"%PDF"));
    assert!(reopened.validate_references().unwrap().is_empty());

    let before = document.to_bytes().unwrap();
    for invalid in [
        AnnotationGraphic::Image {
            resource_id: "999999".into(),
            boundary: [0.0, 0.0, 4.0, 4.0],
            opacity: 255,
        },
        AnnotationGraphic::Text {
            text: "missing font".into(),
            boundary: [0.0, 0.0, 10.0, 10.0],
            size: 4.0,
            font_id: Some("999999".into()),
            color: None,
            opacity: 255,
        },
    ] {
        let mut candidate = objects.clone();
        candidate.push(invalid);
        assert!(document
            .add_mixed_annotation(0, [2.0, 3.0, 32.0, 12.0], &candidate)
            .is_err());
        assert_eq!(document.to_bytes().unwrap(), before);
    }
    document
        .add_mixed_annotation(
            0,
            [0.0, 0.0, 12.0, 10.0],
            &[AnnotationGraphic::Text {
                text: "transparent".into(),
                boundary: [0.0, 0.0, 12.0, 10.0],
                size: 4.0,
                font_id: None,
                color: None,
                opacity: 0,
            }],
        )
        .unwrap();
    let annotation_path = &document.annotations().unwrap()[1].source_path;
    let xml = std::str::from_utf8(document.entry(annotation_path).unwrap().unwrap()).unwrap();
    assert!(xml.contains("FillColor Value=\"0 0 0\" Alpha=\"0\""));
    let stamp_id = document
        .add_mixed_stamp_annotation(0, [2.0, 15.0, 32.0, 12.0], &objects)
        .unwrap();
    let annotations = document.annotations().unwrap();
    assert_eq!(annotations[2].id, stamp_id);
    assert_eq!(annotations[2].annotation_type, "Stamp");
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.annotations().unwrap()[2].annotation_type, "Stamp");
    assert_eq!(reopened.annotation_objects(0, &stamp_id).unwrap().len(), 3);
    assert!(reopened.annotation_objects(0, "missing").is_err());
    assert!(reopened.annotation_objects(1, &stamp_id).is_err());
    assert!(reopened.to_pdf().unwrap().starts_with(b"%PDF"));
    assert!(reopened.validate_references().unwrap().is_empty());

    let red_strokes_before = document.page_svg(0).unwrap().matches("#ff0000").count();
    let path_id = appearance_objects[0].id.as_deref().unwrap();
    document
        .update_annotation_object(
            0,
            &id,
            path_id,
            &ofdrw::AnnotationObjectUpdate {
                boundary: Some([1.0, 1.0, 9.0, 9.0]),
                ctm: Some(Some([1.0, 0.0, 0.0, 1.0, 2.0, 3.0])),
                visible: Some(false),
                alpha: Some(128),
            },
        )
        .unwrap();
    let edited = document.annotation_objects(0, &id).unwrap();
    assert_eq!(edited[0].boundary, Some([1.0, 1.0, 9.0, 9.0]));
    assert_eq!(edited[0].ctm, Some([1.0, 0.0, 0.0, 1.0, 2.0, 3.0]));
    assert!(!edited[0].visible);
    assert_eq!(edited[0].alpha, 128);
    assert_eq!(edited[1..], appearance_objects[1..]);
    assert!(document.page_svg(0).unwrap().matches("#ff0000").count() < red_strokes_before);
    document
        .update_annotation_object(
            0,
            &id,
            path_id,
            &ofdrw::AnnotationObjectUpdate {
                ctm: Some(None),
                ..Default::default()
            },
        )
        .unwrap();
    assert_eq!(document.annotation_objects(0, &id).unwrap()[0].ctm, None);
    let before_edit = document.to_bytes().unwrap();
    assert!(document
        .update_annotation_object(
            0,
            &id,
            path_id,
            &ofdrw::AnnotationObjectUpdate {
                boundary: Some([0.0, 0.0, 0.0, 9.0]),
                ..Default::default()
            }
        )
        .is_err());
    assert!(document
        .update_annotation_object(
            0,
            &id,
            "missing",
            &ofdrw::AnnotationObjectUpdate {
                alpha: Some(1),
                ..Default::default()
            }
        )
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before_edit);
    let image_object_id = edited[2].id.as_deref().unwrap();
    document
        .remove_annotation_object(0, &id, image_object_id)
        .unwrap();
    assert_eq!(document.annotation_objects(0, &id).unwrap().len(), 2);
    assert_eq!(document.annotation_objects(0, &stamp_id).unwrap().len(), 3);
    let before_remove = document.to_bytes().unwrap();
    assert!(document
        .remove_annotation_object(0, &id, image_object_id)
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before_remove);
    let reopened = OfdDocument::from_bytes(&before_remove).unwrap();
    assert_eq!(reopened.annotation_objects(0, &id).unwrap().len(), 2);
    assert!(reopened.validate_references().unwrap().is_empty());
    assert!(reopened.to_pdf().unwrap().starts_with(b"%PDF"));
}

#[test]
fn appends_annotation_graphics_atomically_across_round_trip() {
    use ofdrw::{AnnotationGraphic, AnnotationPath};

    let mut document = OfdDocument::new();
    document.add_blank_page(40.0, 30.0).unwrap();
    let initial = AnnotationGraphic::Text {
        text: "first".into(),
        boundary: [0.0, 0.0, 8.0, 5.0],
        size: 3.0,
        font_id: None,
        color: None,
        opacity: 255,
    };
    let id = document
        .add_mixed_stamp_annotation(0, [1.0, 1.0, 20.0, 10.0], &[initial])
        .unwrap();
    let appended = document
        .append_annotation_objects(
            0,
            &id,
            &[
                AnnotationGraphic::Path(AnnotationPath {
                    commands: "M 0 0 L 5 5".into(),
                    boundary: [0.0, 0.0, 5.0, 5.0],
                    style: PathStyle::default(),
                }),
                AnnotationGraphic::Text {
                    text: "second".into(),
                    boundary: [5.0, 0.0, 8.0, 5.0],
                    size: 3.0,
                    font_id: None,
                    color: None,
                    opacity: 255,
                },
            ],
        )
        .unwrap();
    assert_eq!(appended.len(), 2);
    assert_eq!(document.annotations().unwrap().len(), 1);
    let bytes = document.to_bytes().unwrap();
    let reopened = OfdDocument::from_bytes(&bytes).unwrap();
    let graphics = reopened.annotation_objects(0, &id).unwrap();
    assert_eq!(graphics.len(), 3);
    assert_eq!(graphics[1].id.as_deref(), Some(appended[0].as_str()));
    assert_eq!(graphics[2].id.as_deref(), Some(appended[1].as_str()));
    assert!(reopened.page_svg(0).unwrap().contains("second"));
    assert!(reopened.validate_references().unwrap().is_empty());
    assert!(document.append_annotation_objects(0, &id, &[]).is_err());
    assert!(document
        .append_annotation_objects(
            0,
            &id,
            &[AnnotationGraphic::Image {
                resource_id: "999999".into(),
                boundary: [0.0, 0.0, 5.0, 5.0],
                opacity: 255,
            }],
        )
        .is_err());
    assert!(document
        .append_annotation_objects(
            0,
            "missing",
            &[AnnotationGraphic::Path(AnnotationPath {
                commands: "M 0 0 L 5 5".into(),
                boundary: [0.0, 0.0, 5.0, 5.0],
                style: PathStyle::default(),
            })]
        )
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), bytes);
}

#[test]
fn creates_and_appends_composite_annotation_graphics() {
    use ofdrw::{AnnotationGraphic, CompositeStyle};

    let mut document = OfdDocument::new();
    document.add_blank_page(40.0, 30.0).unwrap();
    document
        .add_composite_path_object(
            0,
            "M 0 0 L 8 0 L 8 8 C",
            [0.0, 0.0, 8.0, 8.0],
            PathStyle {
                fill: true,
                stroke: false,
                fill_color: Some([255, 0, 0]),
                ..Default::default()
            },
        )
        .unwrap();
    let resource_id = document.page_composite_objects(0).unwrap()[0]
        .resource_id
        .clone();
    let graphic = AnnotationGraphic::Composite {
        resource_id: resource_id.clone(),
        boundary: [0.0, 0.0, 8.0, 8.0],
        style: CompositeStyle {
            ctm: Some([1.0, 0.0, 0.0, 1.0, 1.0, 2.0]),
            alpha: Some(180),
            draw_param: None,
        },
    };
    let annotation_id = document
        .add_mixed_stamp_annotation(0, [2.0, 2.0, 20.0, 12.0], std::slice::from_ref(&graphic))
        .unwrap();
    let appended = document
        .append_annotation_objects(0, &annotation_id, &[graphic])
        .unwrap();
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    let objects = reopened.annotation_objects(0, &annotation_id).unwrap();
    assert_eq!(objects.len(), 2);
    assert_eq!(objects[0].kind, "CompositeObject");
    assert_eq!(
        objects[0].resource_id.as_deref(),
        Some(resource_id.as_str())
    );
    assert_eq!(objects[0].alpha, 180);
    assert_eq!(objects[1].id.as_deref(), Some(appended[0].as_str()));
    assert!(reopened.page_svg(0).unwrap().contains("#ff0000"));
    assert!(reopened.validate_references().unwrap().is_empty());
    let before = document.to_bytes().unwrap();
    assert!(document
        .append_annotation_objects(
            0,
            &annotation_id,
            &[AnnotationGraphic::Composite {
                resource_id: "999999".into(),
                boundary: [0.0, 0.0, 8.0, 8.0],
                style: CompositeStyle::default(),
            }],
        )
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
}

#[test]
fn edits_annotation_image_and_composite_resources_atomically() {
    use ofdrw::{AnnotationGraphic, AnnotationPath, CompositeStyle};

    let mut document = OfdDocument::new();
    document.add_blank_page(40.0, 30.0).unwrap();
    let png = document.page_png(0, 25.4).unwrap();
    let image_a = document
        .add_multimedia_resource(0, "Image", "PNG", &png)
        .unwrap();
    let image_b = document
        .add_multimedia_resource(0, "Image", "PNG", &png)
        .unwrap();
    let mut composite_ids = Vec::new();
    for color in [[255, 0, 0], [0, 0, 255]] {
        document
            .add_composite_path_object(
                0,
                "M 0 0 L 8 0 L 8 8 C",
                [0.0, 0.0, 8.0, 8.0],
                PathStyle {
                    fill: true,
                    stroke: false,
                    fill_color: Some(color),
                    ..Default::default()
                },
            )
            .unwrap();
        composite_ids.push(
            document
                .page_composite_objects(0)
                .unwrap()
                .last()
                .unwrap()
                .resource_id
                .clone(),
        );
    }
    let id = document
        .add_mixed_annotation(
            0,
            [2.0, 2.0, 30.0, 12.0],
            &[
                AnnotationGraphic::Image {
                    resource_id: image_a.clone(),
                    boundary: [0.0, 0.0, 8.0, 8.0],
                    opacity: 180,
                },
                AnnotationGraphic::Composite {
                    resource_id: composite_ids[0].clone(),
                    boundary: [8.0, 0.0, 8.0, 8.0],
                    style: CompositeStyle::default(),
                },
                AnnotationGraphic::Path(AnnotationPath {
                    commands: "M 0 0 L 8 8".into(),
                    boundary: [16.0, 0.0, 8.0, 8.0],
                    style: PathStyle::default(),
                }),
            ],
        )
        .unwrap();
    let original = document.annotation_objects(0, &id).unwrap();
    document
        .set_annotation_graphic_resource(0, &id, original[0].id.as_deref().unwrap(), &image_b)
        .unwrap();
    document
        .set_annotation_graphic_resource(
            0,
            &id,
            original[1].id.as_deref().unwrap(),
            &composite_ids[1],
        )
        .unwrap();
    let bytes = document.to_bytes().unwrap();
    let reopened = OfdDocument::from_bytes(&bytes).unwrap();
    let edited = reopened.annotation_objects(0, &id).unwrap();
    assert_eq!(edited[0].resource_id.as_deref(), Some(image_b.as_str()));
    assert_eq!(
        edited[1].resource_id.as_deref(),
        Some(composite_ids[1].as_str())
    );
    assert_eq!(edited[0].boundary, original[0].boundary);
    assert_eq!(edited[0].alpha, original[0].alpha);
    assert_eq!(edited[1].boundary, original[1].boundary);
    assert_eq!(edited[2], original[2]);
    assert!(reopened.page_svg(0).is_ok());
    assert!(reopened.validate_references().unwrap().is_empty());
    for (object_id, resource_id) in [
        (original[0].id.as_deref().unwrap(), "999999"),
        (
            original[0].id.as_deref().unwrap(),
            composite_ids[1].as_str(),
        ),
        (original[1].id.as_deref().unwrap(), image_b.as_str()),
        (original[2].id.as_deref().unwrap(), image_b.as_str()),
        ("missing", image_b.as_str()),
        (original[0].id.as_deref().unwrap(), " "),
    ] {
        assert!(document
            .set_annotation_graphic_resource(0, &id, object_id, resource_id)
            .is_err());
        assert_eq!(document.to_bytes().unwrap(), bytes);
    }
}

#[test]
fn edits_annotation_path_commands_atomically() {
    use ofdrw::{AnnotationGraphic, AnnotationPath};

    let mut document = OfdDocument::new();
    document.add_blank_page(40.0, 30.0).unwrap();
    let id = document
        .add_mixed_annotation(
            0,
            [2.0, 2.0, 20.0, 12.0],
            &[
                AnnotationGraphic::Path(AnnotationPath {
                    commands: "M 0 0 L 8 8".into(),
                    boundary: [0.0, 0.0, 8.0, 8.0],
                    style: PathStyle::default(),
                }),
                AnnotationGraphic::Text {
                    text: "keep".into(),
                    boundary: [8.0, 0.0, 8.0, 8.0],
                    size: 3.0,
                    font_id: None,
                    color: None,
                    opacity: 255,
                },
            ],
        )
        .unwrap();
    let objects = document.annotation_objects(0, &id).unwrap();
    let path_id = objects[0].id.as_deref().unwrap();
    let text_id = objects[1].id.as_deref().unwrap();
    document
        .set_annotation_path_data(0, &id, path_id, "M 0 8 L 8 0")
        .unwrap();
    let bytes = document.to_bytes().unwrap();
    let reopened = OfdDocument::from_bytes(&bytes).unwrap();
    let edited = reopened.annotation_objects(0, &id).unwrap();
    assert_eq!(edited[0].commands.as_deref(), Some("M 0 8 L 8 0"));
    assert_eq!(edited[0].boundary, objects[0].boundary);
    assert_eq!(edited[1], objects[1]);
    assert!(reopened.page_svg(0).is_ok());
    for (object_id, commands) in [
        (path_id, "bad"),
        (text_id, "M 0 0 L 8 8"),
        ("missing", "M 0 0 L 8 8"),
    ] {
        assert!(document
            .set_annotation_path_data(0, &id, object_id, commands)
            .is_err());
    }
    assert_eq!(document.to_bytes().unwrap(), bytes);
}

#[test]
fn edits_annotation_path_stroke_style_atomically() {
    use ofdrw::{AnnotationGraphic, AnnotationPath};

    let mut document = OfdDocument::new();
    document.add_blank_page(40.0, 30.0).unwrap();
    let id = document
        .add_mixed_annotation(
            0,
            [2.0, 2.0, 20.0, 12.0],
            &[
                AnnotationGraphic::Path(AnnotationPath {
                    commands: "M 0 0 L 8 8".into(),
                    boundary: [0.0, 0.0, 8.0, 8.0],
                    style: PathStyle::default(),
                }),
                AnnotationGraphic::Text {
                    text: "keep".into(),
                    boundary: [8.0, 0.0, 8.0, 8.0],
                    size: 3.0,
                    font_id: None,
                    color: None,
                    opacity: 255,
                },
            ],
        )
        .unwrap();
    let objects = document.annotation_objects(0, &id).unwrap();
    let path_id = objects[0].id.as_deref().unwrap();
    let text_id = objects[1].id.as_deref().unwrap();
    let style = PathStrokeStyle {
        line_width: 1.25,
        cap: Some(PathLineCap::Round),
        join: Some(PathLineJoin::Bevel),
        miter_limit: Some(4.0),
        dash_sequence: Some(vec![1.0, 2.0, 3.0]),
        dash_offset: Some(0.5),
        ..Default::default()
    };
    document
        .set_annotation_path_stroke_style(0, &id, path_id, style)
        .unwrap();
    let path = document.annotations().unwrap()[0].source_path.clone();
    let bytes = document.to_bytes().unwrap();
    let reopened = OfdDocument::from_bytes(&bytes).unwrap();
    let xml = std::str::from_utf8(reopened.entry(&path).unwrap().unwrap()).unwrap();
    let parsed = roxmltree::Document::parse(xml).unwrap();
    let node = parsed
        .descendants()
        .find(|node| {
            node.tag_name().name() == "PathObject" && node.attribute("ID") == Some(path_id)
        })
        .unwrap();
    assert_eq!(node.attribute("LineWidth"), Some("1.25"));
    assert_eq!(node.attribute("Cap"), Some("Round"));
    assert_eq!(node.attribute("Join"), Some("Bevel"));
    assert_eq!(node.attribute("MiterLimit"), Some("4"));
    assert_eq!(node.attribute("DashPattern"), Some("1 2 3"));
    assert_eq!(node.attribute("DashOffset"), Some("0.5"));
    assert_eq!(reopened.annotation_objects(0, &id).unwrap(), objects);
    assert!(reopened.page_svg(0).is_ok());
    assert!(reopened.validate_references().unwrap().is_empty());
    for (object_id, style) in [
        (
            path_id,
            PathStrokeStyle {
                line_width: -1.0,
                ..Default::default()
            },
        ),
        (
            path_id,
            PathStrokeStyle {
                line_width: 1.0,
                dash_sequence: Some(vec![0.0]),
                ..Default::default()
            },
        ),
        (text_id, PathStrokeStyle::default()),
        ("missing", PathStrokeStyle::default()),
    ] {
        assert!(document
            .set_annotation_path_stroke_style(0, &id, object_id, style)
            .is_err());
        assert_eq!(document.to_bytes().unwrap(), bytes);
    }
    document
        .set_annotation_path_stroke_style(0, &id, path_id, PathStrokeStyle::default())
        .unwrap();
    let cleared = document.entry(&path).unwrap().unwrap();
    let cleared = roxmltree::Document::parse(std::str::from_utf8(cleared).unwrap()).unwrap();
    let node = cleared
        .descendants()
        .find(|node| {
            node.tag_name().name() == "PathObject" && node.attribute("ID") == Some(path_id)
        })
        .unwrap();
    assert_eq!(node.attribute("LineWidth"), Some("0.4"));
    for attribute in ["Cap", "Join", "MiterLimit", "DashPattern", "DashOffset"] {
        assert!(node.attribute(attribute).is_none());
    }
}

#[test]
fn edits_annotation_text_runs_and_remeasures_advances() {
    use ofdrw::{AnnotationGraphic, AnnotationPath};

    let mut document = OfdDocument::new();
    document.add_blank_page(40.0, 30.0).unwrap();
    let id = document
        .add_mixed_annotation(
            0,
            [2.0, 2.0, 25.0, 12.0],
            &[
                AnnotationGraphic::Text {
                    text: "AB".into(),
                    boundary: [0.0, 0.0, 15.0, 8.0],
                    size: 3.0,
                    font_id: None,
                    color: None,
                    opacity: 255,
                },
                AnnotationGraphic::Path(AnnotationPath {
                    commands: "M 0 0 L 8 8".into(),
                    boundary: [15.0, 0.0, 8.0, 8.0],
                    style: PathStyle::default(),
                }),
            ],
        )
        .unwrap();
    let objects = document.annotation_objects(0, &id).unwrap();
    let text_id = objects[0].id.as_deref().unwrap();
    let path_id = objects[1].id.as_deref().unwrap();
    let annotation_path = document.annotations().unwrap()[0].source_path.clone();
    let original_xml =
        std::str::from_utf8(document.entry(&annotation_path).unwrap().unwrap()).unwrap();
    let original_tree = roxmltree::Document::parse(original_xml).unwrap();
    let original_delta = original_tree
        .descendants()
        .find(|node| node.tag_name().name() == "TextCode")
        .unwrap()
        .attribute("DeltaX")
        .unwrap()
        .to_owned();
    document
        .set_annotation_text_code(0, &id, text_id, 0, "A & <B>")
        .unwrap();
    let bytes = document.to_bytes().unwrap();
    let reopened = OfdDocument::from_bytes(&bytes).unwrap();
    let edited = reopened.annotation_objects(0, &id).unwrap();
    assert_eq!(edited[0].text, ["A & <B>"]);
    assert_eq!(edited[1], objects[1]);
    let xml = std::str::from_utf8(reopened.entry(&annotation_path).unwrap().unwrap()).unwrap();
    let tree = roxmltree::Document::parse(xml).unwrap();
    let code = tree
        .descendants()
        .find(|node| node.tag_name().name() == "TextCode")
        .unwrap();
    assert_eq!(code.text(), Some("A & <B>"));
    let updated_delta = code.attribute("DeltaX").unwrap();
    assert_ne!(updated_delta, original_delta);
    assert_eq!(
        updated_delta.split_whitespace().count(),
        "A & <B>".chars().count() - 1
    );
    assert!(reopened.page_svg(0).unwrap().contains("A &amp; &lt;B&gt;"));
    for (object_id, index) in [(text_id, 1), (path_id, 0), ("missing", 0)] {
        assert!(document
            .set_annotation_text_code(0, &id, object_id, index, "bad")
            .is_err());
    }
    assert_eq!(document.to_bytes().unwrap(), bytes);
    for (name, modified) in [
        (
            "shaped",
            xml.replacen("<ofd:TextCode", "<ofd:CGTransform/><ofd:TextCode", 1),
        ),
        (
            "vertical",
            xml.replacen("DeltaX=", "DeltaY=\"0 0 0 0 0 0\" DeltaX=", 1),
        ),
    ] {
        let mut candidate = reopened.clone();
        candidate
            .set_entry(&annotation_path, modified.into_bytes())
            .unwrap();
        let before = candidate.to_bytes().unwrap();
        assert!(
            candidate
                .set_annotation_text_code(0, &id, text_id, 0, "short")
                .is_err(),
            "{name}"
        );
        assert_eq!(candidate.to_bytes().unwrap(), before, "{name}");
    }
}

#[test]
fn edits_annotation_text_font_and_rejects_invalid_resources() {
    use ofdrw::AnnotationGraphic;

    let font = std::fs::read(
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/dejavu-serif.ttf"),
    )
    .unwrap();
    let mut document = OfdDocument::new();
    document.add_blank_page(40.0, 30.0).unwrap();
    let first_font = document
        .add_embedded_font("DejaVu Serif", &font)
        .unwrap()
        .to_string();
    let second_font = document
        .add_embedded_font("DejaVu Serif copy", &font)
        .unwrap()
        .to_string();
    let annotation_id = document
        .add_mixed_annotation(
            0,
            [2.0, 2.0, 20.0, 10.0],
            &[AnnotationGraphic::Text {
                text: "AB".into(),
                boundary: [0.0, 0.0, 15.0, 8.0],
                size: 3.0,
                font_id: Some(first_font.clone()),
                color: None,
                opacity: 255,
            }],
        )
        .unwrap();
    let object_id = document.annotation_objects(0, &annotation_id).unwrap()[0]
        .id
        .clone()
        .unwrap();
    document
        .set_annotation_text_font(0, &annotation_id, &object_id, &second_font)
        .unwrap();
    let before = document.to_bytes().unwrap();
    assert_eq!(
        document.annotation_objects(0, &annotation_id).unwrap()[0]
            .font_id
            .as_deref(),
        Some(second_font.as_str())
    );
    assert!(document
        .set_annotation_text_font(0, &annotation_id, &object_id, "999999")
        .is_err());
    assert!(document
        .set_annotation_text_font(0, &annotation_id, "missing", &first_font)
        .is_err());
    assert!(document
        .set_annotation_text_font(0, &annotation_id, &object_id, "")
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    let reopened = OfdDocument::from_bytes(&before).unwrap();
    assert_eq!(
        reopened.annotation_objects(0, &annotation_id).unwrap()[0]
            .font_id
            .as_deref(),
        Some(second_font.as_str())
    );
}

#[test]
fn removes_annotation_text_codes_without_moving_following_runs() {
    use ofdrw::AnnotationGraphic;

    let mut document = OfdDocument::new();
    document.add_blank_page(40.0, 30.0).unwrap();
    let annotation_id = document
        .add_mixed_annotation(
            0,
            [2.0, 2.0, 20.0, 10.0],
            &[AnnotationGraphic::Text {
                text: "AB".into(),
                boundary: [0.0, 0.0, 15.0, 8.0],
                size: 3.0,
                font_id: None,
                color: None,
                opacity: 255,
            }],
        )
        .unwrap();
    let object_id = document.annotation_objects(0, &annotation_id).unwrap()[0]
        .id
        .clone()
        .unwrap();
    let path = document.annotations().unwrap()[0].source_path.clone();
    let source = std::str::from_utf8(document.entry(&path).unwrap().unwrap()).unwrap();
    let modified = source.replacen(
        "</ofd:TextObject>",
        "<ofd:TextCode>CD</ofd:TextCode><ofd:TextCode X=\"12\">EF</ofd:TextCode></ofd:TextObject>",
        1,
    );
    assert_ne!(modified, source);
    let mut shaped = document.clone();
    let shaped_xml = modified.replacen("<ofd:TextCode", "<ofd:CGTransform/><ofd:TextCode", 1);
    shaped.set_entry(&path, shaped_xml.into_bytes()).unwrap();
    let shaped_before = shaped.to_bytes().unwrap();
    assert!(shaped
        .remove_annotation_text_code(0, &annotation_id, &object_id, 0)
        .is_err());
    assert_eq!(shaped.to_bytes().unwrap(), shaped_before);
    document.set_entry(&path, modified.into_bytes()).unwrap();
    let original = document.annotation_objects(0, &annotation_id).unwrap();
    assert_eq!(original[0].text, ["AB", "CD", "EF"]);
    document
        .remove_annotation_text_code(0, &annotation_id, &object_id, 0)
        .unwrap();
    let xml = std::str::from_utf8(document.entry(&path).unwrap().unwrap()).unwrap();
    let tree = roxmltree::Document::parse(xml).unwrap();
    let codes: Vec<_> = tree
        .descendants()
        .filter(|node| node.tag_name().name() == "TextCode")
        .collect();
    assert_eq!(codes.len(), 2);
    assert_eq!(codes[0].text(), Some("CD"));
    assert_eq!(codes[0].attribute("X"), Some("0"));
    assert_eq!(codes[0].attribute("Y"), Some("3"));
    assert_eq!(codes[1].attribute("X"), Some("12"));
    document
        .remove_annotation_text_code(0, &annotation_id, &object_id, 1)
        .unwrap();
    let before = document.to_bytes().unwrap();
    assert!(document
        .remove_annotation_text_code(0, &annotation_id, &object_id, 0)
        .is_err());
    assert!(document
        .remove_annotation_text_code(0, &annotation_id, &object_id, 1)
        .is_err());
    assert!(document
        .remove_annotation_text_code(0, &annotation_id, "missing", 0)
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    let reopened = OfdDocument::from_bytes(&before).unwrap();
    assert_eq!(
        reopened.annotation_objects(0, &annotation_id).unwrap()[0].text,
        ["CD"]
    );
}

#[test]
fn appends_annotation_text_codes_with_layout_and_atomic_validation() {
    use ofdrw::{AnnotationGraphic, AnnotationPath};

    let mut document = OfdDocument::new();
    document.add_blank_page(40.0, 30.0).unwrap();
    let annotation_id = document
        .add_mixed_annotation(
            0,
            [2.0, 2.0, 25.0, 12.0],
            &[
                AnnotationGraphic::Text {
                    text: "AB".into(),
                    boundary: [0.0, 0.0, 15.0, 8.0],
                    size: 3.0,
                    font_id: None,
                    color: None,
                    opacity: 255,
                },
                AnnotationGraphic::Path(AnnotationPath {
                    commands: "M 0 0 L 8 8".into(),
                    boundary: [15.0, 0.0, 8.0, 8.0],
                    style: PathStyle::default(),
                }),
            ],
        )
        .unwrap();
    let objects = document.annotation_objects(0, &annotation_id).unwrap();
    let text_id = objects[0].id.as_deref().unwrap();
    let path_id = objects[1].id.as_deref().unwrap();
    document
        .append_annotation_text_code(
            0,
            &annotation_id,
            text_id,
            "C&D",
            &TextCodeLayout {
                delta_x: Some(vec![2.0, 2.5]),
                ..TextCodeLayout::default()
            },
        )
        .unwrap();
    document
        .append_annotation_text_code(
            0,
            &annotation_id,
            text_id,
            "EF",
            &TextCodeLayout {
                x: Some(12.0),
                y: Some(6.0),
                delta_x: Some(vec![3.0]),
                ..TextCodeLayout::default()
            },
        )
        .unwrap();
    let path = document.annotations().unwrap()[0].source_path.clone();
    let xml = std::str::from_utf8(document.entry(&path).unwrap().unwrap()).unwrap();
    let tree = roxmltree::Document::parse(xml).unwrap();
    let codes: Vec<_> = tree
        .descendants()
        .filter(|node| node.tag_name().name() == "TextCode")
        .collect();
    assert_eq!(codes.len(), 3);
    assert_eq!(codes[1].text(), Some("C&D"));
    assert_eq!(codes[1].attribute("DeltaX"), Some("2 2.5"));
    assert!(codes[1].attribute("X").is_none());
    assert_eq!(codes[2].attribute("X"), Some("12"));
    assert_eq!(codes[2].attribute("Y"), Some("6"));
    let mut shaped = document.clone();
    let shaped_xml = xml.replacen("<ofd:TextCode", "<ofd:CGTransform/><ofd:TextCode", 1);
    shaped.set_entry(&path, shaped_xml.into_bytes()).unwrap();
    let shaped_before = shaped.to_bytes().unwrap();
    assert!(shaped
        .append_annotation_text_code(0, &annotation_id, text_id, "X", &TextCodeLayout::default())
        .is_err());
    assert_eq!(shaped.to_bytes().unwrap(), shaped_before);
    let before = document.to_bytes().unwrap();
    for (object_id, layout) in [
        (
            text_id,
            TextCodeLayout {
                delta_x: Some(vec![1.0, 2.0]),
                ..TextCodeLayout::default()
            },
        ),
        (
            text_id,
            TextCodeLayout {
                x: Some(f64::NAN),
                ..TextCodeLayout::default()
            },
        ),
        (path_id, TextCodeLayout::default()),
    ] {
        assert!(document
            .append_annotation_text_code(0, &annotation_id, object_id, "XY", &layout)
            .is_err());
    }
    assert_eq!(document.to_bytes().unwrap(), before);
    let reopened = OfdDocument::from_bytes(&before).unwrap();
    assert_eq!(
        reopened.annotation_objects(0, &annotation_id).unwrap()[0].text,
        ["AB", "C&D", "EF"]
    );
}

#[test]
fn annotation_text_readers_decode_ofd_unicode_escapes() {
    use ofdrw::AnnotationGraphic;

    let mut document = OfdDocument::new();
    document.add_blank_page(40.0, 30.0).unwrap();
    let annotation_id = document
        .add_mixed_annotation(
            0,
            [2.0, 2.0, 20.0, 10.0],
            &[AnnotationGraphic::Text {
                text: "AB".into(),
                boundary: [0.0, 0.0, 15.0, 8.0],
                size: 3.0,
                font_id: None,
                color: None,
                opacity: 255,
            }],
        )
        .unwrap();
    let object_id = document.annotation_objects(0, &annotation_id).unwrap()[0]
        .id
        .clone()
        .unwrap();
    document
        .set_annotation_text_code(0, &annotation_id, &object_id, 0, "A\0B")
        .unwrap();
    document
        .append_annotation_text_code(
            0,
            &annotation_id,
            &object_id,
            "C\0D",
            &TextCodeLayout::default(),
        )
        .unwrap();
    assert_eq!(document.annotations().unwrap()[0].text, ["A\0B", "C\0D"]);
    assert_eq!(
        document.annotation_objects(0, &annotation_id).unwrap()[0].text,
        ["A\0B", "C\0D"]
    );
    let path = document.annotations().unwrap()[0].source_path.clone();
    let xml = std::str::from_utf8(document.entry(&path).unwrap().unwrap()).unwrap();
    assert!(xml.contains(r"A\0000B"));
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(
        reopened.annotation_objects(0, &annotation_id).unwrap()[0].text,
        ["A\0B", "C\0D"]
    );
}

