#[test]
fn document_resources_use_unique_archive_case_for_reading_and_editing() {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../../ofdrw-converter/src/test/resources/containsJPEG.ofd");
    let mut document = OfdDocument::open(path).unwrap();
    let root = "Doc_0/Document.xml";
    let original = std::str::from_utf8(document.entry(root).unwrap().unwrap())
        .unwrap()
        .to_owned();
    let changed = original
        .replace(">DocumentRes.xml<", ">DOCUMENTRES.XML<")
        .replace(">PublicRes.xml<", ">PUBLICRES.XML<");
    assert_ne!(changed, original);
    document.set_entry(root, changed.into_bytes()).unwrap();

    assert!(document
        .page_image_data(0, 0)
        .unwrap()
        .starts_with(b"\xff\xd8"));
    assert!(document.validate_references().unwrap().is_empty());
    let before = document
        .entry("Doc_0/PublicRes.xml")
        .unwrap()
        .unwrap()
        .to_vec();
    document
        .add_document_draw_param(0, &DrawParamStyle::default())
        .unwrap();
    assert_ne!(
        document.entry("Doc_0/PublicRes.xml").unwrap().unwrap(),
        before
    );
    assert!(document.entry("Doc_0/PUBLICRES.XML").unwrap().is_none());
    assert!(document.validate_references().unwrap().is_empty());

    let mut ambiguous_public = document.clone();
    ambiguous_public
        .set_entry("Doc_0/publicres.xml", before)
        .unwrap();
    assert!(matches!(
        ambiguous_public.fonts(),
        Err(OfdError::Invalid(message)) if message.contains("ambiguous entry reference")
    ));

    let document_resource = document
        .entry("Doc_0/DocumentRes.xml")
        .unwrap()
        .unwrap()
        .to_vec();
    document
        .set_entry("Doc_0/documentres.xml", document_resource)
        .unwrap();
    assert!(matches!(
        document.page_image_data(0, 0),
        Err(OfdError::Invalid(message)) if message.contains("ambiguous entry reference")
    ));
}

#[test]
fn decrypts_java_certificate_encrypted_document() {
    let encrypted =
        OfdDocument::from_bytes(include_bytes!("fixtures/java-cert-encrypted.ofd")).unwrap();
    assert!(encrypted.is_encrypted());
    assert_eq!(encrypted.encryption_info().unwrap()[0].usernames, ["777"]);
    let key = include_bytes!("fixtures/java-sm2-private-key.bin");
    assert!(encrypted
        .decrypt_with_sm2_private_key(&[0_u8; 32], Some("777"))
        .is_err());
    assert!(encrypted
        .decrypt_with_sm2_private_key(key, Some("other"))
        .is_err());
    let restored = encrypted
        .decrypt_with_sm2_private_key(key, Some("777"))
        .unwrap();
    let original = OfdDocument::from_bytes(include_bytes!(
        "../../../../ofdrw-crypto/src/test/resources/hello.ofd"
    ))
    .unwrap();
    for path in original.entry_names() {
        assert_eq!(
            restored.entry(path).unwrap(),
            original.entry(path).unwrap(),
            "{path}"
        );
    }
    assert_eq!(
        restored.entry_names().count(),
        original.entry_names().count()
    );
}

#[test]
fn certificate_encryption_round_trip_and_rejects_invalid_inputs() {
    let original = OfdDocument::new();
    let recipient = CertificateRecipient {
        username: "alice".into(),
        certificate_der: include_bytes!("fixtures/user-cert.der").to_vec(),
        user_type: Some("Owner".into()),
    };
    let key = include_bytes!("fixtures/user-private-key.bin");
    let encrypted = original
        .encrypt_with_certificates(std::slice::from_ref(&recipient))
        .unwrap();
    assert_eq!(
        encrypted.encryption_info().unwrap()[0]
            .protection_case_id
            .as_deref(),
        Some("1.1.2")
    );
    assert!(encrypted.decrypt_with_password("secret", None).is_err());
    let reopened = OfdDocument::from_bytes(&encrypted.to_bytes().unwrap()).unwrap();
    let restored = reopened.decrypt_with_sm2_private_key(key, None).unwrap();
    for path in original.entry_names() {
        assert_eq!(
            restored.entry(path).unwrap(),
            original.entry(path).unwrap(),
            "{path}"
        );
    }
    assert!(original.encrypt_with_certificates(&[]).is_err());
    assert!(original
        .encrypt_with_certificates(&[recipient.clone(), recipient.clone()])
        .is_err());
    let mut bad = recipient.clone();
    bad.certificate_der = vec![1, 2, 3];
    assert!(original.encrypt_with_certificates(&[bad]).is_err());
    let mut bad = recipient;
    bad.user_type = Some("Admin".into());
    assert!(original.encrypt_with_certificates(&[bad]).is_err());
    assert!(encrypted.encrypt_with_certificates(&[]).is_err());
    assert!(encrypted
        .decrypt_with_sm2_private_key(&[0_u8; 31], None)
        .is_err());
}

#[test]
fn mixed_password_and_certificate_recipients_restore_the_same_document() {
    let original = OfdDocument::from_bytes(include_bytes!(
        "../../../../ofdrw-crypto/src/test/resources/hello.ofd"
    ))
    .unwrap();
    let recipients = [
        EncryptionRecipient::Certificate(CertificateRecipient {
            username: "certificate-user".into(),
            certificate_der: include_bytes!("fixtures/java-sm2-cert.der").to_vec(),
            user_type: Some("Owner".into()),
        }),
        EncryptionRecipient::Password(PasswordRecipient {
            username: "password-user".into(),
            password: "mixed-secret".into(),
            user_type: None,
        }),
    ];
    let encrypted = original.encrypt_with_recipients(&recipients).unwrap();
    assert_eq!(
        encrypted.encryption_info().unwrap()[0].protection_case_id,
        None
    );
    assert_eq!(
        encrypted.encryption_info().unwrap()[0].usernames,
        ["certificate-user", "password-user"]
    );
    let reopened = OfdDocument::from_bytes(&encrypted.to_bytes().unwrap()).unwrap();
    let key = include_bytes!("fixtures/java-sm2-private-key.bin");
    let by_password = reopened
        .decrypt_with_password("mixed-secret", Some("password-user"))
        .unwrap();
    let by_certificate = reopened
        .decrypt_with_sm2_private_key(key, Some("certificate-user"))
        .unwrap();
    assert!(reopened.decrypt_with_password("mixed-secret", None).is_ok());
    assert!(reopened.decrypt_with_sm2_private_key(key, None).is_ok());
    for path in original.entry_names() {
        assert_eq!(
            by_password.entry(path).unwrap(),
            original.entry(path).unwrap(),
            "{path}"
        );
        assert_eq!(
            by_certificate.entry(path).unwrap(),
            original.entry(path).unwrap(),
            "{path}"
        );
    }
    assert!(reopened
        .decrypt_with_password("mixed-secret", Some("certificate-user"))
        .is_err());
    assert!(reopened
        .decrypt_with_sm2_private_key(key, Some("password-user"))
        .is_err());
    assert!(original.encrypt_with_recipients(&[]).is_err());
    assert!(original
        .encrypt_with_recipients(&[recipients[0].clone(), recipients[0].clone()])
        .is_err());
}

