#[test]
fn resource_readers_ignore_extension_font_and_palette_lookalikes() {
    let mut document = OfdDocument::new();
    document.add_text_page("font", 20.0, 20.0).unwrap();
    let font = document.fonts().unwrap().remove(0);
    let spec = ColorSpaceSpec {
        color_type: "RGB".into(),
        bits_per_component: 8,
        profile: None,
        palette: vec![vec![255, 0, 0], vec![0, 0, 255]],
    };
    let color_id = document.add_document_color_space(0, &spec).unwrap();
    let path = document.document_color_spaces(0).unwrap()[0]
        .resource_path
        .clone();
    let original = std::str::from_utf8(document.entry(&path).unwrap().unwrap()).unwrap();
    let font_start = format!("<ofd:Font ID=\"{}\"", font.id);
    let mut decorated = original
        .replacen(
            "xmlns:ofd=",
            "xmlns:ext=\"urn:example:extension\" xmlns:ofd=",
            1,
        )
        .replacen(
            &font_start,
            &format!(
                "<ext:Font ID=\"{}\" FontName=\"fake\"/>{font_start}",
                font.id
            ),
            1,
        )
        .replacen(
            "<ofd:ColorSpaces>",
            &format!(
                "<ext:ColorSpaces><ext:ColorSpace ID=\"{color_id}\" Type=\"GRAY\"/></ext:ColorSpaces>\
                 <ColorSpaces><ColorSpace ID=\"{color_id}\" Type=\"GRAY\"/></ColorSpaces>\
                 <ofd:ColorSpaces><ext:ColorSpace ID=\"{color_id}\" Type=\"GRAY\"/>"
            ),
            1,
        )
        .replacen(
            "<ofd:Palette>",
            "<ext:Palette><ext:CV>0</ext:CV></ext:Palette>\
             <ofd:Palette><ext:CV>0 255 0</ext:CV><CV>0 255 0</CV>",
            1,
        );
    let font_start_at = decorated.find(&font_start).unwrap();
    let font_end_at = font_start_at + decorated[font_start_at..].find("/>").unwrap();
    decorated.replace_range(
        font_end_at..font_end_at + 2,
        "><ext:FontFile>missing.ttf</ext:FontFile></ofd:Font>",
    );
    assert_ne!(decorated, original);
    document.set_entry(&path, decorated.into_bytes()).unwrap();

    let spaces = document.document_color_spaces(0).unwrap();
    assert_eq!(spaces.len(), 1);
    assert_eq!(spaces[0].id, color_id);
    assert_eq!(spaces[0].palette, spec.palette);
    assert_eq!(document.fonts().unwrap(), [font]);
    assert!(document.validate_references().unwrap().is_empty());
    document
        .add_text_page("still uses the real font", 20.0, 20.0)
        .unwrap();
    assert_eq!(document.page_text(1).unwrap(), ["still uses the real font"]);
}

#[test]
fn creates_color_space_without_existing_public_resources_and_validates_icc() {
    let mut document = OfdDocument::new();
    let spec = ColorSpaceSpec {
        color_type: "RGB".into(),
        bits_per_component: 8,
        profile: None,
        palette: vec![],
    };
    let id = document.add_document_color_space(0, &spec).unwrap();
    assert_eq!(document.document_color_spaces(0).unwrap()[0].id, id);
    let reopened = OfdDocument::from_reader(Cursor::new(document.to_bytes().unwrap())).unwrap();
    assert_eq!(reopened.document_color_spaces(0).unwrap()[0].id, id);
    document
        .set_entry("Doc_0/Res/bad.icc", b"invalid profile".to_vec())
        .unwrap();
    let bad = ColorSpaceSpec {
        profile: Some("bad.icc".into()),
        ..spec
    };
    assert!(document.add_document_color_space(0, &bad).is_err());
    assert_eq!(document.document_color_spaces(0).unwrap().len(), 1);
    let profile = include_bytes!("fixtures/swapped-rg.icc");
    document
        .set_entry("Doc_0/Res/good.icc", profile.to_vec())
        .unwrap();
    let matching = ColorSpaceSpec {
        color_type: "RGB".into(),
        bits_per_component: 8,
        profile: Some("GOOD.ICC".into()),
        palette: vec![],
    };
    let second = document.add_document_color_space(0, &matching).unwrap();
    assert_eq!(document.document_color_spaces(0).unwrap()[1].id, second);
    let mismatch = ColorSpaceSpec {
        color_type: "GRAY".into(),
        ..matching
    };
    assert!(document.add_document_color_space(0, &mismatch).is_err());
    assert_eq!(document.document_color_spaces(0).unwrap().len(), 2);
}

#[test]
fn page_color_space_and_default_cs_round_trip() {
    let mut document = OfdDocument::new();
    for _ in 0..2 {
        document
            .add_path_page(
                "M 0 0 L 20 0 L 20 20 L 0 20 C",
                [0.0, 0.0, 20.0, 20.0],
                20.0,
                20.0,
                true,
                false,
            )
            .unwrap();
    }
    let gray = ColorSpaceSpec {
        color_type: "GRAY".into(),
        bits_per_component: 4,
        profile: None,
        palette: vec![],
    };
    let doc_id = document.add_document_color_space(0, &gray).unwrap();
    assert_eq!(document.document_default_color_space(0).unwrap(), None);
    assert!(document
        .set_document_default_color_space(0, Some("999999"))
        .is_err());
    document
        .set_document_default_color_space(0, Some(&doc_id))
        .unwrap();
    for page in document.pages().unwrap() {
        let source = std::str::from_utf8(document.entry(&page.path).unwrap().unwrap()).unwrap();
        document
            .set_entry(
                &page.path,
                source
                    .replace(
                        "</ofd:PathObject>",
                        "<ofd:FillColor Value=\"8\"/></ofd:PathObject>",
                    )
                    .into_bytes(),
            )
            .unwrap();
        assert!(document
            .page_svg(page.index)
            .unwrap()
            .contains("fill=\"#888888\""));
    }
    let rgb = ColorSpaceSpec {
        color_type: "RGB".into(),
        bits_per_component: 8,
        profile: None,
        palette: vec![vec![0, 0, 255]],
    };
    let page_id = document.add_page_color_space(0, &rgb).unwrap();
    assert_eq!(document.document_color_spaces(0).unwrap().len(), 1);
    let first = document.page_color_spaces(0).unwrap();
    assert_eq!(first.len(), 2);
    assert_eq!(first[0].id, page_id);
    assert_eq!(first[1].id, doc_id);
    assert_eq!(document.page_color_spaces(1).unwrap().len(), 1);
    let path = document.pages().unwrap()[0].path.clone();
    let source = std::str::from_utf8(document.entry(&path).unwrap().unwrap()).unwrap();
    document
        .set_entry(
            &path,
            source
                .replace(
                    "<ofd:FillColor Value=\"8\"/>",
                    &format!("<ofd:FillColor ColorSpace=\"{page_id}\" Index=\"0\"/>"),
                )
                .into_bytes(),
        )
        .unwrap();
    assert!(document.page_svg(0).unwrap().contains("fill=\"#0000ff\""));
    assert!(document.page_svg(1).unwrap().contains("fill=\"#888888\""));
    let reopened = OfdDocument::from_reader(Cursor::new(document.to_bytes().unwrap())).unwrap();
    assert_eq!(
        reopened.document_default_color_space(0).unwrap(),
        Some(doc_id)
    );
    assert_eq!(reopened.page_color_spaces(0).unwrap(), first);
    assert!(reopened.validate_references().unwrap().is_empty());
    document.set_document_default_color_space(0, None).unwrap();
    assert_eq!(document.document_default_color_space(0).unwrap(), None);
    assert!(document.add_page_color_space(2, &rgb).is_err());
    let bad = ColorSpaceSpec {
        bits_per_component: 3,
        ..rgb
    };
    assert!(document.add_page_color_space(0, &bad).is_err());
    assert_eq!(document.page_color_spaces(0).unwrap(), first);
}

#[test]
fn replaces_document_and_page_color_spaces_atomically() {
    let mut document = OfdDocument::new();
    document.add_blank_page(20.0, 20.0).unwrap();
    document.append_blank_page(0, 20.0, 20.0).unwrap();
    let gray = ColorSpaceSpec {
        color_type: "GRAY".into(),
        bits_per_component: 4,
        profile: None,
        palette: vec![],
    };
    let public = document.add_document_color_space(0, &gray).unwrap();
    document
        .set_document_default_color_space(0, Some(&public))
        .unwrap();
    let rgb = ColorSpaceSpec {
        color_type: "RGB".into(),
        bits_per_component: 8,
        profile: None,
        palette: vec![vec![255, 0, 0]],
    };
    let local = document.add_page_color_space(0, &rgb).unwrap();
    document
        .set_document_color_space(
            0,
            &public,
            &ColorSpaceSpec {
                palette: vec![vec![0], vec![15]],
                ..gray.clone()
            },
        )
        .unwrap();
    document
        .set_page_color_space(
            0,
            &local,
            &ColorSpaceSpec {
                palette: vec![vec![0, 0, 255]],
                ..rgb.clone()
            },
        )
        .unwrap();
    assert_eq!(
        document.document_default_color_space(0).unwrap(),
        Some(public.clone())
    );
    assert_eq!(
        document.document_color_spaces(0).unwrap()[0].palette,
        vec![vec![0], vec![15]]
    );
    assert_eq!(
        document.page_color_spaces(0).unwrap()[0].palette,
        vec![vec![0, 0, 255]]
    );
    assert_eq!(document.page_color_spaces(1).unwrap().len(), 1);
    assert!(document.validate_references().unwrap().is_empty());
    let before = document.to_bytes().unwrap();
    assert!(document.set_page_color_space(1, &local, &rgb).is_err());
    assert!(document.set_page_color_space(0, &public, &gray).is_err());
    assert!(document.set_document_color_space(0, &local, &rgb).is_err());
    assert!(document
        .set_document_color_space(
            0,
            &public,
            &ColorSpaceSpec {
                palette: vec![vec![16]],
                ..gray
            }
        )
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    let reopened = OfdDocument::from_bytes(&before).unwrap();
    assert_eq!(
        reopened.page_color_spaces(0).unwrap()[0].palette,
        vec![vec![0, 0, 255]]
    );
}

#[test]
fn removes_only_unreferenced_color_spaces_in_the_requested_scope() {
    let mut document = OfdDocument::new();
    document
        .add_path_page(
            "M 0 0 L 10 0 L 10 10 C",
            [0.0, 0.0, 10.0, 10.0],
            20.0,
            20.0,
            true,
            false,
        )
        .unwrap();
    let spec = ColorSpaceSpec {
        color_type: "RGB".into(),
        bits_per_component: 8,
        profile: None,
        palette: vec![vec![255, 0, 0]],
    };
    let public = document.add_document_color_space(0, &spec).unwrap();
    let local = document.add_page_color_space(0, &spec).unwrap();
    document
        .set_document_default_color_space(0, Some(&public))
        .unwrap();
    let before = document.to_bytes().unwrap();
    assert!(document.remove_document_color_space(0, &public).is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    let page = document.pages().unwrap()[0].path.clone();
    let xml = std::str::from_utf8(document.entry(&page).unwrap().unwrap()).unwrap();
    document
        .set_entry(
            &page,
            xml.replace(
                "</ofd:PathObject>",
                &format!("<ofd:FillColor ColorSpace=\"{local}\" Index=\"0\"/></ofd:PathObject>"),
            )
            .into_bytes(),
        )
        .unwrap();
    let before = document.to_bytes().unwrap();
    assert!(document.remove_page_color_space(0, &local).is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    let xml = std::str::from_utf8(document.entry(&page).unwrap().unwrap()).unwrap();
    document
        .set_entry(
            &page,
            xml.replace(
                &format!("<ofd:FillColor ColorSpace=\"{local}\" Index=\"0\"/>"),
                "<ofd:FillColor Value=\"255 0 0\"/>",
            )
            .into_bytes(),
        )
        .unwrap();
    document.remove_page_color_space(0, &local).unwrap();
    assert_eq!(document.page_color_spaces(0).unwrap().len(), 1);
    assert!(document.remove_page_color_space(0, &public).is_err());
    document.set_document_default_color_space(0, None).unwrap();
    document.remove_document_color_space(0, &public).unwrap();
    assert!(document.document_color_spaces(0).unwrap().is_empty());
    assert!(document.validate_references().unwrap().is_empty());
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert!(reopened.page_color_spaces(0).unwrap().is_empty());
}

