#[test]
fn page_resource_deletion_checks_annotation_page_id_aliases() {
    let mut document = OfdDocument::new();
    document.add_blank_page(20.0, 20.0).unwrap();
    let draw_id = document
        .add_page_draw_param(0, &DrawParamStyle::default())
        .unwrap();
    let color_id = document
        .add_page_color_space(
            0,
            &ColorSpaceSpec {
                color_type: "RGB".into(),
                bits_per_component: 8,
                profile: None,
                palette: vec![vec![255, 0, 0]],
            },
        )
        .unwrap();
    document
        .add_shape_annotation(0, "Square", [1.0, 1.0, 8.0, 8.0], &Default::default())
        .unwrap();
    let path = document.annotations().unwrap()[0].source_path.clone();
    let source = String::from_utf8(document.entry(&path).unwrap().unwrap().to_vec()).unwrap();
    let changed = source
        .replacen(
            "<ofd:PathObject ID=",
            &format!("<ofd:PathObject DrawParam=\"{draw_id}\" ID="),
            1,
        )
        .replacen(
            "</ofd:PathObject>",
            &format!("<ofd:FillColor ColorSpace=\"{color_id}\" Index=\"0\"/></ofd:PathObject>"),
            1,
        );
    assert_ne!(source, changed);
    document.set_entry(&path, changed.into_bytes()).unwrap();
    let page_id = document.pages().unwrap()[0].id.clone();
    let list_path = "Doc_0/Annots/Annotations.xml";
    let source = String::from_utf8(document.entry(list_path).unwrap().unwrap().to_vec()).unwrap();
    let changed = source.replacen(
        &format!("PageID=\"{page_id}\""),
        &format!("PageID=\"0{page_id}\""),
        1,
    );
    assert_ne!(source, changed);
    document.set_entry(list_path, changed.into_bytes()).unwrap();
    let before = document.to_bytes().unwrap();
    assert!(document.remove_page_draw_param(0, &draw_id).is_err());
    assert!(document.remove_page_color_space(0, &color_id).is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
}

#[test]
fn validates_missing_default_page_and_annotation_color_spaces() {
    let mut document = OfdDocument::new();
    document
        .add_path_page(
            "M 0 0 L 10 0 L 10 10 C",
            [0.0, 0.0, 10.0, 10.0],
            20.0,
            20.0,
            true,
            false,
        )
        .unwrap();
    let page = document.pages().unwrap()[0].path.clone();
    let source = std::str::from_utf8(document.entry(&page).unwrap().unwrap()).unwrap();
    document
        .set_entry(
            &page,
            source
                .replace(
                    "</ofd:PathObject>",
                    "<ofd:FillColor ColorSpace=\"901\" Value=\"1 2 3\"/></ofd:PathObject>",
                )
                .into_bytes(),
        )
        .unwrap();
    document
        .add_shape_annotation(0, "Square", [1.0, 1.0, 8.0, 8.0], &Default::default())
        .unwrap();
    let annotation = document.annotations().unwrap()[0].source_path.clone();
    let source = std::str::from_utf8(document.entry(&annotation).unwrap().unwrap()).unwrap();
    document
        .set_entry(
            &annotation,
            source
                .replace(
                    "</ofd:PathObject>",
                    "<ofd:StrokeColor ColorSpace=\"902\" Value=\"1 2 3\"/></ofd:PathObject>",
                )
                .into_bytes(),
        )
        .unwrap();
    let root = "Doc_0/Document.xml";
    let source = std::str::from_utf8(document.entry(root).unwrap().unwrap()).unwrap();
    document
        .set_entry(
            root,
            source
                .replace(
                    "</ofd:CommonData>",
                    "<ofd:DefaultCS>903</ofd:DefaultCS></ofd:CommonData>",
                )
                .into_bytes(),
        )
        .unwrap();
    let issues = document.validate_references().unwrap();
    assert!(issues
        .iter()
        .any(|issue| issue.code == "default_color_space_reference"));
    assert!(issues
        .iter()
        .any(|issue| issue.code == "color_space_reference" && issue.message.contains("901")));
    assert!(issues
        .iter()
        .any(|issue| issue.code == "color_space_reference" && issue.message.contains("902")));
}

#[test]
fn validates_palette_index_and_color_channels() {
    let mut document = OfdDocument::new();
    document
        .add_path_page(
            "M 0 0 L 10 0 L 10 10 C",
            [0.0, 0.0, 10.0, 10.0],
            20.0,
            20.0,
            true,
            false,
        )
        .unwrap();
    let id = document
        .add_document_color_space(
            0,
            &ColorSpaceSpec {
                color_type: "GRAY".into(),
                bits_per_component: 4,
                profile: None,
                palette: vec![vec![15]],
            },
        )
        .unwrap();
    let page = document.pages().unwrap()[0].path.clone();
    let original = std::str::from_utf8(document.entry(&page).unwrap().unwrap())
        .unwrap()
        .to_owned();
    for (color, expected) in [
        (
            format!("<ofd:FillColor ColorSpace=\"{id}\" Index=\"1\"/>"),
            Some("invalid_color_index"),
        ),
        (
            format!("<ofd:FillColor ColorSpace=\"{id}\" Value=\"16\"/>"),
            Some("invalid_color_value"),
        ),
        (
            format!("<ofd:FillColor ColorSpace=\"{id}\" Value=\"1 2\"/>"),
            Some("invalid_color_value"),
        ),
        (
            format!("<ofd:FillColor ColorSpace=\"{id}\" Value=\"15\"/>"),
            None,
        ),
    ] {
        document
            .set_entry(
                &page,
                original
                    .replace("</ofd:PathObject>", &format!("{color}</ofd:PathObject>"))
                    .into_bytes(),
            )
            .unwrap();
        let issues = document.validate_references().unwrap();
        if let Some(code) = expected {
            assert!(issues.iter().any(|issue| issue.code == code), "{issues:?}");
        } else {
            assert!(issues.is_empty(), "{issues:?}");
        }
    }
}

#[test]
fn rejects_invalid_palettes_read_from_existing_resource_files() {
    let mut document = OfdDocument::new();
    document.add_blank_page(20.0, 20.0).unwrap();
    let id = document
        .add_document_color_space(
            0,
            &ColorSpaceSpec {
                color_type: "RGB".into(),
                bits_per_component: 8,
                profile: None,
                palette: vec![vec![255, 0, 0]],
            },
        )
        .unwrap();
    let resource = document.document_color_spaces(0).unwrap()[0]
        .resource_path
        .clone();
    let original = std::str::from_utf8(document.entry(&resource).unwrap().unwrap())
        .unwrap()
        .to_owned();
    for channels in ["255 0", "256 0 0"] {
        let bytes = original.replace("255 0 0", channels).into_bytes();
        document.set_entry(&resource, bytes).unwrap();
        let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
        assert!(reopened.page_svg(0).is_err());
        assert!(reopened
            .validate_references()
            .unwrap()
            .iter()
            .any(|issue| { issue.code == "color_space_resources" && issue.message.contains(&id) }));
    }
}

#[test]
fn page_draw_params_are_scoped_and_support_relative_and_pattern_paints() {
    let mut document = OfdDocument::new();
    document.add_blank_page(40.0, 30.0).unwrap();
    document.append_blank_page(0, 40.0, 30.0).unwrap();
    let path_style = PathStyle {
        fill: true,
        stroke: false,
        ..PathStyle::default()
    };
    let first = document
        .add_path_object(
            0,
            "M 0 0 L 10 0 L 10 10 C",
            [1.0, 1.0, 10.0, 10.0],
            path_style.clone(),
        )
        .unwrap();
    let second = document
        .add_path_object(
            1,
            "M 0 0 L 10 0 L 10 10 C",
            [1.0, 1.0, 10.0, 10.0],
            path_style,
        )
        .unwrap();
    let public = document
        .add_document_draw_param(
            0,
            &DrawParamStyle {
                fill: Some(SolidPaintStyle {
                    color: [255, 0, 0],
                    alpha: 255,
                }),
                ..DrawParamStyle::default()
            },
        )
        .unwrap();
    let local = document
        .add_page_draw_param(
            0,
            &DrawParamStyle {
                relative: Some(public.clone()),
                fill: Some(SolidPaintStyle {
                    color: [0, 255, 0],
                    alpha: 255,
                }),
                ..DrawParamStyle::default()
            },
        )
        .unwrap();
    document
        .set_page_object_draw_param(0, &first, Some(&local))
        .unwrap();
    assert!(document.page_svg(0).unwrap().contains("fill=\"#00ff00\""));
    let page_path = document.pages().unwrap()[0].path.clone();
    let resource_name = format!("RustPageDrawParams_{local}.xml");
    assert!(
        std::str::from_utf8(document.entry(&page_path).unwrap().unwrap())
            .unwrap()
            .contains(&resource_name)
    );
    assert!(document
        .entry(&format!("Doc_0/Pages/Page_0/{resource_name}"))
        .unwrap()
        .is_some());
    let document_params = document.document_draw_params(0).unwrap();
    assert_eq!(document_params.len(), 1);
    assert_eq!(document_params[0].id, public);
    let first_page_params = document.page_draw_params(0).unwrap();
    assert_eq!(first_page_params.len(), 2);
    let local_param = first_page_params
        .iter()
        .find(|param| param.id == local)
        .unwrap();
    assert_eq!(local_param.relative.as_deref(), Some(public.as_str()));
    assert!(local_param.xml.contains("<ofd:DrawParam"));
    assert!(local_param.resource_path.ends_with(&resource_name));
    assert_eq!(document.page_draw_params(1).unwrap().len(), 1);

    let pattern = PatternStyle {
        width: 4.0,
        height: 4.0,
        x_step: None,
        y_step: None,
        reflect: PatternReflectMethod::Normal,
        relative_to: PatternRelativeTo::Object,
        ctm: None,
        alpha: None,
        thumbnail: None,
        cells: vec![PatternCell::Path {
            commands: "M 0 0 L 4 0 L 4 4 L 0 4 C".into(),
            boundary: [0.0, 0.0, 4.0, 4.0],
            style: PathStyle {
                fill: true,
                stroke: false,
                fill_color: Some([0, 0, 255]),
                ..PathStyle::default()
            },
        }],
    };
    let pattern_id = document
        .add_page_draw_param(
            0,
            &DrawParamStyle {
                fill_pattern: Some(pattern),
                ..DrawParamStyle::default()
            },
        )
        .unwrap();
    document
        .set_page_object_draw_param(0, &first, Some(&pattern_id))
        .unwrap();
    assert_eq!(
        document.page_object_paints(0).unwrap()[0]
            .effective_fill
            .as_ref()
            .unwrap()
            .kind,
        "Pattern"
    );
    assert!(document.page_svg(0).unwrap().contains("<pattern "));

    let before = document.to_bytes().unwrap();
    assert!(document
        .set_page_object_draw_param(1, &second, Some(&local))
        .is_err());
    assert!(document
        .add_page_draw_param(
            1,
            &DrawParamStyle {
                relative: Some(local),
                ..DrawParamStyle::default()
            },
        )
        .is_err());
    assert!(document
        .add_page_draw_param(
            0,
            &DrawParamStyle {
                line_width: Some(f64::NAN),
                ..DrawParamStyle::default()
            },
        )
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    assert!(document.validate_references().unwrap().is_empty());
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.page_draw_params(0).unwrap().len(), 3);
    assert_eq!(
        reopened.page_object_paints(0).unwrap(),
        document.page_object_paints(0).unwrap()
    );
}

#[test]
fn duplicate_draw_param_ids_are_reported_and_rejected_on_read() {
    let mut document = OfdDocument::new();
    document.add_blank_page(20.0, 20.0).unwrap();
    let id = document
        .add_document_draw_param(0, &DrawParamStyle::default())
        .unwrap();
    let path = document.document_draw_params(0).unwrap()[0]
        .resource_path
        .clone();
    let original = String::from_utf8(document.entry(&path).unwrap().unwrap().to_vec()).unwrap();
    let duplicate = format!("<ofd:DrawParam ID=\"0{id}\"/>");
    let changed = original.replacen(
        "</ofd:DrawParams>",
        &format!("{duplicate}</ofd:DrawParams>"),
        1,
    );
    assert_ne!(changed, original);
    document.set_entry(&path, changed.into_bytes()).unwrap();

    assert!(document
        .validate_references()
        .unwrap()
        .iter()
        .any(|issue| { issue.path == path && issue.code == "duplicate_resource_id" }));
    assert!(matches!(
        document.document_draw_params(0),
        Err(OfdError::Invalid(message)) if message.contains("duplicate DrawParam ID")
    ));
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert!(reopened.document_draw_params(0).is_err());
}

#[test]
fn duplicate_font_ids_in_one_resource_file_are_rejected() {
    let mut document = OfdDocument::new();
    document.add_blank_page(20.0, 20.0).unwrap();
    document
        .add_document_color_space(
            0,
            &ColorSpaceSpec {
                color_type: "RGB".into(),
                bits_per_component: 8,
                profile: None,
                palette: Vec::new(),
            },
        )
        .unwrap();
    let id = "999";
    let path = document.document_color_spaces(0).unwrap()[0]
        .resource_path
        .clone();
    let original = String::from_utf8(document.entry(&path).unwrap().unwrap().to_vec()).unwrap();
    let duplicate = format!(
        "<ofd:Fonts><ofd:Font ID=\"{id}\" FontName=\"First\"/><ofd:Font ID=\"0{id}\" FontName=\"Second\"/></ofd:Fonts>"
    );
    let changed = original.replacen("</ofd:Res>", &format!("{duplicate}</ofd:Res>"), 1);
    assert_ne!(changed, original);
    document.set_entry(&path, changed.into_bytes()).unwrap();

    assert!(document
        .validate_references()
        .unwrap()
        .iter()
        .any(|issue| { issue.path == path && issue.code == "duplicate_resource_id" }));
    assert!(matches!(
        document.fonts(),
        Err(OfdError::Invalid(message)) if message.contains("duplicate Font ID")
    ));
}

#[test]
fn duplicate_multimedia_ids_are_rejected_by_list_and_data_readers() {
    let mut document = OfdDocument::new();
    document.add_blank_page(20.0, 20.0).unwrap();
    let id = document
        .add_multimedia_resource(0, "Audio", "MP3", b"audio bytes")
        .unwrap();
    let path = "Doc_0/DocumentRes.xml";
    let original = String::from_utf8(document.entry(path).unwrap().unwrap().to_vec()).unwrap();
    let start = original.find("<ofd:MultiMedia ").unwrap();
    let end =
        start + original[start..].find("</ofd:MultiMedia>").unwrap() + "</ofd:MultiMedia>".len();
    let duplicate =
        original[start..end].replacen(&format!("ID=\"{id}\""), &format!("ID=\"0{id}\""), 1);
    let changed = original.replacen(
        "</ofd:MultiMedias>",
        &format!("{duplicate}</ofd:MultiMedias>"),
        1,
    );
    assert_ne!(changed, original);
    document.set_entry(path, changed.into_bytes()).unwrap();

    assert!(document
        .validate_references()
        .unwrap()
        .iter()
        .any(|issue| { issue.path == path && issue.code == "duplicate_resource_id" }));
    assert!(matches!(
        document.document_multimedia_resources(0),
        Err(OfdError::Invalid(message)) if message.contains("duplicate MultiMedia ID")
    ));
    assert!(matches!(
        document.document_multimedia_data(0, &id),
        Err(OfdError::Invalid(message)) if message.contains("duplicate MultiMedia ID")
    ));
    assert!(document.page_multimedia_data(0, &id).is_err());
}

