#[test]
fn draw_params_can_be_replaced_in_their_scope_atomically() {
    let mut document = OfdDocument::new();
    document.add_blank_page(20.0, 20.0).unwrap();
    document.append_blank_page(0, 20.0, 20.0).unwrap();
    let path_style = PathStyle {
        fill: true,
        stroke: false,
        ..PathStyle::default()
    };
    let first = document
        .add_path_object(
            0,
            "M 0 0 L 10 0 L 10 10 C",
            [0.0, 0.0, 10.0, 10.0],
            path_style.clone(),
        )
        .unwrap();
    let second = document
        .add_path_object(
            1,
            "M 0 0 L 10 0 L 10 10 C",
            [0.0, 0.0, 10.0, 10.0],
            path_style,
        )
        .unwrap();
    let public = document
        .add_document_draw_param(
            0,
            &DrawParamStyle {
                fill: Some(SolidPaintStyle {
                    color: [255, 0, 0],
                    alpha: 255,
                }),
                ..DrawParamStyle::default()
            },
        )
        .unwrap();
    let local = document
        .add_page_draw_param(
            0,
            &DrawParamStyle {
                relative: Some(public.clone()),
                fill: Some(SolidPaintStyle {
                    color: [0, 255, 0],
                    alpha: 255,
                }),
                ..DrawParamStyle::default()
            },
        )
        .unwrap();
    document
        .set_page_object_draw_param(0, &first, Some(&local))
        .unwrap();
    document
        .set_page_object_draw_param(1, &second, Some(&public))
        .unwrap();
    document
        .set_document_draw_param(
            0,
            &public,
            &DrawParamStyle {
                fill: Some(SolidPaintStyle {
                    color: [0, 0, 255],
                    alpha: 255,
                }),
                ..DrawParamStyle::default()
            },
        )
        .unwrap();
    assert!(document.page_svg(1).unwrap().contains("fill=\"#0000ff\""));
    assert!(document.page_svg(0).unwrap().contains("fill=\"#00ff00\""));

    let pattern = PatternStyle {
        width: 4.0,
        height: 4.0,
        x_step: None,
        y_step: None,
        reflect: PatternReflectMethod::Normal,
        relative_to: PatternRelativeTo::Object,
        ctm: None,
        alpha: None,
        thumbnail: None,
        cells: vec![PatternCell::Path {
            commands: "M 0 0 L 4 0 L 4 4 L 0 4 C".into(),
            boundary: [0.0, 0.0, 4.0, 4.0],
            style: PathStyle {
                fill: true,
                stroke: false,
                fill_color: Some([255, 255, 0]),
                ..PathStyle::default()
            },
        }],
    };
    document
        .set_page_draw_param(
            0,
            &local,
            &DrawParamStyle {
                relative: Some(public.clone()),
                fill_pattern: Some(pattern),
                ..DrawParamStyle::default()
            },
        )
        .unwrap();
    assert!(document.page_svg(0).unwrap().contains("<pattern "));
    assert_eq!(
        document.page_object_paints(0).unwrap()[0]
            .effective_fill
            .as_ref()
            .unwrap()
            .kind,
        "Pattern"
    );
    assert!(document.validate_references().unwrap().is_empty());

    let child = document
        .add_page_draw_param(
            0,
            &DrawParamStyle {
                relative: Some(local.clone()),
                ..DrawParamStyle::default()
            },
        )
        .unwrap();
    let before = document.to_bytes().unwrap();
    assert!(document
        .set_page_draw_param(
            0,
            &local,
            &DrawParamStyle {
                relative: Some(child),
                ..DrawParamStyle::default()
            }
        )
        .is_err());
    assert!(document
        .set_page_draw_param(1, &local, &DrawParamStyle::default())
        .is_err());
    assert!(document
        .set_page_draw_param(0, &public, &DrawParamStyle::default())
        .is_err());
    assert!(document
        .set_document_draw_param(0, &local, &DrawParamStyle::default())
        .is_err());
    assert!(document
        .set_document_draw_param(
            0,
            &public,
            &DrawParamStyle {
                line_width: Some(-1.0),
                ..DrawParamStyle::default()
            }
        )
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    let reopened = OfdDocument::from_bytes(&before).unwrap();
    assert!(reopened.page_svg(0).unwrap().contains("<pattern "));
    assert!(reopened.page_svg(1).unwrap().contains("fill=\"#0000ff\""));
}

#[test]
fn draw_param_writers_reject_resource_files_shared_across_scopes() {
    let mut document = OfdDocument::new();
    document.add_blank_page(20.0, 20.0).unwrap();
    document.append_blank_page(0, 20.0, 20.0).unwrap();
    let public = document
        .add_document_draw_param(0, &DrawParamStyle::default())
        .unwrap();
    let local = document
        .add_page_draw_param(0, &DrawParamStyle::default())
        .unwrap();

    let pages = document.pages().unwrap();
    let other_path = &pages[1].path;
    let source = std::str::from_utf8(document.entry(other_path).unwrap().unwrap()).unwrap();
    let link = format!("<ofd:PageRes>../Page_0/RustPageDrawParams_{local}.xml</ofd:PageRes>");
    document
        .set_entry(
            other_path,
            source
                .replace("<ofd:Content>", &format!("{link}<ofd:Content>"))
                .into_bytes(),
        )
        .unwrap();
    let before = document.to_bytes().unwrap();
    assert!(document
        .set_page_draw_param(0, &local, &DrawParamStyle::default())
        .unwrap_err()
        .to_string()
        .contains("shared outside this page"));
    assert_eq!(document.to_bytes().unwrap(), before);

    document.append_document_body().unwrap();
    let root = "Doc_1/Document.xml";
    let source = std::str::from_utf8(document.entry(root).unwrap().unwrap())
        .unwrap()
        .to_owned();
    document
        .set_entry(
            root,
            source
                .replace(
                    "<ofd:PublicRes>PublicRes.xml</ofd:PublicRes>",
                    "<ofd:PublicRes>../Doc_0/PublicRes.xml</ofd:PublicRes>",
                )
                .into_bytes(),
        )
        .unwrap();
    let before = document.to_bytes().unwrap();
    assert!(document
        .set_document_draw_param(0, &public, &DrawParamStyle::default())
        .unwrap_err()
        .to_string()
        .contains("shared by document bodies"));
    assert!(document
        .add_document_draw_param(0, &DrawParamStyle::default())
        .unwrap_err()
        .to_string()
        .contains("shared by document bodies"));
    assert_eq!(document.to_bytes().unwrap(), before);

    let template = "<ofd:TemplatePage ID=\"2\" BaseLoc=\"../Doc_0/Pages/Page_0/Content.xml\"/>";
    document
        .set_entry(
            root,
            source
                .replace("</ofd:CommonData>", &format!("{template}</ofd:CommonData>"))
                .into_bytes(),
        )
        .unwrap();
    let first_path = &pages[0].path;
    let source = std::str::from_utf8(document.entry(first_path).unwrap().unwrap()).unwrap();
    document
        .set_entry(
            first_path,
            source
                .replace(
                    "<ofd:Content>",
                    "<ofd:PageRes>../../PublicRes.xml</ofd:PageRes><ofd:Content>",
                )
                .into_bytes(),
        )
        .unwrap();
    let before = document.to_bytes().unwrap();
    assert!(document
        .set_document_draw_param(0, &public, &DrawParamStyle::default())
        .unwrap_err()
        .to_string()
        .contains("shared by document bodies"));
    assert_eq!(document.to_bytes().unwrap(), before);
}

#[test]
fn validates_unreferenced_draw_param_inheritance_in_document_and_page_resources() {
    let mut document = OfdDocument::new();
    document.add_blank_page(20.0, 20.0).unwrap();
    let public = document
        .add_document_draw_param(0, &DrawParamStyle::default())
        .unwrap();
    let local = document
        .add_page_draw_param(0, &DrawParamStyle::default())
        .unwrap();
    assert!(document.validate_references().unwrap().is_empty());

    for (id, path) in [
        (
            public.clone(),
            document.document_draw_params(0).unwrap()[0]
                .resource_path
                .clone(),
        ),
        (
            local.clone(),
            document.page_draw_params(0).unwrap()[0]
                .resource_path
                .clone(),
        ),
    ] {
        let source = std::str::from_utf8(document.entry(&path).unwrap().unwrap()).unwrap();
        let updated = source.replace(
            &format!("<ofd:DrawParam ID=\"{id}\""),
            &format!("<ofd:DrawParam ID=\"{id}\" Relative=\"999999\""),
        );
        document.set_entry(&path, updated.into_bytes()).unwrap();
    }
    let issues = document.validate_references().unwrap();
    assert!(issues.iter().any(|issue| {
        issue.code == "draw_param_inheritance" && issue.message.contains(&public)
    }));
    assert!(issues
        .iter()
        .any(|issue| { issue.code == "draw_param_inheritance" && issue.message.contains(&local) }));
}

#[test]
fn removes_only_unreferenced_draw_params_and_preserves_allocated_ids() {
    let mut document = OfdDocument::new();
    document.add_blank_page(20.0, 20.0).unwrap();
    let public = document
        .add_document_draw_param(0, &DrawParamStyle::default())
        .unwrap();
    let inherited = document
        .add_document_draw_param(
            0,
            &DrawParamStyle {
                relative: Some(public.clone()),
                ..DrawParamStyle::default()
            },
        )
        .unwrap();
    let local = document
        .add_page_draw_param(0, &DrawParamStyle::default())
        .unwrap();
    let local_child = document
        .add_page_draw_param(
            0,
            &DrawParamStyle {
                relative: Some(local.clone()),
                ..DrawParamStyle::default()
            },
        )
        .unwrap();
    let before = document.to_bytes().unwrap();
    assert!(document.remove_document_draw_param(0, &public).is_err());
    assert!(document.remove_page_draw_param(0, &local).is_err());
    assert_eq!(document.to_bytes().unwrap(), before);

    document.remove_page_draw_param(0, &local_child).unwrap();
    document.remove_page_draw_param(0, &local).unwrap();
    document.remove_document_draw_param(0, &inherited).unwrap();
    document.remove_document_draw_param(0, &public).unwrap();
    assert!(document.document_draw_params(0).unwrap().is_empty());
    assert!(document.page_draw_params(0).unwrap().is_empty());
    assert!(document.validate_references().unwrap().is_empty());
    let next = document
        .add_document_draw_param(0, &DrawParamStyle::default())
        .unwrap();
    assert!(next.parse::<usize>().unwrap() > local_child.parse::<usize>().unwrap());
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.document_draw_params(0).unwrap()[0].id, next);
}

#[test]
fn referenced_draw_params_cannot_be_removed_across_scopes() {
    let mut document = OfdDocument::new();
    document.add_blank_page(20.0, 20.0).unwrap();
    document.append_blank_page(0, 20.0, 20.0).unwrap();
    let style = PathStyle {
        fill: true,
        stroke: false,
        ..PathStyle::default()
    };
    let first = document
        .add_path_object(
            0,
            "M 0 0 L 10 0 L 10 10 C",
            [0.0, 0.0, 10.0, 10.0],
            style.clone(),
        )
        .unwrap();
    let second = document
        .add_path_object(1, "M 0 0 L 10 0 L 10 10 C", [0.0, 0.0, 10.0, 10.0], style)
        .unwrap();
    let public = document
        .add_document_draw_param(0, &DrawParamStyle::default())
        .unwrap();
    let local = document
        .add_page_draw_param(0, &DrawParamStyle::default())
        .unwrap();
    document
        .set_page_object_draw_param(0, &first, Some(&local))
        .unwrap();
    document
        .set_page_object_draw_param(1, &second, Some(&public))
        .unwrap();
    let before = document.to_bytes().unwrap();
    assert!(document.remove_page_draw_param(0, &local).is_err());
    assert!(document.remove_document_draw_param(0, &public).is_err());
    assert!(document.remove_page_draw_param(1, &local).is_err());
    assert!(document.remove_document_draw_param(0, &local).is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
}

