#[test]
fn finds_repeated_keywords_across_text_codes_with_page_boxes() {
    let mut document = OfdDocument::new();
    document.add_blank_page(80.0, 50.0).unwrap();
    document
        .add_text_object(0, "ABAB", [10.0, 20.0, 40.0, 10.0], 5.0, None)
        .unwrap();
    let path = document.pages().unwrap()[0].path.clone();
    let original = without_first_text_code_delta_x(
        std::str::from_utf8(document.entry(&path).unwrap().unwrap()).unwrap(),
    );
    let updated = original.replace(
        "<ofd:TextCode X=\"0\" Y=\"5\">ABAB</ofd:TextCode>",
        "<ofd:TextCode X=\"0\" Y=\"5\" DeltaX=\"5\">AB</ofd:TextCode><ofd:TextCode X=\"10\" Y=\"5\" DeltaX=\"5\">AB</ofd:TextCode>",
    );
    assert_ne!(original, updated);
    document.set_entry(&path, updated.into_bytes()).unwrap();
    document.add_text_page("AB", 80.0, 50.0).unwrap();
    let matches = document
        .keyword_positions(&["AB", "BA"], Some(&[0]))
        .unwrap();
    assert_eq!(matches.len(), 3);
    assert_eq!(matches[0].keyword, "AB");
    assert_eq!(matches[0].box_mm, [10.0, 20.0, 10.0, 5.0]);
    assert_eq!(matches[1].keyword, "BA");
    assert_eq!(matches[1].box_mm, [15.0, 20.0, 10.0, 5.0]);
    assert_eq!(matches[2].keyword, "AB");
    assert_eq!(matches[2].box_mm, [20.0, 20.0, 10.0, 5.0]);
    assert_eq!(
        document
            .keyword_positions(&["AB"], Some(&[1]))
            .unwrap()
            .len(),
        1
    );
    assert_eq!(document.keyword_positions(&["missing"], None).unwrap(), []);
    assert!(document.keyword_positions(&[""], None).is_err());
    assert!(document.keyword_positions(&["AB"], Some(&[2])).is_err());
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(
        reopened
            .keyword_positions(&["AB", "BA"], Some(&[0]))
            .unwrap(),
        matches
    );
}

