#[test]
fn keyword_boxes_follow_character_direction_and_horizontal_scale() {
    let mut document = OfdDocument::new();
    document.add_text_page("A", 30.0, 20.0).unwrap();
    let id = document.page_text_objects(0).unwrap()[0]
        .id
        .clone()
        .unwrap();
    for (direction, expected) in [
        (0, [10.0, 10.0, 2.5, 5.0]),
        (90, [10.0, 15.0, 5.0, 2.5]),
        (180, [7.5, 15.0, 2.5, 5.0]),
        (270, [5.0, 12.5, 5.0, 2.5]),
    ] {
        document
            .set_page_text_typography(
                0,
                &id,
                TextTypographyStyle {
                    size: 5.0,
                    h_scale: Some(0.5),
                    read_direction: Some(180),
                    char_direction: Some(direction),
                    weight: None,
                    italic: None,
                },
            )
            .unwrap();
        let positions = document.keyword_positions(&["A"], None).unwrap();
        assert_eq!(positions.len(), 1);
        assert_eq!(positions[0].box_mm, expected, "direction={direction}");
        assert_eq!(
            document
                .page_text_in_region(0, [10.0, 15.0, 1.0, 1.0])
                .unwrap(),
            ["A"]
        );
    }
    document
        .set_page_text_typography(
            0,
            &id,
            TextTypographyStyle {
                size: 5.0,
                h_scale: Some(0.5),
                read_direction: None,
                char_direction: Some(90),
                weight: None,
                italic: None,
            },
        )
        .unwrap();
    let path = document.pages().unwrap()[0].path.clone();
    let source = std::str::from_utf8(document.entry(&path).unwrap().unwrap()).unwrap();
    let rotated = source.replace(
        "Boundary=\"10 10 10 8\"",
        "Boundary=\"10 10 10 8\" CTM=\"0 1 -1 0 0 0\"",
    );
    assert_ne!(source, rotated);
    document.set_entry(&path, rotated.into_bytes()).unwrap();
    let positions = document.keyword_positions(&["A"], None).unwrap();
    assert_eq!(positions[0].box_mm, [2.5, 10.0, 2.5, 5.0]);
    assert!(document.validate_references().unwrap().is_empty());
}

