#[test]
fn imports_pdf_rotated_pages_with_text_paths_and_images() {
    let fixtures: [(&str, [f64; 4], (u32, u32)); 3] = [
        ("rotate-90.pdf", [0.0, 0.0, 76.2, 50.8], (5, 10)),
        ("rotate-180.pdf", [0.0, 0.0, 50.8, 76.2], (40, 10)),
        ("rotate-270.pdf", [0.0, 0.0, 76.2, 50.8], (60, 32)),
    ];
    for (name, box_, red_at) in fixtures {
        let bytes = std::fs::read(
            PathBuf::from(env!("CARGO_MANIFEST_DIR"))
                .join("tests/fixtures")
                .join(name),
        )
        .unwrap();
        let document = OfdDocument::from_pdf_bytes(&bytes).unwrap();
        let physical = document.pages().unwrap()[0].physical_box.unwrap();
        for (actual, expected) in physical.into_iter().zip(box_) {
            assert!(
                (actual - expected).abs() < 1e-8,
                "{name}: {actual} != {expected}"
            );
        }
        assert_eq!(document.page_text(0).unwrap(), ["Hi"], "{name}");
        assert_eq!(document.page_paths(0).unwrap().len(), 2, "{name}");
        assert_eq!(document.page_images(0).unwrap().len(), 1, "{name}");
        assert!(document.validate_references().unwrap().is_empty(), "{name}");
        if name == "rotate-90.pdf" {
            assert!(document.page_svg(0).unwrap().contains("clipPath"));
        }
        let png = document.page_png(0, 25.4).unwrap();
        let decoded = resvg::tiny_skia::Pixmap::decode_png(&png).unwrap();
        assert_eq!(decoded.width(), box_[2].round() as u32, "{name}");
        assert_eq!(decoded.height(), box_[3].round() as u32, "{name}");
        let color = decoded.pixel(red_at.0, red_at.1).unwrap();
        assert!(
            color.red() > 240 && color.green() < 15 && color.blue() < 15,
            "{name}"
        );
        if name == "rotate-90.pdf" {
            let clipped = decoded.pixel(65, 43).unwrap();
            assert!(clipped.red() > 240 && clipped.green() > 240 && clipped.blue() > 240);
        }
        let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
        assert_eq!(reopened.page_text(0).unwrap(), ["Hi"], "{name}");
        assert_eq!(reopened.page_images(0).unwrap().len(), 1, "{name}");
    }
}

