#[test]
fn renders_image_to_declared_boundary_even_when_pixel_aspect_differs() {
    let mut png = Vec::new();
    {
        let mut encoder = png::Encoder::new(&mut png, 5, 2);
        encoder.set_color(png::ColorType::Grayscale);
        encoder.set_depth(png::BitDepth::Eight);
        encoder
            .write_header()
            .unwrap()
            .write_image_data(&[0; 10])
            .unwrap();
    }
    let mut document = OfdDocument::new();
    document.add_blank_page(20.0, 20.0).unwrap();
    let id = document
        .add_image_object(0, &png, "png", [2.0, 2.0, 10.0, 10.0])
        .unwrap();
    assert_eq!(
        document.page_images(0).unwrap()[0].ctm,
        Some([10.0, 0.0, 0.0, 10.0, 0.0, 0.0])
    );
    let raster =
        resvg::tiny_skia::Pixmap::decode_png(&document.page_png(0, 25.4).unwrap()).unwrap();
    assert!(raster.pixel(7, 4).unwrap().red() < 60);
    assert!(raster.pixel(7, 10).unwrap().red() < 60);
    assert!(raster.pixel(7, 14).unwrap().red() > 235);
    assert!(document
        .page_svg(0)
        .unwrap()
        .contains("preserveAspectRatio=\"none\""));
    document.set_page_object_ctm(0, &id, None).unwrap();
    let unscaled =
        resvg::tiny_skia::Pixmap::decode_png(&document.page_png(0, 254.0).unwrap()).unwrap();
    assert!(unscaled.pixel(25, 25).unwrap().red() < 60);
    assert!(unscaled.pixel(70, 40).unwrap().red() > 235);
}

#[test]
fn clips_transformed_image_to_its_ofd_boundary() {
    let mut png = Vec::new();
    {
        let mut encoder = png::Encoder::new(&mut png, 1, 1);
        encoder.set_color(png::ColorType::Grayscale);
        encoder.set_depth(png::BitDepth::Eight);
        encoder
            .write_header()
            .unwrap()
            .write_image_data(&[0])
            .unwrap();
    }
    let mut document = OfdDocument::new();
    document.add_blank_page(20.0, 20.0).unwrap();
    let id = document
        .add_image_object(0, &png, "png", [2.0, 2.0, 5.0, 5.0])
        .unwrap();
    document
        .set_page_object_ctm(0, &id, Some([10.0, 0.0, 0.0, 10.0, 0.0, 0.0]))
        .unwrap();
    let raster =
        resvg::tiny_skia::Pixmap::decode_png(&document.page_png(0, 25.4).unwrap()).unwrap();
    assert!(raster.pixel(4, 4).unwrap().red() < 20);
    assert!(raster.pixel(9, 4).unwrap().red() > 235);
    assert!(document.page_svg(0).unwrap().contains("ofd-image-boundary"));
}

#[test]
fn clips_path_and_text_to_their_ofd_boundaries() {
    let mut document = OfdDocument::new();
    document.add_text_page("base", 30.0, 20.0).unwrap();
    document
        .add_path_object(
            0,
            "M 0 0 L 10 0 L 10 10 L 0 10 C",
            [2.0, 2.0, 5.0, 5.0],
            PathStyle {
                fill: true,
                stroke: false,
                fill_color: Some([255, 0, 0]),
                ..PathStyle::default()
            },
        )
        .unwrap();
    let svg = document.page_svg(0).unwrap();
    assert!(svg.contains("ofd-path-boundary-"));
    assert!(svg.contains("ofd-text-boundary-"));
    let raster =
        resvg::tiny_skia::Pixmap::decode_png(&document.page_png(0, 25.4).unwrap()).unwrap();
    let inside = raster.pixel(4, 4).unwrap();
    let outside = raster.pixel(9, 4).unwrap();
    assert!(inside.red() > 240 && inside.green() < 15);
    assert!(outside.red() > 235 && outside.green() > 235);
}

