#[test]
fn writes_uri_and_goto_links_with_quadrilateral_regions() {
    let mut document = OfdDocument::new();
    document.add_blank_page(30.0, 20.0).unwrap();
    document.add_blank_page(30.0, 20.0).unwrap();
    let quads = [[[3.0, 4.0], [6.0, 4.0], [7.0, 6.0], [4.0, 6.0]]];
    let before = document.to_bytes().unwrap();
    let invalid = [[[3.0, 4.0], [7.0, 6.0], [6.0, 4.0], [4.0, 6.0]]];
    assert!(document
        .add_uri_link_annotation_with_quads(
            0,
            "https://example.org",
            [2.0, 3.0, 10.0, 5.0],
            &invalid
        )
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    document
        .add_uri_link_annotation_with_quads(0, "https://example.org", [2.0, 3.0, 10.0, 5.0], &quads)
        .unwrap();
    let target_id = document.pages().unwrap()[1].id.clone();
    document
        .add_goto_link_annotation_with_quads(
            0,
            DestinationInfo {
                page_id: target_id,
                kind: "Fit".into(),
                left: None,
                top: None,
                right: None,
                bottom: None,
                zoom: None,
            },
            [2.0, 3.0, 10.0, 5.0],
            &quads,
        )
        .unwrap();
    let annotations = document.annotations().unwrap();
    assert_eq!(annotations.len(), 2);
    assert_eq!(
        annotations[0].actions[0].region.as_ref().unwrap().areas[0].start,
        [3.0, 4.0]
    );
    let pdf = lopdf::Document::load_mem(&document.to_pdf().unwrap()).unwrap();
    let page = pdf
        .get_dictionary(*pdf.get_pages().get(&1).unwrap())
        .unwrap();
    let links = page.get(b"Annots").unwrap().as_array().unwrap();
    assert_eq!(links.len(), 2);
    for link in links {
        assert_eq!(
            pdf.get_dictionary(link.as_reference().unwrap())
                .unwrap()
                .get(b"QuadPoints")
                .unwrap()
                .as_array()
                .unwrap()
                .len(),
            8
        );
    }
}

