    document.add_text_page("first body", 30.0, 20.0).unwrap();
    let mut document = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(document.append_document_body().unwrap(), 1);
    assert_eq!(document.insert_blank_page(1, 0, 30.0, 20.0).unwrap(), 1);
    assert_eq!(document.insert_blank_page(1, 0, 30.0, 20.0).unwrap(), 1);
    assert_eq!(
        document
            .insert_text_page(0, 0, "front", 30.0, 20.0)
            .unwrap(),
        0
    );
