#[test]
fn duplicates_page_at_position_with_annotations_and_fresh_ids() {
    let mut document = OfdDocument::new();
    document.add_text_page("A", 40.0, 30.0).unwrap();
    document.add_text_page("B", 40.0, 30.0).unwrap();
    document
        .add_text_watermark(1, "stamp", [1.0, 1.0, 10.0, 5.0], 4.0)
        .unwrap();
    assert_eq!(document.duplicate_page_at(1, 0).unwrap(), 0);
    assert_eq!(
        document.all_text().unwrap(),
        [vec!["B"], vec!["A"], vec!["B"]]
    );
    let pages = document.pages().unwrap();
    assert_ne!(pages[0].id, pages[2].id);
    assert_ne!(pages[0].path, pages[2].path);
    let annotations = document.annotations().unwrap();
    assert_eq!(annotations.len(), 2);
    assert_ne!(annotations[0].id, annotations[1].id);
    assert!(document.page_svg(0).unwrap().contains("stamp"));
    assert!(document.validate_references().unwrap().is_empty());

    let before = document.to_bytes().unwrap();
    assert!(document.duplicate_page_at(1, 4).is_err());
    assert!(document.duplicate_page_at(4, 0).is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    let reopened = OfdDocument::from_bytes(&before).unwrap();
    assert_eq!(reopened.all_text().unwrap(), document.all_text().unwrap());
}

