#[test]
fn new_document_mutations_preserve_unrelated_document_xml() {
    let mut document = OfdDocument::new();
    document.add_text_page("A", 20.0, 20.0).unwrap();
    let original = std::str::from_utf8(document.entry("Doc_0/Document.xml").unwrap().unwrap())
        .unwrap()
        .to_owned();
    let extended = original.replace(
        "</ofd:Document>",
        "<extra:Keep xmlns:extra=\"urn:test\" Value=\"preserve\"/></ofd:Document>",
    );
    document
        .set_entry("Doc_0/Document.xml", extended.into_bytes())
        .unwrap();
    document.add_text_page("B", 20.0, 20.0).unwrap();
    document.add_attachment("note.txt", b"keep").unwrap();
    let first_page_id = document.pages().unwrap()[0].id.clone();
    document
        .add_bookmark(
            0,
            "first",
            ofdrw::DestinationInfo {
                page_id: first_page_id,
                kind: "Fit".into(),
                left: None,
                top: None,
                right: None,
                bottom: None,
                zoom: None,
            },
        )
        .unwrap();
    document
        .add_path_page(
            "M 0 0 L 10 10",
            [0.0, 0.0, 10.0, 10.0],
            20.0,
            20.0,
            false,
            true,
        )
        .unwrap();
    let second_page_id = document.pages().unwrap()[1].id.clone();
    document
        .add_bookmark(
            0,
            "second",
            ofdrw::DestinationInfo {
                page_id: second_page_id,
                kind: "Fit".into(),
                left: None,
                top: None,
                right: None,
                bottom: None,
                zoom: None,
            },
        )
        .unwrap();
    let source = OfdDocument::open(fixture("发票示例.ofd")).unwrap();
    document
        .add_image_page(source.page_image_data(0, 0).unwrap(), "png", 20.0, 20.0)
        .unwrap();
    assert!(
        std::str::from_utf8(document.entry("Doc_0/Document.xml").unwrap().unwrap())
            .unwrap()
            .contains("<extra:Keep xmlns:extra=\"urn:test\" Value=\"preserve\"/>")
    );
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.pages().unwrap().len(), 4);
    assert_eq!(reopened.bookmarks().unwrap().len(), 2);
    assert_eq!(reopened.attachments().unwrap().len(), 1);
    assert!(reopened.validate_references().unwrap().is_empty());
}

#[test]
fn new_document_mutations_reject_broken_structure_without_partial_writes() {
    let cases = [
        ("<ofd:Pages></ofd:Pages>", ""),
        ("<ofd:MaxUnitID>1</ofd:MaxUnitID>", ""),
        ("<ofd:MaxUnitID>1</ofd:MaxUnitID>", "<ofd:MaxUnitID/>"),
    ];
    for (before, after) in cases {
        let mut document = OfdDocument::new();
        let original = std::str::from_utf8(document.entry("Doc_0/Document.xml").unwrap().unwrap())
            .unwrap()
            .to_owned();
        document
            .set_entry(
                "Doc_0/Document.xml",
                original.replace(before, after).into_bytes(),
            )
            .unwrap();
        let snapshot = document.to_bytes().unwrap();
        assert!(document.add_attachment("note.txt", b"note").is_err());
        assert_eq!(document.to_bytes().unwrap(), snapshot);
    }
}

