#[test]
fn removes_pages_without_losing_entries_or_later_append_order() {
    let mut document = OfdDocument::new();
    for text in ["A", "B", "C"] {
        document.add_text_page(text, 20.0, 20.0).unwrap();
    }
    let removed_path = document.pages().unwrap()[1].path.clone();
    let removed_data = document.entry(&removed_path).unwrap().unwrap().to_vec();
    document.remove_page(1).unwrap();
    document.add_text_page("D", 20.0, 20.0).unwrap();
    assert_eq!(
        document.all_text().unwrap(),
        vec![vec!["A"], vec!["C"], vec!["D"]]
    );
    assert_eq!(
        document.entry(&removed_path).unwrap().unwrap(),
        removed_data
    );
    assert!(document.validate_references().unwrap().is_empty());
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(
        reopened.all_text().unwrap(),
        vec![vec!["A"], vec!["C"], vec!["D"]]
    );
    assert!(matches!(
        document.remove_page(3),
        Err(OfdError::PageIndex { .. })
    ));

    let mut java = OfdDocument::open(fixture("keyword2.ofd")).unwrap();
    let original_issues = java.validate_references().unwrap();
    java.remove_page(0).unwrap();
    assert_eq!(java.pages().unwrap().len(), 1);
    assert!(java.validate_references().unwrap().len() <= original_issues.len());
}

