#[test]
fn remove_page_recognizes_numeric_page_id_aliases() {
    let mut document = OfdDocument::new();
    document.add_blank_page(30.0, 20.0).unwrap();
    let page_id = document.pages().unwrap()[0].id.clone();
    document
        .add_text_watermark(0, "mark", [1.0, 1.0, 8.0, 5.0], 4.0)
        .unwrap();
    let list_path = "Doc_0/Annots/Annotations.xml";
    let list = std::str::from_utf8(document.entry(list_path).unwrap().unwrap())
        .unwrap()
        .to_owned();
    document
        .set_entry(
            list_path,
            list.replace(
                &format!("PageID=\"{page_id}\""),
                &format!("PageID=\"0{page_id}\""),
            )
            .into_bytes(),
        )
        .unwrap();
    let before = document.to_bytes().unwrap();
    assert!(document.remove_page(0).is_err());
    assert_eq!(document.to_bytes().unwrap(), before);

    let mut navigation = OfdDocument::new();
    navigation.add_blank_page(30.0, 20.0).unwrap();
    let page_id = navigation.pages().unwrap()[0].id.clone();
    let root = "Doc_0/Document.xml";
    let xml = std::str::from_utf8(navigation.entry(root).unwrap().unwrap())
        .unwrap()
        .to_owned();
    navigation
        .set_entry(
            root,
            xml.replace(
                "</ofd:Document>",
                &format!("<ofd:Bookmarks><ofd:Bookmark Name=\"target\"><ofd:Dest Type=\"Fit\" PageID=\"0{page_id}\"/></ofd:Bookmark></ofd:Bookmarks></ofd:Document>"),
            )
            .into_bytes(),
        )
        .unwrap();
    let before = navigation.to_bytes().unwrap();
    assert!(navigation.remove_page(0).is_err());
    assert_eq!(navigation.to_bytes().unwrap(), before);
}

