#[test]
fn standalone_svg_prioritizes_used_font_before_unused_fonts_at_size_limit() {
    let unused = include_bytes!("fixtures/dejavu-sans.ttf");
    let used = include_bytes!("fixtures/dejavu-serif.ttf");
    let mut document = OfdDocument::new();
    for index in 0..11 {
        document
            .add_embedded_font(&format!("Unused {index}"), unused)
            .unwrap();
    }
    let font = document.add_embedded_font("Used", used).unwrap();
    document
        .add_text_page_with_font("visible", 60.0, 30.0, font)
        .unwrap();
    let svg = document.page_svg(0).unwrap();
    let parsed = roxmltree::Document::parse(&svg).unwrap();
    let style = parsed
        .descendants()
        .find(|node| node.tag_name().name() == "style")
        .unwrap()
        .text()
        .unwrap();
    let first_encoded = style
        .split("base64,")
        .nth(1)
        .unwrap()
        .split('"')
        .next()
        .unwrap();
    assert_eq!(STANDARD.decode(first_encoded).unwrap(), used);
    assert!(svg.contains("font-family=\"ofd-embedded-font-0\""));
    assert!(style.matches("@font-face").count() < 12);
}

#[test]
fn standalone_svg_prioritizes_fonts_used_by_templates_composites_and_annotations() {
    use ofdrw::AnnotationGraphic;

    let unused = include_bytes!("fixtures/dejavu-sans.ttf");
    let used = include_bytes!("fixtures/dejavu-serif.ttf");
    let mut document = OfdDocument::new();
    for index in 0..11 {
        document
            .add_embedded_font(&format!("Unused {index}"), unused)
            .unwrap();
    }
    let font = document.add_embedded_font("Used", used).unwrap();
    document
        .add_text_page_with_font("template", 60.0, 30.0, font)
        .unwrap();
    for _ in 0..3 {
        document.add_blank_page(60.0, 30.0).unwrap();
    }
    document
        .promote_page_to_template(0, &[1], "Background")
        .unwrap();
    document
        .add_composite_text_object(
            2,
            "composite",
            [2.0, 2.0, 30.0, 8.0],
            5.0,
            Some(&font.to_string()),
        )
        .unwrap();
    document
        .add_mixed_annotation(
            3,
            [2.0, 2.0, 30.0, 8.0],
            &[AnnotationGraphic::Text {
                text: "annotation".into(),
                boundary: [0.0, 0.0, 30.0, 8.0],
                size: 5.0,
                font_id: Some(font.to_string()),
                color: None,
                opacity: 255,
            }],
        )
        .unwrap();
    for page in [1, 2, 3] {
        let svg = document.page_svg(page).unwrap();
        let parsed = roxmltree::Document::parse(&svg).unwrap();
        let style = parsed
            .descendants()
            .find(|node| node.tag_name().name() == "style")
            .unwrap()
            .text()
            .unwrap();
        let first_encoded = style
            .split("base64,")
            .nth(1)
            .unwrap()
            .split('"')
            .next()
            .unwrap();
        assert_eq!(STANDARD.decode(first_encoded).unwrap(), used, "page {page}");
        assert!(svg.contains("font-family=\"ofd-embedded-font-0\""));
    }
}

#[test]
fn navigation_writers_and_pdf_export_resolve_numeric_page_id_aliases() {
    let mut document = OfdDocument::new();
    document.add_text_page("source", 40.0, 30.0).unwrap();
    document.add_blank_page(40.0, 30.0).unwrap();
    let pages = document.pages().unwrap();
    let alias = format!("0{}", pages[1].id);
    let destination = DestinationInfo {
        page_id: alias,
        kind: "Fit".into(),
        left: None,
        top: None,
        right: None,
        bottom: None,
        zoom: None,
    };
    let object_id = document.page_text_objects(0).unwrap()[0]
        .id
        .clone()
        .unwrap();
    document
        .add_bookmark(0, "alias", destination.clone())
        .unwrap();
    document
        .add_outline(0, "alias", None, Some(destination.clone()), true)
        .unwrap();
    document
        .add_document_action(0, "DO", DocumentActionTarget::Page(destination.clone()))
        .unwrap();
    document
        .add_page_action(0, DocumentActionTarget::Page(destination.clone()))
        .unwrap();
    document
        .add_page_object_goto_action(0, &object_id, destination.clone())
        .unwrap();
    document
        .add_goto_link_annotation(0, destination.clone(), [2.0, 2.0, 8.0, 8.0])
        .unwrap();
    assert!(document.validate_references().unwrap().is_empty());
    assert!(document.to_pdf().unwrap().starts_with(b"%PDF-"));

    let path = "Doc_0/Document.xml";
    let source = String::from_utf8(document.entry(path).unwrap().unwrap().to_vec()).unwrap();
    let changed = source.replacen(
        &format!("<ofd:Page ID=\"{}\"", pages[1].id),
        &format!("<ofd:Page ID=\"0{}\"", pages[0].id),
        1,
    );
    assert_ne!(source, changed);
    document.set_entry(path, changed.into_bytes()).unwrap();
    let ambiguous = DestinationInfo {
        page_id: pages[0].id.clone(),
        ..destination
    };
    let before = document.to_bytes().unwrap();
    assert!(document.add_bookmark(0, "bad", ambiguous.clone()).is_err());
    assert!(document
        .add_outline(0, "bad", None, Some(ambiguous.clone()), true)
        .is_err());
    assert!(document
        .add_document_action(0, "DO", DocumentActionTarget::Page(ambiguous.clone()))
        .is_err());
    assert!(document
        .add_page_action(0, DocumentActionTarget::Page(ambiguous.clone()))
        .is_err());
    assert!(document
        .add_page_object_goto_action(0, &object_id, ambiguous.clone())
        .is_err());
    assert!(document
        .add_goto_link_annotation(0, ambiguous, [2.0, 2.0, 8.0, 8.0])
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
}

#[test]
fn appends_document_bodies_with_independent_pages_and_resources() {
    let mut document = OfdDocument::new();
    document.add_text_page("first", 40.0, 30.0).unwrap();
    document
        .set_entry("Doc_1/reserved.bin", b"keep".to_vec())
        .unwrap();
    assert_eq!(document.append_document_body().unwrap(), 1);
    assert_eq!(
        document.document_info().unwrap()[1].root,
        "Doc_2/Document.xml"
    );
    document.append_text_page(1, "second", 50.0, 40.0).unwrap();
    document.append_blank_page(0, 20.0, 20.0).unwrap();
    assert_eq!(document.append_document_body().unwrap(), 2);
    document.append_blank_page(2, 30.0, 30.0).unwrap();

    let info = document.document_info().unwrap();
    assert_eq!(info.len(), 3);
    assert_eq!(info[2].root, "Doc_3/Document.xml");
    assert_eq!(
        info.iter()
            .map(|item| &item.doc_id)
            .collect::<std::collections::HashSet<_>>()
            .len(),
        3
    );
    let pages = document.pages().unwrap();
    assert_eq!(
        pages
            .iter()
            .map(|page| page.document_index)
            .collect::<Vec<_>>(),
        [0, 0, 1, 2]
    );
    assert_eq!(document.page_text(0).unwrap(), ["first"]);
    assert_eq!(document.page_text(2).unwrap(), ["second"]);
    assert_eq!(
        document.entry("Doc_1/reserved.bin").unwrap(),
        Some(b"keep".as_slice())
    );
    assert!(document.validate_references().unwrap().is_empty());

    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.document_info().unwrap(), info);
    assert_eq!(reopened.pages().unwrap(), pages);
    assert_eq!(reopened.page_text(2).unwrap(), ["second"]);
}

#[test]
fn moves_document_bodies_and_keeps_paths_and_annotations() {
    let mut document = OfdDocument::new();
    document.add_text_page("first", 40.0, 30.0).unwrap();
    document
        .add_text_watermark(0, "first mark", [1.0, 1.0, 10.0, 5.0], 4.0)
        .unwrap();
    assert_eq!(document.append_document_body().unwrap(), 1);
    document.append_text_page(1, "second", 40.0, 30.0).unwrap();
    assert_eq!(document.append_document_body().unwrap(), 2);
    document.append_text_page(2, "third", 40.0, 30.0).unwrap();
    let roots: Vec<_> = document
        .document_info()
        .unwrap()
        .into_iter()
        .map(|info| info.root)
        .collect();
    let original_page_paths: Vec<_> = document
        .pages()
        .unwrap()
        .into_iter()
        .map(|page| page.path)
        .collect();
    document.move_document_body(0, 2).unwrap();
    assert_eq!(
        document.all_text().unwrap(),
        vec![vec!["second"], vec!["third"], vec!["first"]]
    );
    assert_eq!(document.document_info().unwrap()[2].root, roots[0]);
    assert_eq!(document.pages().unwrap()[2].path, original_page_paths[0]);
    assert_eq!(document.annotations().unwrap()[0].document_index, 2);
    assert!(document.validate_references().unwrap().is_empty());
    let before = document.to_bytes().unwrap();
    assert!(document.move_document_body(0, 3).is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    document.move_document_body(2, 0).unwrap();
    assert_eq!(
        document.all_text().unwrap(),
        vec![vec!["first"], vec!["second"], vec!["third"]]
    );
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.all_text().unwrap(), document.all_text().unwrap());
    assert!(reopened.validate_references().unwrap().is_empty());
}

#[test]
fn removes_document_body_without_deleting_package_entries() {
    let mut document = OfdDocument::new();
    document.add_text_page("first", 40.0, 30.0).unwrap();
    assert_eq!(document.append_document_body().unwrap(), 1);
    document.append_text_page(1, "middle", 40.0, 30.0).unwrap();
    document
        .add_text_watermark(1, "middle mark", [1.0, 1.0, 12.0, 5.0], 4.0)
        .unwrap();
    assert_eq!(document.append_document_body().unwrap(), 2);
    document.append_text_page(2, "last", 40.0, 30.0).unwrap();
    let removed_root = document.document_info().unwrap()[1].root.clone();
    let removed_page = document.pages().unwrap()[1].path.clone();
    let removed_annotation = document.annotations().unwrap()[0].source_path.clone();
    let root_bytes = document.entry(&removed_root).unwrap().unwrap().to_vec();
    let page_bytes = document.entry(&removed_page).unwrap().unwrap().to_vec();
    let annotation_bytes = document
        .entry(&removed_annotation)
        .unwrap()
        .unwrap()
        .to_vec();
    document.remove_document_body(1).unwrap();
    assert_eq!(
        document.all_text().unwrap(),
        vec![vec!["first"], vec!["last"]]
    );
    assert!(document.annotations().unwrap().is_empty());
    assert_eq!(
        document.entry(&removed_root).unwrap(),
        Some(root_bytes.as_slice())
    );
    assert_eq!(
        document.entry(&removed_page).unwrap(),
        Some(page_bytes.as_slice())
    );
    assert_eq!(
        document.entry(&removed_annotation).unwrap(),
        Some(annotation_bytes.as_slice())
    );
    assert!(document.validate_references().unwrap().is_empty());
    let before = document.to_bytes().unwrap();
    assert!(document.remove_document_body(2).is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    document.remove_document_body(0).unwrap();
    assert_eq!(document.all_text().unwrap(), vec![vec!["last"]]);
    let before = document.to_bytes().unwrap();
    assert!(document.remove_document_body(0).is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    let reopened = OfdDocument::from_bytes(&before).unwrap();
    assert_eq!(reopened.all_text().unwrap(), vec![vec!["last"]]);
    assert!(reopened.validate_references().unwrap().is_empty());
}

#[test]
fn extracts_one_document_body_without_changing_source() {
    let mut source = OfdDocument::new();
    source.add_text_page("first", 40.0, 30.0).unwrap();
    assert_eq!(source.append_document_body().unwrap(), 1);
    source.append_text_page(1, "selected", 50.0, 35.0).unwrap();
    source
        .add_attachment_to_document(1, "selected.txt", b"payload")
        .unwrap();
    assert_eq!(source.append_document_body().unwrap(), 2);
    source.append_text_page(2, "last", 60.0, 40.0).unwrap();
    let original_roots = source.document_info().unwrap();
    let first_page_path = source.pages().unwrap()[0].path.clone();
    let before = source.to_bytes().unwrap();
    assert!(source.extract_document_body(3).is_err());
    assert_eq!(source.to_bytes().unwrap(), before);
    let mut extracted = source.extract_document_body(1).unwrap();
    assert_eq!(extracted.document_info().unwrap().len(), 1);
    assert_eq!(
        extracted.document_info().unwrap()[0].root,
        original_roots[1].root
    );
    assert_eq!(extracted.all_text().unwrap(), vec![vec!["selected"]]);
    assert_eq!(extracted.attachment_data(0).unwrap(), b"payload");
    assert!(extracted.entry(&first_page_path).unwrap().is_some());
    assert!(extracted.validate_references().unwrap().is_empty());
    extracted.append_text_page(0, "later", 50.0, 35.0).unwrap();
    assert_eq!(extracted.page_text(1).unwrap(), ["later"]);
    assert_eq!(source.to_bytes().unwrap(), before);
    let reopened = OfdDocument::from_bytes(&extracted.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.all_text().unwrap(), extracted.all_text().unwrap());
    assert!(reopened.validate_references().unwrap().is_empty());

    let signed = OfdDocument::open(fixture("SESV4SignDoc.ofd")).unwrap();
    assert_eq!(
        signed.extract_document_body(0).unwrap().to_bytes().unwrap(),
        signed.to_bytes().unwrap()
    );
}

#[test]
fn rejects_document_body_reordering_and_removal_in_signed_package() {
    let mut signed = OfdDocument::open(fixture("SESV4SignDoc.ofd")).unwrap();
    let root = "OFD.xml";
    let original = std::str::from_utf8(signed.entry(root).unwrap().unwrap())
        .unwrap()
        .to_owned();
    let extra = "<ofd:DocBody><ofd:DocInfo><ofd:DocID>extra-body</ofd:DocID></ofd:DocInfo><ofd:DocRoot>Doc_1/Document.xml</ofd:DocRoot></ofd:DocBody>";
    let second_root = signed
        .entry("Doc_0/Document.xml")
        .unwrap()
        .unwrap()
        .to_vec();
    signed.set_entry("Doc_1/Document.xml", second_root).unwrap();
    signed
        .set_entry(
            root,
            original
                .replace("</ofd:OFD>", &format!("{extra}</ofd:OFD>"))
                .into_bytes(),
        )
        .unwrap();
    assert_eq!(signed.document_info().unwrap().len(), 2);
    let before = signed.to_bytes().unwrap();
    assert!(signed.move_document_body(0, 1).is_err());
    assert_eq!(signed.to_bytes().unwrap(), before);
    assert!(signed.remove_document_body(1).is_err());
    assert_eq!(signed.to_bytes().unwrap(), before);
    assert!(signed.extract_document_body(0).is_err());
    assert_eq!(signed.to_bytes().unwrap(), before);
}

#[test]
fn imports_unsigned_document_bodies_with_colliding_source_paths() {
    let mut target = OfdDocument::new();
    target.add_text_page("target", 40.0, 30.0).unwrap();
    let mut source = OfdDocument::new();
    source.add_text_page("source one", 50.0, 35.0).unwrap();
    source
        .add_attachment("note.txt", b"source attachment")
        .unwrap();
    source
        .set_entry("Doc_0/cover.png", b"cover".to_vec())
        .unwrap();
    source
        .set_document_info_field(0, "Cover", "Doc_0/cover.png")
        .unwrap();
    assert_eq!(source.append_document_body().unwrap(), 1);
    source
        .append_text_page(1, "source two", 60.0, 40.0)
        .unwrap();
    let original_source_page = source.entry("Doc_0/Pages/Page_0/Content.xml").unwrap();
    let source_entries = source
        .entry_names()
        .filter(|path| *path != "OFD.xml" && !path.ends_with(".xml"))
        .map(|path| {
            (
                path.to_owned(),
                source.entry(path).unwrap().unwrap().to_vec(),
            )
        })
        .collect::<Vec<_>>();
    assert_eq!(target.append_document_bodies_from(&source).unwrap(), [1, 2]);
    assert_eq!(target.page_text(0).unwrap(), ["target"]);
    assert_eq!(target.page_text(1).unwrap(), ["source one"]);
    assert_eq!(target.page_text(2).unwrap(), ["source two"]);
    assert_eq!(target.document_info().unwrap().len(), 3);
    assert!(target.document_info().unwrap()[1]
        .root
        .starts_with("Imported_0/"));
    assert_eq!(
        target.document_info().unwrap()[1].cover.as_deref(),
        Some("Imported_0/Doc_0/cover.png")
    );
    assert_eq!(target.attachments().unwrap().len(), 1);
    for (path, bytes) in source_entries {
        assert_eq!(
            target.entry(&format!("Imported_0/{path}")).unwrap(),
            Some(bytes.as_slice())
        );
    }
    let imported_attachments = std::str::from_utf8(
        target
            .entry("Imported_0/Doc_0/Attachments.xml")
            .unwrap()
            .unwrap(),
    )
    .unwrap();
    assert!(imported_attachments.contains("/Imported_0/Doc_0/Res/Attachment_0"));
    assert_eq!(
        source.entry("Doc_0/Pages/Page_0/Content.xml").unwrap(),
        original_source_page
    );
    assert!(target.validate_references().unwrap().is_empty());
    let mut reopened = OfdDocument::from_bytes(&target.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.page_text(2).unwrap(), ["source two"]);
    assert_eq!(
        reopened.append_document_bodies_from(&source).unwrap(),
        [3, 4]
    );
    assert_eq!(reopened.page_text(4).unwrap(), ["source two"]);
    let infos = reopened.document_info().unwrap();
    assert_eq!(
        infos
            .iter()
            .map(|info| info.doc_id.as_str())
            .collect::<std::collections::HashSet<_>>()
            .len(),
        infos.len()
    );
}

#[test]
fn imports_only_selected_document_body_with_its_resources() {
    let mut source = OfdDocument::new();
    source.add_text_page("source first", 40.0, 30.0).unwrap();
    assert_eq!(source.append_document_body().unwrap(), 1);
    source
        .append_text_page(1, "source selected", 50.0, 35.0)
        .unwrap();
    source
        .add_attachment_to_document(1, "selected.txt", b"selected payload")
        .unwrap();
    let source_before = source.to_bytes().unwrap();
    let source_id = source.document_info().unwrap()[1].doc_id.clone();
    let mut target = OfdDocument::new();
    target.add_text_page("target", 40.0, 30.0).unwrap();
    let before = target.to_bytes().unwrap();
    assert!(target.append_document_body_from(&source, 2).is_err());
    assert_eq!(target.to_bytes().unwrap(), before);
    assert_eq!(target.append_document_body_from(&source, 1).unwrap(), 1);
    assert_eq!(target.document_info().unwrap().len(), 2);
    assert_ne!(target.document_info().unwrap()[1].doc_id, source_id);
    assert_eq!(
        target.all_text().unwrap(),
        vec![vec!["target"], vec!["source selected"]]
    );
    assert_eq!(target.attachments().unwrap().len(), 1);
    assert_eq!(target.attachment_data(0).unwrap(), b"selected payload");
    assert!(target.validate_references().unwrap().is_empty());
    assert_eq!(source.to_bytes().unwrap(), source_before);
    let reopened = OfdDocument::from_bytes(&target.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.all_text().unwrap(), target.all_text().unwrap());
    assert!(reopened.validate_references().unwrap().is_empty());
}

