#[test]
fn import_document_bodies_rebases_absolute_paths_and_rejects_signatures_atomically() {
    let mut target = OfdDocument::new();
    let mut source = OfdDocument::new();
    let original = String::from_utf8(
        source
            .entry("Doc_0/Document.xml")
            .unwrap()
            .unwrap()
            .to_vec(),
    )
    .unwrap();
    source
        .set_entry(
            "Doc_0/Document.xml",
            original
                .replace(">PublicRes.xml<", ">/Doc_0/PublicRes.xml<")
                .into_bytes(),
        )
        .unwrap();
    let resource = String::from_utf8(
        source
            .entry("Doc_0/PublicRes.xml")
            .unwrap()
            .unwrap()
            .to_vec(),
    )
    .unwrap();
    source
        .set_entry(
            "Doc_0/PublicRes.xml",
            resource
                .replace("BaseLoc=\"Res\"", "BaseLoc=\"/\"")
                .into_bytes(),
        )
        .unwrap();
    assert_eq!(target.append_document_bodies_from(&source).unwrap(), [1]);
    let imported_document = std::str::from_utf8(
        target
            .entry("Imported_0/Doc_0/Document.xml")
            .unwrap()
            .unwrap(),
    )
    .unwrap();
    assert!(imported_document.contains(">/Imported_0/Doc_0/PublicRes.xml<"));
    let imported_resource = std::str::from_utf8(
        target
            .entry("Imported_0/Doc_0/PublicRes.xml")
            .unwrap()
            .unwrap(),
    )
    .unwrap();
    assert!(imported_resource.contains("BaseLoc=\"/Imported_0/\""));
    assert!(target.validate_references().unwrap().is_empty());
    let before = target.to_bytes().unwrap();

    let signed = OfdDocument::open(fixture("SESV4SignDoc.ofd")).unwrap();
    assert!(target.append_document_bodies_from(&signed).is_err());
    assert_eq!(target.to_bytes().unwrap(), before);

    let mut archived = OfdDocument::new();
    archived
        .set_entry("Versions/extra.bin", b"snapshot".to_vec())
        .unwrap();
    assert!(target.append_document_bodies_from(&archived).is_err());
    assert_eq!(target.to_bytes().unwrap(), before);

    let mut unexpected = OfdDocument::new();
    let ofd_xml =
        String::from_utf8(unexpected.entry("OFD.xml").unwrap().unwrap().to_vec()).unwrap();
    unexpected
        .set_entry(
            "OFD.xml",
            ofd_xml
                .replace(
                    "</ofd:DocBody>",
                    "<ofd:Extra>/path</ofd:Extra></ofd:DocBody>",
                )
                .into_bytes(),
        )
        .unwrap();
    assert!(target.append_document_bodies_from(&unexpected).is_err());
    assert_eq!(target.to_bytes().unwrap(), before);

    let mut unknown_path = OfdDocument::new();
    unknown_path
        .set_entry("Doc_0/Unknown.bin", b"payload".to_vec())
        .unwrap();
    unknown_path
        .set_entry(
            "Doc_0/Unknown.xml",
            b"<Root><Value>/Doc_0/Unknown.bin</Value></Root>".to_vec(),
        )
        .unwrap();
    assert!(target.append_document_bodies_from(&unknown_path).is_err());
    assert_eq!(target.to_bytes().unwrap(), before);

    let mut literal = OfdDocument::new();
    let metadata = b"<Root><Value>/a literal value</Value></Root>";
    literal
        .set_entry("Doc_0/Unknown.xml", metadata.to_vec())
        .unwrap();
    assert_eq!(target.append_document_bodies_from(&literal).unwrap(), [2]);
    assert_eq!(
        target.entry("Imported_1/Doc_0/Unknown.xml").unwrap(),
        Some(metadata.as_slice())
    );

    let mut unknown_attribute = OfdDocument::new();
    unknown_attribute
        .set_entry("Doc_0/Unknown.bin", b"payload".to_vec())
        .unwrap();
    unknown_attribute
        .set_entry(
            "Doc_0/Unknown.xml",
            b"<Root Ref=\"/Doc_0/Unknown.bin\"/>".to_vec(),
        )
        .unwrap();
    let before = target.to_bytes().unwrap();
    assert!(target
        .append_document_bodies_from(&unknown_attribute)
        .is_err());
    assert_eq!(target.to_bytes().unwrap(), before);

    let mut literal_attribute = OfdDocument::new();
    let metadata = b"<Root Note=\"/a literal value\"/>";
    literal_attribute
        .set_entry("Doc_0/Unknown.xml", metadata.to_vec())
        .unwrap();
    assert_eq!(
        target
            .append_document_bodies_from(&literal_attribute)
            .unwrap(),
        [3]
    );
    assert_eq!(
        target.entry("Imported_2/Doc_0/Unknown.xml").unwrap(),
        Some(metadata.as_slice())
    );
}

