#[test]
fn duplicates_new_and_existing_pages_with_fresh_ids() {
    let mut created = OfdDocument::new();
    created.add_text_page("copied", 80.0, 50.0).unwrap();
    created
        .add_path_object(
            0,
            "M 0 0 L 10 10",
            [20.0, 20.0, 10.0, 10.0],
            PathStyle::default(),
        )
        .unwrap();
    let local_space = ColorSpaceSpec {
        color_type: "RGB".into(),
        bits_per_component: 8,
        profile: None,
        palette: Vec::new(),
    };
    let local_space_id = created.add_page_color_space(0, &local_space).unwrap();
    let original = created.pages().unwrap()[0].clone();
    let original_bytes = created.entry(&original.path).unwrap().unwrap().to_vec();
    assert_eq!(created.duplicate_page(0).unwrap(), 1);
    let pages = created.pages().unwrap();
    assert_eq!(pages.len(), 2);
    assert_ne!(pages[0].id, pages[1].id);
    assert_ne!(pages[0].path, pages[1].path);
    assert_eq!(
        PathBuf::from(&pages[0].path).parent(),
        PathBuf::from(&pages[1].path).parent()
    );
    assert_eq!(created.page_text(1).unwrap(), ["copied"]);
    assert_eq!(created.page_paths(1).unwrap().len(), 1);
    assert_eq!(created.page_color_spaces(1).unwrap()[0].id, local_space_id);
    assert_ne!(
        created.page_text_objects(0).unwrap()[0].id,
        created.page_text_objects(1).unwrap()[0].id
    );
    assert_eq!(
        created.entry(&original.path).unwrap(),
        Some(original_bytes.as_slice())
    );
    assert!(created.validate_references().unwrap().is_empty());
    created.add_text_page("later", 80.0, 50.0).unwrap();
    assert_eq!(created.page_text(2).unwrap(), ["later"]);
    let reopened = OfdDocument::from_bytes(&created.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.page_text(1).unwrap(), ["copied"]);

    let mut existing = OfdDocument::open(fixture("helloworld.ofd")).unwrap();
    let before = existing.page_text(0).unwrap();
    assert_eq!(existing.duplicate_page(0).unwrap(), 1);
    assert_eq!(existing.page_text(1).unwrap(), before);
    assert!(existing.validate_references().unwrap().is_empty());
    let reopened = OfdDocument::from_bytes(&existing.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.page_text(1).unwrap(), before);

    let mut multi = OfdDocument::new();
    multi.add_text_page("first body", 80.0, 50.0).unwrap();
    assert_eq!(multi.append_document_body().unwrap(), 1);
    multi
        .append_text_page(1, "second body", 80.0, 50.0)
        .unwrap();
    assert_eq!(multi.duplicate_page(0).unwrap(), 1);
    assert_eq!(multi.page_text(1).unwrap(), ["first body"]);
    assert_eq!(multi.page_text(2).unwrap(), ["second body"]);
    assert!(multi.validate_references().unwrap().is_empty());
}

#[test]
fn duplicate_page_copies_annotations_and_rejects_signed_source() {
    let mut annotated = OfdDocument::new();
    annotated.add_text_page("annotated", 80.0, 50.0).unwrap();
    annotated
        .add_text_watermark(0, "mark", [1.0, 1.0, 10.0, 5.0], 4.0)
        .unwrap();
    assert_eq!(annotated.duplicate_page(0).unwrap(), 1);
    let annotations = annotated.annotations().unwrap();
    assert_eq!(annotations.len(), 2);
    assert_ne!(annotations[0].id, annotations[1].id);
    assert_ne!(annotations[0].source_path, annotations[1].source_path);
    assert_eq!(annotations[0].text, annotations[1].text);
    assert_eq!(annotations[1].page_id, annotated.pages().unwrap()[1].id);
    assert!(annotated.page_svg(1).unwrap().contains("mark"));
    assert!(annotated.validate_references().unwrap().is_empty());
    let reopened = OfdDocument::from_bytes(&annotated.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.annotations().unwrap().len(), 2);

    let mut annotated = OfdDocument::new();
    annotated.add_text_page("annotated", 80.0, 50.0).unwrap();
    annotated
        .add_text_watermark(0, "mark", [1.0, 1.0, 10.0, 5.0], 4.0)
        .unwrap();
    let page_id = annotated.pages().unwrap()[0].id.clone();
    let list_path = "Doc_0/Annots/Annotations.xml";
    let list = String::from_utf8(annotated.entry(list_path).unwrap().unwrap().to_vec()).unwrap();
    annotated
        .set_entry(
            list_path,
            list.replace(
                &format!("PageID=\"{page_id}\""),
                &format!("PageID=\"0{page_id}\""),
            )
            .into_bytes(),
        )
        .unwrap();
    assert_eq!(annotated.duplicate_page(0).unwrap(), 1);
    assert_eq!(annotated.annotations().unwrap().len(), 2);
    assert!(annotated.validate_references().unwrap().is_empty());

    let mut signed = OfdDocument::open(fixture("SESV4SignDoc.ofd")).unwrap();
    let before = signed.to_bytes().unwrap();
    assert!(signed.duplicate_page(0).is_err());
    assert_eq!(signed.to_bytes().unwrap(), before);
}

#[test]
fn validates_navigation_annotation_and_stamp_page_targets() {
    let mut navigation = OfdDocument::new();
    navigation.add_text_page("page", 20.0, 20.0).unwrap();
    let path = "Doc_0/Document.xml";
    let original = std::str::from_utf8(navigation.entry(path).unwrap().unwrap())
        .unwrap()
        .to_owned();
    let markup = "<ofd:Bookmarks><ofd:Bookmark Name=\"valid\"><ofd:Dest Type=\"Fit\" PageID=\"2\"/></ofd:Bookmark><ofd:Bookmark Name=\"broken\"><ofd:Dest Type=\"Fit\" PageID=\"999\"/></ofd:Bookmark></ofd:Bookmarks><ofd:Outlines><ofd:OutlineElem Title=\"Missing\"><ofd:Actions><ofd:Goto><ofd:Bookmark Name=\"absent\"/></ofd:Goto></ofd:Actions></ofd:OutlineElem></ofd:Outlines>";
    navigation
        .set_entry(
            path,
            original
                .replace("</ofd:Document>", &format!("{markup}</ofd:Document>"))
                .into_bytes(),
        )
        .unwrap();
    let codes: Vec<_> = navigation
        .validate_references()
        .unwrap()
        .into_iter()
        .map(|issue| issue.code)
        .collect();
    assert!(codes.contains(&"navigation_page_reference".into()));
    assert!(codes.contains(&"bookmark_reference".into()));

    let mut annotated = OfdDocument::new();
    annotated.add_text_page("page", 20.0, 20.0).unwrap();
    annotated
        .add_text_watermark(0, "mark", [1.0, 1.0, 10.0, 5.0], 4.0)
        .unwrap();
    let original = std::str::from_utf8(annotated.entry(path).unwrap().unwrap())
        .unwrap()
        .to_owned();
    let page_id = annotated.pages().unwrap()[0].id.clone();
    let page_markup = format!("<ofd:Page ID=\"{page_id}\" BaseLoc=\"Pages/Page_0/Content.xml\"/>");
    assert!(original.contains(&page_markup));
    annotated
        .set_entry(path, original.replace(&page_markup, "").into_bytes())
        .unwrap();
    assert!(annotated
        .validate_references()
        .unwrap()
        .iter()
        .any(|issue| issue.code == "annotation_page_reference"));

    let mut signed = OfdDocument::open(fixture("SESV4SignDoc.ofd")).unwrap();
    let signature = signed.signatures().unwrap().remove(0);
    let stamp = &signature.stamps[0];
    let original = std::str::from_utf8(signed.entry(&signature.path).unwrap().unwrap())
        .unwrap()
        .to_owned();
    let before = format!("PageRef=\"{}\"", stamp.page_ref);
    assert!(original.contains(&before));
    signed
        .set_entry(
            &signature.path,
            original.replace(&before, "PageRef=\"999999\"").into_bytes(),
        )
        .unwrap();
    assert!(signed
        .validate_references()
        .unwrap()
        .iter()
        .any(|issue| issue.code == "signature_page_reference"));
}

#[test]
fn validates_navigation_targets_in_page_template_and_annotation_xml() {
    let mut page = OfdDocument::new();
    page.add_text_page("source", 30.0, 20.0).unwrap();
    page.add_blank_page(30.0, 20.0).unwrap();
    let target = page.pages().unwrap()[1].id.clone();
    let destination = DestinationInfo {
        page_id: target.clone(),
        kind: "Fit".into(),
        left: None,
        top: None,
        right: None,
        bottom: None,
        zoom: None,
    };
    let object_id = page.page_text_objects(0).unwrap()[0].id.clone().unwrap();
    page.add_page_object_goto_action(0, &object_id, destination.clone())
        .unwrap();
    assert!(page.validate_references().unwrap().is_empty());

    let check_broken = |mut document: OfdDocument, path: &str| {
        let original = std::str::from_utf8(document.entry(path).unwrap().unwrap())
            .unwrap()
            .to_owned();
        let needle = format!("<ofd:Dest Type=\"Fit\" PageID=\"{target}\"");
        assert!(original.contains(&needle), "{path}");
        let aliased = original.replace(
            &needle,
            &format!("<ofd:Dest Type=\"Fit\" PageID=\"0{target}\""),
        );
        document.set_entry(path, aliased.into_bytes()).unwrap();
        assert!(document.validate_references().unwrap().is_empty());
        let broken = original.replace(&needle, "<ofd:Dest Type=\"Fit\" PageID=\"999\"");
        document.set_entry(path, broken.into_bytes()).unwrap();
        let issues = document.validate_references().unwrap();
        assert!(
            issues.iter().any(|issue| {
                issue.path == path
                    && issue.code == "navigation_page_reference"
                    && issue.message.contains("999")
            }),
            "{path}: {issues:?}"
        );
    };

    let page_path = page.pages().unwrap()[0].path.clone();
    check_broken(page.clone(), &page_path);

    let mut template = page.clone();
    template
        .promote_page_to_template(0, &[], "Background")
        .unwrap();
    assert!(template.validate_references().unwrap().is_empty());
    let template_path = template
        .page_sources(0)
        .unwrap()
        .into_iter()
        .find(|source| source.template_id.is_some())
        .unwrap()
        .path;
    check_broken(template, &template_path);

    let mut annotation = page;
    annotation
        .add_goto_link_annotation(0, destination, [1.0, 1.0, 8.0, 5.0])
        .unwrap();
    assert!(annotation.validate_references().unwrap().is_empty());
    let annotation_path = annotation.annotations().unwrap()[0].source_path.clone();
    check_broken(annotation, &annotation_path);
}

#[test]
fn checks_ses_description_hash_and_detects_changes() {
    let mut document = OfdDocument::open(fixture("SESV4SignDoc.ofd")).unwrap();
    assert!(document.check_ses_signature_value(0).unwrap());
    let mut forged = document.clone();
    let forged_path = forged.signatures().unwrap()[0].signed_value_path.clone();
    let mut forged_value = forged.signed_value_data(0).unwrap().to_vec();
    *forged_value.last_mut().unwrap() ^= 1;
    forged.set_entry(&forged_path, forged_value).unwrap();
    assert!(!forged.check_ses_signature_value(0).unwrap());
    let check = document.check_signature_description_hash(0).unwrap();
    assert!(check.valid, "{check:?}");
    assert_eq!(check.expected, check.actual);
    let original = document.entry(&check.path).unwrap().unwrap().to_vec();
    let changed = String::from_utf8(original)
        .unwrap()
        .replace("ProviderName=\"ofdrw-sign\"", "ProviderName=\"tampered\"");
    document
        .set_entry(&check.path, changed.into_bytes())
        .unwrap();
    let changed = document.check_signature_description_hash(0).unwrap();
    assert!(!changed.valid);
    assert_eq!(changed.expected, check.expected);
    assert_ne!(changed.actual, check.actual);
    assert!(document.check_signature_description_hash(1).is_err());
    let value_path = document.signatures().unwrap()[0].signed_value_path.clone();
    document
        .set_entry(&value_path, b"not DER".to_vec())
        .unwrap();
    assert!(document.check_signature_description_hash(0).is_err());

    let digital = OfdDocument::open(
        PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../../ofdrw-sign/src/test/resources/DigitalSign.ofd"),
    )
    .unwrap();
    assert!(matches!(
        digital.check_signature_description_hash(0),
        Err(OfdError::Invalid(message)) if message.contains("raw digital signatures")
    ));
    assert!(digital.check_ses_signature_value(0).is_err());
}

#[test]
fn detects_detached_ses_seal_mismatch_in_signature_reports() {
    let mut document = OfdDocument::open(fixture("SESV4SignDoc.ofd")).unwrap();
    assert_eq!(document.check_signature_seal_match(0).unwrap(), Some(true));
    let path = document.signatures().unwrap()[0].seal_path.clone().unwrap();
    let mut changed = document.seal_data(0).unwrap().to_vec();
    changed[12] ^= 1;
    document.set_entry(&path, changed).unwrap();
    assert_eq!(document.check_signature_seal_match(0).unwrap(), Some(false));
    let report = document
        .verify_signature_with_direct_trust_anchor(
            0,
            &[],
            include_bytes!("fixtures/root-cert.der"),
            1_600_000_000,
            "1234567812345678",
        )
        .unwrap();
    assert_eq!(report.seal_match, Some(false));
    assert_eq!(report.seal_signature_valid, Some(true));
    assert!(!report.all_valid);
    assert!(document.check_signature_seal_match(1).is_err());

    let digital = OfdDocument::open(
        PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../../ofdrw-sign/src/test/resources/DigitalSign.ofd"),
    )
    .unwrap();
    assert_eq!(digital.check_signature_seal_match(0).unwrap(), None);
}

#[test]
fn verifies_embedded_ses_seal_signature_and_detects_modified_seal_info() {
    let document = OfdDocument::open(fixture("SESV4SignDoc.ofd")).unwrap();
    assert!(document.check_ses_seal_signature(0).unwrap());
    assert!(document.check_ses_seal_signer_authorization(0).unwrap());
    assert!(!document.check_ses_seal_validity(0, 0).unwrap());
    assert!(document.check_ses_seal_validity(0, 1_600_000_000).unwrap());
    assert!(!document.check_ses_seal_validity(0, 1_800_000_000).unwrap());
    assert!(!document.check_ses_seal_certificate_validity(0, 0).unwrap());
    assert!(!document
        .check_ses_seal_certificate_validity(0, u64::MAX)
        .unwrap());
    assert!(document
        .check_ses_seal_certificate_validity(0, 1_600_000_000)
        .unwrap());
    assert!(!document
        .check_ses_seal_signature_with_distid(0, "different-id")
        .unwrap());
    let seal = document.seal_data(0).unwrap();
    let path = document.signatures().unwrap()[0].signed_value_path.clone();
    let mut v5 = document.clone();
    v5.set_entry(
        &path,
        include_bytes!("../../../../ofdrw-gm/src/test/resources/SignedValueV5.dat").to_vec(),
    )
    .unwrap();
    assert!(v5.check_ses_seal_signature(0).unwrap());
    assert!(v5.check_ses_seal_signer_authorization(0).unwrap());
    assert!(v5
        .check_ses_seal_certificate_validity(0, 1_600_000_000)
        .unwrap());
    let expired_report = document
        .verify_signature_with_direct_trust_anchor(
            0,
            &[],
            include_bytes!("fixtures/root-cert.der"),
            0,
            "1234567812345678",
        )
        .unwrap();
    assert_eq!(expired_report.seal_certificate_validity_valid, Some(false));
    assert!(!expired_report.all_valid);
    let mut changed = document.signed_value_data(0).unwrap().to_vec();
    let start = changed
        .windows(seal.len())
        .position(|slice| slice == seal)
        .unwrap();
    changed[start + 5_000] ^= 1;
    let mut tampered = document.clone();
    tampered.set_entry(&path, changed).unwrap();
    assert!(!tampered.check_ses_seal_signature(0).unwrap());
    let report = tampered
        .verify_signature_with_direct_trust_anchor(
            0,
            &[],
            include_bytes!("fixtures/root-cert.der"),
            1_600_000_000,
            "1234567812345678",
        )
        .unwrap();
    assert_eq!(report.seal_signature_valid, Some(false));
    assert_eq!(report.seal_certificate_validity_valid, Some(true));
    assert_eq!(report.seal_signer_authorized, Some(true));
    assert_eq!(report.seal_validity_valid, Some(true));
    assert!(!report.all_valid);
    assert!(document.check_ses_seal_signature(1).is_err());

    let digital = OfdDocument::open(
        PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../../ofdrw-sign/src/test/resources/DigitalSign.ofd"),
    )
    .unwrap();
    assert!(digital.check_ses_seal_signature(0).is_err());
    assert!(digital
        .check_ses_seal_certificate_validity(0, 1_600_000_000)
        .is_err());
}

#[test]
fn checks_embedded_seal_issuer_against_ordered_sm2_chain() {
    use base64::{engine::general_purpose::STANDARD, Engine as _};
    use sm2::dsa::{signature::Signer, Signature as Sm2Signature, SigningKey};
    use sm3::{Digest, Sm3};

    fn tlv(bytes: &[u8]) -> (&[u8], &[u8], &[u8]) {
        let mut header_len = 2;
        let content_len = if bytes[1] & 0x80 == 0 {
            usize::from(bytes[1])
        } else {
            let count = usize::from(bytes[1] & 0x7f);
            header_len += count;
            bytes[2..header_len]
                .iter()
                .fold(0_usize, |length, byte| length * 256 + usize::from(*byte))
        };
        let end = header_len + content_len;
        (&bytes[..end], &bytes[header_len..end], &bytes[end..])
    }
    fn encode(tag: u8, content: &[u8]) -> Vec<u8> {
        let mut result = vec![tag];
        if content.len() < 128 {
            result.push(content.len() as u8);
        } else {
            let bytes = content.len().to_be_bytes();
            let first = bytes.iter().position(|byte| *byte != 0).unwrap();
            result.push(0x80 | (bytes.len() - first) as u8);
            result.extend_from_slice(&bytes[first..]);
        }
        result.extend_from_slice(content);
        result
    }

    let mut document = OfdDocument::open(fixture("SESV4SignDoc.ofd")).unwrap();
    let anchor = include_bytes!("fixtures/root-cert.der");
    assert!(!document
        .check_ses_seal_issuer_ordered_sm2_chain(0, &[], anchor, 1_600_000_000, "")
        .unwrap());

    let signed_path = document.signatures().unwrap()[0].signed_value_path.clone();
    let signed_value = document.signed_value_data(0).unwrap().to_vec();
    let (_, outer, _) = tlv(&signed_value);
    let (_, tbs, outer_tail) = tlv(outer);
    let (version, _, rest) = tlv(tbs);
    let (_, seal_tlv_content, tbs_tail) = tlv(rest);
    let (info, _, rest) = tlv(seal_tlv_content);
    let (_, _, seal_tail) = tlv(rest);
    let leaf = include_bytes!("fixtures/trust-leaf-cert.der");
    let mut seal_content = info.to_vec();
    seal_content.extend(encode(0x04, leaf));
    seal_content.extend_from_slice(seal_tail);
    let mut tbs_content = version.to_vec();
    tbs_content.extend(encode(0x30, &seal_content));
    tbs_content.extend_from_slice(tbs_tail);
    let mut signed_content = encode(0x30, &tbs_content);
    signed_content.extend_from_slice(outer_tail);
    document
        .set_entry(&signed_path, encode(0x30, &signed_content))
        .unwrap();

    let trusted_root = include_bytes!("fixtures/trust-root-cert.der");
    assert!(document
        .check_ses_seal_issuer_ordered_sm2_chain(0, &[], trusted_root, 1_893_456_000, "")
        .unwrap());
    assert!(!document
        .check_ses_seal_issuer_ordered_sm2_chain(0, &[], trusted_root, 1_893_456_000, "wrong")
        .unwrap());
    assert!(!document
        .check_ses_seal_issuer_ordered_sm2_chain(0, &[], trusted_root, 1_600_000_000, "")
        .unwrap());
    assert!(!document
        .check_ses_seal_issuer_ordered_sm2_chain(0, &[], anchor, 1_893_456_000, "")
        .unwrap());
    assert!(document
        .check_ses_seal_issuer_ordered_sm2_chain(0, &[b"bad"], trusted_root, 1_893_456_000, "")
        .is_err());
    assert!(document
        .check_ses_seal_issuer_ordered_sm2_chain(
            0,
            &[leaf.as_slice(); 9],
            trusted_root,
            1_893_456_000,
            ""
        )
        .is_err());
    assert!(!document.check_ses_seal_signature(0).unwrap());
    assert!(document.check_ses_seal_signer_authorization(0).unwrap());
    let report = document
        .verify_signature_with_ordered_sm2_chains(
            0,
            &[],
            &[],
            anchor,
            &[],
            trusted_root,
            1_893_456_000,
            "",
            "",
        )
        .unwrap();
    assert_eq!(report.seal_issuer_chain_valid, Some(true));
    assert_eq!(report.signature.seal_signature_valid, Some(false));
    assert_eq!(report.signature.seal_signer_authorized, Some(true));
    assert!(!report.all_valid);

    let key = SigningKey::from_slice(
        "1234567812345678",
        include_bytes!("fixtures/trust-leaf-private-key.bin"),
    )
    .unwrap();
    let (_, info_content, _) = tlv(info);
    let (header, _, rest) = tlv(info_content);
    let (seal_id, _, rest) = tlv(rest);
    let (_, property_content, info_tail) = tlv(rest);
    let (seal_type, _, rest) = tlv(property_content);
    let (seal_name, _, rest) = tlv(rest);
    let (cert_type, _, rest) = tlv(rest);
    let (_, _, dates) = tlv(rest);
    let (created, _, dates) = tlv(dates);
    let (valid_from, _, _) = tlv(dates);
    let mut property = [seal_type, seal_name, cert_type].concat();
    property.extend(encode(0x30, &encode(0x04, leaf)));
    property.extend_from_slice(created);
    property.extend_from_slice(valid_from);
    property.extend(encode(0x18, b"20350101000000Z"));
    let mut info_content = [header, seal_id].concat();
    info_content.extend(encode(0x30, &property));
    info_content.extend_from_slice(info_tail);
    let new_info = encode(0x30, &info_content);
    let seal_signature: Sm2Signature = key.try_sign(&new_info).unwrap();
    let (seal_algorithm, _, _) = tlv(seal_tail);
    let mut new_seal_content = new_info;
    new_seal_content.extend(encode(0x04, leaf));
    new_seal_content.extend_from_slice(seal_algorithm);
    let mut seal_signature_bits = vec![0];
    seal_signature_bits.extend_from_slice(seal_signature.to_der().as_bytes());
    new_seal_content.extend(encode(0x03, &seal_signature_bits));
    let new_seal = encode(0x30, &new_seal_content);

    let mut valid = document.clone();
    let signature = valid.signatures().unwrap().remove(0);
    let seal_path = signature.seal_path.unwrap();
    let old_digest = signature
        .references
        .iter()
        .find(|reference| reference.path == seal_path)
        .unwrap()
        .check_value
        .clone();
    valid.set_entry(&seal_path, new_seal.clone()).unwrap();
    let description = std::str::from_utf8(valid.entry(&signature.path).unwrap().unwrap())
        .unwrap()
        .replace(&old_digest, &STANDARD.encode(Sm3::digest(&new_seal)));
    valid
        .set_entry(&signature.path, description.as_bytes().to_vec())
        .unwrap();
    let (time, _, hash_and_rest) = tlv(tbs_tail);
    let (_, _, tbs_end) = tlv(hash_and_rest);
    let mut new_tbs_content = version.to_vec();
    new_tbs_content.extend_from_slice(&new_seal);
    new_tbs_content.extend_from_slice(time);
    let mut description_hash_bits = vec![0];
    description_hash_bits.extend_from_slice(&Sm3::digest(description.as_bytes()));
    new_tbs_content.extend(encode(0x03, &description_hash_bits));
    new_tbs_content.extend_from_slice(tbs_end);
    let new_tbs = encode(0x30, &new_tbs_content);
    let (_, _, after_signer_certificate) = tlv(outer_tail);
    let (signer_algorithm, _, _) = tlv(after_signer_certificate);
    let signer_signature: Sm2Signature = key.try_sign(&new_tbs).unwrap();
    let mut signer_signature_bits = vec![0];
    signer_signature_bits.extend_from_slice(signer_signature.to_der().as_bytes());
    let mut new_signed_content = new_tbs;
    new_signed_content.extend(encode(0x04, leaf));
    new_signed_content.extend_from_slice(signer_algorithm);
    new_signed_content.extend(encode(0x03, &signer_signature_bits));
    valid
        .set_entry(&signed_path, encode(0x30, &new_signed_content))
        .unwrap();
    let full_report = valid
        .verify_signature_with_ordered_sm2_chains(
            0,
            &[],
            &[],
            trusted_root,
            &[],
            trusted_root,
            1_893_456_000,
            "",
            "",
        )
        .unwrap();
    assert!(full_report.all_valid, "{full_report:?}");
    assert_eq!(full_report.seal_issuer_chain_valid, Some(true));
    let mut unauthorized = valid.clone();
    let valid_signed = valid.signed_value_data(0).unwrap();
    let (_, valid_outer, _) = tlv(valid_signed);
    let (valid_tbs, _, signer_tail) = tlv(valid_outer);
    let (_, _, signature_tail) = tlv(signer_tail);
    let (original_signer, _, _) = tlv(outer_tail);
    let mut unauthorized_outer = valid_tbs.to_vec();
    unauthorized_outer.extend_from_slice(original_signer);
    unauthorized_outer.extend_from_slice(signature_tail);
    unauthorized
        .set_entry(&signed_path, encode(0x30, &unauthorized_outer))
        .unwrap();
    assert!(!unauthorized.check_ses_seal_signer_authorization(0).unwrap());
    let unauthorized_report = unauthorized
        .verify_signature_with_ordered_sm2_chains(
            0,
            &[],
            &[],
            anchor,
            &[],
            trusted_root,
            1_893_456_000,
            "",
            "",
        )
        .unwrap();
    assert_eq!(
        unauthorized_report.signature.seal_signer_authorized,
        Some(false)
    );
    assert!(!unauthorized_report.all_valid);

    let digital = OfdDocument::open(
        PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../../ofdrw-sign/src/test/resources/DigitalSign.ofd"),
    )
    .unwrap();
    assert!(digital
        .check_ses_seal_issuer_ordered_sm2_chain(0, &[], trusted_root, 1_893_456_000, "")
        .is_err());
}

#[test]
fn creates_ses_v4_and_v5_signatures_and_appends_after_existing_signatures() {
    let key = include_bytes!("fixtures/user-private-key.bin");
    let signer = include_bytes!("fixtures/user-cert.der");
    for (version, seal) in [
        (
            4,
            include_bytes!("../../../../ofdrw-gm/src/test/resources/UserV4.esl").as_slice(),
        ),
        (
            5,
            include_bytes!("../../../../ofdrw-gm/src/test/resources/UserV5.esl").as_slice(),
        ),
    ] {
        let mut document = OfdDocument::new();
        document.add_text_page("SES signing", 210.0, 297.0).unwrap();
        let before = document.to_bytes().unwrap();
        assert!(document
            .add_ses_signature(
                include_bytes!("fixtures/trust-leaf-private-key.bin"),
                signer,
                seal,
                "2020-09-13 12:26:40",
            )
            .is_err());
        assert_eq!(document.to_bytes().unwrap(), before);
        assert!(document
            .add_ses_signature(
                key,
                include_bytes!("fixtures/trust-leaf-cert.der"),
                seal,
                "2020-09-13 12:26:40"
            )
            .is_err());
        assert_eq!(document.to_bytes().unwrap(), before);
        assert_eq!(
            document
                .add_ses_signature(key, signer, seal, "2020-09-13 12:26:40")
                .unwrap(),
            0
        );
        assert_eq!(document.seal_data(0).unwrap(), seal);
        assert_eq!(document.check_signature_seal_match(0).unwrap(), Some(true));
        assert!(document.check_ses_seal_signature(0).unwrap());
        assert!(document.check_ses_seal_signer_authorization(0).unwrap());
        assert!(document.check_ses_signature_value(0).unwrap());
        assert!(document.check_signature_description_hash(0).unwrap().valid);
        assert!(document
            .check_signature_references(0)
            .unwrap()
            .iter()
            .all(|check| check.valid));
        assert!(document.validate_references().unwrap().is_empty());
        let signed_value = document.signed_value_data(0).unwrap();
        assert_eq!(signed_value[0], 0x30, "SES v{version}");
        let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
        assert!(reopened.check_ses_signature_value(0).unwrap());
        assert_eq!(
            reopened.signatures().unwrap()[0].signature_type.as_deref(),
            Some("Seal")
        );

        assert_eq!(
            document
                .add_digital_signature(key, "2020-09-13 12:26:40")
                .unwrap(),
            1
        );
        assert_eq!(
            document
                .add_ses_signature(key, signer, seal, "2020-09-13 12:26:40")
                .unwrap(),
            2
        );
        assert_eq!(document.signatures().unwrap().len(), 3);
        assert!(document.check_ses_signature_value(2).unwrap());
        for index in 0..3 {
            assert!(document
                .check_signature_references(index)
                .unwrap()
                .iter()
                .all(|check| check.valid));
        }
    }
}

#[test]
fn creates_positioned_ses_stamps_and_keeps_signature_ids_unique() {
    let key = include_bytes!("fixtures/user-private-key.bin");
    let signer = include_bytes!("fixtures/user-cert.der");
    let seal = include_bytes!("../../../../ofdrw-gm/src/test/resources/UserV4.esl");
    let mut document = OfdDocument::new();
    document.add_text_page("stamped", 210.0, 297.0).unwrap();
    let before = document.to_bytes().unwrap();
    assert!(document
        .add_ses_signature_with_stamp(
            key,
            signer,
            seal,
            "2020-09-13 12:26:40",
            1,
            [10.0, 20.0, 40.0, 40.0]
        )
        .is_err());
    assert!(document
        .add_ses_signature_with_stamp(
            key,
            signer,
            seal,
            "2020-09-13 12:26:40",
            0,
            [10.0, 20.0, 0.0, 40.0]
        )
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    assert_eq!(
        document
            .add_ses_signature_with_stamp(
                key,
                signer,
                seal,
                "2020-09-13 12:26:40",
                0,
                [10.0, 20.0, 40.0, 40.0]
            )
            .unwrap(),
        0
    );
    let first = &document.signatures().unwrap()[0];
    assert_eq!(first.id, "s001");
    assert_eq!(first.stamps.len(), 1);
    assert_eq!(first.stamps[0].id, "s002");
    assert_eq!(first.stamps[0].page_ref, document.pages().unwrap()[0].id);
    assert_eq!(first.stamps[0].boundary, Some([10.0, 20.0, 40.0, 40.0]));
    assert!(document.check_ses_signature_value(0).unwrap());
    let svg = document.page_svg(0).unwrap();
    assert!(svg.contains("data-ofd-stamp=\"s002\""));
    assert!(svg.contains("href=\"data:image/png;base64,"));
    assert!(document.page_png(0, 25.4).unwrap().starts_with(b"\x89PNG"));
    assert_eq!(
        document
            .add_ses_signature_with_stamp(
                key,
                signer,
                seal,
                "2020-09-13 12:26:40",
                0,
                [60.0, 20.0, 40.0, 40.0]
            )
            .unwrap(),
        1
    );
    let signatures = document.signatures().unwrap();
    assert_eq!(signatures[1].id, "s003");
    assert_eq!(signatures[1].stamps[0].id, "s004");
    assert!(document.check_ses_signature_value(1).unwrap());
    assert!(document.validate_references().unwrap().is_empty());
    for index in 0..2 {
        assert!(document
            .check_signature_references(index)
            .unwrap()
            .iter()
            .all(|check| check.valid));
    }
}

#[test]
fn renders_nested_ofd_seal_picture_from_java_sample() {
    let document = OfdDocument::open(
        PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../../ofdrw-layout/src/test/resources/keyword2.ofd"),
    )
    .unwrap();
    let svg = document.page_svg(0).unwrap();
    assert!(svg.contains("data-ofd-stamp="));
    assert!(svg.contains("href=\"data:image/png;base64,"));
    let stamp = svg.split("data-ofd-stamp=").nth(1).unwrap();
    let encoded = stamp
        .split("href=\"data:image/png;base64,")
        .nth(1)
        .unwrap()
        .split('"')
        .next()
        .unwrap();
    let png = STANDARD.decode(encoded).unwrap();
    let picture = image::load_from_memory(&png).unwrap().to_rgba8();
    assert_eq!(picture.get_pixel(0, 0).0[3], 0);
    assert!(picture.pixels().any(|pixel| pixel.0[3] > 0));

    let mut blank = OfdDocument::new();
    blank.add_blank_page(20.0, 20.0).unwrap();
    let ordinary_page = image::load_from_memory(&blank.page_png(0, 25.4).unwrap())
        .unwrap()
        .to_rgba8();
    assert_eq!(ordinary_page.get_pixel(0, 0).0, [255, 255, 255, 255]);
}

#[test]
fn rasterizes_java_page_with_text_paths_images_and_nested_seal() {
    let document = OfdDocument::open(
        PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../../ofdrw-converter/src/test/resources/1.ofd"),
    )
    .unwrap();
    let page = image::load_from_memory(&document.page_png(0, 25.4).unwrap())
        .unwrap()
        .to_rgba8();
    assert_eq!(page.dimensions(), (210, 140));
    assert_eq!(page.get_pixel(0, 0).0, [255, 255, 255, 255]);
    assert!(page.pixels().any(|pixel| {
        let [red, green, blue, alpha] = pixel.0;
        alpha == 255 && red > 150 && red > green.saturating_add(30) && red > blue.saturating_add(30)
    }));
    assert!(page.pixels().any(|pixel| {
        let [red, green, blue, alpha] = pixel.0;
        alpha == 255 && red < 90 && green < 90 && blue < 90
    }));
}

#[test]
fn raster_cache_tracks_page_edits_and_resolution() {
    let mut document = OfdDocument::new();
    document.add_text_page("IIII", 50.0, 30.0).unwrap();
    let first = document.page_png(0, 25.4).unwrap();
    assert_eq!(document.page_png(0, 25.4).unwrap(), first);
    let high_resolution = image::load_from_memory(&document.page_png(0, 50.8).unwrap()).unwrap();
    assert_eq!(
        (high_resolution.width(), high_resolution.height()),
        (100, 60)
    );

    let path = document.pages().unwrap()[0].path.clone();
    let content = String::from_utf8(document.entry(&path).unwrap().unwrap().to_vec()).unwrap();
    assert!(content.contains("IIII"));
    document
        .set_entry(&path, content.replace("IIII", "WWWW").into_bytes())
        .unwrap();
    assert_ne!(document.page_png(0, 25.4).unwrap(), first);
}

#[test]
fn renders_java_riding_stamp_with_page_relative_clip() {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../../ofdrw-converter/src/test/resources/V4RideRight.ofd");
    let document = OfdDocument::open(path).unwrap();
    let signature = &document.signatures().unwrap()[0];
    assert_eq!(signature.stamps.len(), 5);
    assert_eq!(
        signature.stamps[0].boundary,
        Some([202.0, 40.0, 40.0, 40.0])
    );
    assert_eq!(signature.stamps[0].clip, Some([0.0, 0.0, 8.0, 40.0]));
    assert_eq!(signature.stamps[1].clip, Some([8.0, 0.0, 8.0, 40.0]));
    let svg = document.page_svg(0).unwrap();
    assert!(svg.contains("data-ofd-stamp=\"s002\""));
    assert!(svg.contains("clip-path=\"url(#ofd-stamp-clip-"));
    assert!(svg.contains("x=\"202\" y=\"40\" width=\"8\" height=\"40\""));
    assert!(document.page_png(0, 25.4).unwrap().starts_with(b"\x89PNG"));
    let pdf = lopdf::Document::load_mem(&document.to_pdf().unwrap()).unwrap();
    assert_eq!(pdf.get_pages().len(), 5);
}

#[test]
fn creates_ses_v4_and_v5_seals_and_uses_them_for_document_signing() {
    let key = include_bytes!("fixtures/user-private-key.bin");
    let certificate = include_bytes!("fixtures/user-cert.der");
    let picture = include_bytes!("../../../../ofdrw-layout/src/test/resources/testimg.png");
    for version in [4, 5] {
        let mut spec = SesSealSpec {
            version,
            vendor_id: "ofdrw-rs".into(),
            seal_id: format!("rust-seal-v{version}"),
            name: "Rust 测试印章".into(),
            seal_type: 3,
            authorized_signer_certificates: vec![certificate.to_vec()],
            created_at: 1_600_000_000,
            valid_from: 1_600_000_000,
            valid_until: 1_900_000_000,
            picture_type: "PNG".into(),
            picture_width_mm: 40,
            picture_height_mm: 40,
        };
        assert!(create_ses_seal(
            include_bytes!("fixtures/trust-leaf-private-key.bin"),
            certificate,
            picture,
            &spec
        )
        .is_err());
        let seal = create_ses_seal(key, certificate, picture, &spec).unwrap();
        let mut document = OfdDocument::new();
        document.add_text_page("signed", 210.0, 297.0).unwrap();
        document
            .add_ses_signature_with_stamp(
                key,
                certificate,
                &seal,
                "2020-09-13 12:26:40",
                0,
                [10.0, 20.0, 40.0, 40.0],
            )
            .unwrap();
        assert!(document.check_ses_seal_signature(0).unwrap());
        assert!(document.check_ses_seal_signer_authorization(0).unwrap());
        assert!(document.check_ses_signature_value(0).unwrap());
        assert!(document.check_signature_seal_match(0).unwrap().unwrap());
        assert!(document.page_svg(0).unwrap().contains("data-ofd-stamp="));
        assert_eq!(document.seal_data(0).unwrap(), seal);
        spec.version = 3;
        assert!(create_ses_seal(key, certificate, picture, &spec).is_err());
        spec.version = version;
        spec.valid_from = spec.valid_until + 1;
        assert!(create_ses_seal(key, certificate, picture, &spec).is_err());
    }
}

#[test]
fn creates_svg_ses_seal_and_rejects_invalid_material() {
    let key = include_bytes!("fixtures/user-private-key.bin");
    let certificate = include_bytes!("fixtures/user-cert.der");
    let picture = br##"<svg xmlns="http://www.w3.org/2000/svg" width="40" height="40"><circle cx="20" cy="20" r="18" fill="#d02030"/></svg>"##;
    let mut spec = SesSealSpec {
        version: 4,
        vendor_id: "ofdrw-rs".into(),
        seal_id: "svg-seal".into(),
        name: "SVG seal".into(),
        seal_type: 3,
        authorized_signer_certificates: vec![
            include_bytes!("fixtures/trust-leaf-cert.der").to_vec(),
            certificate.to_vec(),
        ],
        created_at: 1_600_000_000,
        valid_from: 1_600_000_000,
        valid_until: 1_900_000_000,
        picture_type: "SVG".into(),
        picture_width_mm: 40,
        picture_height_mm: 40,
    };
    let seal = create_ses_seal(key, certificate, picture, &spec).unwrap();
    let mut document = OfdDocument::new();
    document.add_text_page("signed", 210.0, 297.0).unwrap();
    document
        .add_ses_signature_with_stamp(
            key,
            certificate,
            &seal,
            "2020-09-13 12:26:40",
            0,
            [10.0, 20.0, 40.0, 40.0],
        )
        .unwrap();
    assert!(document.check_ses_seal_signature(0).unwrap());
    assert!(document.check_ses_seal_signer_authorization(0).unwrap());
    assert!(document
        .page_svg(0)
        .unwrap()
        .contains("href=\"data:image/png;base64,"));
    spec.vendor_id = "not ascii 印".into();
    assert!(create_ses_seal(key, certificate, picture, &spec).is_err());
    spec.vendor_id = "ofdrw-rs".into();
    spec.authorized_signer_certificates.clear();
    assert!(create_ses_seal(key, certificate, picture, &spec).is_err());
    spec.authorized_signer_certificates = vec![b"not a certificate".to_vec()];
    assert!(create_ses_seal(key, certificate, picture, &spec).is_err());
    spec.authorized_signer_certificates = vec![certificate.to_vec()];
    spec.picture_type = "PNG".into();
    assert!(create_ses_seal(key, certificate, picture, &spec).is_err());
    spec.picture_type = "SVG".into();
    spec.picture_width_mm = 0;
    assert!(create_ses_seal(key, certificate, picture, &spec).is_err());
    spec.picture_width_mm = 40;
    spec.name.clear();
    assert!(create_ses_seal(key, certificate, picture, &spec).is_err());
}

#[test]
fn checks_raw_digital_signature_with_supplied_certificate() {
    let resources =
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../../ofdrw-sign/src/test/resources");
    let mut document = OfdDocument::open(resources.join("DigitalSign.ofd")).unwrap();
    let certificate = include_bytes!("fixtures/user-cert.der");
    assert!(document
        .check_digital_signature_with_certificate(0, certificate)
        .unwrap());
    let mut unsupported = document.clone();
    let signature_path = unsupported.signatures().unwrap()[0].path.clone();
    let xml = std::str::from_utf8(unsupported.entry(&signature_path).unwrap().unwrap())
        .unwrap()
        .to_owned();
    unsupported
        .set_entry(
            &signature_path,
            xml.replace("1.2.156.10197.1.501", "1.2.156.10197.1.502")
                .into_bytes(),
        )
        .unwrap();
    assert!(matches!(
        unsupported.check_digital_signature_with_certificate(0, certificate),
        Err(OfdError::Invalid(message)) if message.contains("unsupported digital signature algorithm")
    ));
    let mut malformed = document.clone();
    let value_path = malformed.signatures().unwrap()[0].signed_value_path.clone();
    malformed.set_entry(&value_path, b"bad".to_vec()).unwrap();
    assert!(matches!(
        malformed.check_digital_signature_with_certificate(0, certificate),
        Err(OfdError::Invalid(message)) if message.contains("not valid DER")
    ));
    let seal = OfdDocument::open(fixture("SESV4SignDoc.ofd")).unwrap();
    assert!(seal
        .check_digital_signature_with_certificate(0, certificate)
        .is_err());
    let path = document.signatures().unwrap()[0].path.clone();
    let original = std::str::from_utf8(document.entry(&path).unwrap().unwrap())
        .unwrap()
        .to_owned();
    document
        .set_entry(
            &path,
            original.replace("ofdrw-sign", "tampered").into_bytes(),
        )
        .unwrap();
    assert!(!document
        .check_digital_signature_with_certificate(0, certificate)
        .unwrap());
    assert!(document
        .check_digital_signature_with_certificate(0, b"not a certificate")
        .is_err());
    assert!(document
        .check_digital_signature_with_certificate(1, certificate)
        .is_err());
}

#[test]
fn checks_signer_certificate_validity_at_supplied_time() {
    let resources =
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../../ofdrw-sign/src/test/resources");
    let digital = OfdDocument::open(resources.join("DigitalSign.ofd")).unwrap();
    let certificate = include_bytes!("fixtures/user-cert.der");
    // The fixture certificate is valid from 2020-04-21 14:39:08 UTC through
    // 2022-04-21 14:39:08 UTC, inclusive.
    assert!(!digital
        .check_signature_certificate_validity(0, certificate, 1_587_479_947)
        .unwrap());
    assert!(digital
        .check_signature_certificate_validity(0, certificate, 1_587_479_948)
        .unwrap());
    assert!(digital
        .check_signature_certificate_validity(0, certificate, 1_650_551_948)
        .unwrap());
    assert!(!digital
        .check_signature_certificate_validity(0, certificate, 1_650_551_949)
        .unwrap());
    assert!(digital
        .check_signature_certificate_validity(0, &[], 1_600_000_000)
        .is_err());
    assert!(digital
        .check_signature_certificate_validity(0, b"invalid", 1_600_000_000)
        .is_err());
    assert!(digital
        .check_signature_certificate_validity(1, certificate, 1_600_000_000)
        .is_err());

    let seal = OfdDocument::open(fixture("SESV4SignDoc.ofd")).unwrap();
    assert!(seal
        .check_signature_certificate_validity(0, &[], 1_600_000_000)
        .unwrap());
    assert!(!seal
        .check_signature_certificate_validity(0, &[], 0)
        .unwrap());
    assert!(seal
        .check_signature_certificate_validity(0, certificate, 1_600_000_000)
        .is_err());
}

#[test]
fn checks_direct_sm2_trust_anchor_and_signature_value() {
    use der::Decode;
    use x509_cert::{
        ext::pkix::{BasicConstraints, KeyUsage},
        Certificate,
    };
    let key = include_bytes!("fixtures/trust-leaf-private-key.bin");
    let signer = include_bytes!("fixtures/trust-leaf-cert.der");
    let anchor = include_bytes!("fixtures/trust-root-cert.der");
    let other_anchor = include_bytes!("fixtures/root-cert.der");
    let signer_cert = Certificate::from_der(signer).unwrap();
    let anchor_cert = Certificate::from_der(anchor).unwrap();
    assert_eq!(
        signer_cert.tbs_certificate().issuer(),
        anchor_cert.tbs_certificate().subject()
    );
    assert_eq!(
        signer_cert.signature_algorithm(),
        signer_cert.tbs_certificate().signature()
    );
    assert!(
        anchor_cert
            .tbs_certificate()
            .get_extension::<BasicConstraints>()
            .unwrap()
            .unwrap()
            .1
            .ca
    );
    assert!(anchor_cert
        .tbs_certificate()
        .get_extension::<KeyUsage>()
        .unwrap()
        .unwrap()
        .1
        .key_cert_sign());
    assert!(signer_cert
        .tbs_certificate()
        .get_extension::<KeyUsage>()
        .unwrap()
        .unwrap()
        .1
        .digital_signature());
    let mut document = OfdDocument::new();
    document
        .add_text_page("trusted signature", 210.0, 297.0)
        .unwrap();
    document
        .add_digital_signature(key, "2030-01-01 00:00:00")
        .unwrap();
    assert!(document
        .check_digital_signature_with_certificate(0, signer)
        .unwrap());
    assert!(document
        .check_signature_certificate_validity(0, signer, 1_893_456_000)
        .unwrap());
    assert!(document
        .check_signature_direct_trust_anchor(0, signer, anchor, 1_893_456_000, "")
        .unwrap());
    let full_report = document
        .verify_signature_with_ordered_sm2_chains(
            0,
            signer,
            &[],
            anchor,
            &[],
            &[],
            1_893_456_000,
            "",
            "",
        )
        .unwrap();
    assert!(full_report.all_valid, "{full_report:?}");
    assert_eq!(full_report.seal_issuer_chain_valid, None);
    assert!(document
        .verify_signature_with_ordered_sm2_chains(
            0,
            signer,
            &[],
            anchor,
            &[],
            anchor,
            1_893_456_000,
            "",
            "",
        )
        .is_err());
    assert!(!document
        .check_signature_direct_trust_anchor(0, signer, anchor, 1_893_456_000, "1234567812345678")
        .unwrap());
    assert!(!document
        .check_signature_direct_trust_anchor(0, signer, other_anchor, 1_893_456_000, "")
        .unwrap());
    assert!(!document
        .check_signature_direct_trust_anchor(0, signer, anchor, 1_600_000_000, "")
        .unwrap());
    assert!(document
        .check_signature_direct_trust_anchor(0, &[], anchor, 1_893_456_000, "")
        .is_err());
    assert!(document
        .check_signature_direct_trust_anchor(0, b"invalid", anchor, 1_893_456_000, "")
        .is_err());
    assert!(document
        .check_signature_direct_trust_anchor(0, signer, b"invalid", 1_893_456_000, "")
        .is_err());
    assert!(document
        .check_signature_direct_trust_anchor(1, signer, anchor, 1_893_456_000, "")
        .is_err());
    let oid = [0x06, 0x08, 0x2a, 0x81, 0x1c, 0xcf, 0x55, 0x01, 0x83, 0x75];
    let offsets = signer
        .windows(oid.len())
        .enumerate()
        .filter_map(|(index, window)| (window == oid).then_some(index))
        .collect::<Vec<_>>();
    assert_eq!(offsets.len(), 2);
    let mut inconsistent = signer.to_vec();
    inconsistent[offsets[1] + oid.len() - 1] = 0x74;
    assert!(!document
        .check_signature_direct_trust_anchor(0, &inconsistent, anchor, 1_893_456_000, "")
        .unwrap());
    let mut unsupported = signer.to_vec();
    for offset in offsets {
        unsupported[offset + oid.len() - 1] = 0x74;
    }
    assert!(matches!(
        document.check_signature_direct_trust_anchor(0, &unsupported, anchor, 1_893_456_000, ""),
        Err(OfdError::Invalid(message)) if message.contains("unsupported signer certificate algorithm")
    ));

    let mut changed = document.clone();
    let signature_path = changed.signatures().unwrap()[0].path.clone();
    let description =
        std::str::from_utf8(changed.entry(&signature_path).unwrap().unwrap()).unwrap();
    changed
        .set_entry(
            &signature_path,
            description.replace("ofdrw-rs", "tampered").into_bytes(),
        )
        .unwrap();
    assert!(!changed
        .check_signature_direct_trust_anchor(0, signer, anchor, 1_893_456_000, "")
        .unwrap());

    let mut changed_file = document.clone();
    let page_path = "Doc_0/Pages/Page_0/Content.xml";
    let page = std::str::from_utf8(changed_file.entry(page_path).unwrap().unwrap()).unwrap();
    changed_file
        .set_entry(
            page_path,
            page.replace("trusted signature", "modified").into_bytes(),
        )
        .unwrap();
    assert!(changed_file
        .check_signature_direct_trust_anchor(0, signer, anchor, 1_893_456_000, "")
        .unwrap());
    assert!(changed_file
        .check_signature_references(0)
        .unwrap()
        .iter()
        .any(|check| !check.valid));
}

#[test]
fn signs_and_verifies_with_custom_sm2_distinguishing_id() {
    let key = include_bytes!("fixtures/chain-leaf-private-key.bin");
    let signer = include_bytes!("fixtures/chain-leaf-cert.der");
    let intermediate = include_bytes!("fixtures/chain-intermediate-cert.der");
    let anchor = include_bytes!("fixtures/chain-root-cert.der");
    let custom_id = "OFD-Rust-Interop";
    let mut document = OfdDocument::new();
    document.add_text_page("custom ID", 210.0, 297.0).unwrap();
    assert_eq!(
        document
            .add_digital_signature_with_distid(key, "2030-01-01 00:00:00", custom_id)
            .unwrap(),
        0
    );
    assert!(!document
        .check_digital_signature_with_certificate(0, signer)
        .unwrap());
    assert!(document
        .check_digital_signature_with_certificate_and_distid(0, signer, custom_id)
        .unwrap());
    assert!(!document
        .check_signature_ordered_sm2_chain(0, signer, &[intermediate], anchor, 1_893_456_000, "")
        .unwrap());
    assert!(document
        .check_signature_ordered_sm2_chain_with_distids(
            0,
            signer,
            &[intermediate],
            anchor,
            1_893_456_000,
            Sm2DistinguishingIds {
                certificate: "",
                signature: custom_id,
            },
        )
        .unwrap());
    let report = document
        .verify_signature_with_ordered_sm2_chain_and_distids(
            0,
            signer,
            &[intermediate],
            anchor,
            1_893_456_000,
            Sm2DistinguishingIds {
                certificate: "",
                signature: custom_id,
            },
        )
        .unwrap();
    assert!(report.all_valid, "{report:?}");
    assert!(
        !document
            .verify_signature_with_ordered_sm2_chain(
                0,
                signer,
                &[intermediate],
                anchor,
                1_893_456_000,
                ""
            )
            .unwrap()
            .all_valid
    );
    assert_eq!(
        document
            .add_digital_signature(key, "2030-01-02 00:00:00")
            .unwrap(),
        1
    );
    assert!(document
        .check_digital_signature_with_certificate_and_distid(0, signer, custom_id)
        .unwrap());
    assert!(document
        .check_digital_signature_with_certificate(1, signer)
        .unwrap());

    let seal = OfdDocument::open(fixture("SESV4SignDoc.ofd")).unwrap();
    assert!(seal.check_ses_signature_value(0).unwrap());
    assert!(!seal
        .check_ses_signature_value_with_distid(0, custom_id)
        .unwrap());
}

#[test]
fn checks_ordered_sm2_chain_and_path_length() {
    let key = include_bytes!("fixtures/chain-leaf-private-key.bin");
    let signer = include_bytes!("fixtures/chain-leaf-cert.der");
    let intermediate = include_bytes!("fixtures/chain-intermediate-cert.der");
    let anchor = include_bytes!("fixtures/chain-root-cert.der");
    let mut document = OfdDocument::new();
    document.add_text_page("chained", 210.0, 297.0).unwrap();
    document
        .add_digital_signature(key, "2030-01-01 00:00:00")
        .unwrap();
    assert!(document
        .check_digital_signature_with_certificate(0, signer)
        .unwrap());
    assert!(!document
        .check_signature_direct_trust_anchor(0, signer, anchor, 1_893_456_000, "")
        .unwrap());
    assert!(document
        .check_signature_ordered_sm2_chain(0, signer, &[intermediate], anchor, 1_893_456_000, "")
        .unwrap());
    let report = document
        .verify_signature_with_ordered_sm2_chain(
            0,
            signer,
            &[intermediate],
            anchor,
            1_893_456_000,
            "",
        )
        .unwrap();
    assert!(report.all_valid, "{report:?}");
    assert!(report.certificate_chain_valid);
    assert!(report.references_valid);
    let mut changed = document.clone();
    let page_path = "Doc_0/Pages/Page_0/Content.xml";
    let page = std::str::from_utf8(changed.entry(page_path).unwrap().unwrap()).unwrap();
    changed
        .set_entry(page_path, page.replace("chained", "changed").into_bytes())
        .unwrap();
    let report = changed
        .verify_signature_with_ordered_sm2_chain(
            0,
            signer,
            &[intermediate],
            anchor,
            1_893_456_000,
            "",
        )
        .unwrap();
    assert!(!report.all_valid);
    assert!(!report.references_valid);
    assert!(report.certificate_chain_valid);
    assert!(!document
        .check_signature_ordered_sm2_chain(
            0,
            signer,
            &[intermediate],
            anchor,
            1_893_456_000,
            "1234567812345678",
        )
        .unwrap());
    assert!(!document
        .check_signature_ordered_sm2_chain(0, signer, &[anchor], intermediate, 1_893_456_000, "")
        .unwrap());
    assert!(!document
        .check_signature_ordered_sm2_chain(0, signer, &[intermediate], anchor, 1_600_000_000, "")
        .unwrap());
    let mut broken_intermediate = intermediate.to_vec();
    *broken_intermediate.last_mut().unwrap() ^= 1;
    assert!(!document
        .check_signature_ordered_sm2_chain(
            0,
            signer,
            &[&broken_intermediate],
            anchor,
            1_893_456_000,
            ""
        )
        .unwrap());
    let pattern = [0x30, 0x06, 0x01, 0x01, 0xff, 0x02, 0x01, 0x01];
    let mut short_anchor = anchor.to_vec();
    let path_len_offset = short_anchor
        .windows(pattern.len())
        .position(|window| window == pattern)
        .unwrap();
    short_anchor[path_len_offset + pattern.len() - 1] = 0;
    assert!(!document
        .check_signature_ordered_sm2_chain(
            0,
            signer,
            &[intermediate],
            &short_anchor,
            1_893_456_000,
            ""
        )
        .unwrap());
    assert!(document
        .check_signature_ordered_sm2_chain(0, signer, &[b"invalid"], anchor, 1_893_456_000, "")
        .is_err());
    assert!(document
        .check_signature_ordered_sm2_chain(
            0,
            signer,
            &[intermediate.as_slice(); 9],
            anchor,
            1_893_456_000,
            ""
        )
        .is_err());
}

#[test]
fn verifies_raw_signature_with_unordered_certificate_pool() {
    let key = include_bytes!("fixtures/chain-leaf-private-key.bin");
    let signer = include_bytes!("fixtures/chain-leaf-cert.der");
    let intermediate = include_bytes!("fixtures/chain-intermediate-cert.der");
    let anchor = include_bytes!("fixtures/chain-root-cert.der");
    let unrelated = include_bytes!("fixtures/root-cert.der");
    let mut document = OfdDocument::new();
    document
        .add_text_page("pooled signature", 210.0, 297.0)
        .unwrap();
    document
        .add_digital_signature(key, "2030-01-01 00:00:00")
        .unwrap();
    let ids = Sm2DistinguishingIds {
        certificate: "",
        signature: ofdrw::DEFAULT_SM2_DISTID,
    };
    let report = document
        .verify_signature_with_certificate_pool(
            0,
            signer,
            &[unrelated, intermediate],
            anchor,
            1_893_456_000,
            ids,
        )
        .unwrap();
    assert!(report.all_valid, "{report:?}");
    let report = document
        .verify_signature_with_certificate_pool(0, signer, &[unrelated], anchor, 1_893_456_000, ids)
        .unwrap();
    assert!(report.signature_value_valid);
    assert!(!report.certificate_chain_valid);
    assert!(!report.all_valid);
    assert!(document
        .verify_signature_with_certificate_pool(1, signer, &[], anchor, 1_893_456_000, ids,)
        .is_err());
}

