#[test]
fn signature_reader_ignores_extension_elements_inside_descriptions() {
    let mut document = OfdDocument::new();
    document.add_text_page("signed page", 80.0, 50.0).unwrap();
    let key = include_bytes!("fixtures/user-private-key.bin");
    document
        .add_digital_signature(key, "2020-04-22 16:22:44")
        .unwrap();
    let expected = document.signatures().unwrap().remove(0);
    let signed_value = document.signed_value_data(0).unwrap().to_vec();

    let index_path = "Doc_0/Signs/Signatures.xml";
    let index = String::from_utf8(document.entry(index_path).unwrap().unwrap().to_vec()).unwrap();
    let index = index
        .replacen(
            "<ofd:Signatures xmlns:ofd=",
            "<ofd:Signatures xmlns:ext=\"urn:example:extension\" xmlns:ofd=",
            1,
        )
        .replacen(
            "<ofd:Signature ",
            "<ext:Signature ID=\"fake\" BaseLoc=\"/missing.xml\"/><ofd:Signature ",
            1,
        );
    document.set_entry(index_path, index.into_bytes()).unwrap();

    let description =
        String::from_utf8(document.entry(&expected.path).unwrap().unwrap().to_vec()).unwrap();
    let description = description
        .replacen(
            "<ofd:Signature xmlns:ofd=",
            "<ofd:Signature xmlns:ext=\"urn:example:extension\" xmlns:ofd=",
            1,
        )
        .replacen(
            "<ofd:SignedValue>",
            "<ext:SignedValue>/missing.dat</ext:SignedValue><SignedValue>/missing.dat</SignedValue><ofd:SignedValue>",
            1,
        )
        .replacen(
            "<ofd:SignedInfo>",
            "<ext:SignedInfo/><ofd:SignedInfo><ext:References/><ext:Seal><ext:BaseLoc>/missing.dat</ext:BaseLoc></ext:Seal>",
            1,
        )
        .replacen(
            "<ofd:References ",
            "<ext:References><ext:Reference FileRef=\"/missing.xml\"/></ext:References><ofd:References ",
            1,
        );
    document
        .set_entry(&expected.path, description.into_bytes())
        .unwrap();
    assert_eq!(document.signatures().unwrap(), [expected]);
    assert_eq!(document.signed_value_data(0).unwrap(), signed_value);
}

#[test]
fn creates_raw_sm2_signature_and_round_trips_verification() {
    let mut document = OfdDocument::new();
    document.add_text_page("signed page", 210.0, 297.0).unwrap();
    let private_key = include_bytes!("fixtures/user-private-key.bin");
    let certificate = include_bytes!("fixtures/user-cert.der");
    assert_eq!(
        document
            .add_digital_signature(private_key, "2020-04-22 16:22:44")
            .unwrap(),
        0
    );
    assert_eq!(document.signatures().unwrap().len(), 1);
    assert!(document
        .check_digital_signature_with_certificate(0, certificate)
        .unwrap());
    let checks = document.check_signature_references(0).unwrap();
    assert_eq!(checks.len(), 4);
    assert!(checks.iter().all(|check| check.valid));
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert!(reopened
        .check_digital_signature_with_certificate(0, certificate)
        .unwrap());
    assert!(reopened
        .check_signature_references(0)
        .unwrap()
        .iter()
        .all(|check| check.valid));

    let mut tampered = reopened.clone();
    let content_path = "Doc_0/Pages/Page_0/Content.xml";
    let original = std::str::from_utf8(tampered.entry(content_path).unwrap().unwrap()).unwrap();
    tampered
        .set_entry(
            content_path,
            original.replace("signed page", "changed page").into_bytes(),
        )
        .unwrap();
    assert!(tampered
        .check_digital_signature_with_certificate(0, certificate)
        .unwrap());
    assert!(tampered
        .check_signature_references(0)
        .unwrap()
        .iter()
        .any(|check| !check.valid));
    let tampered_before = tampered.to_bytes().unwrap();
    assert!(matches!(
        tampered.add_digital_signature(private_key, "2020-04-23 10:11:12"),
        Err(OfdError::Invalid(message)) if message.contains("invalid protected file digests")
    ));
    assert_eq!(tampered.to_bytes().unwrap(), tampered_before);

    let before = document.to_bytes().unwrap();
    assert!(document
        .add_digital_signature(private_key, "not a date")
        .is_err());
    assert!(document
        .add_digital_signature(private_key, "2021-02-29 00:00:00")
        .is_err());
    assert!(document
        .add_digital_signature(b"bad", "2020-04-22 16:22:44")
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    let first_description = document.signatures().unwrap()[0].path.clone();
    let first_value = document.signed_value_data(0).unwrap().to_vec();
    assert_eq!(
        document
            .add_digital_signature(private_key, "2020-04-23 10:11:12")
            .unwrap(),
        1
    );
    assert_eq!(document.signed_value_data(0).unwrap(), first_value);
    assert!(document.entry(&first_description).unwrap().is_some());
    assert_eq!(document.signatures().unwrap().len(), 2);
    for index in 0..2 {
        assert!(document
            .check_digital_signature_with_certificate(index, certificate)
            .unwrap());
        assert!(document
            .check_signature_references(index)
            .unwrap()
            .iter()
            .all(|check| check.valid));
    }
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.signatures().unwrap().len(), 2);
    assert!(reopened
        .check_digital_signature_with_certificate(1, certificate)
        .unwrap());
}

#[test]
fn appends_to_java_signature_without_invalidating_it() {
    let resources =
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../../ofdrw-sign/src/test/resources");
    let mut document = OfdDocument::open(resources.join("DigitalSign.ofd")).unwrap();
    let key = include_bytes!("fixtures/user-private-key.bin");
    let certificate = include_bytes!("fixtures/user-cert.der");
    let old_index = document
        .entry("Doc_0/Signs/Signatures.xml")
        .unwrap()
        .unwrap()
        .to_vec();
    assert_eq!(
        document
            .add_digital_signature(key, "2020-04-23 10:11:12")
            .unwrap(),
        1
    );
    assert_ne!(
        document
            .entry("Doc_0/Signs/Signatures.xml")
            .unwrap()
            .unwrap(),
        old_index
    );
    for index in 0..2 {
        assert!(document
            .check_digital_signature_with_certificate(index, certificate)
            .unwrap());
        assert!(document
            .check_signature_references(index)
            .unwrap()
            .iter()
            .all(|check| check.valid));
    }
    assert!(document.signatures().unwrap()[1]
        .references
        .iter()
        .any(|reference| reference.path == document.signatures().unwrap()[0].path));
}

