#[test]
fn signing_handles_default_xml_namespace_and_rejects_conflicting_state() {
    let key = include_bytes!("fixtures/user-private-key.bin");
    let certificate = include_bytes!("fixtures/user-cert.der");
    let mut unprefixed = OfdDocument::new();
    let xml = std::str::from_utf8(unprefixed.entry("OFD.xml").unwrap().unwrap()).unwrap();
    unprefixed
        .set_entry(
            "OFD.xml",
            xml.replace("ofd:", "")
                .replace("xmlns:ofd", "xmlns")
                .into_bytes(),
        )
        .unwrap();
    unprefixed
        .add_digital_signature(key, "2020-02-29 23:59:59")
        .unwrap();
    assert!(unprefixed
        .check_digital_signature_with_certificate(0, certificate)
        .unwrap());

    let mut occupied = OfdDocument::new();
    occupied
        .set_entry("Doc_0/Signs/Signatures.xml", b"<Signatures/>".to_vec())
        .unwrap();
    let before = occupied.to_bytes().unwrap();
    assert!(matches!(
        occupied.add_digital_signature(key, "2020-04-22 16:22:44"),
        Err(OfdError::Invalid(message)) if message.contains("already exists")
    ));
    assert_eq!(occupied.to_bytes().unwrap(), before);

    let mut empty_location = OfdDocument::new();
    let ofd = std::str::from_utf8(empty_location.entry("OFD.xml").unwrap().unwrap()).unwrap();
    empty_location
        .set_entry(
            "OFD.xml",
            ofd.replace("</ofd:DocBody>", "<ofd:Signatures/></ofd:DocBody>")
                .into_bytes(),
        )
        .unwrap();
    assert!(matches!(
        empty_location.add_digital_signature(key, "2020-04-22 16:22:44"),
        Err(OfdError::Invalid(message)) if message.contains("empty Signatures location")
    ));

    let mut multiple = OfdDocument::new();
    let document_xml = multiple
        .entry("Doc_0/Document.xml")
        .unwrap()
        .unwrap()
        .to_vec();
    multiple
        .set_entry("Doc_1/Document.xml", document_xml)
        .unwrap();
    let ofd = std::str::from_utf8(multiple.entry("OFD.xml").unwrap().unwrap()).unwrap();
    let second = "<ofd:DocBody><ofd:DocRoot>Doc_1/Document.xml</ofd:DocRoot></ofd:DocBody>";
    multiple
        .set_entry(
            "OFD.xml",
            ofd.replace("</ofd:OFD>", &format!("{second}</ofd:OFD>"))
                .into_bytes(),
        )
        .unwrap();
    assert!(matches!(
        multiple.add_digital_signature(key, "2020-04-22 16:22:44"),
        Err(OfdError::Invalid(message)) if message.contains("one DocBody")
    ));
}

#[test]
fn moves_java_pages_without_changing_unrelated_entries() {
    let mut document = OfdDocument::open(fixture("keyword2.ofd")).unwrap();
    let before = document.clone();
    let original = document.pages().unwrap();
    assert_eq!(original.len(), 2);
    document.move_page(1, 0).unwrap();
    let reordered = document.pages().unwrap();
    assert_eq!(reordered[0].path, original[1].path);
    assert_eq!(reordered[1].path, original[0].path);
    for path in before.entry_names() {
        if !path.ends_with("Document.xml") {
            assert_eq!(
                document.entry(path).unwrap(),
                before.entry(path).unwrap(),
                "{path}"
            );
        }
    }
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.pages().unwrap(), reordered);
}

#[test]
fn rejects_moving_pages_between_document_bodies_without_mutation() {
    let mut document = OfdDocument::new();
    document.add_text_page("A", 20.0, 20.0).unwrap();
    let copies: Vec<_> = document
        .entry_names()
        .filter(|path| path.starts_with("Doc_0/"))
        .map(|path| {
            (
                path.replacen("Doc_0/", "Doc_1/", 1),
                document.entry(path).unwrap().unwrap().to_vec(),
            )
        })
        .collect();
    for (path, bytes) in copies {
        document.set_entry(&path, bytes).unwrap();
    }
    let ofd = std::str::from_utf8(document.entry("OFD.xml").unwrap().unwrap())
        .unwrap()
        .replace(
            "</ofd:OFD>",
            "<ofd:DocBody><ofd:DocRoot>Doc_1/Document.xml</ofd:DocRoot></ofd:DocBody></ofd:OFD>",
        );
    document.set_entry("OFD.xml", ofd.into_bytes()).unwrap();
    assert_eq!(document.pages().unwrap().len(), 2);
    let before = document.to_bytes().unwrap();
    assert!(document.move_page(0, 1).is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
}

#[test]
fn renders_text_weight_from_java_document() {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../../ofdrw-layout/src/test/resources/SplitParagraph.ofd");
    let document = OfdDocument::open(path).unwrap();
    let svg = document.page_svg(0).unwrap();
    assert!(svg.contains("font-weight=\"800\""));
    assert!(document.page_png(0, 25.4).unwrap().starts_with(b"\x89PNG"));
}

#[test]
fn page_text_code_replacement_preserves_layout_and_rejects_shaped_text() {
    let mut document = OfdDocument::new();
    document.add_text_page("AB", 30.0, 20.0).unwrap();
    let id = document.page_text_objects(0).unwrap()[0]
        .id
        .clone()
        .unwrap();
    document.set_page_text_code(0, &id, 0, "A & <B>").unwrap();
    assert_eq!(document.page_text(0).unwrap(), ["A & <B>"]);
    assert_eq!(
        document.page_text_objects(0).unwrap()[0].codes[0].text,
        "A & <B>"
    );
    assert!(document.page_svg(0).unwrap().contains("A &amp; &lt;B&gt;"));
    assert_eq!(
        document.page_text_objects(0).unwrap()[0].codes[0]
            .delta_x
            .as_ref()
            .unwrap()
            .split_whitespace()
            .count(),
        6
    );
    let page_path = document.pages().unwrap()[0].path.clone();
    let before = document.to_bytes().unwrap();
    assert!(document.set_page_text_code(0, &id, 1, "X").is_err());
    assert!(document.set_page_text_code(0, "missing", 0, "X").is_err());
    assert_eq!(document.to_bytes().unwrap(), before);

    let page = std::str::from_utf8(document.entry(&page_path).unwrap().unwrap())
        .unwrap()
        .replace(
            "</ofd:TextObject>",
            "<ofd:TextCode X=\"0\" Y=\"8\" DeltaX=\"2\">XY</ofd:TextCode></ofd:TextObject>",
        );
    document.set_entry(&page_path, page.into_bytes()).unwrap();
    document.set_page_text_code(0, &id, 1, "UV").unwrap();
    assert_eq!(document.page_text(0).unwrap(), ["A & <B>", "UV"]);
    document.set_page_text_code(0, &id, 1, "LONG").unwrap();
    assert_eq!(document.page_text(0).unwrap(), ["A & <B>", "LONG"]);
    assert_eq!(
        document.page_text_objects(0).unwrap()[0].codes[1]
            .delta_x
            .as_ref()
            .unwrap()
            .split_whitespace()
            .count(),
        3
    );
    document
        .set_page_text_code_layout(
            0,
            &id,
            1,
            &TextCodeLayout {
                x: Some(0.0),
                y: Some(8.0),
                delta_y: Some(vec![1.0; 3]),
                ..Default::default()
            },
        )
        .unwrap();
    let before = document.to_bytes().unwrap();
    assert!(document.set_page_text_code(0, &id, 1, "MORE TEXT").is_err());
    assert_eq!(document.to_bytes().unwrap(), before);

    let page = std::str::from_utf8(document.entry(&page_path).unwrap().unwrap())
        .unwrap()
        .replace(
            "</ofd:TextObject>",
            "<ofd:CGTransform CodePosition=\"0\" CodeCount=\"1\" GlyphCount=\"1\"><ofd:Glyphs>1</ofd:Glyphs></ofd:CGTransform></ofd:TextObject>",
        );
    document.set_entry(&page_path, page.into_bytes()).unwrap();
    let before = document.to_bytes().unwrap();
    assert!(document.set_page_text_code(0, &id, 0, "Z").is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
}

#[test]
fn replacing_positioned_text_with_one_character_removes_delta_x() {
    let mut document = OfdDocument::new();
    document.add_text_page("AB", 30.0, 20.0).unwrap();
    let id = document.page_text_objects(0).unwrap()[0]
        .id
        .clone()
        .unwrap();
    document.set_page_text_code(0, &id, 0, "文").unwrap();
    let code = &document.page_text_objects(0).unwrap()[0].codes[0];
    assert_eq!(code.text, "文");
    assert!(code.delta_x.is_none());
    assert!(document.page_svg(0).unwrap().contains("文"));
    assert!(document.validate_references().unwrap().is_empty());
}

#[test]
fn foreign_cg_transform_does_not_shape_or_block_page_text_edits() {
    let mut document = OfdDocument::new();
    document.add_text_page("AB", 30.0, 20.0).unwrap();
    let id = document.page_text_objects(0).unwrap()[0]
        .id
        .clone()
        .unwrap();
    let page_path = document.pages().unwrap()[0].path.clone();
    let page = std::str::from_utf8(document.entry(&page_path).unwrap().unwrap()).unwrap();
    let page = page.replacen(
        "</ofd:TextObject>",
        "<x:CGTransform xmlns:x=\"urn:other\" CodePosition=\"999\"/></ofd:TextObject>",
        1,
    );
    document.set_entry(&page_path, page.into_bytes()).unwrap();
    assert!(document.page_text_objects(0).unwrap()[0]
        .cg_transforms
        .is_empty());
    assert!(document.page_svg(0).unwrap().contains("AB"));
    assert!(document.validate_references().unwrap().is_empty());

    document
        .set_page_text_code_layout(
            0,
            &id,
            0,
            &TextCodeLayout {
                x: Some(2.0),
                y: Some(7.0),
                delta_x: Some(vec![3.0]),
                delta_y: None,
            },
        )
        .unwrap();
    document
        .append_page_text_code(0, &id, "C", &TextCodeLayout::default())
        .unwrap();
    assert_eq!(document.page_text(0).unwrap(), ["AB", "C"]);
    document.remove_page_text_code(0, &id, 1).unwrap();
    assert_eq!(document.page_text(0).unwrap(), ["AB"]);
    let page = std::str::from_utf8(document.entry(&page_path).unwrap().unwrap()).unwrap();
    assert!(page.contains("<x:CGTransform"));
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert!(reopened.page_text_objects(0).unwrap()[0]
        .cg_transforms
        .is_empty());
}

#[test]
fn page_text_code_layout_updates_positions_and_inherits_previous_coordinates() {
    let mut document = OfdDocument::new();
    document.add_text_page("AB", 30.0, 20.0).unwrap();
    let id = document.page_text_objects(0).unwrap()[0]
        .id
        .clone()
        .unwrap();
    document
        .set_page_text_code_layout(
            0,
            &id,
            0,
            &TextCodeLayout {
                x: Some(2.0),
                y: Some(7.0),
                delta_x: Some(vec![3.5]),
                delta_y: None,
            },
        )
        .unwrap();
    let code = &document.page_text_objects(0).unwrap()[0].codes[0];
    assert_eq!(
        (code.x, code.y, code.delta_x.as_deref()),
        (Some(2.0), Some(7.0), Some("3.5"))
    );
    assert!(document
        .page_svg(0)
        .unwrap()
        .contains("x=\"2 5.5\" y=\"7 7\""));
    let page_path = document.pages().unwrap()[0].path.clone();
    let source = std::str::from_utf8(document.entry(&page_path).unwrap().unwrap()).unwrap();
    let updated = source.replace(
        "</ofd:TextObject>",
        "<ofd:TextCode>CD</ofd:TextCode></ofd:TextObject>",
    );
    document
        .set_entry(&page_path, updated.into_bytes())
        .unwrap();
    document
        .set_page_text_code_layout(
            0,
            &id,
            1,
            &TextCodeLayout {
                delta_x: Some(vec![4.0]),
                ..TextCodeLayout::default()
            },
        )
        .unwrap();
    let codes = document.page_text_objects(0).unwrap()[0].codes.clone();
    assert_eq!(
        (codes[1].x, codes[1].y, codes[1].delta_x.as_deref()),
        (None, None, Some("4"))
    );
    assert!(document
        .page_svg(0)
        .unwrap()
        .contains("x=\"2 6\" y=\"7 7\""));
    let matches = document.keyword_positions(&["CD"], Some(&[0])).unwrap();
    assert_eq!(matches.len(), 1);
    assert!((matches[0].box_mm[0] - 12.0).abs() < 1e-6);
    let before = document.to_bytes().unwrap();
    assert!(document
        .set_page_text_code_layout(0, &id, 0, &TextCodeLayout::default())
        .is_err());
    assert!(document
        .set_page_text_code_layout(
            0,
            &id,
            1,
            &TextCodeLayout {
                delta_x: Some(vec![1.0, 2.0]),
                ..TextCodeLayout::default()
            },
        )
        .is_err());
    assert!(document
        .set_page_text_code_layout(
            0,
            &id,
            1,
            &TextCodeLayout {
                x: Some(f64::INFINITY),
                ..TextCodeLayout::default()
            },
        )
        .is_err());
    assert!(document
        .set_page_text_code_layout(
            0,
            &id,
            1,
            &TextCodeLayout {
                x: Some(f64::MAX),
                delta_x: Some(vec![f64::MAX]),
                ..TextCodeLayout::default()
            },
        )
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    let reopened = OfdDocument::from_bytes(&before).unwrap();
    assert_eq!(reopened.page_text_objects(0).unwrap()[0].codes, codes);
    let font = std::fs::read(
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/dejavu-serif.ttf"),
    )
    .unwrap();
    let font_id = document.add_embedded_font("DejaVu Serif", &font).unwrap();
    let shaped_id = document
        .add_shaped_text_object(0, "fi", [5.0, 5.0, 20.0, 8.0], 5.0, &font_id.to_string())
        .unwrap();
    let before = document.to_bytes().unwrap();
    assert!(document
        .set_page_text_code_layout(
            0,
            &shaped_id,
            0,
            &TextCodeLayout {
                x: Some(1.0),
                y: Some(5.0),
                ..TextCodeLayout::default()
            },
        )
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
}

#[test]
fn appends_positioned_text_code_and_preserves_existing_runs() {
    let mut document = OfdDocument::new();
    document.add_text_page("AB", 30.0, 20.0).unwrap();
    let id = document.page_text_objects(0).unwrap()[0]
        .id
        .clone()
        .unwrap();
    document
        .append_page_text_code(
            0,
            &id,
            "C&D",
            &TextCodeLayout {
                delta_x: Some(vec![2.0, 2.5]),
                ..TextCodeLayout::default()
            },
        )
        .unwrap();
    let codes = document.page_text_objects(0).unwrap()[0].codes.clone();
    assert_eq!(codes.len(), 2);
    assert_eq!(codes[0].text, "AB");
    assert_eq!(codes[1].text, "C&D");
    assert_eq!(codes[1].delta_x.as_deref(), Some("2 2.5"));
    assert_eq!((codes[1].x, codes[1].y), (None, None));
    assert_eq!(document.page_text(0).unwrap(), ["AB", "C&D"]);
    let svg = document.page_svg(0).unwrap();
    assert!(svg.contains("x=\"0 2 4.5\" y=\"5 5 5\""));
    assert!(svg.contains("C&amp;D"));
    let before = document.to_bytes().unwrap();
    assert!(document
        .append_page_text_code(
            0,
            &id,
            "XY",
            &TextCodeLayout {
                delta_x: Some(vec![1.0, 2.0]),
                ..TextCodeLayout::default()
            }
        )
        .is_err());
    assert!(document
        .append_page_text_code(0, "missing", "XY", &TextCodeLayout::default())
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    let reopened = OfdDocument::from_bytes(&before).unwrap();
    assert_eq!(reopened.page_text_objects(0).unwrap()[0].codes, codes);

    let font = std::fs::read(
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/dejavu-serif.ttf"),
    )
    .unwrap();
    let font_id = document.add_embedded_font("DejaVu Serif", &font).unwrap();
    let shaped = document
        .add_shaped_text_object(0, "fi", [5.0, 5.0, 20.0, 8.0], 5.0, &font_id.to_string())
        .unwrap();
    let before = document.to_bytes().unwrap();
    assert!(document
        .append_page_text_code(0, &shaped, "Z", &TextCodeLayout::default())
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
}

#[test]
fn first_appended_text_code_requires_coordinates() {
    let mut document = OfdDocument::new();
    document.add_text_page("AB", 30.0, 20.0).unwrap();
    let id = document.page_text_objects(0).unwrap()[0]
        .id
        .clone()
        .unwrap();
    let page_path = document.pages().unwrap()[0].path.clone();
    let source = without_first_text_code_delta_x(
        std::str::from_utf8(document.entry(&page_path).unwrap().unwrap()).unwrap(),
    );
    let updated = source.replace("<ofd:TextCode X=\"0\" Y=\"5\">AB</ofd:TextCode>", "");
    assert_ne!(source, updated);
    document
        .set_entry(&page_path, updated.into_bytes())
        .unwrap();
    let before = document.to_bytes().unwrap();
    assert!(document
        .append_page_text_code(0, &id, "Q", &TextCodeLayout::default())
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    document
        .append_page_text_code(
            0,
            &id,
            "Q",
            &TextCodeLayout {
                x: Some(1.0),
                y: Some(5.0),
                ..TextCodeLayout::default()
            },
        )
        .unwrap();
    assert_eq!(document.page_text(0).unwrap(), ["Q"]);
    assert_eq!(
        document.page_text_objects(0).unwrap()[0].codes[0].x,
        Some(1.0)
    );
}

#[test]
fn removes_text_code_without_moving_inherited_successor() {
    let mut document = OfdDocument::new();
    document.add_text_page("A", 30.0, 20.0).unwrap();
    let id = document.page_text_objects(0).unwrap()[0]
        .id
        .clone()
        .unwrap();
    document
        .append_page_text_code(
            0,
            &id,
            "B",
            &TextCodeLayout {
                x: Some(5.0),
                y: Some(6.0),
                ..TextCodeLayout::default()
            },
        )
        .unwrap();
    document
        .append_page_text_code(0, &id, "C", &TextCodeLayout::default())
        .unwrap();
    assert!(document.page_svg(0).unwrap().contains("x=\"5\" y=\"6\""));
    document.remove_page_text_code(0, &id, 1).unwrap();
    assert_eq!(document.page_text(0).unwrap(), ["A", "C"]);
    let codes = document.page_text_objects(0).unwrap()[0].codes.clone();
    assert_eq!((codes[1].x, codes[1].y), (Some(5.0), Some(6.0)));
    assert!(document.page_svg(0).unwrap().contains("x=\"5\" y=\"6\""));
    document.remove_page_text_code(0, &id, 0).unwrap();
    assert_eq!(document.page_text(0).unwrap(), ["C"]);
    let only = document.page_text_objects(0).unwrap()[0].codes[0].clone();
    assert_eq!((only.x, only.y), (Some(5.0), Some(6.0)));
    let before = document.to_bytes().unwrap();
    assert!(document.remove_page_text_code(0, &id, 0).is_err());
    assert!(document.remove_page_text_code(0, &id, 3).is_err());
    assert!(document.remove_page_text_code(0, "missing", 0).is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    let reopened = OfdDocument::from_bytes(&before).unwrap();
    assert_eq!(reopened.page_text(0).unwrap(), ["C"]);

    let mut trailing = OfdDocument::new();
    trailing.add_text_page("A", 30.0, 20.0).unwrap();
    let trailing_id = trailing.page_text_objects(0).unwrap()[0]
        .id
        .clone()
        .unwrap();
    trailing
        .append_page_text_code(0, &trailing_id, "B", &TextCodeLayout::default())
        .unwrap();
    trailing.remove_page_text_code(0, &trailing_id, 1).unwrap();
    assert_eq!(trailing.page_text(0).unwrap(), ["A"]);

    let font = std::fs::read(
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/dejavu-serif.ttf"),
    )
    .unwrap();
    let font_id = document.add_embedded_font("DejaVu Serif", &font).unwrap();
    let shaped = document
        .add_shaped_text_object(0, "fi", [5.0, 5.0, 20.0, 8.0], 5.0, &font_id.to_string())
        .unwrap();
    let before = document.to_bytes().unwrap();
    assert!(document.remove_page_text_code(0, &shaped, 0).is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
}

#[test]
fn page_text_font_edit_validates_resources_and_shaped_glyphs() {
    let font = std::fs::read(
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/dejavu-serif.ttf"),
    )
    .unwrap();
    let mut document = OfdDocument::new();
    document.add_text_page("AB", 30.0, 20.0).unwrap();
    let original = document.page_text_objects(0).unwrap()[0].clone();
    let id = original.id.unwrap();
    let original_font = original.font_id.unwrap();
    let embedded_id = document.add_embedded_font("DejaVu Serif", &font).unwrap();
    let embedded_id = embedded_id.to_string();
    document.set_page_text_font(0, &id, &embedded_id).unwrap();
    assert_eq!(
        document.page_text_objects(0).unwrap()[0].font_id.as_deref(),
        Some(embedded_id.as_str())
    );
    assert!(document
        .page_svg(0)
        .unwrap()
        .contains("font-family=\"ofd-embedded-font-"));
    let before = document.to_bytes().unwrap();
    assert!(document.set_page_text_font(0, &id, "999999").is_err());
    assert!(document
        .set_page_text_font(0, "missing", &embedded_id)
        .is_err());
    assert!(document.set_page_text_font(0, &id, "").is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    let reopened = OfdDocument::from_bytes(&before).unwrap();
    assert_eq!(
        reopened.page_text_objects(0).unwrap()[0].font_id.as_deref(),
        Some(embedded_id.as_str())
    );

    let shaped_id = document
        .add_shaped_text_object(0, "fi", [5.0, 5.0, 20.0, 8.0], 5.0, &embedded_id)
        .unwrap();
    document
        .set_page_text_font(0, &shaped_id, &embedded_id)
        .unwrap();
    let before = document.to_bytes().unwrap();
    assert!(document
        .set_page_text_font(0, &shaped_id, &original_font)
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
}

#[test]
fn page_text_paint_flags_round_trip_and_restore_defaults() {
    let mut document = OfdDocument::new();
    document.add_text_page("AB", 30.0, 20.0).unwrap();
    let id = document.page_text_objects(0).unwrap()[0]
        .id
        .clone()
        .unwrap();
    let initial = document.page_object_paints(0).unwrap()[0].clone();
    assert!(initial.fill_enabled);
    assert!(!initial.stroke_enabled);

    document
        .set_page_text_paint_flags(0, &id, Some(false), Some(true))
        .unwrap();
    let paint = document.page_object_paints(0).unwrap()[0].clone();
    assert!(!paint.fill_enabled);
    assert!(paint.stroke_enabled);
    let svg = document.page_svg(0).unwrap();
    assert!(svg.contains("fill=\"none\""));
    let bytes = document.to_bytes().unwrap();
    let reopened = OfdDocument::from_bytes(&bytes).unwrap();
    assert_eq!(reopened.page_object_paints(0).unwrap()[0], paint);

    assert!(document
        .set_page_text_paint_flags(0, "missing", Some(true), Some(false))
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), bytes);
    document
        .set_page_text_paint_flags(0, &id, None, None)
        .unwrap();
    let paint = document.page_object_paints(0).unwrap()[0].clone();
    assert!(paint.fill_enabled);
    assert!(!paint.stroke_enabled);
    let page_path = &document.pages().unwrap()[0].path;
    let page_xml = std::str::from_utf8(document.entry(page_path).unwrap().unwrap()).unwrap();
    assert!(!page_xml.contains(" Fill=\""));
    assert!(!page_xml.contains(" Stroke=\""));
}

#[test]
fn page_text_typography_edits_are_atomic_and_restore_defaults() {
    let mut document = OfdDocument::new();
    document.add_text_page("AB", 20.0, 20.0).unwrap();
    let id = document.page_text_objects(0).unwrap()[0]
        .id
        .clone()
        .unwrap();
    let scale = 0.75;
    let style = TextTypographyStyle {
        size: 4.0,
        h_scale: Some(scale),
        read_direction: Some(180),
        char_direction: Some(90),
        weight: Some(700),
        italic: Some(true),
    };
    document.set_page_text_typography(0, &id, style).unwrap();
    let text = &document.page_text_objects(0).unwrap()[0];
    assert_eq!(text.size, Some(4.0));
    assert_eq!(text.h_scale, Some(scale));
    assert_eq!(text.read_direction, 180);
    assert_eq!(text.char_direction, 90);
    assert_eq!(text.weight, 700);
    assert!(text.italic);
    let svg = document.page_svg(0).unwrap();
    assert!(svg.contains("rotate(90) scale(0.75 1)"));
    assert!(svg.contains("font-weight=\"700\" font-style=\"italic\""));

    let before = document.to_bytes().unwrap();
    assert!(document
        .set_page_text_typography(
            0,
            &id,
            TextTypographyStyle {
                weight: Some(750),
                ..style
            }
        )
        .is_err());
    assert!(document
        .set_page_text_typography(0, &id, TextTypographyStyle { size: 0.0, ..style })
        .is_err());
    assert!(document
        .set_page_text_typography(0, "missing", style)
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);

    let path_id = document
        .add_path_object(0, "M 0 0 L 1 1", [0.0, 0.0, 2.0, 2.0], PathStyle::default())
        .unwrap();
    let before = document.to_bytes().unwrap();
    assert!(document
        .set_page_text_typography(0, &path_id, style)
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);

    document
        .set_page_text_typography(
            0,
            &id,
            TextTypographyStyle {
                size: 3.0,
                h_scale: None,
                read_direction: None,
                char_direction: None,
                weight: None,
                italic: None,
            },
        )
        .unwrap();
    let text = &document.page_text_objects(0).unwrap()[0];
    assert_eq!(text.size, Some(3.0));
    assert_eq!(text.h_scale, None);
    assert_eq!(text.read_direction, 0);
    assert_eq!(text.char_direction, 0);
    assert_eq!(text.weight, 400);
    assert!(!text.italic);
}

#[test]
fn renders_text_stroke_italic_scale_and_character_direction() {
    let mut document = OfdDocument::new();
    document.add_text_page("AB", 20.0, 20.0).unwrap();
    let default = &document.page_text_objects(0).unwrap()[0];
    assert_eq!(default.read_direction, 0);
    assert_eq!(default.char_direction, 0);
    assert_eq!(default.weight, 400);
    assert!(!default.italic);
    let path = document.pages().unwrap()[0].path.clone();
    let source = std::str::from_utf8(document.entry(&path).unwrap().unwrap())
        .unwrap()
        .to_owned();
    let styled = without_first_text_code_delta_x(&source)
        .replace(
            "<ofd:TextObject ID=",
            "<ofd:TextObject Stroke=\"true\" Fill=\"false\" Weight=\"700\" Italic=\"true\" HScale=\"0.64\" ReadDirection=\"180\" CharDirection=\"90\" LineWidth=\"0.7\" ID=",
        )
        .replace(
            "<ofd:TextCode",
            "<ofd:StrokeColor Value=\"255 0 0\"/><ofd:TextCode DeltaX=\"8\"",
        );
    document.set_entry(&path, styled.into_bytes()).unwrap();
    let text = &document.page_text_objects(0).unwrap()[0];
    assert_eq!(text.read_direction, 180);
    assert_eq!(text.char_direction, 90);
    assert_eq!(text.weight, 700);
    assert!(text.italic);
    let svg = document.page_svg(0).unwrap();
    assert_eq!(svg.matches("rotate(90) scale(0.64 1)").count(), 2);
    assert!(svg.contains("font-weight=\"700\" font-style=\"italic\""));
    assert!(svg.contains("fill=\"none\""));
    assert!(svg.contains("stroke=\"#ff0000\""));
    assert!(svg.contains("stroke-width=\"0.7\""));
    assert!(document.page_png(0, 25.4).unwrap().starts_with(b"\x89PNG"));
    assert!(lopdf::Document::load_mem(&document.to_pdf().unwrap()).is_ok());
    let invalid = std::str::from_utf8(document.entry(&path).unwrap().unwrap())
        .unwrap()
        .replace("CharDirection=\"90\"", "CharDirection=\"45\"");
    document.set_entry(&path, invalid.into_bytes()).unwrap();
    assert!(document.page_svg(0).is_err());
    assert!(document.page_text_objects(0).is_err());
}

#[test]
fn renders_embedded_font_cgtransform_glyph_outlines() {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../../ofdrw-layout/src/test/resources/ano.ofd");
    let mut document = OfdDocument::open(path).unwrap();
    let svg = document.page_svg(0).unwrap();
    assert!(svg.contains("data-ofd-glyph=\"2591\""));
    assert!(svg.contains("scale(0.10171875 -0.10171875)"));
    assert!(svg.contains("<g opacity=\"0\"><text"));
    assert!(!document.page_text(0).unwrap().is_empty());
    let png = resvg::tiny_skia::Pixmap::decode_png(&document.page_png(0, 25.4).unwrap()).unwrap();
    assert!(png.pixels().iter().any(|pixel| pixel.red() < 255));
    assert!(lopdf::Document::load_mem(&document.to_pdf().unwrap()).is_ok());
    let page_path = document.pages().unwrap()[0].path.clone();
    let original = std::str::from_utf8(document.entry(&page_path).unwrap().unwrap())
        .unwrap()
        .to_owned();
    document
        .set_entry(
            &page_path,
            original
                .replacen("<ofd:Glyphs>2591 ", "<ofd:Glyphs>2592 ", 1)
                .into_bytes(),
        )
        .unwrap();
    let changed = document.page_svg(0).unwrap();
    assert!(changed.contains("data-ofd-glyph=\"2592\""));
    assert_ne!(changed, svg);
    document
        .set_entry(
            &page_path,
            original
                .replacen("GlyphCount=\"7\"", "GlyphCount=\"8\"", 1)
                .into_bytes(),
        )
        .unwrap();
    assert!(document.page_svg(0).is_err());
}

#[test]
fn handles_cgtransform_without_embedded_font_and_rejects_invalid_mapping() {
    let mut document = OfdDocument::new();
    document.add_text_page("AB", 20.0, 20.0).unwrap();
    let path = document.pages().unwrap()[0].path.clone();
    let source = std::str::from_utf8(document.entry(&path).unwrap().unwrap())
        .unwrap()
        .to_owned();
    let mapped = source.replace(
        "<ofd:TextCode",
        "<ofd:CGTransform CodePosition=\"0\" CodeCount=\"2\" GlyphCount=\"2\"><ofd:Glyphs>1 2</ofd:Glyphs></ofd:CGTransform><ofd:TextCode",
    );
    document
        .set_entry(&path, mapped.clone().into_bytes())
        .unwrap();
    let transforms = document.page_text_objects(0).unwrap()[0]
        .cg_transforms
        .clone();
    assert_eq!(transforms.len(), 1);
    assert_eq!(transforms[0].code_position, 0);
    assert_eq!(transforms[0].code_count, 2);
    assert_eq!(transforms[0].glyph_count, 2);
    assert_eq!(transforms[0].glyphs, [1, 2]);
    let svg = document.page_svg(0).unwrap();
    assert!(svg.contains(">AB</text>"));
    assert!(!svg.contains("data-ofd-glyph="));
    for invalid in [
        mapped.replace("CodeCount=\"2\"", "CodeCount=\"0\""),
        mapped.replace("CodePosition=\"0\"", "CodePosition=\"2\""),
        mapped.replace("GlyphCount=\"2\"", "GlyphCount=\"3\""),
        mapped.replace("<ofd:Glyphs>1 2", "<ofd:Glyphs>bad 2"),
        mapped.replace("<ofd:Glyphs>1 2</ofd:Glyphs>", ""),
    ] {
        document.set_entry(&path, invalid.into_bytes()).unwrap();
        assert!(document.page_text_objects(0).is_err());
        assert!(document.page_svg(0).is_err());
    }
    let defaults = source.replace(
        "<ofd:TextCode",
        "<ofd:CGTransform CodePosition=\"0\"><ofd:Glyphs>1</ofd:Glyphs></ofd:CGTransform><ofd:TextCode",
    );
    document.set_entry(&path, defaults.into_bytes()).unwrap();
    let transform = &document.page_text_objects(0).unwrap()[0].cg_transforms[0];
    assert_eq!(transform.code_count, 1);
    assert_eq!(transform.glyph_count, 1);
    assert_eq!(transform.glyphs, [1]);
}

