#[test]
fn invisible_graphic_objects_are_excluded_from_previews() {
    let mut document = OfdDocument::new();
    document
        .add_path_page(
            "M 0 0 L 10 0 L 10 10 L 0 10 C",
            [0.0, 0.0, 10.0, 10.0],
            20.0,
            20.0,
            true,
            false,
        )
        .unwrap();
    let path = document.pages().unwrap()[0].path.clone();
    let source = std::str::from_utf8(document.entry(&path).unwrap().unwrap())
        .unwrap()
        .to_owned();
    let hidden = source.replace("<ofd:PathObject", "<ofd:PathObject Visible=\"false\"");
    document
        .set_entry(&path, hidden.clone().into_bytes())
        .unwrap();
    assert!(!document.page_svg(0).unwrap().contains("<path d="));
    let png = resvg::tiny_skia::Pixmap::decode_png(&document.page_png(0, 25.4).unwrap()).unwrap();
    assert!(png.pixels().iter().all(|pixel| pixel.red() == 255));
    assert!(lopdf::Document::load_mem(&document.to_pdf().unwrap()).is_ok());
    document
        .set_entry(
            &path,
            hidden
                .replace("Visible=\"false\"", "Visible=\"true\"")
                .into_bytes(),
        )
        .unwrap();
    assert!(document.page_svg(0).unwrap().contains("<path d="));
    document
        .set_entry(
            &path,
            hidden
                .replace("Visible=\"false\"", "Visible=\"maybe\"")
                .into_bytes(),
        )
        .unwrap();
    assert!(document.page_svg(0).is_err());
}

#[test]
fn blend_mode_darken_changes_png_pixels_and_pdf_graphics_state() {
    let mut document = OfdDocument::new();
    document
        .add_path_page(
            "M 0 0 L 20 0 L 20 20 L 0 20 C",
            [0.0, 0.0, 20.0, 20.0],
            20.0,
            20.0,
            true,
            false,
        )
        .unwrap();
    let second_id = document
        .add_path_object(
            0,
            "M 0 0 L 20 0 L 20 20 L 0 20 C",
            [0.0, 0.0, 20.0, 20.0],
            PathStyle {
                fill: true,
                stroke: false,
                fill_color: Some([0, 255, 0]),
                ..PathStyle::default()
            },
        )
        .unwrap();
    let path = document.pages().unwrap()[0].path.clone();
    let source = std::str::from_utf8(document.entry(&path).unwrap().unwrap())
        .unwrap()
        .to_owned();
    let original_tag = format!("<ofd:PathObject ID=\"{second_id}\"");
    let blended = source.replace(
        &original_tag,
        &format!("<ofd:PathObject BlendMode=\"Darken\" ID=\"{second_id}\""),
    );
    document
        .set_entry(&path, blended.clone().into_bytes())
        .unwrap();
    let svg = document.page_svg(0).unwrap();
    assert!(svg.contains("style=\"mix-blend-mode:darken\""));
    let png = resvg::tiny_skia::Pixmap::decode_png(&document.page_png(0, 25.4).unwrap()).unwrap();
    let pixel = png.pixel(10, 10).unwrap();
    assert!(pixel.red() < 16 && pixel.green() < 16 && pixel.blue() < 16);
    let pdf = document.to_pdf().unwrap();
    assert!(lopdf::Document::load_mem(&pdf).is_ok());
    assert!(String::from_utf8_lossy(&pdf).contains("/Darken"));
    document
        .set_entry(
            &path,
            blended
                .replace("BlendMode=\"Darken\"", "BlendMode=\"Invalid\"")
                .into_bytes(),
        )
        .unwrap();
    assert!(document.page_svg(0).is_err());
}

