#[test]
fn reference_validation_checks_document_and_page_resource_ids() {
    let mut document = OfdDocument::new();
    document.add_text_page("page", 40.0, 30.0).unwrap();
    let public_path = "Doc_0/PublicRes.xml";
    let original = std::str::from_utf8(document.entry(public_path).unwrap().unwrap())
        .unwrap()
        .to_owned();
    assert!(document.validate_references().unwrap().is_empty());

    for (extra, code) in [
        ("<ofd:Font ID=\"01\"/>", "duplicate_resource_id"),
        ("<ofd:Font/>", "missing_resource_id"),
        ("<ofd:Font ID=\"bad\"/>", "invalid_resource_id"),
        ("<ofd:Font ID=\"999999\"/>", "id_exceeds_max"),
    ] {
        let changed = original.replace("</ofd:Fonts>", &format!("{extra}</ofd:Fonts>"));
        document
            .set_entry(public_path, changed.into_bytes())
            .unwrap();
        assert!(document
            .validate_references()
            .unwrap()
            .iter()
            .any(|issue| issue.path == public_path && issue.code == code));
    }
    let cross_kind = original.replace(
        "</ofd:Res>",
        "<ofd:DrawParams><ofd:DrawParam ID=\"1\"/></ofd:DrawParams></ofd:Res>",
    );
    document
        .set_entry(public_path, cross_kind.into_bytes())
        .unwrap();
    assert!(document
        .validate_references()
        .unwrap()
        .iter()
        .any(|issue| { issue.path == public_path && issue.code == "duplicate_resource_id" }));
    document
        .set_entry(public_path, original.into_bytes())
        .unwrap();

    let page_path = document.pages().unwrap()[0].path.clone();
    let page = std::str::from_utf8(document.entry(&page_path).unwrap().unwrap())
        .unwrap()
        .to_owned();
    document
        .set_entry(
            &page_path,
            page.replace(
                "</ofd:Page>",
                "<ofd:PageRes>PageRes.xml</ofd:PageRes></ofd:Page>",
            )
            .into_bytes(),
        )
        .unwrap();
    let page_resource_path = "Doc_0/Pages/Page_0/PageRes.xml";
    document
        .set_entry(
            page_resource_path,
            b"<ofd:Res xmlns:ofd=\"http://www.ofdspec.org/2016\"><ofd:Fonts><ofd:Font ID=\"bad\"/></ofd:Fonts></ofd:Res>".to_vec(),
        )
        .unwrap();
    assert!(document
        .validate_references()
        .unwrap()
        .iter()
        .any(|issue| { issue.path == page_resource_path && issue.code == "invalid_resource_id" }));
}

