#[test]
fn validates_positive_numeric_page_object_ids_and_aliases() {
    let mut document = OfdDocument::new();
    document.add_text_page("text", 80.0, 50.0).unwrap();
    let path_id = document
        .add_path_object(
            0,
            "M 0 0 L 10 10",
            [20.0, 20.0, 10.0, 10.0],
            PathStyle::default(),
        )
        .unwrap();
    let text_id = document.page_text_objects(0).unwrap()[0]
        .id
        .clone()
        .unwrap();
    let page_path = document.pages().unwrap()[0].path.clone();
    let source = String::from_utf8(document.entry(&page_path).unwrap().unwrap().to_vec()).unwrap();
    let old = format!("<ofd:PathObject ID=\"{path_id}\"");
    assert!(source.contains(&old));

    document
        .set_entry(
            &page_path,
            source
                .replacen(&old, &format!("<ofd:PathObject ID=\"0{text_id}\""), 1)
                .into_bytes(),
        )
        .unwrap();
    assert!(document
        .validate_references()
        .unwrap()
        .iter()
        .any(|issue| issue.code == "duplicate_object_id" && issue.path == page_path));

    for invalid in ["0", "-1", "invalid"] {
        document
            .set_entry(
                &page_path,
                source
                    .replacen(&old, &format!("<ofd:PathObject ID=\"{invalid}\""), 1)
                    .into_bytes(),
            )
            .unwrap();
        assert!(document
            .validate_references()
            .unwrap()
            .iter()
            .any(|issue| issue.code == "invalid_object_id" && issue.path == page_path));
    }
}

