#[test]
fn validates_attachment_size_in_kilobytes() {
    let mut document = OfdDocument::new();
    document.add_attachment("note.txt", b"data").unwrap();
    let list_path = "Doc_0/Attachments.xml";
    let original = String::from_utf8(document.entry(list_path).unwrap().unwrap().to_vec()).unwrap();
    assert!(document.validate_references().unwrap().is_empty());

    for size in ["-1", "NaN", "inf", "not-a-number", ""] {
        let changed = original.replacen("Size=\"0.00390625\"", &format!("Size=\"{size}\""), 1);
        assert_ne!(changed, original);
        document.set_entry(list_path, changed.into_bytes()).unwrap();
        assert!(document
            .validate_references()
            .unwrap()
            .iter()
            .any(|issue| { issue.path == list_path && issue.code == "invalid_attachment_size" }));
    }

    document
        .set_entry(list_path, original.into_bytes())
        .unwrap();
    assert!(document.validate_references().unwrap().is_empty());
}

#[test]
fn validates_numeric_attachment_ids_and_normalized_action_targets() {
    let mut document = OfdDocument::new();
    document.add_text_page("open", 80.0, 40.0).unwrap();
    document.add_attachment("first.txt", b"first").unwrap();
    document.add_attachment("second.txt", b"second").unwrap();
    let attachments = document.attachments().unwrap();
    let first = &attachments[0].id;
    let second = &attachments[1].id;
    let object_id = document.page_objects(0).unwrap()[0].id.clone().unwrap();
    document
        .add_page_object_attachment_action(0, &object_id, first, None)
        .unwrap();
    let list_path = "Doc_0/Attachments.xml";
    let source = String::from_utf8(document.entry(list_path).unwrap().unwrap().to_vec()).unwrap();
    let page_path = document.pages().unwrap()[0].path.clone();
    let page = String::from_utf8(document.entry(&page_path).unwrap().unwrap().to_vec()).unwrap();
    assert!(page.contains(&format!("AttachID=\"{first}\"")));

    document
        .set_entry(
            list_path,
            source
                .replacen(&format!("ID=\"{second}\""), &format!("ID=\"0{first}\""), 1)
                .into_bytes(),
        )
        .unwrap();
    document
        .set_entry(
            &page_path,
            page.replacen(
                &format!("AttachID=\"{first}\""),
                &format!("AttachID=\"0{first}\""),
                1,
            )
            .into_bytes(),
        )
        .unwrap();
    let issues = document.validate_references().unwrap();
    assert!(issues
        .iter()
        .any(|issue| issue.code == "duplicate_attachment_id"));
    assert!(!issues
        .iter()
        .any(|issue| issue.code == "attachment_action_reference"));

    for invalid in ["0", "-1", "not-an-id"] {
        document
            .set_entry(
                list_path,
                source
                    .replacen(&format!("ID=\"{second}\""), &format!("ID=\"{invalid}\""), 1)
                    .into_bytes(),
            )
            .unwrap();
        let issues = document.validate_references().unwrap();
        assert!(issues
            .iter()
            .any(|issue| issue.code == "invalid_attachment_id"));
    }

    document
        .set_entry(
            list_path,
            source
                .replacen(&format!("ID=\"{second}\""), "ID=\"999999999\"", 1)
                .into_bytes(),
        )
        .unwrap();
    assert!(document
        .validate_references()
        .unwrap()
        .iter()
        .any(|issue| issue.code == "id_exceeds_max" && issue.message.contains("attachment")));
}

#[test]
fn checks_other_attachments_when_one_file_is_missing() {
    let mut document = OfdDocument::new();
    document.add_attachment("first.txt", b"first").unwrap();
    document.add_attachment("second.txt", b"second").unwrap();
    document.add_attachment("third.txt", b"third").unwrap();
    let attachments = document.attachments().unwrap();
    let list_path = "Doc_0/Attachments.xml";
    let source = std::str::from_utf8(document.entry(list_path).unwrap().unwrap()).unwrap();
    let changed = source.replacen(
        &format!("ID=\"{}\"", attachments[2].id),
        &format!("ID=\"{}\"", attachments[1].id),
        1,
    );
    let changed = changed.replace(&attachments[0].path, "Doc_0/Res/missing");
    document.set_entry(list_path, changed.into_bytes()).unwrap();

    let issues = document.validate_references().unwrap();
    assert!(issues.iter().any(|issue| {
        issue.code == "attachment_reference" && issue.message.contains("Doc_0/Res/missing")
    }));
    assert!(issues
        .iter()
        .any(|issue| issue.code == "duplicate_attachment_id"));
    assert_eq!(
        issues
            .iter()
            .filter(|issue| issue.code == "attachment_reference")
            .count(),
        1
    );
}

