#[test]
fn writes_and_renders_bmp_and_tiff_image_resources() {
    let pixels =
        image::RgbImage::from_raw(2, 2, vec![255, 0, 0, 0, 255, 0, 0, 0, 255, 255, 255, 0])
            .unwrap();
    for (input_format, image_format, resource_format) in [
        (image::ImageFormat::Bmp, "bmp", "BMP"),
        (image::ImageFormat::Tiff, "tiff", "TIFF"),
    ] {
        let mut encoded = Cursor::new(Vec::new());
        image::DynamicImage::ImageRgb8(pixels.clone())
            .write_to(&mut encoded, input_format)
            .unwrap();
        let bytes = encoded.into_inner();
        let mut document = OfdDocument::new();
        let before = document.to_bytes().unwrap();
        assert!(document
            .add_image_page(b"invalid", image_format, 20.0, 20.0)
            .is_err());
        assert_eq!(document.to_bytes().unwrap(), before);
        document
            .add_image_page(&bytes, image_format, 20.0, 20.0)
            .unwrap();
        assert_eq!(document.page_image_data(0, 0).unwrap(), bytes);
        assert_eq!(
            document.page_images(0).unwrap()[0].format.as_deref(),
            Some(resource_format)
        );
        assert!(document
            .page_svg(0)
            .unwrap()
            .contains("data:image/png;base64,"));
        let preview = image::load_from_memory(&document.page_png(0, 25.4).unwrap())
            .unwrap()
            .to_rgba8();
        let red = preview.get_pixel(2, 2);
        let green = preview.get_pixel(17, 2);
        assert!(red[0] > 220 && red[1] < 35 && red[2] < 35, "{red:?}");
        assert!(
            green[1] > 220 && green[0] < 35 && green[2] < 35,
            "{green:?}"
        );
        assert!(lopdf::Document::load_mem(&document.to_pdf().unwrap()).is_ok());
        let mut reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
        assert_eq!(reopened.page_image_data(0, 0).unwrap(), bytes);
        reopened
            .add_image_object(0, &bytes, image_format, [1.0, 1.0, 5.0, 5.0])
            .unwrap();
        reopened
            .append_image_page(0, &bytes, image_format, [20.0, 20.0])
            .unwrap();
        assert_eq!(reopened.page_images(0).unwrap().len(), 2);
        assert_eq!(reopened.page_image_data(1, 0).unwrap(), bytes);
        assert!(reopened.validate_references().unwrap().is_empty());
    }

    let mut multipage = Cursor::new(Vec::new());
    {
        let mut encoder = tiff::encoder::TiffEncoder::new(&mut multipage).unwrap();
        encoder
            .write_image::<tiff::encoder::colortype::RGB8>(1, 1, &[255, 0, 0])
            .unwrap();
        encoder
            .write_image::<tiff::encoder::colortype::RGB8>(1, 1, &[0, 255, 0])
            .unwrap();
    }
    let mut document = OfdDocument::new();
    let multipage = multipage.into_inner();
    document
        .add_image_page(&multipage, "tiff", 20.0, 20.0)
        .unwrap();
    assert_eq!(document.page_image_data(0, 0).unwrap(), multipage);
    let preview = image::load_from_memory(&document.page_png(0, 25.4).unwrap())
        .unwrap()
        .to_rgba8();
    let first_frame = preview.get_pixel(10, 10);
    assert!(
        first_frame[0] > 220 && first_frame[1] < 35 && first_frame[2] < 35,
        "{first_frame:?}"
    );
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.page_image_data(0, 0).unwrap(), multipage);
}

#[test]
fn writes_and_renders_jpeg2000_container_and_codestream() {
    let jp2 = include_bytes!("fixtures/red-32x32.jp2");
    let codestream = include_bytes!("fixtures/blue-32x32.j2k");
    for (format, bytes, expected_color) in [
        ("jp2", jp2.as_slice(), [255, 0, 0]),
        ("j2k", codestream.as_slice(), [0, 0, 255]),
    ] {
        let mut document = OfdDocument::new();
        let before = document.to_bytes().unwrap();
        assert!(document
            .add_image_page(b"invalid", format, 32.0, 32.0)
            .is_err());
        assert!(document
            .add_image_page(&bytes[..20], format, 32.0, 32.0)
            .is_err());
        assert_eq!(document.to_bytes().unwrap(), before);
        document.add_image_page(bytes, format, 32.0, 32.0).unwrap();
        assert_eq!(document.page_image_data(0, 0).unwrap(), bytes);
        assert_eq!(
            document.page_images(0).unwrap()[0].format.as_deref(),
            Some("JPEG2000")
        );
        assert!(document
            .page_svg(0)
            .unwrap()
            .contains("data:image/png;base64,"));
        let preview = image::load_from_memory(&document.page_png(0, 25.4).unwrap())
            .unwrap()
            .to_rgba8();
        let pixel = preview.get_pixel(16, 16);
        for (actual, expected) in pixel.0[..3].iter().zip(expected_color) {
            assert!(actual.abs_diff(expected) < 10, "{pixel:?}");
        }
        assert!(lopdf::Document::load_mem(&document.to_pdf().unwrap()).is_ok());
        let extra_id = document
            .add_multimedia_resource(0, "Image", "JPEG2000", bytes)
            .unwrap();
        assert_eq!(
            document.document_multimedia_data(0, &extra_id).unwrap(),
            bytes
        );
        document
            .add_image_object(0, bytes, format, [1.0, 1.0, 5.0, 5.0])
            .unwrap();
        assert!(document.validate_references().unwrap().is_empty());
        let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
        assert_eq!(reopened.page_image_data(0, 0).unwrap(), bytes);
        assert!(reopened
            .page_svg(0)
            .unwrap()
            .contains("data:image/png;base64,"));
    }
}

