#[test]
fn page_resolves_local_multimedia_before_document_resources() {
    let source = OfdDocument::open(fixture("发票示例.ofd")).unwrap();
    let png = source.page_image_data(0, 0).unwrap();
    let mut document = OfdDocument::new();
    document
        .add_path_page(
            "M 0 0 L 20 0 L 20 20 L 0 20 C",
            [0.0, 0.0, 20.0, 20.0],
            20.0,
            20.0,
            true,
            false,
        )
        .unwrap();
    let page_path = document.pages().unwrap()[0].path.clone();
    let page = std::str::from_utf8(document.entry(&page_path).unwrap().unwrap())
        .unwrap()
        .to_owned();
    let start = page.find("<ofd:PathObject").unwrap();
    let end = page.find("</ofd:PathObject>").unwrap() + "</ofd:PathObject>".len();
    let page = format!(
        "{}<ofd:ImageObject ID=\"3\" ResourceID=\"40\" Boundary=\"0 0 20 20\"/>{}",
        &page[..start],
        &page[end..]
    )
    .replace(
        "<ofd:Content>",
        "<ofd:PageRes>PageRes.xml</ofd:PageRes><ofd:Content>",
    );
    document.set_entry(&page_path, page.into_bytes()).unwrap();
    let resource_path = format!("{}/PageRes.xml", page_path.rsplit_once('/').unwrap().0);
    let image_path = format!("{}/Res/sample.png", page_path.rsplit_once('/').unwrap().0);
    document
        .set_entry(
            &resource_path,
            "<ofd:Res xmlns:ofd=\"http://www.ofdspec.org/2016\" BaseLoc=\"Res\"><ofd:MultiMedias><ofd:MultiMedia ID=\"40\" Type=\"Image\" Format=\"PNG\"><ofd:MediaFile>sample.png</ofd:MediaFile></ofd:MultiMedia></ofd:MultiMedias></ofd:Res>".as_bytes().to_vec(),
        )
        .unwrap();
    document.set_entry(&image_path, png.to_vec()).unwrap();

    let images = document.page_images(0).unwrap();
    assert_eq!(images[0].media_path.as_deref(), Some(image_path.as_str()));
    assert_eq!(document.page_image_data(0, 0).unwrap(), png);
    assert!(document
        .page_svg(0)
        .unwrap()
        .contains("data:image/png;base64,"));
    assert!(document.page_png(0, 25.4).unwrap().starts_with(b"\x89PNG"));
    assert!(!document
        .validate_references()
        .unwrap()
        .iter()
        .any(|issue| issue.code == "missing_media"));
}

#[test]
fn renders_java_jbig2_image_resource() {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../../ofdrw-layout/src/test/resources/keyword2.ofd");
    let document = OfdDocument::open(path).unwrap();
    let image = &document.page_images(0).unwrap()[0];
    assert_eq!(image.format.as_deref(), Some("GBIG2"));
    let source = document.page_image_data(0, 0).unwrap();
    assert!(source.starts_with(&justbig2::header::MAGIC));
    let converted = justbig2::decode(source).unwrap();
    assert_eq!(converted.len(), 1);
    let svg = document.page_svg(0).unwrap();
    assert!(svg.contains("href=\"data:image/png;base64,"));
    assert!(document.page_png(0, 25.4).unwrap().starts_with(b"\x89PNG"));
    assert!(lopdf::Document::load_mem(&document.to_pdf().unwrap()).is_ok());

    let (header, start) = justbig2::header::FileHeader::parse(source)
        .unwrap()
        .unwrap();
    assert_eq!(header.n_pages, Some(1));
    let (_, header_len) = justbig2::segment::SegmentHeader::parse(&source[start..])
        .unwrap()
        .unwrap();
    let mut oversized = source.to_vec();
    oversized[start + header_len..start + header_len + 4].copy_from_slice(&u32::MAX.to_be_bytes());
    let mut invalid = document.clone();
    invalid
        .set_entry(image.media_path.as_ref().unwrap(), oversized)
        .unwrap();
    assert!(invalid.page_svg(0).is_err());
}

