#[test]
fn creates_composite_path_on_unprefixed_page_without_content() {
    let mut document = OfdDocument::new();
    document.add_text_page("old", 30.0, 30.0).unwrap();
    let path = document.pages().unwrap()[0].path.clone();
    let original = std::str::from_utf8(document.entry(&path).unwrap().unwrap())
        .unwrap()
        .to_owned();
    let start = original.find("<ofd:Content>").unwrap();
    let end = original.find("</ofd:Content>").unwrap() + "</ofd:Content>".len();
    let mut page = original;
    page.replace_range(start..end, "");
    page = page
        .replace("xmlns:ofd=", "xmlns=")
        .replace("<ofd:", "<")
        .replace("</ofd:", "</");
    document.set_entry(&path, page.into_bytes()).unwrap();
    let id = document
        .add_composite_path_object(
            0,
            "M 0 0 L 10 0 L 10 10 C",
            [1.0, 2.0, 10.0, 10.0],
            PathStyle {
                fill: true,
                stroke: false,
                ..Default::default()
            },
        )
        .unwrap();
    let page = std::str::from_utf8(document.entry(&path).unwrap().unwrap()).unwrap();
    assert!(page.contains("<Content><Layer"));
    let root = std::str::from_utf8(document.entry("Doc_0/Document.xml").unwrap().unwrap()).unwrap();
    assert!(root.contains("<ofd:DocumentRes>CompositeRes_"));
    assert_eq!(
        document.page_composite_objects(0).unwrap()[0].id.as_deref(),
        Some(id.as_str())
    );
    assert!(document.page_svg(0).unwrap().contains("<path "));
    assert!(document.validate_references().unwrap().is_empty());
}

#[test]
fn reports_duplicate_resource_ids_across_resource_files() {
    let mut document = OfdDocument::new();
    document.add_blank_page(30.0, 30.0).unwrap();
    for x in [1.0, 12.0] {
        document
            .add_composite_path_object(
                0,
                "M 0 0 L 10 0 L 10 10 C",
                [x, 1.0, 10.0, 10.0],
                PathStyle::default(),
            )
            .unwrap();
    }
    assert!(document.validate_references().unwrap().is_empty());
    let objects = document.page_composite_objects(0).unwrap();
    let first = &objects[0].resource_id;
    let second = &objects[1].resource_id;
    let path = format!("Doc_0/CompositeRes_{second}.xml");
    let xml = String::from_utf8(document.entry(&path).unwrap().unwrap().to_vec()).unwrap();
    let duplicate = xml.replacen(
        &format!("<ofd:CompositeGraphicUnit ID=\"{second}\""),
        &format!("<ofd:CompositeGraphicUnit ID=\"0{first}\""),
        1,
    );
    assert_ne!(duplicate, xml);
    document.set_entry(&path, duplicate.into_bytes()).unwrap();
    assert!(document.validate_references().unwrap().iter().any(|issue| {
        issue.path == path
            && issue.code == "duplicate_resource_id"
            && issue.message.contains(&format!("CompositeRes_{first}.xml"))
    }));
}

#[test]
fn validates_composite_resource_object_ids_once_across_pages() {
    let mut document = OfdDocument::new();
    document.add_blank_page(30.0, 30.0).unwrap();
    document.add_blank_page(30.0, 30.0).unwrap();
    document
        .add_composite_path_object(
            0,
            "M 0 0 L 10 0 L 10 10 C",
            [1.0, 1.0, 10.0, 10.0],
            PathStyle::default(),
        )
        .unwrap();
    let unit_id = document.page_composite_objects(0).unwrap()[0]
        .resource_id
        .clone();
    document
        .add_composite_object(1, &unit_id, [1.0, 1.0, 10.0, 10.0], Default::default())
        .unwrap();
    assert!(document.validate_references().unwrap().is_empty());

    let path = format!("Doc_0/CompositeRes_{unit_id}.xml");
    let source = String::from_utf8(document.entry(&path).unwrap().unwrap().to_vec()).unwrap();
    let child_id = source
        .split("<ofd:PathObject ID=\"")
        .nth(1)
        .unwrap()
        .split('"')
        .next()
        .unwrap()
        .parse::<u64>()
        .unwrap();
    let root_path = "Doc_0/Document.xml";
    let root = String::from_utf8(document.entry(root_path).unwrap().unwrap().to_vec()).unwrap();
    let max = root
        .split("<ofd:MaxUnitID>")
        .nth(1)
        .unwrap()
        .split('<')
        .next()
        .unwrap();
    let mut stale = document.clone();
    stale
        .set_entry(
            root_path,
            root.replace(
                &format!("<ofd:MaxUnitID>{max}</ofd:MaxUnitID>"),
                &format!("<ofd:MaxUnitID>{}</ofd:MaxUnitID>", child_id - 1),
            )
            .into_bytes(),
        )
        .unwrap();
    assert!(stale.validate_references().unwrap().iter().any(|issue| {
        issue.path == path && issue.code == "id_exceeds_max" && issue.message.contains("object ID")
    }));

    let mut duplicate = document.clone();
    let duplicate_xml = source.replacen(
        &format!("<ofd:PathObject ID=\"{child_id}\""),
        &format!("<ofd:PathObject ID=\"{}\"", child_id - 1),
        1,
    );
    duplicate
        .set_entry(&path, duplicate_xml.into_bytes())
        .unwrap();
    assert!(duplicate
        .validate_references()
        .unwrap()
        .iter()
        .any(|issue| { issue.path == path && issue.code == "duplicate_object_id" }));
}

#[test]
fn creates_composite_text_resource_and_preserves_font_reference() {
    let mut document = OfdDocument::new();
    document.add_text_page("base", 60.0, 40.0).unwrap();
    let before = document.to_bytes().unwrap();
    let text = "A&B<中>";
    let id = document
        .add_composite_text_object(0, text, [5.0, 6.0, 30.0, 8.0], 5.0, Some("1"))
        .unwrap();
    let objects = document.page_composite_objects(0).unwrap();
    assert_eq!(objects.len(), 1);
    assert_eq!(objects[0].id.as_deref(), Some(id.as_str()));
    assert_eq!(document.page_text(0).unwrap(), ["base", text]);
    let svg = document.page_svg(0).unwrap();
    assert!(svg.contains("A&amp;B&lt;中&gt;"));
    assert!(document.page_png(0, 25.4).unwrap().starts_with(b"\x89PNG"));
    assert!(document.to_pdf().unwrap().starts_with(b"%PDF-"));
    assert!(document.validate_references().unwrap().is_empty());
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.page_text(0).unwrap(), ["base", text]);
    assert!(reopened.validate_references().unwrap().is_empty());
    assert_ne!(document.to_bytes().unwrap(), before);

    let snapshot = document.to_bytes().unwrap();
    for (value, boundary, size, font) in [
        ("", [5.0, 6.0, 30.0, 8.0], 5.0, Some("1")),
        ("bad", [5.0, 6.0, 0.0, 8.0], 5.0, Some("1")),
        ("bad", [5.0, 6.0, 30.0, 8.0], 0.0, Some("1")),
        ("bad", [5.0, 6.0, 30.0, 8.0], 5.0, Some("missing")),
    ] {
        assert!(document
            .add_composite_text_object(0, value, boundary, size, font)
            .is_err());
    }
    assert!(matches!(
        document.add_composite_text_object(1, "bad", [0.0, 0.0, 10.0, 10.0], 5.0, None),
        Err(OfdError::PageIndex { .. })
    ));
    assert_eq!(document.to_bytes().unwrap(), snapshot);
}

