#[test]
fn plain_and_styled_flow_prefer_word_boundaries_through_package_round_trip() {
    let font = std::fs::read(
        PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../../ofdrw-layout/src/test/resources/simhei-cut1.ttf"),
    )
    .unwrap();
    let mut document = OfdDocument::new();
    let font_id = document.add_embedded_font("SimHei", &font).unwrap();
    let style = ofdrw::FlowTextStyle {
        page_size: [6.0, 8.0],
        margins: [1.0, 1.0, 1.0, 1.0],
        font_size: 1.0,
        line_height: 1.5,
        font_id: Some(font_id.to_string()),
        ..ofdrw::FlowTextStyle::default()
    };
    assert_eq!(
        document
            .add_flowed_text(0, "hello world", style.clone())
            .unwrap(),
        [0]
    );
    assert_eq!(document.page_text(0).unwrap(), ["hello ", "world"]);
    let spans = [
        ofdrw::FlowSpan::new("hello "),
        ofdrw::FlowSpan::new("world"),
    ];
    assert_eq!(
        document.add_flowed_spans(0, &spans, style.clone()).unwrap(),
        [1]
    );
    assert_eq!(document.page_text(1).unwrap(), ["hello ", "world"]);
    assert_eq!(
        document
            .add_flowed_text(0, "A\r\nB\u{2028}C", style.clone())
            .unwrap(),
        [2]
    );
    assert_eq!(document.page_text(2).unwrap(), ["A", "B", "C"]);
    let spans = [
        ofdrw::FlowSpan::new("A\r"),
        ofdrw::FlowSpan::new("\nB\u{2028}C"),
    ];
    assert_eq!(document.add_flowed_spans(0, &spans, style).unwrap(), [3]);
    assert_eq!(document.page_text(3).unwrap(), ["A", "B", "C"]);
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.page_text(0).unwrap(), ["hello ", "world"]);
    assert_eq!(reopened.page_text(1).unwrap(), ["hello ", "world"]);
    assert_eq!(reopened.page_text(2).unwrap(), ["A", "B", "C"]);
    assert_eq!(reopened.page_text(3).unwrap(), ["A", "B", "C"]);
    assert!(reopened.validate_references().unwrap().is_empty());
}

#[test]
fn flowed_text_aligns_lines_and_indents_only_first_line() {
    let font = std::fs::read(
        PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../../ofdrw-layout/src/test/resources/simhei-cut1.ttf"),
    )
    .unwrap();
    let mut document = OfdDocument::new();
    let font_id = document.add_embedded_font("SimHei", &font).unwrap();
    let style = ofdrw::FlowTextStyle {
        page_size: [30.0, 22.0],
        margins: [5.0; 4],
        font_size: 5.0,
        line_height: 6.0,
        paragraph_gap: 0.0,
        keep_paragraphs_together: false,
        font_id: Some(font_id.to_string()),
        align: ofdrw::FlowTextAlign::Right,
        first_line_indent: 5.0,
        rest_line_indent: 0.0,
        first_line_indent_chars: 0,
        indent_each_paragraph: false,
        shape: false,
        language: None,
    };
    assert_eq!(
        document
            .add_flowed_text(0, "中文中文中\n中", style.clone())
            .unwrap(),
        [0, 1]
    );
    let first = document.page_text_objects(0).unwrap();
    let second = document.page_text_objects(1).unwrap();
    assert_eq!(first[0].boundary, Some([10.0, 5.0, 15.0, 6.0]));
    assert_eq!(first[1].boundary, Some([15.0, 11.0, 10.0, 6.0]));
    assert_eq!(second[0].boundary, Some([20.0, 5.0, 5.0, 6.0]));
    assert_eq!(document.page_text(0).unwrap(), ["中文中", "文中"]);
    assert_eq!(document.page_text(1).unwrap(), ["中"]);
    assert!(document.validate_references().unwrap().is_empty());
    assert_eq!(
        document
            .add_flowed_text(
                0,
                "中",
                ofdrw::FlowTextStyle {
                    align: ofdrw::FlowTextAlign::Center,
                    first_line_indent: 0.0,
                    ..style.clone()
                }
            )
            .unwrap(),
        [2]
    );
    assert_eq!(
        document.page_text_objects(2).unwrap()[0].boundary,
        Some([12.5, 5.0, 5.0, 6.0])
    );
    let left_style = ofdrw::FlowTextStyle {
        align: ofdrw::FlowTextAlign::Left,
        ..style.clone()
    };
    assert_eq!(
        document
            .add_flowed_text(0, "中\n中", left_style.clone())
            .unwrap(),
        [3]
    );
    let plain = document.page_text_objects(3).unwrap();
    assert_eq!(plain[0].boundary, Some([10.0, 5.0, 5.0, 6.0]));
    assert_eq!(plain[1].boundary, Some([5.0, 11.0, 5.0, 6.0]));
    assert_eq!(
        document
            .add_flowed_spans(0, &[ofdrw::FlowSpan::new("中\n中")], left_style)
            .unwrap(),
        [4]
    );
    let styled = document.page_text_objects(4).unwrap();
    assert_eq!(styled[0].boundary, Some([10.0, 5.0, 5.0, 6.0]));
    assert_eq!(styled[1].boundary, Some([5.0, 11.0, 5.0, 6.0]));
    assert_eq!(
        document.add_flowed_text(0, "中\n", style.clone()).unwrap(),
        [5]
    );
    assert_eq!(document.page_text(5).unwrap(), ["中"]);
    assert_eq!(
        document
            .add_flowed_spans(0, &[ofdrw::FlowSpan::new("中\n")], style.clone())
            .unwrap(),
        [6]
    );
    assert_eq!(document.page_text(6).unwrap(), ["中"]);
    let before = document.to_bytes().unwrap();
    assert!(document.add_flowed_text(0, "\n\n", style.clone()).is_err());
    assert!(document
        .add_flowed_spans(0, &[ofdrw::FlowSpan::new("\n\n")], style.clone())
        .is_err());
    assert!(document
        .add_flowed_text(
            0,
            "bad",
            ofdrw::FlowTextStyle {
                first_line_indent: 20.0,
                ..style.clone()
            }
        )
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
}

#[test]
fn flowed_text_can_indent_each_paragraph_in_plain_styled_and_shaped_modes() {
    let font = include_bytes!("fixtures/dejavu-serif.ttf");
    let mut document = OfdDocument::new();
    let font_id = document.add_embedded_font("DejaVu Serif", font).unwrap();
    let style = ofdrw::FlowTextStyle {
        page_size: [40.0, 40.0],
        margins: [2.0; 4],
        font_size: 4.0,
        line_height: 5.0,
        font_id: Some(font_id.to_string()),
        first_line_indent: 5.0,
        indent_each_paragraph: true,
        ..ofdrw::FlowTextStyle::default()
    };
    assert_eq!(
        document.add_flowed_text(0, "A\nA", style.clone()).unwrap(),
        [0]
    );
    let span = ofdrw::FlowSpan::new("A\nA");
    assert_eq!(
        document
            .add_flowed_spans(0, std::slice::from_ref(&span), style.clone())
            .unwrap(),
        [1]
    );
    let mut shaped = style.clone();
    shaped.shape = true;
    assert_eq!(
        document.add_flowed_text(0, "A\nA", shaped.clone()).unwrap(),
        [2]
    );
    assert_eq!(document.add_flowed_spans(0, &[span], shaped).unwrap(), [3]);
    for page in 0..4 {
        let objects = document.page_text_objects(page).unwrap();
        assert_eq!(objects.len(), 2);
        assert_eq!(objects[0].boundary.unwrap()[0], 7.0);
        assert_eq!(objects[1].boundary.unwrap()[0], 7.0);
    }
    let mut first = ofdrw::FlowSpan::new("A");
    first.line_break_after = true;
    document
        .add_flowed_spans(0, &[first, ofdrw::FlowSpan::new("A")], style.clone())
        .unwrap();
    let objects = document.page_text_objects(4).unwrap();
    assert_eq!(
        objects
            .iter()
            .map(|object| object.boundary.unwrap()[0])
            .collect::<Vec<_>>(),
        [7.0, 7.0]
    );
    document
        .add_flowed_spans(
            0,
            &[ofdrw::FlowSpan::new("A\r"), ofdrw::FlowSpan::new("\nA")],
            style.clone(),
        )
        .unwrap();
    let objects = document.page_text_objects(5).unwrap();
    assert_eq!(
        objects
            .iter()
            .map(|object| object.boundary.unwrap()[0])
            .collect::<Vec<_>>(),
        [7.0, 7.0]
    );
    let mut default = style;
    default.indent_each_paragraph = false;
    document.add_flowed_text(0, "A\nA", default).unwrap();
    assert_eq!(
        document.page_text_objects(6).unwrap()[1].boundary.unwrap()[0],
        2.0
    );
    assert!(document.validate_references().unwrap().is_empty());
}

#[test]
fn flowed_paragraph_gap_paginates_plain_styled_and_shaped_text() {
    let font = include_bytes!("fixtures/dejavu-serif.ttf");
    let mut document = OfdDocument::new();
    let font_id = document.add_embedded_font("DejaVu Serif", font).unwrap();
    let style = ofdrw::FlowTextStyle {
        page_size: [30.0, 22.0],
        margins: [2.0; 4],
        font_size: 4.0,
        line_height: 5.0,
        paragraph_gap: 3.0,
        font_id: Some(font_id.to_string()),
        ..ofdrw::FlowTextStyle::default()
    };
    let text = "A\nB\nC";
    assert_eq!(
        document.add_flowed_text(0, text, style.clone()).unwrap(),
        [0, 1]
    );
    assert_eq!(
        document
            .add_flowed_spans(0, &[ofdrw::FlowSpan::new(text)], style.clone())
            .unwrap(),
        [2, 3]
    );
    let mut shaped = style.clone();
    shaped.shape = true;
    assert_eq!(
        document.add_flowed_text(0, text, shaped.clone()).unwrap(),
        [4, 5]
    );
    assert_eq!(
        document
            .add_flowed_spans(0, &[ofdrw::FlowSpan::new(text)], shaped)
            .unwrap(),
        [6, 7]
    );
    for first_page in [0, 2, 4, 6] {
        let first = document.page_text_objects(first_page).unwrap();
        assert_eq!(
            first
                .iter()
                .map(|object| object.boundary.unwrap()[1])
                .collect::<Vec<_>>(),
            [2.0, 10.0]
        );
        assert_eq!(
            document.page_text_objects(first_page + 1).unwrap()[0]
                .boundary
                .unwrap()[1],
            2.0
        );
    }
    let before = document.to_bytes().unwrap();
    let invalid = ofdrw::FlowTextStyle {
        paragraph_gap: -1.0,
        ..style
    };
    assert!(document.add_flowed_text(0, text, invalid).is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
}

#[test]
fn flowed_paragraphs_can_stay_together_across_page_breaks() {
    let font = include_bytes!("fixtures/dejavu-serif.ttf");
    let mut document = OfdDocument::new();
    let font_id = document.add_embedded_font("DejaVu Serif", font).unwrap();
    let style = ofdrw::FlowTextStyle {
        page_size: [14.0, 18.0],
        margins: [2.0; 4],
        font_size: 4.0,
        line_height: 5.0,
        paragraph_gap: 2.0,
        keep_paragraphs_together: true,
        font_id: Some(font_id.to_string()),
        ..ofdrw::FlowTextStyle::default()
    };
    let text = "A\nBBBBB";
    assert_eq!(
        document.add_flowed_text(0, text, style.clone()).unwrap(),
        [0, 1]
    );
    assert_eq!(
        document
            .add_flowed_spans(0, &[ofdrw::FlowSpan::new(text)], style.clone())
            .unwrap(),
        [2, 3]
    );
    let mut shaped = style.clone();
    shaped.shape = true;
    assert_eq!(
        document.add_flowed_text(0, text, shaped.clone()).unwrap(),
        [4, 5]
    );
    assert_eq!(
        document
            .add_flowed_spans(0, &[ofdrw::FlowSpan::new(text)], shaped)
            .unwrap(),
        [6, 7]
    );
    for first_page in [0, 2, 4, 6] {
        assert_eq!(document.page_text(first_page).unwrap(), ["A"]);
        assert_eq!(document.page_text_objects(first_page + 1).unwrap().len(), 2);
        assert_eq!(
            document.page_text_objects(first_page + 1).unwrap()[0]
                .boundary
                .unwrap()[1],
            2.0
        );
    }
    let split = ofdrw::FlowTextStyle {
        keep_paragraphs_together: false,
        ..style.clone()
    };
    assert_eq!(document.add_flowed_text(0, text, split).unwrap(), [8, 9]);
    assert_eq!(document.page_text_objects(8).unwrap().len(), 2);
    assert_eq!(document.page_text_objects(9).unwrap().len(), 1);
    let before = document.to_bytes().unwrap();
    assert!(document.add_flowed_text(0, &"B".repeat(40), style).is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
}

#[test]
fn flowed_blank_paragraphs_keep_spacing_and_indentation() {
    let font = include_bytes!("fixtures/dejavu-serif.ttf");
    let mut document = OfdDocument::new();
    let font_id = document.add_embedded_font("DejaVu Serif", font).unwrap();
    let style = ofdrw::FlowTextStyle {
        page_size: [30.0, 40.0],
        margins: [2.0; 4],
        font_size: 4.0,
        line_height: 5.0,
        paragraph_gap: 1.0,
        first_line_indent: 2.0,
        indent_each_paragraph: true,
        keep_paragraphs_together: true,
        font_id: Some(font_id.to_string()),
        ..ofdrw::FlowTextStyle::default()
    };
    let text = "\nA\n\nB";
    assert_eq!(
        document.add_flowed_text(0, text, style.clone()).unwrap(),
        [0]
    );
    assert_eq!(
        document
            .add_flowed_spans(0, &[ofdrw::FlowSpan::new(text)], style.clone())
            .unwrap(),
        [1]
    );
    let mut shaped = style.clone();
    shaped.shape = true;
    assert_eq!(
        document.add_flowed_text(0, text, shaped.clone()).unwrap(),
        [2]
    );
    assert_eq!(
        document
            .add_flowed_spans(0, &[ofdrw::FlowSpan::new(text)], shaped)
            .unwrap(),
        [3]
    );
    for page in 0..4 {
        assert_eq!(document.page_text(page).unwrap(), ["A", "B"]);
        let objects = document.page_text_objects(page).unwrap();
        assert_eq!(
            objects
                .iter()
                .map(|object| object.boundary.unwrap()[1])
                .collect::<Vec<_>>(),
            [8.0, 20.0]
        );
        assert_eq!(
            objects
                .iter()
                .map(|object| object.boundary.unwrap()[0])
                .collect::<Vec<_>>(),
            [4.0, 4.0]
        );
    }
    let before = document.to_bytes().unwrap();
    let narrow = ofdrw::FlowTextStyle {
        page_size: [14.0, 18.0],
        first_line_indent: 0.0,
        ..style
    };
    assert!(document
        .add_flowed_spans(0, &[ofdrw::FlowSpan::new("B".repeat(40))], narrow.clone())
        .is_err());
    assert!(document
        .add_flowed_spans(
            0,
            &[ofdrw::FlowSpan::new("B".repeat(40))],
            ofdrw::FlowTextStyle {
                shape: true,
                ..narrow
            }
        )
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
}

