#[test]
fn flowed_spans_preserve_styles_and_baselines_across_pages() {
    let font = std::fs::read(
        PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../../ofdrw-layout/src/test/resources/simhei-cut1.ttf"),
    )
    .unwrap();
    let mut document = OfdDocument::new();
    let font_id = document.add_embedded_font("SimHei", &font).unwrap();
    let alternate_font_id = document
        .add_embedded_font("SimHei Alternate", &font)
        .unwrap();
    let mut red = ofdrw::FlowSpan::new("中");
    red.fill_color = Some([255, 0, 0]);
    red.bold = true;
    let mut blue = ofdrw::FlowSpan::new("文中文\n中");
    blue.font_id = Some(alternate_font_id.to_string());
    blue.font_size = Some(3.0);
    blue.fill_color = Some([0, 0, 255]);
    blue.italic = true;
    let style = ofdrw::FlowTextStyle {
        page_size: [25.0, 16.0],
        margins: [5.0; 4],
        font_size: 5.0,
        line_height: 6.0,
        paragraph_gap: 0.0,
        keep_paragraphs_together: false,
        font_id: Some(font_id.to_string()),
        align: ofdrw::FlowTextAlign::Right,
        first_line_indent: 1.0,
        rest_line_indent: 0.0,
        first_line_indent_chars: 0,
        indent_each_paragraph: false,
        shape: false,
        language: None,
    };
    assert_eq!(
        document
            .add_flowed_spans(0, &[red.clone(), blue.clone()], style.clone())
            .unwrap(),
        [0, 1]
    );
    let first = document.page_text_objects(0).unwrap();
    let second = document.page_text_objects(1).unwrap();
    assert_eq!(first.len(), 2);
    assert_eq!(
        first[0].font_id.as_deref(),
        Some(font_id.to_string().as_str())
    );
    assert_eq!(
        first[1].font_id.as_deref(),
        Some(alternate_font_id.to_string().as_str())
    );
    assert_eq!(first[0].boundary, Some([6.0, 5.0, 5.0, 6.0]));
    assert_eq!(first[1].boundary, Some([11.0, 5.0, 9.0, 6.0]));
    assert_eq!(second[0].boundary, Some([17.0, 5.0, 3.0, 4.0]));
    assert_eq!(document.page_text(0).unwrap(), ["中", "文中文"]);
    assert_eq!(document.page_text(1).unwrap(), ["中"]);
    let svg = document.page_svg(0).unwrap();
    assert!(svg.contains("#ff0000"));
    assert!(svg.contains("#0000ff"));
    assert!(svg.contains("font-weight=\"800\""));
    assert!(svg.contains("font-style=\"italic\""));
    assert!(document.validate_references().unwrap().is_empty());
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.page_text(0).unwrap(), ["中", "文中文"]);
    assert_eq!(reopened.page_text(1).unwrap(), ["中"]);

    let before = document.to_bytes().unwrap();
    blue.font_size = Some(7.0);
    assert!(document
        .add_flowed_spans(0, &[red.clone(), blue], style.clone())
        .is_err());
    assert!(document
        .add_flowed_spans(
            0,
            &[ofdrw::FlowSpan::new("中")],
            ofdrw::FlowTextStyle {
                font_id: Some("missing".into()),
                ..style.clone()
            }
        )
        .is_err());
    assert!(document.add_flowed_spans(0, &[], style).is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
}

#[test]
fn flowed_spans_use_tallest_font_on_each_line_for_pagination() {
    let mut document = OfdDocument::new();
    let style = ofdrw::FlowTextStyle {
        page_size: [40.0, 20.0],
        margins: [5.0; 4],
        ..ofdrw::FlowTextStyle::default()
    };
    let mut small = ofdrw::FlowSpan::new("x\n");
    small.font_size = Some(3.0);
    let mut second = ofdrw::FlowSpan::new("B\n");
    second.font_size = Some(3.0);
    let mut third = ofdrw::FlowSpan::new("C");
    third.font_size = Some(3.0);
    assert_eq!(
        document
            .add_flowed_spans(
                0,
                &[ofdrw::FlowSpan::new("A"), small, second, third],
                style.clone()
            )
            .unwrap(),
        [0, 1]
    );
    let first = document.page_text_objects(0).unwrap();
    assert_eq!(document.page_text(0).unwrap(), ["A", "x", "B"]);
    assert_eq!(first[0].boundary.unwrap()[1], 5.0);
    assert_eq!(first[0].boundary.unwrap()[3], 6.0);
    assert_eq!(first[1].boundary.unwrap()[1], 5.0);
    assert_eq!(first[1].boundary.unwrap()[3], 6.0);
    assert_eq!(first[2].boundary.unwrap()[1], 11.0);
    assert_eq!(first[2].boundary.unwrap()[3], 4.0);
    assert_eq!(document.page_text(1).unwrap(), ["C"]);
    assert_eq!(
        document.page_text_objects(1).unwrap()[0].boundary.unwrap()[3],
        4.0
    );
    assert!(document.validate_references().unwrap().is_empty());
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.page_text(0).unwrap(), ["A", "x", "B"]);
    assert_eq!(reopened.page_text(1).unwrap(), ["C"]);

    let mut larger = ofdrw::FlowSpan::new("L");
    larger.font_size = Some(7.0);
    assert_eq!(
        document
            .add_flowed_spans(0, &[larger], style.clone())
            .unwrap(),
        [2]
    );
    assert_eq!(
        document.page_text_objects(2).unwrap()[0].boundary.unwrap()[3],
        8.0
    );
    let before = document.to_bytes().unwrap();
    let mut too_tall = ofdrw::FlowSpan::new("Z");
    too_tall.font_size = Some(10.0);
    assert!(document.add_flowed_spans(0, &[too_tall], style).is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
}

