#[test]
fn flowed_text_uses_embedded_font_kerning_within_a_span() {
    let font = std::fs::read(
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/kerning-simhei.ttf"),
    )
    .unwrap();
    let mut document = OfdDocument::new();
    let font_id = document.add_embedded_font("Kerning Test", &font).unwrap();
    let style = ofdrw::FlowTextStyle {
        page_size: [14.5, 20.0],
        margins: [5.0; 4],
        font_id: Some(font_id.to_string()),
        ..ofdrw::FlowTextStyle::default()
    };
    assert_eq!(
        document.add_flowed_text(0, "HW", style.clone()).unwrap(),
        [0]
    );
    assert_eq!(document.page_text(0).unwrap(), ["HW"]);
    let plain = document.page_text_objects(0).unwrap();
    assert_eq!(plain[0].boundary.unwrap()[2], 3.75);
    assert_eq!(plain[0].codes[0].delta_x.as_deref(), Some("1.25"));
    assert!(document.page_svg(0).unwrap().contains("x=\"0 1.25\""));
    let mut kept = ofdrw::FlowSpan::new("HW");
    kept.keep_together = true;
    assert_eq!(
        document
            .add_flowed_spans(0, &[kept], style.clone())
            .unwrap(),
        [1]
    );
    let styled = document.page_text_objects(1).unwrap();
    assert_eq!(styled[0].boundary.unwrap()[2], 3.75);
    assert_eq!(styled[0].codes[0].delta_x.as_deref(), Some("1.25"));
    assert_eq!(
        document
            .add_flowed_spans(
                0,
                &[ofdrw::FlowSpan::new("H"), ofdrw::FlowSpan::new("W")],
                style
            )
            .unwrap(),
        [2, 3]
    );
    assert_eq!(document.page_text(2).unwrap(), ["H"]);
    assert_eq!(document.page_text(3).unwrap(), ["W"]);
    assert!(document.validate_references().unwrap().is_empty());
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.page_text(0).unwrap(), ["HW"]);
    assert_eq!(
        reopened.page_text_objects(1).unwrap()[0].codes[0]
            .delta_x
            .as_deref(),
        Some("1.25")
    );
}

#[test]
fn shaped_text_object_writes_ligature_mapping_and_renders_outline() {
    let font = std::fs::read(
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/dejavu-serif.ttf"),
    )
    .unwrap();
    let mut document = OfdDocument::new();
    let font_id = document.add_embedded_font("DejaVu Serif", &font).unwrap();
    document.add_blank_page(40.0, 20.0).unwrap();
    let id = document
        .add_shaped_text_object(0, "AfiB", [5.0, 5.0, 30.0, 10.0], 6.0, &font_id.to_string())
        .unwrap();
    assert_eq!(document.page_text(0).unwrap(), ["AfiB"]);
    let path = document.pages().unwrap()[0].path.clone();
    let xml = String::from_utf8(document.entry(&path).unwrap().unwrap().to_vec()).unwrap();
    assert!(xml.contains(&format!("TextObject ID=\"{id}\"")));
    assert!(xml.contains("CodePosition=\"1\" CodeCount=\"2\" GlyphCount=\"1\""));
    let objects = document.page_text_objects(0).unwrap();
    assert_eq!(objects[0].codes[0].text, "AfiB");
    assert!(objects[0].codes[0].delta_x.is_some());
    assert_eq!(objects[0].cg_transforms.len(), 3);
    assert_eq!(objects[0].cg_transforms[1].code_position, 1);
    assert_eq!(objects[0].cg_transforms[1].code_count, 2);
    assert_eq!(objects[0].cg_transforms[1].glyph_count, 1);
    assert_eq!(objects[0].cg_transforms[1].glyphs.len(), 1);
    let svg = document.page_svg(0).unwrap();
    assert!(svg.contains("data-ofd-glyph="));
    assert!(svg.contains(">AfiB</text>"));
    assert!(document.page_png(0, 25.4).unwrap().starts_with(b"\x89PNG"));
    assert!(document.to_pdf().unwrap().starts_with(b"%PDF-"));
    assert!(document.validate_references().unwrap().is_empty());
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.page_text(0).unwrap(), ["AfiB"]);
    assert!(reopened.page_svg(0).unwrap().contains("data-ofd-glyph="));

    let before = document.to_bytes().unwrap();
    assert!(document
        .add_shaped_text_object(0, "AfiB", [5.0, 5.0, 0.0, 10.0], 6.0, &font_id.to_string())
        .is_err());
    assert!(document
        .add_shaped_text_object(0, "A\nB", [5.0, 5.0, 30.0, 10.0], 6.0, &font_id.to_string())
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
}

#[test]
fn shaped_text_object_writes_right_to_left_glyph_order() {
    let font = std::fs::read(
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/dejavu-sans.ttf"),
    )
    .unwrap();
    let mut document = OfdDocument::new();
    let font_id = document.add_embedded_font("DejaVu Sans", &font).unwrap();
    document.add_blank_page(40.0, 20.0).unwrap();
    document
        .add_shaped_text_object(0, "سلام", [5.0, 5.0, 30.0, 10.0], 6.0, &font_id.to_string())
        .unwrap();
    let path = document.pages().unwrap()[0].path.clone();
    let xml = String::from_utf8(document.entry(&path).unwrap().unwrap().to_vec()).unwrap();
    let parsed = roxmltree::Document::parse(&xml).unwrap();
    let transform = parsed
        .descendants()
        .find(|node| node.tag_name().name() == "CGTransform")
        .unwrap();
    assert_eq!(transform.attribute("CodePosition"), Some("0"));
    assert_eq!(transform.attribute("CodeCount"), Some("4"));
    let actual_glyphs = transform
        .descendants()
        .find(|node| node.tag_name().name() == "Glyphs")
        .unwrap()
        .text()
        .unwrap()
        .split_whitespace()
        .map(str::parse::<u32>)
        .collect::<Result<Vec<_>, _>>()
        .unwrap();
    let face = rustybuzz::Face::from_slice(&font, 0).unwrap();
    let mut buffer = rustybuzz::UnicodeBuffer::new();
    buffer.push_str("سلام");
    buffer.guess_segment_properties();
    assert_eq!(buffer.direction(), rustybuzz::Direction::RightToLeft);
    let expected = rustybuzz::shape(&face, &[], buffer)
        .glyph_infos()
        .iter()
        .map(|glyph| glyph.glyph_id)
        .collect::<Vec<_>>();
    assert_eq!(actual_glyphs, expected);
    assert_eq!(
        document.page_text_objects(0).unwrap()[0].cg_transforms[0].glyphs,
        actual_glyphs
    );
    assert!(actual_glyphs.len() < 4);
    assert_eq!(document.page_text(0).unwrap(), ["سلام"]);
    let svg = document.page_svg(0).unwrap();
    assert_eq!(svg.matches("data-ofd-glyph=").count(), actual_glyphs.len());
    assert!(document.page_png(0, 25.4).unwrap().starts_with(b"\x89PNG"));
    assert!(document.to_pdf().unwrap().starts_with(b"%PDF-"));
    assert!(document.validate_references().unwrap().is_empty());
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.page_text(0).unwrap(), ["سلام"]);
    assert_eq!(
        reopened
            .page_svg(0)
            .unwrap()
            .matches("data-ofd-glyph=")
            .count(),
        actual_glyphs.len()
    );

    let before = document.to_bytes().unwrap();
    assert!(document
        .add_shaped_text_object(
            0,
            "A\nسلام",
            [5.0, 5.0, 30.0, 10.0],
            6.0,
            &font_id.to_string()
        )
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
}

#[test]
fn shaped_text_language_selects_localized_cyrillic_glyphs() {
    let font = include_bytes!("fixtures/dejavu-sans.ttf");
    let mut document = OfdDocument::new();
    let font_id = document.add_embedded_font("DejaVu Sans", font).unwrap();
    document.add_blank_page(40.0, 20.0).unwrap();
    let font_id = font_id.to_string();
    document
        .add_shaped_text_object_with_language(
            0,
            "бгдпт",
            [2.0, 2.0, 30.0, 6.0],
            5.0,
            &font_id,
            "ru",
        )
        .unwrap();
    document
        .add_shaped_text_object_with_language(
            0,
            "бгдпт",
            [2.0, 9.0, 30.0, 6.0],
            5.0,
            &font_id,
            "sr",
        )
        .unwrap();
    let objects = document.page_text_objects(0).unwrap();
    let glyphs = |index: usize| {
        objects[index]
            .cg_transforms
            .iter()
            .flat_map(|mapping| mapping.glyphs.iter().copied())
            .collect::<Vec<_>>()
    };
    assert_ne!(glyphs(0), glyphs(1));
    assert_eq!(document.page_text(0).unwrap(), ["бгдпт", "бгдпт"]);
    document
        .add_shaped_text_object_with_language(
            0,
            "AбгдптB",
            [2.0, 2.0, 30.0, 6.0],
            5.0,
            &font_id,
            "ru",
        )
        .unwrap();
    document
        .add_shaped_text_object_with_language(
            0,
            "AбгдптB",
            [2.0, 9.0, 30.0, 6.0],
            5.0,
            &font_id,
            "sr",
        )
        .unwrap();
    let mixed = document.page_text_objects(0).unwrap();
    let mixed_glyphs = |index: usize| {
        mixed[index]
            .cg_transforms
            .iter()
            .flat_map(|mapping| mapping.glyphs.iter().copied())
            .collect::<Vec<_>>()
    };
    assert_ne!(mixed_glyphs(2), mixed_glyphs(3));
    let before = document.to_bytes().unwrap();
    assert!(document
        .add_shaped_text_object_with_language(
            0,
            "бгдпт",
            [2.0, 2.0, 30.0, 6.0],
            5.0,
            &font_id,
            "sr__invalid",
        )
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
}

