#[test]
fn shaped_text_object_places_bidirectional_runs_and_keeps_logical_text() {
    let font = std::fs::read(
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/dejavu-sans.ttf"),
    )
    .unwrap();
    let mut document = OfdDocument::new();
    let font_id = document.add_embedded_font("DejaVu Sans", &font).unwrap();
    document.add_blank_page(50.0, 20.0).unwrap();
    document
        .add_shaped_text_object(
            0,
            "AسلامB",
            [5.0, 5.0, 40.0, 10.0],
            6.0,
            &font_id.to_string(),
        )
        .unwrap();
    let path = document.pages().unwrap()[0].path.clone();
    let xml = String::from_utf8(document.entry(&path).unwrap().unwrap().to_vec()).unwrap();
    assert!(xml.contains("CodePosition=\"0\" CodeCount=\"6\" GlyphCount=\"5\""));
    let parsed = roxmltree::Document::parse(&xml).unwrap();
    let glyphs = parsed
        .descendants()
        .find(|node| node.tag_name().name() == "Glyphs")
        .unwrap()
        .text()
        .unwrap()
        .split_whitespace()
        .map(str::parse::<u32>)
        .collect::<Result<Vec<_>, _>>()
        .unwrap();
    let face = rustybuzz::Face::from_slice(&font, 0).unwrap();
    let shape = |text: &str| {
        let mut buffer = rustybuzz::UnicodeBuffer::new();
        buffer.push_str(text);
        buffer.guess_segment_properties();
        rustybuzz::shape(&face, &[], buffer)
            .glyph_infos()
            .iter()
            .map(|glyph| glyph.glyph_id)
            .collect::<Vec<_>>()
    };
    let mut expected = shape("A");
    expected.extend(shape("سلام"));
    expected.extend(shape("B"));
    assert_eq!(glyphs, expected);
    let mapped = &document.page_text_objects(0).unwrap()[0].cg_transforms[0];
    assert_eq!(mapped.code_count, 6);
    assert_eq!(mapped.glyph_count, 5);
    assert_eq!(mapped.glyphs, glyphs);
    assert_eq!(document.page_text(0).unwrap(), ["AسلامB"]);
    let svg = document.page_svg(0).unwrap();
    assert_eq!(svg.matches("data-ofd-glyph=").count(), 5);
    assert!(document.page_png(0, 25.4).unwrap().starts_with(b"\x89PNG"));
    assert!(document.to_pdf().unwrap().starts_with(b"%PDF-"));
    assert!(document.validate_references().unwrap().is_empty());
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.page_text(0).unwrap(), ["AسلامB"]);
    assert_eq!(
        reopened
            .page_svg(0)
            .unwrap()
            .matches("data-ofd-glyph=")
            .count(),
        5
    );
}

#[test]
fn shaped_flow_wraps_ligatures_using_shaped_width_and_keeps_text() {
    let font = std::fs::read(
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/dejavu-serif.ttf"),
    )
    .unwrap();
    let mut document = OfdDocument::new();
    let font_id = document.add_embedded_font("DejaVu Serif", &font).unwrap();
    let style = ofdrw::FlowTextStyle {
        page_size: [14.5, 22.0],
        margins: [5.0; 4],
        font_size: 5.0,
        line_height: 6.0,
        font_id: Some(font_id.to_string()),
        shape: true,
        ..ofdrw::FlowTextStyle::default()
    };
    assert_eq!(
        document.add_flowed_text(0, "fifi", style.clone()).unwrap(),
        [0]
    );
    assert_eq!(document.page_text(0).unwrap(), ["fi", "fi"]);
    let objects = document.page_text_objects(0).unwrap();
    assert_eq!(objects.len(), 2);
    for object in &objects {
        assert!(object.boundary.unwrap()[2] <= 4.5);
        assert_eq!(object.cg_transforms[0].code_count, 2);
        assert_eq!(object.cg_transforms[0].glyph_count, 1);
    }
    assert_eq!(
        document
            .page_svg(0)
            .unwrap()
            .matches("data-ofd-glyph=")
            .count(),
        2
    );
    assert!(document.page_png(0, 25.4).unwrap().starts_with(b"\x89PNG"));
    assert!(document.to_pdf().unwrap().starts_with(b"%PDF-"));
    assert!(document.validate_references().unwrap().is_empty());
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.page_text(0).unwrap(), ["fi", "fi"]);

    let mut paged = OfdDocument::new();
    let paged_font = paged.add_embedded_font("DejaVu Serif", &font).unwrap();
    let paged_style = ofdrw::FlowTextStyle {
        font_id: Some(paged_font.to_string()),
        ..style.clone()
    };
    assert_eq!(
        paged.add_flowed_text(0, "fifi\nfifi", paged_style).unwrap(),
        [0, 1]
    );
    assert_eq!(paged.page_text(0).unwrap(), ["fi", "fi"]);
    assert_eq!(paged.page_text(1).unwrap(), ["fi", "fi"]);
    assert!(paged.validate_references().unwrap().is_empty());

    let before = document.to_bytes().unwrap();
    let narrow = ofdrw::FlowTextStyle {
        page_size: [11.0, 22.0],
        ..style.clone()
    };
    assert!(document.add_flowed_text(0, "a\u{301}", narrow).is_err());
    assert_eq!(document.to_bytes().unwrap(), before);

    let mut without_embedded_font = OfdDocument::new();
    let before = without_embedded_font.to_bytes().unwrap();
    assert!(without_embedded_font
        .add_flowed_text(
            0,
            "fi",
            ofdrw::FlowTextStyle {
                font_id: None,
                ..style
            },
        )
        .is_err());
    assert_eq!(without_embedded_font.to_bytes().unwrap(), before);
}

