#[test]
fn shaped_flow_language_controls_wrapping_and_span_overrides() {
    let font = include_bytes!("fixtures/dejavu-sans.ttf");
    let face = rustybuzz::Face::from_slice(font, 0).unwrap();
    let width = |language: &str, text: &str| {
        let mut buffer = rustybuzz::UnicodeBuffer::new();
        buffer.push_str(text);
        buffer.guess_segment_properties();
        buffer.set_language(language.parse().unwrap());
        rustybuzz::shape(&face, &[], buffer)
            .glyph_positions()
            .iter()
            .map(|position| f64::from(position.x_advance))
            .sum::<f64>()
            * 5.0
            / f64::from(face.units_per_em())
    };
    let ru_pair = width("ru", "бб");
    let sr_pair = width("sr", "бб");
    assert!(ru_pair > sr_pair);
    let available = (ru_pair + sr_pair) / 2.0;
    let mut document = OfdDocument::new();
    let font_id = document.add_embedded_font("DejaVu Sans", font).unwrap();
    let style = ofdrw::FlowTextStyle {
        page_size: [available + 2.0, 20.0],
        margins: [1.0; 4],
        font_size: 5.0,
        line_height: 6.0,
        font_id: Some(font_id.to_string()),
        shape: true,
        language: Some("ru".into()),
        ..ofdrw::FlowTextStyle::default()
    };
    assert_eq!(
        document.add_flowed_text(0, "бб", style.clone()).unwrap(),
        [0]
    );
    assert_eq!(document.page_text(0).unwrap(), ["б", "б"]);
    assert_eq!(
        document
            .add_flowed_text(
                0,
                "бб",
                ofdrw::FlowTextStyle {
                    language: Some("sr".into()),
                    ..style.clone()
                },
            )
            .unwrap(),
        [1]
    );
    assert_eq!(document.page_text(1).unwrap(), ["бб"]);
    assert!(document.page_text_objects(1).unwrap()[0].boundary.unwrap()[2] <= available);

    let mut second = ofdrw::FlowSpan::new("б");
    second.language = Some("sr".into());
    let mixed_width = width("ru", "б") + width("sr", "б");
    let styled = ofdrw::FlowTextStyle {
        page_size: [(mixed_width + ru_pair) / 2.0 + 2.0, 20.0],
        ..style.clone()
    };
    assert_eq!(
        document
            .add_flowed_spans(0, &[ofdrw::FlowSpan::new("б"), second], styled)
            .unwrap(),
        [2]
    );
    let objects = document.page_text_objects(2).unwrap();
    assert_eq!(objects.len(), 2);
    assert_eq!(
        objects[0].boundary.unwrap()[1],
        objects[1].boundary.unwrap()[1]
    );
    assert_ne!(
        objects[0].cg_transforms[0].glyphs,
        objects[1].cg_transforms[0].glyphs
    );

    let before = document.to_bytes().unwrap();
    assert!(document
        .add_flowed_text(
            0,
            "б",
            ofdrw::FlowTextStyle {
                shape: false,
                ..style.clone()
            },
        )
        .is_err());
    assert!(document
        .add_flowed_text(
            0,
            "б",
            ofdrw::FlowTextStyle {
                language: Some("sr__invalid".into()),
                ..style
            },
        )
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
}

#[test]
fn flowed_rest_line_indent_applies_to_plain_shaped_and_styled_lines() {
    let font = include_bytes!("fixtures/dejavu-sans.ttf");
    let mut document = OfdDocument::new();
    let font_id = document.add_embedded_font("DejaVu Sans", font).unwrap();
    let style = ofdrw::FlowTextStyle {
        page_size: [25.0, 80.0],
        margins: [2.0; 4],
        font_size: 5.0,
        line_height: 6.0,
        font_id: Some(font_id.to_string()),
        rest_line_indent: 4.0,
        ..ofdrw::FlowTextStyle::default()
    };
    let text = "AAAAAAAAAAAA";
    for shape in [false, true] {
        let mut shaped = style.clone();
        shaped.shape = shape;
        let page = document.add_flowed_text(0, text, shaped.clone()).unwrap()[0];
        let objects = document.page_text_objects(page).unwrap();
        assert!(objects.len() >= 2);
        assert_eq!(objects[0].boundary.unwrap()[0], 2.0);
        assert!(objects[1..]
            .iter()
            .all(|object| object.boundary.unwrap()[0] == 6.0));
        assert!(objects[1..]
            .iter()
            .all(|object| object.boundary.unwrap()[0] + object.boundary.unwrap()[2] <= 23.0));

        let page = document
            .add_flowed_spans(0, &[ofdrw::FlowSpan::new(text)], shaped)
            .unwrap()[0];
        let objects = document.page_text_objects(page).unwrap();
        assert!(objects.len() >= 2);
        assert_eq!(objects[0].boundary.unwrap()[0], 2.0);
        assert!(objects[1..]
            .iter()
            .all(|object| object.boundary.unwrap()[0] == 6.0));
    }
    let page = document
        .add_flowed_text(0, "AAAA\nAAAA", style.clone())
        .unwrap()[0];
    let objects = document.page_text_objects(page).unwrap();
    assert_eq!(objects.len(), 2);
    assert_eq!(objects[0].boundary.unwrap()[0], 2.0);
    assert_eq!(objects[1].boundary.unwrap()[0], 6.0);
    let page = document
        .add_flowed_text(
            0,
            "AAAA\nAAAA",
            ofdrw::FlowTextStyle {
                indent_each_paragraph: true,
                ..style.clone()
            },
        )
        .unwrap()[0];
    let objects = document.page_text_objects(page).unwrap();
    assert_eq!(objects.len(), 2);
    assert!(objects
        .iter()
        .all(|object| object.boundary.unwrap()[0] == 2.0));
    let before = document.to_bytes().unwrap();
    assert!(document
        .add_flowed_text(
            0,
            text,
            ofdrw::FlowTextStyle {
                rest_line_indent: 21.0,
                ..style.clone()
            },
        )
        .is_err());
    assert!(document
        .add_flowed_spans(
            0,
            &[ofdrw::FlowSpan::new(text)],
            ofdrw::FlowTextStyle {
                rest_line_indent: -1.0,
                ..style.clone()
            },
        )
        .is_err());
    for shape in [false, true] {
        assert!(document
            .add_flowed_spans(
                0,
                &[ofdrw::FlowSpan::new("AAAAAAA")],
                ofdrw::FlowTextStyle {
                    rest_line_indent: 20.0,
                    shape,
                    ..style.clone()
                },
            )
            .is_err());
    }
    assert_eq!(document.to_bytes().unwrap(), before);
}

#[test]
fn creates_layers_and_moves_page_objects_atomically() {
    let mut document = OfdDocument::new();
    document.add_blank_page(20.0, 20.0).unwrap();
    let background = document.add_page_layer(0, "Background", None).unwrap();
    let foreground = document.add_page_layer(0, "Foreground", None).unwrap();
    assert_eq!(document.page_layers(0).unwrap().len(), 3);
    let commands = "M 0 0 L 20 0 L 20 20 L 0 20 C";
    let blue = document
        .add_path_object(
            0,
            commands,
            [0.0, 0.0, 20.0, 20.0],
            PathStyle {
                fill: true,
                stroke: false,
                fill_color: Some([0, 0, 255]),
                ..PathStyle::default()
            },
        )
        .unwrap();
    document
        .move_page_object_to_layer(0, &blue, &background)
        .unwrap();
    let red = document
        .add_path_object(
            0,
            commands,
            [0.0, 0.0, 20.0, 20.0],
            PathStyle {
                fill: true,
                stroke: false,
                fill_color: Some([255, 0, 0]),
                ..PathStyle::default()
            },
        )
        .unwrap();
    document
        .move_page_object_to_layer(0, &red, &foreground)
        .unwrap();
    let layers = document.page_layers(0).unwrap();
    assert_eq!(
        layers
            .iter()
            .map(|layer| layer.object_count)
            .collect::<Vec<_>>(),
        [1, 0, 1]
    );
    let svg = document.page_svg(0).unwrap();
    assert!(svg.find("#0000ff").unwrap() < svg.find("#ff0000").unwrap());
    let png = resvg::tiny_skia::Pixmap::decode_png(&document.page_png(0, 25.4).unwrap()).unwrap();
    assert!(png.pixel(10, 10).unwrap().red() > 240);
    assert!(document.validate_references().unwrap().is_empty());
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.page_layers(0).unwrap(), layers);
    let before = document.to_bytes().unwrap();
    for invalid in ["Unknown", ""] {
        assert!(document.add_page_layer(0, invalid, None).is_err());
    }
    assert!(document.add_page_layer(0, "Body", Some("missing")).is_err());
    assert!(document.add_page_layer(1, "Body", None).is_err());
    assert!(document
        .move_page_object_to_layer(0, "missing", &foreground)
        .is_err());
    assert!(document
        .move_page_object_to_layer(0, &blue, "missing")
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    document
        .move_page_object_to_layer(0, &red, &foreground)
        .unwrap();
    assert_eq!(document.to_bytes().unwrap(), before);

    let mut opened = OfdDocument::open(fixture("helloworld.ofd")).unwrap();
    let original_text = opened.page_text(0).unwrap();
    let layer_id = opened.add_page_layer(0, "Foreground", None).unwrap();
    let text_id = opened.page_text_objects(0).unwrap()[0].id.clone().unwrap();
    opened
        .move_page_object_to_layer(0, &text_id, &layer_id)
        .unwrap();
    assert_eq!(opened.page_text(0).unwrap(), original_text);
    assert_eq!(
        opened.page_layers(0).unwrap().last().unwrap().id.as_deref(),
        Some(layer_id.as_str())
    );
    assert!(opened.validate_references().unwrap().is_empty());
}

#[test]
fn edits_layer_type_and_draw_param_without_losing_page_content() {
    let mut document = OfdDocument::new();
    document.add_text_page("layer text", 40.0, 30.0).unwrap();
    let layer_id = document.add_page_layer(0, "Foreground", None).unwrap();
    let path_id = document
        .add_path_object(
            0,
            "M 0 0 L 10 0",
            [2.0, 15.0, 10.0, 2.0],
            PathStyle::default(),
        )
        .unwrap();
    document
        .move_page_object_to_layer(0, &path_id, &layer_id)
        .unwrap();
    let param = document
        .add_document_draw_param(
            0,
            &DrawParamStyle {
                line_width: Some(1.25),
                stroke: Some(SolidPaintStyle {
                    color: [255, 0, 0],
                    alpha: 255,
                }),
                ..DrawParamStyle::default()
            },
        )
        .unwrap();
    document
        .set_page_layer_draw_param(0, &layer_id, Some(&param))
        .unwrap();
    document
        .set_page_layer_type(0, &layer_id, "background")
        .unwrap();
    document
        .set_page_layer_name(0, &layer_id, Some("图层 & A\tB"))
        .unwrap();
    let layers = document.page_layers(0).unwrap();
    assert_eq!(layers[0].id.as_deref(), Some(layer_id.as_str()));
    assert_eq!(layers[0].layer_type, "Background");
    assert_eq!(layers[0].name.as_deref(), Some("图层 & A\tB"));
    assert_eq!(layers[0].draw_param.as_deref(), Some(param.as_str()));
    assert_eq!(layers[0].object_count, 1);
    let paints = document.page_object_paints(0).unwrap();
    assert_eq!(
        paints[0].effective_stroke_draw_param.as_deref(),
        Some(param.as_str())
    );
    assert!(document.page_svg(0).unwrap().contains("stroke=\"#ff0000\""));
    assert_eq!(document.page_text(0).unwrap(), ["layer text"]);
    assert!(document.validate_references().unwrap().is_empty());
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.page_layers(0).unwrap(), layers);

    let before = document.to_bytes().unwrap();
    assert!(document
        .set_page_layer_type(0, &layer_id, "Invalid")
        .is_err());
    assert!(document
        .set_page_layer_draw_param(0, &layer_id, Some("missing"))
        .is_err());
    assert!(document.set_page_layer_type(0, "missing", "Body").is_err());
    assert!(document
        .set_page_layer_name(0, &layer_id, Some("bad\0name"))
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    document
        .set_page_layer_draw_param(0, &layer_id, None)
        .unwrap();
    document.set_page_layer_name(0, &layer_id, None).unwrap();
    assert_eq!(document.page_layers(0).unwrap()[0].name, None);
    assert_eq!(document.page_layers(0).unwrap()[0].draw_param, None);
}

#[test]
fn reorders_page_objects_and_preserves_layer_content() {
    let mut document = OfdDocument::new();
    document.add_blank_page(20.0, 20.0).unwrap();
    let commands = "M 0 0 L 20 0 L 20 20 L 0 20 C";
    let mut ids = Vec::new();
    for color in [[255, 0, 0], [0, 255, 0], [0, 0, 255]] {
        ids.push(
            document
                .add_path_object(
                    0,
                    commands,
                    [0.0, 0.0, 20.0, 20.0],
                    PathStyle {
                        fill: true,
                        stroke: false,
                        fill_color: Some(color),
                        ..PathStyle::default()
                    },
                )
                .unwrap(),
        );
    }
    let [red, green, blue] = ids.as_slice() else {
        panic!("three paths");
    };
    assert!(
        resvg::tiny_skia::Pixmap::decode_png(&document.page_png(0, 25.4).unwrap())
            .unwrap()
            .pixel(10, 10)
            .unwrap()
            .blue()
            > 240
    );
    document.move_page_object(0, blue, Some(red)).unwrap();
    assert_eq!(
        document
            .page_paths(0)
            .unwrap()
            .iter()
            .map(|path| path.id.as_deref())
            .collect::<Vec<_>>(),
        [
            Some(blue.as_str()),
            Some(red.as_str()),
            Some(green.as_str())
        ]
    );
    assert!(
        resvg::tiny_skia::Pixmap::decode_png(&document.page_png(0, 25.4).unwrap())
            .unwrap()
            .pixel(10, 10)
            .unwrap()
            .green()
            > 240
    );
    document.move_page_object(0, red, None).unwrap();
    assert_eq!(
        document
            .page_paths(0)
            .unwrap()
            .iter()
            .map(|path| path.id.as_deref())
            .collect::<Vec<_>>(),
        [
            Some(blue.as_str()),
            Some(green.as_str()),
            Some(red.as_str())
        ]
    );
    assert!(
        resvg::tiny_skia::Pixmap::decode_png(&document.page_png(0, 25.4).unwrap())
            .unwrap()
            .pixel(10, 10)
            .unwrap()
            .red()
            > 240
    );
    let foreground = document.add_page_layer(0, "Foreground", None).unwrap();
    document
        .move_page_object_to_layer(0, green, &foreground)
        .unwrap();
    assert!(
        resvg::tiny_skia::Pixmap::decode_png(&document.page_png(0, 25.4).unwrap())
            .unwrap()
            .pixel(10, 10)
            .unwrap()
            .green()
            > 240
    );
    document.move_page_object(0, green, Some(blue)).unwrap();
    assert_eq!(
        document
            .page_layers(0)
            .unwrap()
            .last()
            .unwrap()
            .object_count,
        0
    );
    assert!(
        resvg::tiny_skia::Pixmap::decode_png(&document.page_png(0, 25.4).unwrap())
            .unwrap()
            .pixel(10, 10)
            .unwrap()
            .red()
            > 240
    );
    let before = document.to_bytes().unwrap();
    document.move_page_object(0, red, Some(red)).unwrap();
    assert_eq!(document.to_bytes().unwrap(), before);
    for (id, anchor) in [
        ("missing", None),
        (red.as_str(), Some("missing")),
        (red.as_str(), Some("")),
    ] {
        assert!(document.move_page_object(0, id, anchor).is_err());
        assert_eq!(document.to_bytes().unwrap(), before);
    }
    assert!(document.validate_references().unwrap().is_empty());
    let reopened = OfdDocument::from_bytes(&before).unwrap();
    assert_eq!(
        reopened.page_png(0, 25.4).unwrap(),
        document.page_png(0, 25.4).unwrap()
    );

    let mut java = OfdDocument::open(fixture("helloworld.ofd")).unwrap();
    let existing = java.page_text_objects(0).unwrap()[0].id.clone().unwrap();
    let added = java
        .add_text_object(0, "moved first", [20.0, 20.0, 40.0, 8.0], 5.0, None)
        .unwrap();
    java.move_page_object(0, &added, Some(&existing)).unwrap();
    assert_eq!(java.page_text(0).unwrap()[0], "moved first");
    assert!(java.validate_references().unwrap().is_empty());
}

#[test]
fn page_object_name_round_trips_and_rejects_invalid_xml_without_mutation() {
    let mut document = OfdDocument::new();
    document.add_text_page("named", 40.0, 30.0).unwrap();
    let id = document.page_objects(0).unwrap()[0].id.clone().unwrap();
    assert_eq!(document.page_objects(0).unwrap()[0].name, None);
    document
        .set_page_object_name(0, &id, Some("发票 & \"A\""))
        .unwrap();
    assert_eq!(
        document.page_objects(0).unwrap()[0].name.as_deref(),
        Some("发票 & \"A\"")
    );
    let page = document.pages().unwrap()[0].path.clone();
    let xml = std::str::from_utf8(document.entry(&page).unwrap().unwrap()).unwrap();
    assert!(xml.contains("Name=\"发票 &amp; &quot;A&quot;\""));
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(
        reopened.page_objects(0).unwrap()[0].name,
        document.page_objects(0).unwrap()[0].name
    );

    let whitespace_name = "line\nnext\tcarriage\rreturn";
    document
        .set_page_object_name(0, &id, Some(whitespace_name))
        .unwrap();
    assert_eq!(
        document.page_objects(0).unwrap()[0].name.as_deref(),
        Some(whitespace_name)
    );
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(
        reopened.page_objects(0).unwrap()[0].name.as_deref(),
        Some(whitespace_name)
    );

    let before = document.to_bytes().unwrap();
    assert!(document
        .set_page_object_name(0, &id, Some("bad\0name"))
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    document.set_page_object_name(0, &id, None).unwrap();
    assert_eq!(document.page_objects(0).unwrap()[0].name, None);
    assert_eq!(document.page_text(0).unwrap(), ["named"]);
}

#[test]
fn page_object_blend_mode_round_trips_and_changes_preview() {
    let mut document = OfdDocument::new();
    document.add_blank_page(30.0, 30.0).unwrap();
    let id = document
        .add_path_object(
            0,
            "M 0 0 L 20 0 L 20 20 L 0 20 C",
            [0.0, 0.0, 20.0, 20.0],
            PathStyle {
                fill: true,
                stroke: false,
                fill_color: Some([255, 0, 0]),
                ..PathStyle::default()
            },
        )
        .unwrap();
    assert_eq!(document.page_objects(0).unwrap()[0].blend_mode, None);
    document
        .set_page_object_blend_mode(0, &id, Some("color-dodge"))
        .unwrap();
    assert_eq!(
        document.page_objects(0).unwrap()[0].blend_mode.as_deref(),
        Some("ColorDodge")
    );
    assert!(document
        .page_svg(0)
        .unwrap()
        .contains("mix-blend-mode:color-dodge"));
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(
        reopened.page_objects(0).unwrap()[0].blend_mode.as_deref(),
        Some("ColorDodge")
    );
    let before = document.to_bytes().unwrap();
    assert!(document
        .set_page_object_blend_mode(0, &id, Some("unknown"))
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    document.set_page_object_blend_mode(0, &id, None).unwrap();
    assert_eq!(document.page_objects(0).unwrap()[0].blend_mode, None);
    assert!(!document.page_svg(0).unwrap().contains("mix-blend-mode:"));
    for (input, canonical, css) in [
        ("multiply", "Multiply", "multiply"),
        ("screen", "Screen", "screen"),
        ("overlay", "Overlay", "overlay"),
        ("darken", "Darken", "darken"),
        ("lighten", "Lighten", "lighten"),
        ("color-burn", "ColorBurn", "color-burn"),
        ("hard-light", "HardLight", "hard-light"),
        ("soft-light", "SoftLight", "soft-light"),
        ("difference", "Difference", "difference"),
        ("exclusion", "Exclusion", "exclusion"),
        ("hue", "Hue", "hue"),
        ("saturation", "Saturation", "saturation"),
        ("color", "Color", "color"),
        ("luminosity", "Luminosity", "luminosity"),
    ] {
        document
            .set_page_object_blend_mode(0, &id, Some(input))
            .unwrap();
        assert_eq!(
            document.page_objects(0).unwrap()[0].blend_mode.as_deref(),
            Some(canonical)
        );
        assert!(document
            .page_svg(0)
            .unwrap()
            .contains(&format!("mix-blend-mode:{css}")));
    }
    document
        .set_page_object_blend_mode(0, &id, Some("Normal"))
        .unwrap();
    assert!(!document.page_svg(0).unwrap().contains("mix-blend-mode:"));
}

#[test]
fn updates_page_object_visibility_and_alpha_without_losing_content() {
    let mut document = OfdDocument::new();
    document.add_blank_page(20.0, 20.0).unwrap();
    let path_id = document
        .add_path_object(
            0,
            "M 0 0 L 20 0 L 20 20 L 0 20 C",
            [0.0, 0.0, 20.0, 20.0],
            PathStyle {
                fill: true,
                stroke: false,
                fill_color: Some([255, 0, 0]),
                ..PathStyle::default()
            },
        )
        .unwrap();
    let text_id = document
        .add_text_object(0, "visible text", [1.0, 1.0, 18.0, 8.0], 4.0, None)
        .unwrap();
    assert!(document
        .page_text(0)
        .unwrap()
        .contains(&"visible text".to_owned()));
    document
        .set_page_object_visible(0, &text_id, false)
        .unwrap();
    assert!(document.page_text(0).unwrap().is_empty());
    document.set_page_object_visible(0, &text_id, true).unwrap();
    assert!(document
        .page_text(0)
        .unwrap()
        .contains(&"visible text".to_owned()));
    document.set_page_object_alpha(0, &path_id, 0).unwrap();
    let pixel = resvg::tiny_skia::Pixmap::decode_png(&document.page_png(0, 25.4).unwrap())
        .unwrap()
        .pixel(15, 15)
        .unwrap();
    assert_eq!((pixel.red(), pixel.green(), pixel.blue()), (255, 255, 255));
    document.set_page_object_alpha(0, &path_id, 128).unwrap();
    let png = document.page_png(0, 25.4).unwrap();
    let pixmap = resvg::tiny_skia::Pixmap::decode_png(&png).unwrap();
    let pixel = pixmap.pixel(15, 15).unwrap();
    assert!(pixel.red() > 245 && pixel.green() > 110 && pixel.green() < 150);
    let page_path = document.pages().unwrap()[0].path.clone();
    let before = document.entry(&page_path).unwrap().unwrap().to_vec();
    assert!(document
        .set_page_object_visible(0, "missing", false)
        .is_err());
    assert!(document.set_page_object_alpha(1, &path_id, 255).is_err());
    assert_eq!(document.entry(&page_path).unwrap().unwrap(), before);
    assert!(document.validate_references().unwrap().is_empty());
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.page_png(0, 25.4).unwrap(), png);
    assert_eq!(
        reopened.page_text(0).unwrap(),
        document.page_text(0).unwrap()
    );

    let mut java = OfdDocument::open(fixture("helloworld.ofd")).unwrap();
    let java_id = java.page_text_objects(0).unwrap()[0].id.clone().unwrap();
    let original = java.page_text(0).unwrap();
    java.set_page_object_visible(0, &java_id, false).unwrap();
    assert!(java.page_text(0).unwrap().is_empty());
    java.set_page_object_visible(0, &java_id, true).unwrap();
    java.set_page_object_alpha(0, &java_id, 255).unwrap();
    assert_eq!(java.page_text(0).unwrap(), original);
    assert!(java.validate_references().unwrap().is_empty());
}

#[test]
fn edits_page_object_boundary_and_ctm_with_rendered_effect() {
    let mut document = OfdDocument::new();
    document.add_blank_page(30.0, 20.0).unwrap();
    let id = document
        .add_path_object(
            0,
            "M 0 0 L 5 0 L 5 5 L 0 5 C",
            [2.0, 2.0, 5.0, 5.0],
            PathStyle {
                fill: true,
                stroke: false,
                fill_color: Some([255, 0, 0]),
                ..PathStyle::default()
            },
        )
        .unwrap();
    document
        .set_page_object_boundary(0, &id, [12.0, 2.0, 5.0, 5.0])
        .unwrap();
    assert_eq!(
        document.page_paths(0).unwrap()[0].boundary,
        Some([12.0, 2.0, 5.0, 5.0])
    );
    let image = resvg::tiny_skia::Pixmap::decode_png(&document.page_png(0, 25.4).unwrap()).unwrap();
    assert_eq!(image.pixel(4, 4).unwrap().red(), 255);
    assert!(image.pixel(14, 4).unwrap().red() > 240);
    assert!(image.pixel(14, 4).unwrap().green() < 20);
    document
        .set_page_object_ctm(0, &id, Some([1.0, 0.0, 0.0, 1.0, 5.0, 0.0]))
        .unwrap();
    assert_eq!(
        document.page_paths(0).unwrap()[0].ctm,
        Some([1.0, 0.0, 0.0, 1.0, 5.0, 0.0])
    );
    let image = resvg::tiny_skia::Pixmap::decode_png(&document.page_png(0, 25.4).unwrap()).unwrap();
    assert_eq!(image.pixel(14, 4).unwrap().green(), 255);
    assert_eq!(image.pixel(19, 4).unwrap().green(), 255);
    document.set_page_object_ctm(0, &id, None).unwrap();
    assert_eq!(document.page_paths(0).unwrap()[0].ctm, None);
    let text_id = document
        .add_text_object(0, "A", [2.0, 10.0, 5.0, 5.0], 4.0, None)
        .unwrap();
    document
        .set_page_object_boundary(0, &text_id, [12.0, 10.0, 5.0, 5.0])
        .unwrap();
    assert_eq!(
        document
            .page_text_in_region(0, [12.0, 10.0, 5.0, 5.0])
            .unwrap(),
        ["A"]
    );
    let page_path = document.pages().unwrap()[0].path.clone();
    let before = document.entry(&page_path).unwrap().unwrap().to_vec();
    for boundary in [[0.0, 0.0, 0.0, 5.0], [f64::NAN, 0.0, 5.0, 5.0]] {
        assert!(document.set_page_object_boundary(0, &id, boundary).is_err());
    }
    assert!(document
        .set_page_object_ctm(0, &id, Some([1.0, 0.0, 0.0, 1.0, f64::INFINITY, 0.0]))
        .is_err());
    assert!(document
        .set_page_object_boundary(0, "missing", [0.0, 0.0, 5.0, 5.0])
        .is_err());
    assert_eq!(document.entry(&page_path).unwrap().unwrap(), before);
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(
        reopened.page_paths(0).unwrap(),
        document.page_paths(0).unwrap()
    );
    assert!(reopened.validate_references().unwrap().is_empty());
}

#[test]
fn lists_mixed_page_objects_in_painting_order_with_editable_state() {
    let mut document = OfdDocument::new();
    document.add_blank_page(20.0, 20.0).unwrap();
    let commands = "M 0 0 L 5 0 L 5 5 L 0 5 C";
    let path = document
        .add_path_object(0, commands, [1.0, 1.0, 5.0, 5.0], PathStyle::default())
        .unwrap();
    let text = document
        .add_text_object(0, "hello", [2.0, 2.0, 10.0, 5.0], 4.0, None)
        .unwrap();
    let foreground = document.add_page_layer(0, "Foreground", None).unwrap();
    document
        .move_page_object_to_layer(0, &path, &foreground)
        .unwrap();
    document.set_page_object_visible(0, &text, false).unwrap();
    document.set_page_object_alpha(0, &path, 128).unwrap();
    document
        .set_page_object_ctm(0, &path, Some([1.0, 0.0, 0.0, 1.0, 3.0, 0.0]))
        .unwrap();
    let objects = document.page_objects(0).unwrap();
    assert_eq!(objects.len(), 2);
    assert_eq!(objects[0].id.as_deref(), Some(text.as_str()));
    assert_eq!(objects[0].kind, "TextObject");
    assert_eq!(objects[0].layer_type, "Body");
    assert!(!objects[0].visible);
    assert_eq!(objects[0].alpha, 255);
    assert_eq!(objects[1].id.as_deref(), Some(path.as_str()));
    assert_eq!(objects[1].kind, "PathObject");
    assert_eq!(objects[1].layer_id.as_deref(), Some(foreground.as_str()));
    assert_eq!(objects[1].alpha, 128);
    assert_eq!(objects[1].ctm, Some([1.0, 0.0, 0.0, 1.0, 3.0, 0.0]));
    assert!(objects.iter().all(|object| object.template_id.is_none()));
    assert!(document.page_objects(1).is_err());
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.page_objects(0).unwrap(), objects);
    let page_path = document.pages().unwrap()[0].path.clone();
    let original =
        String::from_utf8(document.entry(&page_path).unwrap().unwrap().to_vec()).unwrap();
    for (from, to) in [
        ("Alpha=\"128\"", "Alpha=\"999\""),
        ("Visible=\"false\"", "Visible=\"maybe\""),
    ] {
        let mut malformed = document.clone();
        malformed
            .set_entry(&page_path, original.replace(from, to).into_bytes())
            .unwrap();
        assert!(malformed.page_objects(0).is_err());
    }

    let invoice = OfdDocument::open(fixture("发票示例.ofd")).unwrap();
    let objects = invoice.page_objects(0).unwrap();
    assert!(!objects.is_empty());
    assert!(objects.iter().any(|object| object.template_id.is_some()));
}

#[test]
fn removes_only_empty_page_layers_and_keeps_allocated_ids() {
    let mut document = OfdDocument::new();
    document.add_blank_page(20.0, 20.0).unwrap();
    let empty = document.add_page_layer(0, "Foreground", None).unwrap();
    let filled = document.add_page_layer(0, "Foreground", None).unwrap();
    let object = document
        .add_path_object(
            0,
            "M 0 0 L 10 10",
            [0.0, 0.0, 10.0, 10.0],
            PathStyle::default(),
        )
        .unwrap();
    document
        .move_page_object_to_layer(0, &object, &filled)
        .unwrap();
    let before = document.to_bytes().unwrap();
    for id in ["", "missing", &filled] {
        assert!(document.remove_page_layer(0, id).is_err());
    }
    assert!(document.remove_page_layer(1, &empty).is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    document.remove_page_layer(0, &empty).unwrap();
    assert_eq!(document.page_layers(0).unwrap().len(), 2);
    assert!(document.validate_references().unwrap().is_empty());
    let next = document.add_page_layer(0, "Background", None).unwrap();
    assert!(next.parse::<usize>().unwrap() > empty.parse::<usize>().unwrap());
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(
        reopened.page_layers(0).unwrap(),
        document.page_layers(0).unwrap()
    );
    assert_eq!(reopened.page_paths(0).unwrap().len(), 1);

    let mut opened = OfdDocument::open(fixture("helloworld.ofd")).unwrap();
    let original_text = opened.page_text(0).unwrap();
    let layer = opened.add_page_layer(0, "Foreground", None).unwrap();
    opened.remove_page_layer(0, &layer).unwrap();
    assert_eq!(opened.page_text(0).unwrap(), original_text);
    assert!(opened.validate_references().unwrap().is_empty());
}

#[test]
fn page_layers_interleave_templates_with_page_layers() {
    let mut document = OfdDocument::new();
    document.add_blank_page(20.0, 20.0).unwrap();
    let page_path = document.pages().unwrap()[0].path.clone();
    let page_xml =
        String::from_utf8(document.entry(&page_path).unwrap().unwrap().to_vec()).unwrap();
    let parsed = roxmltree::Document::parse(&page_xml).unwrap();
    let layer = parsed
        .descendants()
        .find(|node| node.tag_name().name() == "Layer")
        .unwrap();
    let mut updated = page_xml.clone();
    updated.replace_range(layer.range(), "<ofd:Layer ID=\"51\" Type=\"Foreground\"/><ofd:Layer ID=\"52\" Name=\"Direct\" Type=\"Background\"/><ofd:Layer ID=\"53\" Type=\"Body\"/>");
    updated = updated.replace("<ofd:Content>", "<ofd:Template TemplateID=\"71\" ZOrder=\"Background\"/><ofd:Template TemplateID=\"72\" ZOrder=\"Body\"/><ofd:Template TemplateID=\"73\" ZOrder=\"Foreground\"/><ofd:Content>");
    document
        .set_entry(&page_path, updated.into_bytes())
        .unwrap();
    let document_path = "Doc_0/Document.xml";
    let root = String::from_utf8(document.entry(document_path).unwrap().unwrap().to_vec()).unwrap();
    let definitions = (71..=73)
        .map(|id| format!("<ofd:TemplatePage ID=\"{id}\" BaseLoc=\"Templates/T{id}.xml\"/>"))
        .collect::<String>();
    let root = root.replace(
        "</ofd:CommonData>",
        &format!("{definitions}</ofd:CommonData>"),
    );
    document
        .set_entry(document_path, root.into_bytes())
        .unwrap();
    for id in 71..=73 {
        let xml = format!("<?xml version=\"1.0\" encoding=\"UTF-8\"?><ofd:Page xmlns:ofd=\"http://www.ofdspec.org/2016\"><ofd:Content><ofd:Layer ID=\"{id}\" Name=\"Template {id}\" Type=\"Body\"/></ofd:Content></ofd:Page>");
        document
            .set_entry(&format!("Doc_0/Templates/T{id}.xml"), xml.into_bytes())
            .unwrap();
    }
    let layers = document.page_layers(0).unwrap();
    assert_eq!(
        layers
            .iter()
            .map(|layer| layer.id.as_deref().unwrap())
            .collect::<Vec<_>>(),
        ["71", "52", "72", "53", "73", "51"]
    );
    assert_eq!(layers[0].name.as_deref(), Some("Template 71"));
    assert_eq!(layers[1].name.as_deref(), Some("Direct"));
    let svg = document.page_svg(0).unwrap();
    let mut last = 0;
    for id in ["71", "52", "72", "53", "73", "51"] {
        let index = svg.find(&format!("data-ofd-layer=\"{id}\"")).unwrap();
        assert!(index >= last);
        last = index;
    }
}

#[test]
fn page_layers_follow_type_order_for_svg_png_and_pdf() {
    let mut document = OfdDocument::new();
    document.add_blank_page(20.0, 20.0).unwrap();
    let path = document.pages().unwrap()[0].path.clone();
    let xml = String::from_utf8(document.entry(&path).unwrap().unwrap().to_vec()).unwrap();
    let parsed = roxmltree::Document::parse(&xml).unwrap();
    let layer = parsed
        .descendants()
        .find(|node| node.tag_name().name() == "Layer")
        .unwrap();
    let mut layers = String::new();
    for (id, kind, color) in [
        (10, "Foreground", "255 0 0"),
        (20, "Body", "0 255 0"),
        (30, "Background", "0 0 255"),
    ] {
        layers.push_str(&format!(
            "<ofd:Layer ID=\"{id}\" Type=\"{kind}\"><ofd:PathObject ID=\"{}\" Boundary=\"0 0 20 20\" Fill=\"true\" Stroke=\"false\"><ofd:FillColor Value=\"{color}\"/><ofd:AbbreviatedData>M 0 0 L 20 0 L 20 20 L 0 20 C</ofd:AbbreviatedData></ofd:PathObject></ofd:Layer>",
            id + 1
        ));
    }
    let mut updated = xml.clone();
    updated.replace_range(layer.range(), &layers);
    document.set_entry(&path, updated.into_bytes()).unwrap();
    let info = document.page_layers(0).unwrap();
    assert_eq!(
        info.iter()
            .map(|layer| layer.layer_type.as_str())
            .collect::<Vec<_>>(),
        ["Background", "Body", "Foreground"]
    );
    assert_eq!(
        info.iter()
            .map(|layer| layer.object_count)
            .collect::<Vec<_>>(),
        [1, 1, 1]
    );
    assert!(info.iter().all(|layer| layer.source_path == path));
    let svg = document.page_svg(0).unwrap();
    assert!(svg.find("#0000ff").unwrap() < svg.find("#00ff00").unwrap());
    assert!(svg.find("#00ff00").unwrap() < svg.find("#ff0000").unwrap());
    let png = resvg::tiny_skia::Pixmap::decode_png(&document.page_png(0, 25.4).unwrap()).unwrap();
    assert!(png.pixel(10, 10).unwrap().red() > 240);
    assert!(png.pixel(10, 10).unwrap().blue() < 15);
    assert!(lopdf::Document::load_mem(&document.to_pdf().unwrap()).is_ok());
    let before = document.to_bytes().unwrap();
    let broken = xml.replace("<ofd:Layer", "<ofd:Layer Type=\"Unknown\"");
    document.set_entry(&path, broken.into_bytes()).unwrap();
    assert!(document.page_layers(0).is_err());
    assert!(document
        .validate_references()
        .unwrap()
        .iter()
        .any(|issue| issue.code == "invalid_layer_type"));
    document = OfdDocument::from_bytes(&before).unwrap();
    assert_eq!(document.page_layers(0).unwrap().len(), 3);
}

#[test]
fn flowed_text_and_spans_support_character_indents() {
    let font = std::fs::read(
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/dejavu-serif.ttf"),
    )
    .unwrap();
    let mut document = OfdDocument::new();
    let font_id = document.add_embedded_font("DejaVu Serif", &font).unwrap();
    let style = ofdrw::FlowTextStyle {
        page_size: [40.0, 22.0],
        margins: [5.0; 4],
        font_size: 5.0,
        line_height: 6.0,
        font_id: Some(font_id.to_string()),
        first_line_indent_chars: 2,
        ..ofdrw::FlowTextStyle::default()
    };
    assert_eq!(
        document.add_flowed_text(0, "A\nB", style.clone()).unwrap(),
        [0]
    );
    assert_eq!(
        document.page_text_objects(0).unwrap()[0].boundary.unwrap()[0],
        15.0
    );
    assert_eq!(
        document.page_text_objects(0).unwrap()[1].boundary.unwrap()[0],
        5.0
    );

    let mut span = ofdrw::FlowSpan::new("fi\nfi");
    span.font_size = Some(3.0);
    span.letter_spacing = 0.5;
    assert_eq!(
        document
            .add_flowed_spans(0, &[span.clone()], style.clone())
            .unwrap(),
        [1]
    );
    assert_eq!(
        document.page_text_objects(1).unwrap()[0].boundary.unwrap()[0],
        12.0
    );
    assert_eq!(
        document.page_text_objects(1).unwrap()[1].boundary.unwrap()[0],
        5.0
    );

    let shaped = ofdrw::FlowTextStyle {
        shape: true,
        ..style.clone()
    };
    assert_eq!(
        document
            .add_flowed_text(0, "fi\nfi", shaped.clone())
            .unwrap(),
        [2]
    );
    assert_eq!(
        document.page_text_objects(2).unwrap()[0].boundary.unwrap()[0],
        15.0
    );
    assert_eq!(document.add_flowed_spans(0, &[span], shaped).unwrap(), [3]);
    assert_eq!(
        document.page_text_objects(3).unwrap()[0].boundary.unwrap()[0],
        12.0
    );

    let millimeters = ofdrw::FlowTextStyle {
        first_line_indent: 3.0,
        ..style.clone()
    };
    assert_eq!(document.add_flowed_text(0, "A", millimeters).unwrap(), [4]);
    assert_eq!(
        document.page_text_objects(4).unwrap()[0].boundary.unwrap()[0],
        8.0
    );
    let before = document.to_bytes().unwrap();
    let overwide = ofdrw::FlowTextStyle {
        first_line_indent_chars: 7,
        ..style
    };
    assert!(document.add_flowed_text(0, "A", overwide).is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
}

#[test]
fn shaped_flowed_spans_preserve_styles_ligatures_and_pagination() {
    let font = std::fs::read(
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/dejavu-serif.ttf"),
    )
    .unwrap();
    let mut document = OfdDocument::new();
    let font_id = document.add_embedded_font("DejaVu Serif", &font).unwrap();
    let alternate = document.add_embedded_font("Other Serif", &font).unwrap();
    let mut red = ofdrw::FlowSpan::new("fi");
    red.fill_color = Some([255, 0, 0]);
    red.bold = true;
    red.underline = true;
    red.letter_spacing = 0.1;
    let mut blue = ofdrw::FlowSpan::new("fi");
    blue.font_id = Some(alternate.to_string());
    blue.fill_color = Some([0, 0, 255]);
    blue.italic = true;
    let style = ofdrw::FlowTextStyle {
        page_size: [14.5, 16.0],
        margins: [5.0; 4],
        font_size: 5.0,
        line_height: 6.0,
        font_id: Some(font_id.to_string()),
        shape: true,
        ..ofdrw::FlowTextStyle::default()
    };
    assert_eq!(
        document
            .add_flowed_spans(0, &[red.clone(), blue], style.clone())
            .unwrap(),
        [0, 1]
    );
    for page in 0..2 {
        assert_eq!(document.page_text(page).unwrap(), ["fi"]);
        let object = &document.page_text_objects(page).unwrap()[0];
        assert_eq!(object.cg_transforms[0].code_count, 2);
        assert_eq!(object.cg_transforms[0].glyph_count, 1);
    }
    assert_eq!(
        document.page_text_objects(1).unwrap()[0].font_id.as_deref(),
        Some(alternate.to_string().as_str())
    );
    assert!(document.page_svg(0).unwrap().contains("#ff0000"));
    assert!(document.page_svg(1).unwrap().contains("#0000ff"));
    assert_eq!(document.page_paths(0).unwrap().len(), 1);
    assert!(document.validate_references().unwrap().is_empty());
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.page_text(1).unwrap(), ["fi"]);

    let before = document.to_bytes().unwrap();
    red.text = "fifi".into();
    red.keep_together = true;
    assert!(document.add_flowed_spans(0, &[red], style.clone()).is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    let mut no_font = OfdDocument::new();
    let before = no_font.to_bytes().unwrap();
    assert!(no_font
        .add_flowed_spans(
            0,
            &[ofdrw::FlowSpan::new("fi")],
            ofdrw::FlowTextStyle {
                font_id: None,
                ..style
            },
        )
        .is_err());
    assert_eq!(no_font.to_bytes().unwrap(), before);
}

#[test]
fn flowed_spans_write_weight_fill_and_stroke_styles() {
    let mut document = OfdDocument::new();
    let mut outline = ofdrw::FlowSpan::new("描边");
    outline.fill = false;
    outline.stroke = true;
    outline.stroke_color = Some([20, 40, 60]);
    outline.stroke_width = Some(0.2);
    outline.bold = true;
    outline.weight = Some(600);
    let style = ofdrw::FlowTextStyle {
        page_size: [40.0, 20.0],
        margins: [5.0; 4],
        ..ofdrw::FlowTextStyle::default()
    };
    assert_eq!(
        document
            .add_flowed_spans(0, &[outline.clone()], style.clone())
            .unwrap(),
        [0]
    );
    let page_path = document.pages().unwrap()[0].path.clone();
    let page_xml =
        String::from_utf8(document.entry(&page_path).unwrap().unwrap().to_vec()).unwrap();
    assert!(page_xml.contains("Weight=\"600\""));
    assert!(page_xml.contains("Fill=\"false\" Stroke=\"true\" LineWidth=\"0.2\""));
    assert!(page_xml.contains("<ofd:StrokeColor Value=\"20 40 60\"/>"));
    let svg = document.page_svg(0).unwrap();
    assert!(svg.contains("font-weight=\"600\""));
    assert!(svg.contains("fill=\"none\""));
    assert!(svg.contains("stroke=\"#14283c\""));
    assert!(document.validate_references().unwrap().is_empty());
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.page_text(0).unwrap(), ["描边"]);
    assert!(reopened.page_svg(0).unwrap().contains("stroke=\"#14283c\""));

    let before = document.to_bytes().unwrap();
    outline.weight = Some(650);
    assert!(document
        .add_flowed_spans(0, &[outline.clone()], style.clone())
        .is_err());
    outline.weight = Some(600);
    outline.stroke_width = Some(0.0);
    assert!(document.add_flowed_spans(0, &[outline], style).is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
}

#[test]
fn flowed_span_letter_spacing_and_underline_round_trip() {
    let font = std::fs::read(
        PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../../ofdrw-layout/src/test/resources/simhei-cut1.ttf"),
    )
    .unwrap();
    let mut document = OfdDocument::new();
    let font_id = document.add_embedded_font("SimHei", &font).unwrap();
    let mut span = ofdrw::FlowSpan::new("中文中");
    span.letter_spacing = 1.0;
    span.underline = true;
    span.underline_offset = 0.5;
    span.underline_width = 0.3;
    span.fill_color = Some([200, 30, 10]);
    let style = ofdrw::FlowTextStyle {
        page_size: [22.0, 16.0],
        margins: [5.0; 4],
        font_size: 5.0,
        line_height: 6.0,
        font_id: Some(font_id.to_string()),
        ..ofdrw::FlowTextStyle::default()
    };
    assert_eq!(
        document
            .add_flowed_spans(0, &[span.clone()], style.clone())
            .unwrap(),
        [0, 1]
    );
    let first = document.page_text_objects(0).unwrap();
    assert_eq!(first[0].boundary, Some([5.0, 5.0, 12.0, 6.0]));
    assert_eq!(first[0].codes[0].delta_x.as_deref(), Some("6"));
    assert_eq!(document.page_text(0).unwrap(), ["中文"]);
    assert_eq!(document.page_text(1).unwrap(), ["中"]);
    let underlines = document.page_paths(0).unwrap();
    assert_eq!(underlines.len(), 1);
    assert_eq!(underlines[0].boundary, Some([5.0, 5.0, 12.0, 6.0]));
    assert_eq!(
        underlines[0].abbreviated_data.as_deref(),
        Some("M 0 5.5 L 12 5.5")
    );
    let svg = document.page_svg(0).unwrap();
    assert!(svg.contains("#c81e0a"));
    assert!(document.validate_references().unwrap().is_empty());
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(
        reopened.page_text_objects(0).unwrap()[0].codes[0]
            .delta_x
            .as_deref(),
        Some("6")
    );
    assert_eq!(reopened.page_paths(0).unwrap().len(), 1);

    let before = document.to_bytes().unwrap();
    span.letter_spacing = -5.0;
    assert!(document
        .add_flowed_spans(0, &[span.clone()], style.clone())
        .is_err());
    span.letter_spacing = 1.0;
    span.underline_width = -0.1;
    assert!(document.add_flowed_spans(0, &[span], style).is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
}

#[test]
fn flowed_spans_honor_line_breaks_and_keep_together() {
    let font = std::fs::read(
        PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../../ofdrw-layout/src/test/resources/simhei-cut1.ttf"),
    )
    .unwrap();
    let mut document = OfdDocument::new();
    let font_id = document.add_embedded_font("SimHei", &font).unwrap();
    let mut first = ofdrw::FlowSpan::new("中");
    first.line_break_after = true;
    let middle = ofdrw::FlowSpan::new("文");
    let mut kept = ofdrw::FlowSpan::new("中文");
    kept.keep_together = true;
    let style = ofdrw::FlowTextStyle {
        page_size: [22.0, 22.0],
        margins: [5.0; 4],
        font_size: 5.0,
        line_height: 6.0,
        font_id: Some(font_id.to_string()),
        ..ofdrw::FlowTextStyle::default()
    };
    assert_eq!(
        document
            .add_flowed_spans(0, &[first.clone(), middle, kept.clone()], style.clone())
            .unwrap(),
        [0, 1]
    );
    assert_eq!(document.page_text(0).unwrap(), ["中", "文"]);
    assert_eq!(document.page_text(1).unwrap(), ["中文"]);
    assert_eq!(
        document.page_text_objects(0).unwrap()[1].boundary,
        Some([5.0, 11.0, 5.0, 6.0])
    );
    assert_eq!(
        document.page_text_objects(1).unwrap()[0].boundary,
        Some([5.0, 5.0, 10.0, 6.0])
    );
    assert!(document.validate_references().unwrap().is_empty());
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.page_text(1).unwrap(), ["中文"]);

    let before = document.to_bytes().unwrap();
    kept.text.push('中');
    assert!(matches!(
        document.add_flowed_spans(0, &[first, kept], style.clone()),
        Err(OfdError::Invalid(message)) if message.contains("keep-together")
    ));
    assert_eq!(document.to_bytes().unwrap(), before);
    let mut final_span = ofdrw::FlowSpan::new("中");
    final_span.line_break_after = true;
    assert_eq!(
        document
            .add_flowed_spans(0, &[final_span], style.clone())
            .unwrap(),
        [2]
    );
    assert_eq!(document.page_text(2).unwrap(), ["中"]);
    let mut indented = ofdrw::FlowSpan::new("中文");
    indented.keep_together = true;
    assert_eq!(
        document
            .add_flowed_spans(
                0,
                &[indented],
                ofdrw::FlowTextStyle {
                    first_line_indent: 5.0,
                    ..style.clone()
                }
            )
            .unwrap(),
        [3]
    );
    assert_eq!(
        document.page_text_objects(3).unwrap()[0].boundary,
        Some([5.0, 11.0, 10.0, 6.0])
    );
    let mut trailing = ofdrw::FlowSpan::new("中");
    trailing.line_break_after = true;
    assert_eq!(
        document
            .add_flowed_spans(0, &[trailing, ofdrw::FlowSpan::new("")], style)
            .unwrap(),
        [4]
    );
    assert_eq!(document.page_text(4).unwrap(), ["中"]);
}

