#[test]
fn appends_text_page_to_existing_document_without_losing_extensions() {
    let mut document = OfdDocument::open(fixture("helloworld.ofd")).unwrap();
    let root = "Doc_0/Document.xml";
    let original = String::from_utf8(document.entry(root).unwrap().unwrap().to_vec()).unwrap();
    let augmented = original.replace(
        "</ofd:Document>",
        "<ofd:Extensions><ofd:Extension ID=\"custom\"/></ofd:Extensions></ofd:Document>",
    );
    document.set_entry(root, augmented.into_bytes()).unwrap();
    let first_page = document
        .entry(&document.pages().unwrap()[0].path)
        .unwrap()
        .unwrap()
        .to_vec();
    document
        .append_text_page(0, "新增 & <页>", 180.0, 250.0)
        .unwrap();
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.pages().unwrap().len(), 2);
    assert_eq!(reopened.page_text(1).unwrap(), vec!["新增 & <页>"]);
    assert_eq!(
        reopened
            .entry(&reopened.pages().unwrap()[0].path)
            .unwrap()
            .unwrap(),
        first_page
    );
    assert!(
        String::from_utf8_lossy(reopened.entry(root).unwrap().unwrap()).contains("ID=\"custom\"")
    );
    assert!(reopened.pages().unwrap()[1].physical_box == Some([0.0, 0.0, 180.0, 250.0]));
}

