#[test]
fn appends_path_page_without_font_and_rejects_bad_input_atomically() {
    let original = OfdDocument::new();
    let mut document = OfdDocument::from_bytes(&original.to_bytes().unwrap()).unwrap();
    let root = "Doc_0/Document.xml";
    let source = std::str::from_utf8(document.entry(root).unwrap().unwrap()).unwrap();
    document
        .set_entry(
            root,
            source
                .replace("<ofd:PublicRes>PublicRes.xml</ofd:PublicRes>", "")
                .into_bytes(),
        )
        .unwrap();
    assert!(document.append_text_page(0, "font", 40.0, 40.0).is_err());
    let before = document.to_bytes().unwrap();
    for (index, commands, boundary, width) in [
        (1, "M 0 0 L 10 10", [0.0, 0.0, 10.0, 10.0], 40.0),
        (0, "", [0.0, 0.0, 10.0, 10.0], 40.0),
        (0, "M 0 0 L 10 10", [0.0, 0.0, 0.0, 10.0], 40.0),
        (0, "M 0 0 L 10 10", [0.0, 0.0, 10.0, 10.0], 0.0),
    ] {
        assert!(document
            .append_path_page(index, commands, boundary, [width, 40.0], true, false)
            .is_err());
        assert_eq!(document.to_bytes().unwrap(), before);
    }
    document
        .append_path_page(
            0,
            "M 0 0 L 10 10",
            [0.0, 0.0, 10.0, 10.0],
            [40.0, 40.0],
            false,
            true,
        )
        .unwrap();
    assert_eq!(document.page_paths(0).unwrap().len(), 1);
    assert!(document.validate_references().unwrap().is_empty());
}

#[test]
fn appends_image_page_to_existing_documents_with_and_without_resources() {
    let image_source = OfdDocument::open(fixture("发票示例.ofd")).unwrap();
    let png = image_source.page_image_data(0, 0).unwrap();
    for name in ["helloworld.ofd", "发票示例.ofd"] {
        let mut document = OfdDocument::open(fixture(name)).unwrap();
        let first_page_path = document.pages().unwrap()[0].path.clone();
        let first_page = document.entry(&first_page_path).unwrap().unwrap().to_vec();
        let prior_page_count = document.pages().unwrap().len();
        let prior_images = document.page_images(0).unwrap().len();
        document
            .append_image_page(0, png, "png", [50.0, 40.0])
            .unwrap();
        let page = &document.pages().unwrap()[prior_page_count];
        assert_eq!(page.physical_box, Some([0.0, 0.0, 50.0, 40.0]));
        assert_eq!(document.page_images(prior_page_count).unwrap().len(), 1);
        assert_eq!(
            document.page_images(prior_page_count).unwrap()[0].ctm,
            Some([50.0, 0.0, 0.0, 40.0, 0.0, 0.0])
        );
        assert_eq!(document.page_image_data(prior_page_count, 0).unwrap(), png);
        assert!(document
            .page_svg(prior_page_count)
            .unwrap()
            .contains("data:image/png;base64,"));
        assert_eq!(
            document.entry(&first_page_path).unwrap().unwrap(),
            first_page
        );
        assert_eq!(document.page_images(0).unwrap().len(), prior_images);
        let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
        assert_eq!(reopened.page_image_data(prior_page_count, 0).unwrap(), png);
        assert!(reopened.validate_references().unwrap().is_empty());
    }
}

#[test]
fn appends_jbig2_image_page_and_rejects_invalid_input_atomically() {
    let source = OfdDocument::open(
        PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../../ofdrw-layout/src/test/resources/keyword2.ofd"),
    )
    .unwrap();
    let data = source.page_image_data(0, 0).unwrap();
    let mut document = OfdDocument::from_bytes(&OfdDocument::new().to_bytes().unwrap()).unwrap();
    let before = document.to_bytes().unwrap();
    for (index, image, format, size) in [
        (1, data, "jb2", [20.0, 20.0]),
        (0, b"bad".as_slice(), "png", [20.0, 20.0]),
        (0, data, "jb2", [0.0, 20.0]),
    ] {
        assert!(document
            .append_image_page(index, image, format, size)
            .is_err());
        assert_eq!(document.to_bytes().unwrap(), before);
    }
    let mut collision = document.clone();
    collision
        .set_entry("Doc_0/ImageRes_5.xml", b"<custom/>".to_vec())
        .unwrap();
    let collision_before = collision.to_bytes().unwrap();
    assert!(collision
        .append_image_page(0, data, "jb2", [20.0, 20.0])
        .is_err());
    assert_eq!(collision.to_bytes().unwrap(), collision_before);
    document
        .append_image_page(0, data, "jb2", [20.0, 20.0])
        .unwrap();
    assert_eq!(
        document.page_images(0).unwrap()[0].format.as_deref(),
        Some("GBIG2")
    );
    assert_eq!(document.page_image_data(0, 0).unwrap(), data);
    assert!(document.validate_references().unwrap().is_empty());
}

