#[test]
fn duplicate_template_ids_fail_page_reads_and_reference_validation() {
    let mut document = OfdDocument::new();
    document.add_text_page("template text", 40.0, 30.0).unwrap();
    document
        .promote_page_to_template(0, &[], "Background")
        .unwrap();
    let root_path = "Doc_0/Document.xml";
    let root = std::str::from_utf8(document.entry(root_path).unwrap().unwrap())
        .unwrap()
        .to_owned();
    let parsed = roxmltree::Document::parse(&root).unwrap();
    let definition = parsed
        .descendants()
        .find(|node| node.tag_name().name() == "TemplatePage")
        .unwrap();
    let duplicate = &root[definition.range()];
    let mut updated = root.clone();
    updated.insert_str(definition.range().end, duplicate);
    document.set_entry(root_path, updated.into_bytes()).unwrap();

    assert!(matches!(
        document.pages(),
        Err(OfdError::Invalid(message)) if message.contains("ambiguous")
    ));
    assert!(matches!(
        document.page_sources(0),
        Err(OfdError::Invalid(message)) if message.contains("ambiguous")
    ));
    assert!(document.page_text_with_templates(0).is_err());
    assert!(document.page_layers(0).is_err());
    assert!(document.keyword_positions(&["template"], None).is_err());
    assert!(document.validate_references().unwrap().iter().any(|issue| {
        issue.code == "template_reference" && issue.message.contains("ambiguous")
    }));

    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert!(reopened.page_sources(0).is_err());

    let id = definition.attribute("ID").unwrap();
    let alias = duplicate.replacen(&format!("ID=\"{id}\""), &format!("ID=\"0{id}\""), 1);
    let mut updated = root.clone();
    updated.insert_str(definition.range().end, &alias);
    document.set_entry(root_path, updated.into_bytes()).unwrap();
    assert!(matches!(
        document.pages(),
        Err(OfdError::Invalid(message)) if message.contains("ambiguous")
    ));
    assert!(matches!(
        document.page_sources(0),
        Err(OfdError::Invalid(message)) if message.contains("ambiguous")
    ));
    assert!(document.validate_references().unwrap().iter().any(|issue| {
        issue.code == "template_reference" && issue.message.contains("ambiguous")
    }));
}

