#[test]
fn extracts_same_text_as_java_content_extractor() {
    // Java ContentExtractor ignores text in composite units. The other 167
    // sample pages provide an independent ordering/content baseline.
    let root = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../..");
    let mut current_path = String::new();
    let mut document = None;
    let mut checked = 0;
    for row in include_str!("fixtures/java_text_sha256.tsv").lines() {
        let mut fields = row.splitn(3, '\t');
        let relative = fields.next().unwrap();
        let page_index = fields.next().unwrap().parse::<usize>().unwrap();
        let expected = fields.next().unwrap();
        if current_path != relative {
            document = Some(OfdDocument::open(root.join(relative)).unwrap());
            current_path = relative.to_owned();
        }
        let mut digest = Sha256::new();
        for text in document.as_ref().unwrap().page_text(page_index).unwrap() {
            let bytes = text.as_bytes();
            digest.update(u64::try_from(bytes.len()).unwrap().to_be_bytes());
            digest.update(bytes);
        }
        let actual = digest
            .finalize()
            .iter()
            .map(|byte| format!("{byte:02x}"))
            .collect::<String>();
        assert_eq!(actual, expected, "{relative} page {page_index}");
        checked += 1;
    }
    assert_eq!(checked, 167);

    let extra = OfdDocument::open(root.join("ofdrw-converter/src/test/resources/y.ofd")).unwrap();
    assert_eq!(extra.pages().unwrap().len(), 3);
    for page_index in 0..3 {
        assert!(!extra.page_text(page_index).unwrap().is_empty());
    }
}

