#[test]
fn renders_java_paths_without_boundary() {
    let document = OfdDocument::open(
        PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../../ofdrw-converter/src/test/resources/intro-数科.ofd"),
    )
    .unwrap();
    for index in [7, 8] {
        let paths = document.page_paths(index).unwrap();
        assert!(paths.iter().any(|path| path.boundary.is_none()));
        let svg = document.page_svg(index).unwrap();
        assert!(svg.contains("<path "));
    }
    assert!(document.page_png(7, 25.4).unwrap().starts_with(b"\x89PNG"));
    assert!(
        !document.validate_references().unwrap().iter().any(|issue| {
            issue.code == "invalid_boundary"
                && (issue.message.contains("PathObject 277")
                    || issue.message.contains("PathObject 327"))
        })
    );
}

