#[test]
fn document_cover_metadata_resolves_and_validates_package_entry() {
    let mut document = OfdDocument::new();
    let cover = include_bytes!("../../../../ofdrw-layout/src/test/resources/testimg.png");
    document
        .set_entry("Doc_0/Res/cover.png", cover.to_vec())
        .unwrap();
    let before = document.to_bytes().unwrap();
    assert!(document
        .set_document_info_field(0, "Cover", "missing.png")
        .is_err());
    assert!(document
        .set_document_info_field(0, "Cover", "../escape.png")
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    document
        .set_document_info_field(0, "Cover", "/Doc_0/Res/cover.png")
        .unwrap();
    assert_eq!(
        document.document_info().unwrap()[0].cover.as_deref(),
        Some("/Doc_0/Res/cover.png")
    );
    assert!(document.validate_references().unwrap().is_empty());
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(
        reopened.document_info().unwrap()[0].cover,
        document.document_info().unwrap()[0].cover
    );

    let source = std::str::from_utf8(document.entry("OFD.xml").unwrap().unwrap()).unwrap();
    document
        .set_entry(
            "OFD.xml",
            source
                .replace("/Doc_0/Res/cover.png", "missing.png")
                .into_bytes(),
        )
        .unwrap();
    assert!(document
        .validate_references()
        .unwrap()
        .iter()
        .any(|issue| issue.code == "cover_reference"));
    document.remove_document_info_field(0, "Cover").unwrap();
    assert_eq!(document.document_info().unwrap()[0].cover, None);
    assert!(document.validate_references().unwrap().is_empty());

    let mut signed = OfdDocument::open(fixture("SESV4SignDoc.ofd")).unwrap();
    signed
        .set_entry("Doc_0/Res/cover.png", cover.to_vec())
        .unwrap();
    let before = signed.to_bytes().unwrap();
    assert!(signed
        .set_document_info_field(0, "Cover", "Doc_0/Res/cover.png")
        .unwrap_err()
        .to_string()
        .contains("signed"));
    assert_eq!(signed.to_bytes().unwrap(), before);
}

#[test]
fn edits_custom_document_metadata_without_losing_other_markup() {
    let mut document = OfdDocument::new();
    document.add_text_page("body", 100.0, 60.0).unwrap();
    let before = document.to_bytes().unwrap();
    assert!(document.remove_document_custom_data(0, "missing").is_err());
    assert!(document.set_document_custom_data(0, "", "value").is_err());
    assert!(document
        .set_document_custom_data(1, "Key", "value")
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    document
        .set_document_custom_data(0, "客户&类型", "<VIP>")
        .unwrap();
    document
        .set_document_custom_data(0, "Other", "keep")
        .unwrap();
    document
        .set_document_custom_data(0, "客户&类型", "更新 & 完成")
        .unwrap();
    assert_eq!(
        document.document_info().unwrap()[0].custom_data,
        [
            ("客户&类型".into(), "更新 & 完成".into()),
            ("Other".into(), "keep".into())
        ]
    );
    document
        .remove_document_custom_data(0, "客户&类型")
        .unwrap();
    assert_eq!(
        document.document_info().unwrap()[0].custom_data,
        [("Other".into(), "keep".into())]
    );
    document.remove_document_custom_data(0, "Other").unwrap();
    assert!(document.document_info().unwrap()[0].custom_data.is_empty());
    let ofd_xml = std::str::from_utf8(document.entry("OFD.xml").unwrap().unwrap()).unwrap();
    assert!(!ofd_xml.contains("CustomDatas"));
    assert_eq!(document.page_text(0).unwrap(), ["body"]);
    assert!(document.validate_references().unwrap().is_empty());
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert!(reopened.document_info().unwrap()[0].custom_data.is_empty());

    let mut java = OfdDocument::open(fixture("发票示例.ofd")).unwrap();
    let original = java.document_info().unwrap()[0].custom_data.clone();
    java.set_document_custom_data(0, "合计金额", "4200.00")
        .unwrap();
    java.set_document_custom_data(0, "Rust tag", "present")
        .unwrap();
    let edited = &java.document_info().unwrap()[0].custom_data;
    assert_eq!(edited.len(), original.len() + 1);
    assert!(edited
        .iter()
        .any(|(name, value)| name == "合计金额" && value == "4200.00"));
    java.remove_document_custom_data(0, "Rust tag").unwrap();
    assert_eq!(
        java.document_info().unwrap()[0].custom_data.len(),
        original.len()
    );
    assert!(java.validate_references().unwrap().is_empty());

    let mut signed = OfdDocument::open(fixture("SESV4SignDoc.ofd")).unwrap();
    let before = signed.to_bytes().unwrap();
    assert!(signed.set_document_custom_data(0, "Key", "value").is_err());
    assert!(signed
        .set_document_info_field(0, "Title", "changed")
        .is_err());
    assert_eq!(signed.to_bytes().unwrap(), before);
}

#[test]
fn edits_standard_document_metadata_and_keywords_without_losing_markup() {
    let mut document = OfdDocument::new();
    document.add_text_page("body", 100.0, 60.0).unwrap();
    document
        .set_document_custom_data(0, "Other", "keep")
        .unwrap();
    let before = document.to_bytes().unwrap();
    assert!(document.remove_document_info_field(0, "Title").is_err());
    assert!(document.remove_document_info_field(0, "DocID").is_err());
    assert!(document.remove_document_keyword(0, 0).is_err());
    assert!(document.add_document_keyword(0, " ").is_err());
    assert!(document.add_document_keyword(1, "bad").is_err());
    for (field, value) in [
        ("CreationDate", "2024-02-30"),
        ("ModDate", "2024-2-3"),
        ("DocUsage", "Magazine"),
    ] {
        assert!(document.set_document_info_field(0, field, value).is_err());
    }
    assert_eq!(document.to_bytes().unwrap(), before);

    document
        .set_document_info_field(0, "Title", "Rust & OFD")
        .unwrap();
    document
        .set_document_info_field(0, "CreationDate", "2024-02-29")
        .unwrap();
    document
        .set_document_info_field(0, "DocUsage", "EBook")
        .unwrap();
    document.add_document_keyword(0, "票据 & 发票").unwrap();
    document.add_document_keyword(0, "duplicate").unwrap();
    document.add_document_keyword(0, "duplicate").unwrap();
    assert_eq!(
        document.document_info().unwrap()[0].keywords,
        ["票据 & 发票", "duplicate", "duplicate"]
    );
    assert!(document.remove_document_keyword(0, 3).is_err());
    document.remove_document_keyword(0, 1).unwrap();
    assert_eq!(
        document.document_info().unwrap()[0].keywords,
        ["票据 & 发票", "duplicate"]
    );
    document.remove_document_info_field(0, "Title").unwrap();
    assert_eq!(document.document_info().unwrap()[0].title, None);
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    let info = &reopened.document_info().unwrap()[0];
    assert_eq!(info.creation_date.as_deref(), Some("2024-02-29"));
    assert_eq!(info.doc_usage.as_deref(), Some("EBook"));
    assert_eq!(info.keywords, ["票据 & 发票", "duplicate"]);
    assert_eq!(info.custom_data, [("Other".into(), "keep".into())]);
    assert_eq!(reopened.page_text(0).unwrap(), ["body"]);
    assert!(reopened.validate_references().unwrap().is_empty());
    document.remove_document_keyword(0, 1).unwrap();
    document.remove_document_keyword(0, 0).unwrap();
    assert!(document.document_info().unwrap()[0].keywords.is_empty());
    assert!(
        !std::str::from_utf8(document.entry("OFD.xml").unwrap().unwrap())
            .unwrap()
            .contains("Keywords")
    );

    let mut signed = OfdDocument::open(fixture("SESV4SignDoc.ofd")).unwrap();
    let before = signed.to_bytes().unwrap();
    assert!(signed.remove_document_info_field(0, "Title").is_err());
    assert!(signed.add_document_keyword(0, "bad").is_err());
    assert!(signed.remove_document_keyword(0, 0).is_err());
    assert_eq!(signed.to_bytes().unwrap(), before);
}

#[test]
fn edits_required_document_ids_uniquely_and_preserves_other_bodies() {
    let mut document = OfdDocument::new();
    document.add_text_page("first", 40.0, 30.0).unwrap();
    assert_eq!(document.append_document_body().unwrap(), 1);
    document.append_text_page(1, "second", 40.0, 30.0).unwrap();
    let previous = document.document_info().unwrap();
    let before = document.to_bytes().unwrap();
    for invalid in ["", "short", "z0000000000000000000000000000000"] {
        assert!(document
            .set_document_info_field(0, "DocID", invalid)
            .is_err());
        assert_eq!(document.to_bytes().unwrap(), before);
    }
    assert!(document
        .set_document_info_field(0, "DocID", &previous[1].doc_id.to_uppercase())
        .is_err());
    assert!(document.remove_document_info_field(0, "DocID").is_err());
    assert_eq!(document.to_bytes().unwrap(), before);

    let id = "0123456789abcdef0123456789abcdef";
    document.set_document_info_field(0, "DocID", id).unwrap();
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    let infos = reopened.document_info().unwrap();
    assert_eq!(infos[0].doc_id, id);
    assert_eq!(infos[1].doc_id, previous[1].doc_id);
    assert_eq!(
        reopened.all_text().unwrap(),
        [vec!["first"], vec!["second"]]
    );
    assert!(reopened.validate_references().unwrap().is_empty());

    let mut signed = OfdDocument::open(fixture("SESV4SignDoc.ofd")).unwrap();
    let before = signed.to_bytes().unwrap();
    assert!(signed.set_document_info_field(0, "DocID", id).is_err());
    assert_eq!(signed.to_bytes().unwrap(), before);
}

#[test]
fn reports_invalid_and_duplicate_document_ids_without_rejecting_package_open() {
    let mut document = OfdDocument::new();
    document.add_blank_page(40.0, 30.0).unwrap();
    assert_eq!(document.append_document_body().unwrap(), 1);
    document.append_blank_page(1, 40.0, 30.0).unwrap();
    assert!(document.validate_references().unwrap().is_empty());
    let original = document.entry("OFD.xml").unwrap().unwrap().to_vec();
    let xml = std::str::from_utf8(&original).unwrap();
    let ids: Vec<_> = document
        .document_info()
        .unwrap()
        .into_iter()
        .map(|info| info.doc_id)
        .collect();

    let invalid = xml.replacen(&ids[1], "bad", 1);
    document.set_entry("OFD.xml", invalid.into_bytes()).unwrap();
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert!(reopened
        .validate_references()
        .unwrap()
        .iter()
        .any(|issue| { issue.path == "OFD.xml" && issue.code == "invalid_doc_id" }));

    let hyphenate = |id: &str| {
        format!(
            "{}-{}-{}-{}-{}",
            &id[..8],
            &id[8..12],
            &id[12..16],
            &id[16..20],
            &id[20..]
        )
    };
    let hyphenated = xml.replacen(&ids[1], &hyphenate(&ids[1]), 1);
    document
        .set_entry("OFD.xml", hyphenated.into_bytes())
        .unwrap();
    assert!(document.validate_references().unwrap().is_empty());

    let duplicate = xml.replacen(&ids[1], &hyphenate(&ids[0]).to_uppercase(), 1);
    document
        .set_entry("OFD.xml", duplicate.into_bytes())
        .unwrap();
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert!(reopened
        .validate_references()
        .unwrap()
        .iter()
        .any(|issue| { issue.path == "OFD.xml" && issue.code == "duplicate_doc_id" }));

    let missing = xml.replacen(&format!("<ofd:DocID>{}</ofd:DocID>", ids[1]), "", 1);
    document.set_entry("OFD.xml", missing.into_bytes()).unwrap();
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    let infos = reopened.document_info().unwrap();
    assert_eq!(infos[0].doc_id, ids[0]);
    assert_eq!(infos[1].doc_id, "");
    assert_eq!(reopened.pages().unwrap().len(), 2);
    assert!(document.validate_references().unwrap().is_empty());
    document.set_entry("OFD.xml", original).unwrap();
    assert!(document.validate_references().unwrap().is_empty());
}

#[test]
fn reports_missing_and_duplicate_doc_info_without_rejecting_package_open() {
    let mut document = OfdDocument::new();
    document.add_blank_page(40.0, 30.0).unwrap();
    let original = String::from_utf8(document.entry("OFD.xml").unwrap().unwrap().to_vec()).unwrap();
    let info_start = original.find("<ofd:DocInfo>").unwrap();
    let info_end = original.find("</ofd:DocInfo>").unwrap() + "</ofd:DocInfo>".len();

    let mut missing = original.clone();
    missing.replace_range(info_start..info_end, "");
    document.set_entry("OFD.xml", missing.into_bytes()).unwrap();
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.pages().unwrap().len(), 1);
    assert!(reopened.document_info().is_err());
    let issues = reopened.validate_references().unwrap();
    assert!(issues
        .iter()
        .any(|issue| { issue.path == "OFD.xml" && issue.code == "missing_doc_info" }));

    let duplicate = original.replacen("</ofd:DocInfo>", "</ofd:DocInfo><ofd:DocInfo/>", 1);
    document
        .set_entry("OFD.xml", duplicate.into_bytes())
        .unwrap();
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.pages().unwrap().len(), 1);
    assert!(reopened.document_info().is_err());
    let issues = reopened.validate_references().unwrap();
    assert!(issues
        .iter()
        .any(|issue| { issue.path == "OFD.xml" && issue.code == "duplicate_doc_info" }));
    assert!(!issues.iter().any(|issue| issue.code == "invalid_doc_id"));
    let before = document.to_bytes().unwrap();
    assert!(document.set_document_info_field(0, "Title", "new").is_err());
    assert!(document.add_document_keyword(0, "new").is_err());
    assert!(document.remove_document_keyword(0, 0).is_err());
    assert!(document.set_document_custom_data(0, "Key", "new").is_err());
    assert!(document.remove_document_custom_data(0, "Key").is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
}

#[test]
fn validates_doc_info_field_cardinality_and_usage() {
    let mut document = OfdDocument::new();
    document.add_blank_page(40.0, 30.0).unwrap();
    let original = String::from_utf8(document.entry("OFD.xml").unwrap().unwrap().to_vec()).unwrap();
    assert!(document.validate_references().unwrap().is_empty());
    for (fields, code) in [
        (
            "<ofd:Title>first</ofd:Title><ofd:Title>second</ofd:Title>",
            "duplicate_doc_info_field",
        ),
        ("<ofd:DocUsage>Other</ofd:DocUsage>", "invalid_doc_usage"),
    ] {
        let xml = original.replacen("</ofd:DocInfo>", &format!("{fields}</ofd:DocInfo>"), 1);
        document.set_entry("OFD.xml", xml.into_bytes()).unwrap();
        let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
        assert_eq!(reopened.pages().unwrap().len(), 1);
        assert!(reopened
            .validate_references()
            .unwrap()
            .iter()
            .any(|issue| { issue.path == "OFD.xml" && issue.code == code }));
    }
}

#[test]
fn annotation_reader_ignores_extension_namespace_entries() {
    let mut document = OfdDocument::new();
    document.add_blank_page(80.0, 50.0).unwrap();
    let id = document
        .add_text_stamp_annotation(0, "seal-real", [5.0, 5.0, 30.0, 10.0], 4.0)
        .unwrap();
    let expected = document.annotations().unwrap().remove(0);
    let index_path = "Doc_0/Annots/Annotations.xml";
    let index = String::from_utf8(document.entry(index_path).unwrap().unwrap().to_vec()).unwrap();
    let index = index
        .replacen(
            "<ofd:Annotations xmlns:ofd=",
            "<ofd:Annotations xmlns:ext=\"urn:example:extension\" xmlns:ofd=",
            1,
        )
        .replacen(
            "<ofd:Page PageID=",
            "<ext:Page PageID=\"fake\"><ext:FileLoc>missing.xml</ext:FileLoc></ext:Page><ofd:Page PageID=",
            1,
        )
        .replacen(
            "<ofd:FileLoc>",
            "<ext:FileLoc>missing.xml</ext:FileLoc><ofd:FileLoc>",
            1,
        );
    document.set_entry(index_path, index.into_bytes()).unwrap();

    let content = String::from_utf8(
        document
            .entry(&expected.source_path)
            .unwrap()
            .unwrap()
            .to_vec(),
    )
    .unwrap();
    let content = content
        .replacen(
            "<ofd:PageAnnot xmlns:ofd=",
            "<ofd:PageAnnot xmlns:ext=\"urn:example:extension\" xmlns:ofd=",
            1,
        )
        .replacen(
            "<ofd:Annot ",
            &format!("<ext:Annot ID=\"{id}\" Type=\"Stamp\"/><ofd:Annot "),
            1,
        )
        .replacen(
            "<ofd:Appearance ",
            "<ext:Appearance Boundary=\"0 0 1 1\"><ext:TextCode>fake</ext:TextCode></ext:Appearance><ext:Remark>fake</ext:Remark><ext:Parameters><ext:Parameter Name=\"key\">fake</ext:Parameter></ext:Parameters><ofd:Appearance ",
            1,
        )
        .replacen(
            "<ofd:TextObject ",
            "<ext:TextObject ID=\"fake\" Boundary=\"0 0 1 1\"><ext:TextCode>fake</ext:TextCode></ext:TextObject><ofd:TextObject ",
            1,
        );
    document
        .set_entry(&expected.source_path, content.into_bytes())
        .unwrap();

    let annotations = document.annotations().unwrap();
    assert_eq!(annotations.len(), 1);
    assert_eq!(annotations[0].id, id);
    assert_eq!(annotations[0].text, ["seal-real"]);
    assert_eq!(annotations[0].appearance_box, expected.appearance_box);
    assert_eq!(document.annotation_objects(0, &id).unwrap().len(), 1);
    let svg = document.page_svg(0).unwrap();
    assert!(svg.contains("seal-real"));
    assert!(!svg.contains("fake"));

    document
        .set_annotation_remark(0, &id, Some("note-real"))
        .unwrap();
    document
        .set_annotation_parameter(0, &id, "key", "value-real")
        .unwrap();
    document
        .set_annotation_appearance_boundary(0, &id, [6.0, 6.0, 31.0, 11.0])
        .unwrap();
    let updated = document.annotations().unwrap().remove(0);
    assert_eq!(updated.remark.as_deref(), Some("note-real"));
    assert_eq!(
        updated.parameters.get("key").map(String::as_str),
        Some("value-real")
    );
    assert_eq!(updated.appearance_box, Some([6.0, 6.0, 31.0, 11.0]));
    let content =
        std::str::from_utf8(document.entry(&expected.source_path).unwrap().unwrap()).unwrap();
    assert!(content.contains("<ext:Annot"));
    assert!(content.contains("<ext:Remark>fake</ext:Remark>"));
}

