#[test]
fn adds_text_watermarks_to_new_and_existing_documents() {
    let mut document = OfdDocument::new();
    document.add_text_page("first", 210.0, 297.0).unwrap();
    let id = document
        .add_text_watermark(0, "水印 & Rust", [20.0, 30.0, 60.0, 10.0], 5.0)
        .unwrap();
    document.add_text_page("second", 210.0, 297.0).unwrap();
    let next = document
        .add_text_watermark(1, "second mark", [20.0, 30.0, 60.0, 10.0], 5.0)
        .unwrap();
    let repeated = document
        .add_text_watermark(0, "again", [40.0, 50.0, 60.0, 10.0], 5.0)
        .unwrap();
    assert_ne!(id, next);
    assert_ne!(id, repeated);
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    let marks = reopened.annotations().unwrap();
    assert_eq!(marks.len(), 3);
    assert_eq!(marks[0].id, id);
    assert_eq!(marks[0].annotation_type, "Watermark");
    assert_eq!(marks[0].appearance_box, Some([20.0, 30.0, 60.0, 10.0]));
    assert_eq!(marks[0].text, vec!["水印 & Rust"]);
    let svg = reopened.page_svg(0).unwrap();
    assert!(svg.contains("data-ofd-annotation"));
    assert!(svg.contains("水印 &amp; Rust"));
    assert_eq!(marks[1].id, repeated);
    assert_eq!(marks[2].id, next);
    assert_eq!(reopened.page_text(1).unwrap(), vec!["second"]);

    let mut existing = OfdDocument::open(fixture("helloworld.ofd")).unwrap();
    let original = existing.page_text(0).unwrap();
    existing
        .add_text_watermark(0, "existing", [10.0, 20.0, 40.0, 8.0], 4.0)
        .unwrap();
    let reopened = OfdDocument::from_bytes(&existing.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.page_text(0).unwrap(), original);
    assert_eq!(reopened.annotations().unwrap()[0].text, vec!["existing"]);

    let mut existing = OfdDocument::open(fixture("发票示例.ofd")).unwrap();
    existing
        .add_text_watermark(0, "appended", [10.0, 20.0, 40.0, 8.0], 4.0)
        .unwrap();
    let reopened = OfdDocument::from_bytes(&existing.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.annotations().unwrap().len(), 3);
    assert_eq!(reopened.annotations().unwrap()[2].text, vec!["appended"]);
    assert!(reopened.page_svg(0).unwrap().contains("appended"));
}

#[test]
fn styled_text_watermark_round_trips_and_rejects_invalid_style_atomically() {
    let mut document = OfdDocument::new();
    document.add_text_page("body", 80.0, 50.0).unwrap();
    let style = TextWatermarkStyle {
        color: [255, 0, 0],
        opacity: 96,
        angle_degrees: -30.0,
        bold: true,
        italic: true,
        ..TextWatermarkStyle::default()
    };
    let id = document
        .add_styled_text_watermark(0, "DRAFT", [10.0, 10.0, 50.0, 20.0], 5.0, &style)
        .unwrap();
    let marks = document.annotations().unwrap();
    assert_eq!(marks[0].id, id);
    assert_eq!(marks[0].text, ["DRAFT"]);
    let xml = std::str::from_utf8(document.entry(&marks[0].source_path).unwrap().unwrap()).unwrap();
    assert!(xml.contains("Type=\"Watermark\""));
    assert!(xml.contains("Value=\"255 0 0\" Alpha=\"96\""));
    assert!(xml.contains("Weight=\"700\" Italic=\"true\""));
    assert!(xml.contains(" CTM=\""));
    let svg = document.page_svg(0).unwrap();
    assert!(svg.contains("#ff0000"));
    assert!(svg.contains("fill-opacity=\"0.376"));
    assert!(document.to_pdf().unwrap().starts_with(b"%PDF"));
    assert!(document.validate_references().unwrap().is_empty());
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.page_svg(0).unwrap(), svg);

    let before = document.to_bytes().unwrap();
    for invalid in [
        TextWatermarkStyle {
            angle_degrees: f64::NAN,
            ..style.clone()
        },
        TextWatermarkStyle {
            font_id: Some("missing".into()),
            ..style.clone()
        },
    ] {
        assert!(document
            .add_styled_text_watermark(0, "invalid", [10.0, 10.0, 50.0, 20.0], 5.0, &invalid)
            .is_err());
        assert_eq!(document.to_bytes().unwrap(), before);
    }
}

#[test]
fn watermarks_all_pages_using_each_page_box_and_rolls_back_across_bodies() {
    let mut document = OfdDocument::new();
    document.add_blank_page(40.0, 30.0).unwrap();
    document.add_text_page("second", 60.0, 50.0).unwrap();
    let style = TextWatermarkStyle {
        color: [0, 0, 255],
        opacity: 128,
        tile_spacing: Some([20.0, 15.0]),
        ..TextWatermarkStyle::default()
    };
    let ids = document
        .add_text_watermark_to_all_pages("COPY", 5.0, &style)
        .unwrap();
    assert_eq!(ids.len(), 2);
    let marks = document.annotations().unwrap();
    assert_eq!(
        marks.iter().map(|mark| &mark.id).collect::<Vec<_>>(),
        ids.iter().collect::<Vec<_>>()
    );
    assert_eq!(marks[0].appearance_box, Some([0.0, 0.0, 40.0, 30.0]));
    assert_eq!(marks[1].appearance_box, Some([0.0, 0.0, 60.0, 50.0]));
    assert_eq!(marks[0].text.len(), 4);
    assert_eq!(marks[1].text.len(), 12);
    assert!(document.page_svg(0).unwrap().contains("#0000ff"));
    assert!(document.page_svg(1).unwrap().contains("#0000ff"));
    assert!(document.validate_references().unwrap().is_empty());
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.annotations().unwrap().len(), 2);

    let mut empty = OfdDocument::new();
    assert!(empty
        .add_text_watermark_to_all_pages("COPY", 5.0, &style)
        .unwrap()
        .is_empty());

    let font = include_bytes!("fixtures/dejavu-sans.ttf");
    let mut mixed = OfdDocument::new();
    let font_id = mixed.add_embedded_font("DejaVu Sans", font).unwrap();
    mixed
        .add_text_page_with_font("one", 40.0, 30.0, font_id)
        .unwrap();
    assert_eq!(mixed.append_document_body().unwrap(), 1);
    mixed.append_blank_page(1, 50.0, 30.0).unwrap();
    let selected = TextWatermarkStyle {
        font_id: Some(font_id.to_string()),
        ..TextWatermarkStyle::default()
    };
    let before = mixed.to_bytes().unwrap();
    assert!(mixed
        .add_text_watermark_to_all_pages("COPY", 5.0, &selected)
        .is_err());
    assert_eq!(mixed.to_bytes().unwrap(), before);
    assert!(mixed.annotations().unwrap().is_empty());
}

#[test]
fn tiled_watermark_uses_distinct_graphic_ids_and_checks_grid_limit() {
    let mut document = OfdDocument::new();
    document.add_blank_page(40.0, 30.0).unwrap();
    let style = TextWatermarkStyle {
        tile_spacing: Some([20.0, 15.0]),
        angle_degrees: -30.0,
        color: [0, 0, 255],
        ..TextWatermarkStyle::default()
    };
    let annotation_id = document
        .add_styled_text_watermark(0, "COPY", [0.0, 0.0, 40.0, 30.0], 5.0, &style)
        .unwrap();
    let annotation = &document.annotations().unwrap()[0];
    assert_eq!(annotation.id, annotation_id);
    assert_eq!(annotation.text, ["COPY"; 4]);
    let xml =
        std::str::from_utf8(document.entry(&annotation.source_path).unwrap().unwrap()).unwrap();
    let parsed = roxmltree::Document::parse(xml).unwrap();
    let ids = parsed
        .descendants()
        .filter(|node| node.tag_name().name() == "TextObject")
        .map(|node| node.attribute("ID").unwrap().parse::<usize>().unwrap())
        .collect::<Vec<_>>();
    assert_eq!(ids.len(), 4);
    assert_eq!(
        ids.iter()
            .copied()
            .collect::<std::collections::HashSet<_>>()
            .len(),
        4
    );
    assert!(ids.iter().all(|id| *id < annotation_id.parse().unwrap()));
    let svg = document.page_svg(0).unwrap();
    assert_eq!(svg.matches("COPY").count(), 4);
    for position in [
        "translate(0 0)",
        "translate(0 15)",
        "translate(20 0)",
        "translate(20 15)",
    ] {
        assert!(svg.contains(position), "missing tile at {position}");
    }
    assert!(document.validate_references().unwrap().is_empty());
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.page_svg(0).unwrap(), svg);

    let before = document.to_bytes().unwrap();
    for spacing in [[0.0, 15.0], [0.001, 0.001], [f64::INFINITY, 15.0]] {
        let invalid = TextWatermarkStyle {
            tile_spacing: Some(spacing),
            ..style.clone()
        };
        assert!(document
            .add_styled_text_watermark(0, "bad", [0.0, 0.0, 40.0, 30.0], 5.0, &invalid)
            .is_err());
        assert_eq!(document.to_bytes().unwrap(), before);
    }
}

#[test]
fn image_watermark_reuses_image_resources_and_rolls_back_invalid_input() {
    let invoice = OfdDocument::open(fixture("发票示例.ofd")).unwrap();
    let image = invoice.page_image_data(0, 0).unwrap();
    let mut document = OfdDocument::new();
    document.add_blank_page(40.0, 30.0).unwrap();
    document.add_blank_page(40.0, 30.0).unwrap();
    let first = document
        .add_image_watermark_from_bytes(0, image, "png", [5.0, 5.0, 20.0, 15.0], 128)
        .unwrap();
    let resource = document.document_multimedia_resources(0).unwrap();
    assert_eq!(resource.len(), 1);
    let second = document
        .add_image_watermark(1, &resource[0].id, [10.0, 10.0, 20.0, 15.0], 255)
        .unwrap();
    assert_ne!(first, second);
    let marks = document.annotations().unwrap();
    assert_eq!(marks.len(), 2);
    assert!(marks.iter().all(|mark| mark.annotation_type == "Watermark"));
    assert!(marks.iter().all(|mark| mark.text.is_empty()));
    let svg = document.page_svg(0).unwrap();
    assert!(svg.contains("<image"));
    assert!(svg.contains("opacity=\"0.501"));
    assert!(document.page_svg(1).unwrap().contains("<image"));
    assert!(document.to_pdf().unwrap().starts_with(b"%PDF"));
    assert!(document.validate_references().unwrap().is_empty());
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.page_svg(0).unwrap(), svg);

    let before = document.to_bytes().unwrap();
    assert!(document
        .add_image_watermark(0, "missing", [0.0, 0.0, 20.0, 15.0], 255)
        .is_err());
    assert!(document
        .add_image_watermark_from_bytes(0, b"bad", "png", [0.0, 0.0, 20.0, 15.0], 255)
        .is_err());
    assert!(document
        .add_image_watermark_from_bytes(0, image, "png", [0.0, 0.0, -1.0, 15.0], 255)
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
}

