#[test]
fn adds_path_annotations_to_blank_pages_without_font_resources() {
    let mut document = OfdDocument::new();
    document.add_blank_page(30.0, 20.0).unwrap();
    let mut document = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    let root = "Doc_0/Document.xml";
    let source = std::str::from_utf8(document.entry(root).unwrap().unwrap())
        .unwrap()
        .to_owned();
    let parsed = roxmltree::Document::parse(&source).unwrap();
    let mut without_fonts = source.clone();
    let mut resource_links: Vec<_> = parsed
        .descendants()
        .filter(|node| matches!(node.tag_name().name(), "PublicRes" | "DocumentRes"))
        .map(|node| node.range())
        .collect();
    resource_links.reverse();
    for range in resource_links {
        without_fonts.replace_range(range, "");
    }
    document
        .set_entry(root, without_fonts.into_bytes())
        .unwrap();
    assert!(document.fonts().unwrap().is_empty());
    let style = PathStyle {
        fill: false,
        stroke: true,
        stroke_color: Some([255, 0, 0]),
        line_width: 1.0,
        ..PathStyle::default()
    };
    let annotation_id = document
        .add_path_annotation(
            0,
            "M 0 0 L 10 0 L 10 5 L 0 5 C",
            [2.0, 3.0, 10.0, 5.0],
            style,
        )
        .unwrap();
    let annotations = document.annotations().unwrap();
    assert_eq!(annotations.len(), 1);
    assert_eq!(annotations[0].id, annotation_id);
    assert_eq!(annotations[0].annotation_type, "Path");
    assert_eq!(annotations[0].appearance_box, Some([2.0, 3.0, 10.0, 5.0]));
    assert!(annotations[0].text.is_empty());
    assert!(document.fonts().unwrap().is_empty());
    assert!(document.page_text(0).unwrap().is_empty());
    let svg = document.page_svg(0).unwrap();
    assert!(svg.contains("data-ofd-annotation"));
    assert!(svg.contains("#ff0000"));
    assert!(document.page_png(0, 25.4).unwrap().starts_with(b"\x89PNG"));
    assert!(document.validate_references().unwrap().is_empty());
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.page_svg(0).unwrap(), svg);

    let before = document.to_bytes().unwrap();
    assert!(document
        .add_path_annotation(0, "", [2.0, 3.0, 10.0, 5.0], PathStyle::default())
        .is_err());
    assert!(document
        .add_path_annotation(
            0,
            "M 0 0 L 1 1",
            [f64::NAN, 3.0, 10.0, 5.0],
            PathStyle::default(),
        )
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    document.remove_annotation(0, &annotation_id).unwrap();
    assert!(document.annotations().unwrap().is_empty());
    assert!(!document
        .page_svg(0)
        .unwrap()
        .contains("data-ofd-annotation"));

    let mut signed = OfdDocument::open(
        PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../../ofdrw-sign/src/test/resources/signedFile.ofd"),
    )
    .unwrap();
    assert!(signed
        .add_path_annotation(0, "M 0 0 L 1 1", [0.0, 0.0, 2.0, 2.0], PathStyle::default())
        .is_err());
}

#[test]
fn writes_highlight_annotation_with_translucent_appearance() {
    let mut document = OfdDocument::new();
    document.add_blank_page(30.0, 20.0).unwrap();
    let id = document
        .add_highlight_annotation(0, [2.0, 3.0, 10.0, 5.0], [255, 220, 0], 96)
        .unwrap();
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    let annotations = reopened.annotations().unwrap();
    assert_eq!(annotations.len(), 1);
    assert_eq!(annotations[0].id, id);
    assert_eq!(annotations[0].annotation_type, "Highlight");
    let date = annotations[0].last_mod_date.as_deref().unwrap();
    assert_eq!(date.len(), 10);
    assert_eq!(date.as_bytes()[4], b'-');
    assert_eq!(date.as_bytes()[7], b'-');
    assert_eq!(annotations[0].attributes["LastModDate"], date);
    assert_eq!(annotations[0].appearance_box, Some([2.0, 3.0, 10.0, 5.0]));
    let svg = reopened.page_svg(0).unwrap();
    assert!(svg.contains("#ffdc00"));
    assert!(svg.contains("fill-opacity=\"0.3764705882352941\""));
    assert!(reopened.page_png(0, 25.4).unwrap().starts_with(b"\x89PNG"));
    let pdf = lopdf::Document::load_mem(&reopened.to_pdf().unwrap()).unwrap();
    let page = pdf
        .get_dictionary(*pdf.get_pages().get(&1).unwrap())
        .unwrap();
    let reference = page.get(b"Annots").unwrap().as_array().unwrap()[0]
        .as_reference()
        .unwrap();
    let markup = pdf.get_dictionary(reference).unwrap();
    assert_eq!(
        markup.get(b"Subtype").unwrap().as_name().unwrap(),
        b"Highlight"
    );
    assert_eq!(
        markup.get(b"QuadPoints").unwrap().as_array().unwrap().len(),
        8
    );
    assert_eq!(markup.get(b"C").unwrap().as_array().unwrap().len(), 3);
    assert!((markup.get(b"CA").unwrap().as_float().unwrap() - 96.0 / 255.0).abs() < 1e-6);
    assert!(reopened.validate_references().unwrap().is_empty());

    let before = document.to_bytes().unwrap();
    for boundary in [[2.0, 3.0, 0.0, 5.0], [f64::NAN, 3.0, 10.0, 5.0]] {
        assert!(document
            .add_highlight_annotation(0, boundary, [255, 220, 0], 96)
            .is_err());
        assert_eq!(document.to_bytes().unwrap(), before);
    }
}

#[test]
fn writes_editable_text_note_and_rejects_invalid_style_atomically() {
    let mut document = OfdDocument::new();
    document.add_blank_page(30.0, 20.0).unwrap();
    let style = TextNoteStyle {
        color: Some([25, 100, 220]),
        opacity: Some(128),
        icon: "Comment".into(),
        open: true,
    };
    let id = document
        .add_text_note_annotation(0, "审核 & <通过>", [2.0, 3.0, 5.0, 5.0], &style)
        .unwrap();
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    let note = &reopened.annotations().unwrap()[0];
    assert_eq!(note.id, id);
    assert_eq!(note.annotation_type, "Path");
    assert_eq!(note.subtype.as_deref(), Some("Text"));
    assert_eq!(note.remark.as_deref(), Some("审核 & <通过>"));
    assert_eq!(note.parameters["PDFTextIcon"], "Comment");
    assert_eq!(note.parameters["PDFTextOpen"], "true");
    assert!(reopened.page_svg(0).unwrap().contains("#1964dc"));
    let mut legacy = reopened.clone();
    let xml =
        String::from_utf8(legacy.entry(&note.source_path).unwrap().unwrap().to_vec()).unwrap();
    let old_xml =
        xml.replacen("Type=\"Path\"", "Type=\"Text\"", 1)
            .replacen(" Subtype=\"Text\"", "", 1);
    assert_ne!(old_xml, xml);
    assert!(!old_xml.contains("Subtype=\"Text\""));
    legacy
        .set_entry(&note.source_path, old_xml.into_bytes())
        .unwrap();
    assert!(legacy.to_pdf().unwrap().starts_with(b"%PDF"));
    let pdf = lopdf::Document::load_mem(&reopened.to_pdf().unwrap()).unwrap();
    let page = pdf
        .get_dictionary(*pdf.get_pages().get(&1).unwrap())
        .unwrap();
    let note = pdf
        .get_dictionary(
            page.get(b"Annots").unwrap().as_array().unwrap()[0]
                .as_reference()
                .unwrap(),
        )
        .unwrap();
    assert_eq!(note.get(b"Subtype").unwrap().as_name().unwrap(), b"Text");
    assert_eq!(note.get(b"Name").unwrap().as_name().unwrap(), b"Comment");
    assert!(note.get(b"Open").unwrap().as_bool().unwrap());
    assert_eq!(
        lopdf::decode_text_string(note.get(b"Contents").unwrap()).unwrap(),
        "审核 & <通过>"
    );
    let before = document.to_bytes().unwrap();
    let mut invalid = style.clone();
    invalid.icon = "Unknown".into();
    assert!(document
        .add_text_note_annotation(0, "bad", [2.0, 3.0, 5.0, 5.0], &invalid)
        .is_err());
    assert!(document
        .add_text_note_annotation(0, "bad", [2.0, 3.0, 0.0, 5.0], &style)
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
}

#[test]
fn moves_annotation_appearance_without_changing_its_graphics() {
    let mut document = OfdDocument::new();
    document.add_blank_page(40.0, 30.0).unwrap();
    let id = document
        .add_highlight_annotation(0, [2.0, 3.0, 10.0, 5.0], [255, 220, 0], 96)
        .unwrap();
    let before_svg = document.page_svg(0).unwrap();
    let before = document.to_bytes().unwrap();
    for invalid in [[2.0, 3.0, 0.0, 5.0], [f64::NAN, 3.0, 10.0, 5.0]] {
        assert!(document
            .set_annotation_appearance_boundary(0, &id, invalid)
            .is_err());
        assert_eq!(document.to_bytes().unwrap(), before);
    }
    document
        .set_annotation_appearance_boundary(0, &id, [12.0, 8.0, 10.0, 5.0])
        .unwrap();
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(
        reopened.annotations().unwrap()[0].appearance_box,
        Some([12.0, 8.0, 10.0, 5.0])
    );
    assert_ne!(reopened.page_svg(0).unwrap(), before_svg);
    assert!(reopened.page_svg(0).unwrap().contains("#ffdc00"));
    let pdf = lopdf::Document::load_mem(&reopened.to_pdf().unwrap()).unwrap();
    let page = pdf
        .get_dictionary(*pdf.get_pages().get(&1).unwrap())
        .unwrap();
    let reference = page.get(b"Annots").unwrap().as_array().unwrap()[0]
        .as_reference()
        .unwrap();
    let markup = pdf.get_dictionary(reference).unwrap();
    let quad = markup.get(b"QuadPoints").unwrap().as_array().unwrap();
    assert!((quad[0].as_float().unwrap() - 12.0 * 72.0 / 25.4).abs() < 0.01);
    assert!((quad[1].as_float().unwrap() - 22.0 * 72.0 / 25.4).abs() < 0.01);
}

#[test]
fn adds_invisible_uri_link_annotation_in_java_compatible_shape() {
    let mut document = OfdDocument::new();
    document.add_blank_page(30.0, 20.0).unwrap();
    let blank_png = document.page_png(0, 25.4).unwrap();
    let id = document
        .add_uri_link_annotation(0, "https://example.com/?a=1&b=2", [2.0, 3.0, 10.0, 5.0])
        .unwrap();
    let annotation = &document.annotations().unwrap()[0];
    assert_eq!(annotation.id, id);
    assert_eq!(annotation.annotation_type, "Link");
    assert_eq!(annotation.appearance_box, Some([2.0, 3.0, 10.0, 5.0]));
    assert_eq!(annotation.actions.len(), 1);
    assert_eq!(annotation.actions[0].event, "CLICK");
    assert_eq!(annotation.actions[0].kind, "URI");
    assert_eq!(
        annotation.actions[0]
            .attributes
            .get("URI")
            .map(String::as_str),
        Some("https://example.com/?a=1&b=2")
    );
    let xml =
        std::str::from_utf8(document.entry(&annotation.source_path).unwrap().unwrap()).unwrap();
    let parsed = roxmltree::Document::parse(xml).unwrap();
    let path = parsed
        .descendants()
        .find(|node| node.tag_name().name() == "PathObject")
        .unwrap();
    assert_eq!(path.attribute("Visible"), Some("false"));
    let action = path
        .descendants()
        .find(|node| node.tag_name().name() == "Action")
        .unwrap();
    assert_eq!(action.attribute("Event"), Some("CLICK"));
    assert_eq!(
        action
            .descendants()
            .find(|node| node.tag_name().name() == "URI")
            .unwrap()
            .attribute("URI"),
        Some("https://example.com/?a=1&b=2")
    );
    assert_eq!(document.page_png(0, 25.4).unwrap(), blank_png);
    let pdf = lopdf::Document::load_mem(&document.to_pdf().unwrap()).unwrap();
    let pdf_page_id = *pdf.get_pages().get(&1).unwrap();
    let pdf_page = pdf.get_dictionary(pdf_page_id).unwrap();
    let links = pdf_page.get(b"Annots").unwrap().as_array().unwrap();
    assert_eq!(links.len(), 1);
    let link = pdf
        .get_dictionary(links[0].as_reference().unwrap())
        .unwrap();
    assert_eq!(link.get(b"Subtype").unwrap().as_name().unwrap(), b"Link");
    let rect = link.get(b"Rect").unwrap().as_array().unwrap();
    for (actual, expected) in rect.iter().zip([2.0, 12.0, 12.0, 17.0]) {
        assert!((actual.as_float().unwrap() - (expected * 72.0 / 25.4) as f32).abs() < 0.01);
    }
    let action = link.get(b"A").unwrap().as_dict().unwrap();
    assert_eq!(action.get(b"S").unwrap().as_name().unwrap(), b"URI");
    assert_eq!(
        action.get(b"URI").unwrap().as_str().unwrap(),
        b"https://example.com/?a=1&b=2"
    );
    let mut offset_page = document.clone();
    offset_page
        .set_page_area(
            0,
            PageArea {
                physical_box: [1.0, 2.0, 30.0, 20.0],
                application_box: None,
                content_box: None,
                bleed_box: None,
            },
        )
        .unwrap();
    let offset_pdf = lopdf::Document::load_mem(&offset_page.to_pdf().unwrap()).unwrap();
    let offset_page_dict = offset_pdf
        .get_dictionary(*offset_pdf.get_pages().get(&1).unwrap())
        .unwrap();
    let offset_link = offset_pdf
        .get_dictionary(
            offset_page_dict.get(b"Annots").unwrap().as_array().unwrap()[0]
                .as_reference()
                .unwrap(),
        )
        .unwrap();
    let offset_rect = offset_link.get(b"Rect").unwrap().as_array().unwrap();
    for (actual, expected) in offset_rect.iter().zip([1.0, 14.0, 11.0, 19.0]) {
        assert!((actual.as_float().unwrap() - (expected * 72.0 / 25.4) as f32).abs() < 0.01);
    }
    document.set_annotation_print(0, &id, false).unwrap();
    let hidden = lopdf::Document::load_mem(&document.to_pdf().unwrap()).unwrap();
    let hidden_page = hidden
        .get_dictionary(*hidden.get_pages().get(&1).unwrap())
        .unwrap();
    let hidden_link = hidden
        .get_dictionary(
            hidden_page.get(b"Annots").unwrap().as_array().unwrap()[0]
                .as_reference()
                .unwrap(),
        )
        .unwrap();
    assert_eq!(hidden_link.get(b"F").unwrap().as_i64().unwrap(), 0);
    document.set_annotation_print(0, &id, true).unwrap();
    document.set_annotation_visible(0, &id, false).unwrap();
    let hidden = lopdf::Document::load_mem(&document.to_pdf().unwrap()).unwrap();
    let hidden_page = hidden
        .get_dictionary(*hidden.get_pages().get(&1).unwrap())
        .unwrap();
    let hidden_link = hidden
        .get_dictionary(
            hidden_page.get(b"Annots").unwrap().as_array().unwrap()[0]
                .as_reference()
                .unwrap(),
        )
        .unwrap();
    assert_eq!(hidden_link.get(b"F").unwrap().as_i64().unwrap(), 4 | 2);
    document.set_annotation_visible(0, &id, true).unwrap();
    document.set_annotation_no_zoom(0, &id, true).unwrap();
    document.set_annotation_no_rotate(0, &id, true).unwrap();
    document.set_annotation_read_only(0, &id, true).unwrap();
    document
        .set_annotation_parameter(0, &id, "PDFFlags", "64")
        .unwrap();
    let styled = lopdf::Document::load_mem(&document.to_pdf().unwrap()).unwrap();
    let styled_page = styled
        .get_dictionary(*styled.get_pages().get(&1).unwrap())
        .unwrap();
    let styled_link = styled
        .get_dictionary(
            styled_page.get(b"Annots").unwrap().as_array().unwrap()[0]
                .as_reference()
                .unwrap(),
        )
        .unwrap();
    assert_eq!(
        styled_link.get(b"F").unwrap().as_i64().unwrap(),
        4 | 8 | 16 | 64 | 128
    );
    assert!(document.validate_references().unwrap().is_empty());
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.annotations().unwrap()[0].annotation_type, "Link");
    let before = document.to_bytes().unwrap();
    assert!(document
        .add_uri_link_annotation(0, "", [2.0, 3.0, 10.0, 5.0])
        .is_err());
    assert!(document
        .add_uri_link_annotation(0, "https://example.com", [2.0, 3.0, 0.0, 5.0])
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);

    let mut java = OfdDocument::open(
        PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../../ofdrw-converter/src/test/resources/ano.ofd"),
    )
    .unwrap();
    assert!(java.annotations().unwrap().iter().any(|annotation| {
        annotation.annotation_type == "Link"
            && annotation
                .actions
                .iter()
                .any(|action| action.kind == "Goto" && action.destination.is_some())
    }));
    // The Java fixture's Link targets refer to PageID=5, which is absent from
    // its three-page Document.xml. Point them at a real page for PDF export.
    let source = java
        .annotations()
        .unwrap()
        .into_iter()
        .find(|annotation| {
            annotation.annotation_type == "Link"
                && annotation
                    .actions
                    .iter()
                    .any(|action| action.kind == "Goto")
        })
        .unwrap()
        .source_path;
    let source_xml = std::str::from_utf8(java.entry(&source).unwrap().unwrap()).unwrap();
    java.set_entry(
        &source,
        source_xml
            .replace("PageID=\"5\"", "PageID=\"3\"")
            .into_bytes(),
    )
    .unwrap();
    let java_pdf = lopdf::Document::load_mem(&java.to_pdf().unwrap()).unwrap();
    let target_page = *java_pdf.get_pages().get(&3).unwrap();
    assert!(java_pdf.objects.values().any(|object| {
        object.as_dict().is_ok_and(|dict| {
            dict.get(b"Subtype")
                .ok()
                .and_then(|value| value.as_name().ok())
                == Some(b"Link")
                && dict
                    .get(b"A")
                    .ok()
                    .and_then(|value| value.as_dict().ok())
                    .is_some_and(|action| {
                        action.get(b"S").ok().and_then(|value| value.as_name().ok())
                            == Some(b"GoTo")
                            && action
                                .get(b"D")
                                .ok()
                                .and_then(|value| value.as_array().ok())
                                .is_some_and(|destination| {
                                    destination.len() >= 3
                                        && destination[0].as_reference().ok() == Some(target_page)
                                        && destination[1].as_name().ok() == Some(b"XYZ")
                                        && destination[2].as_float().is_ok_and(|left| {
                                            (left - (24.3417 * 72.0 / 25.4) as f32).abs() < 0.01
                                        })
                                })
                    })
        })
    }));
}

#[test]
fn writes_goto_and_bookmark_link_annotations_to_pdf() {
    let mut document = OfdDocument::new();
    document.add_blank_page(30.0, 20.0).unwrap();
    document.add_blank_page(40.0, 25.0).unwrap();
    let target_page_id = document.pages().unwrap()[1].id.clone();
    let bookmark_destination = DestinationInfo {
        page_id: target_page_id.clone(),
        kind: "FitH".into(),
        left: None,
        top: Some(9.0),
        right: None,
        bottom: None,
        zoom: None,
    };
    document
        .add_bookmark(0, "chapter & 2", bookmark_destination)
        .unwrap();
    let goto_id = document
        .add_goto_link_annotation(
            0,
            DestinationInfo {
                page_id: target_page_id.clone(),
                kind: "XYZ".into(),
                left: Some(4.0),
                top: Some(6.0),
                right: None,
                bottom: None,
                zoom: Some(1.5),
            },
            [2.0, 3.0, 10.0, 5.0],
        )
        .unwrap();
    let bookmark_id = document
        .add_bookmark_link_annotation(0, "chapter & 2", [13.0, 3.0, 10.0, 5.0])
        .unwrap();
    let annotations = document.annotations().unwrap();
    assert_eq!(annotations.len(), 2);
    assert_eq!(
        annotations[0].actions[0]
            .destination
            .as_ref()
            .unwrap()
            .page_id,
        target_page_id
    );
    assert_eq!(
        annotations[1].actions[0].bookmark.as_deref(),
        Some("chapter & 2")
    );
    assert!(document.validate_references().unwrap().is_empty());
    let pdf = lopdf::Document::load_mem(&document.to_pdf().unwrap()).unwrap();
    let pages = pdf.get_pages();
    let target = *pages.get(&2).unwrap();
    let first_page = pdf.get_dictionary(*pages.get(&1).unwrap()).unwrap();
    let links = first_page.get(b"Annots").unwrap().as_array().unwrap();
    assert_eq!(links.len(), 2);
    let destinations: Vec<_> = links
        .iter()
        .map(|link| {
            let annotation = pdf.get_dictionary(link.as_reference().unwrap()).unwrap();
            assert_eq!(
                annotation.get(b"Subtype").unwrap().as_name().unwrap(),
                b"Link"
            );
            let action = annotation.get(b"A").unwrap().as_dict().unwrap();
            assert_eq!(action.get(b"S").unwrap().as_name().unwrap(), b"GoTo");
            action.get(b"D").unwrap().as_array().unwrap().clone()
        })
        .collect();
    assert_eq!(destinations[0][0].as_reference().unwrap(), target);
    assert_eq!(destinations[0][1].as_name().unwrap(), b"XYZ");
    assert!((destinations[0][2].as_float().unwrap() - (4.0 * 72.0 / 25.4) as f32).abs() < 0.01);
    assert!((destinations[0][3].as_float().unwrap() - (19.0 * 72.0 / 25.4) as f32).abs() < 0.01);
    assert!((destinations[0][4].as_float().unwrap() - 1.5).abs() < 0.01);
    assert_eq!(destinations[1][0].as_reference().unwrap(), target);
    assert_eq!(destinations[1][1].as_name().unwrap(), b"FitH");
    assert!((destinations[1][2].as_float().unwrap() - (16.0 * 72.0 / 25.4) as f32).abs() < 0.01);
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.annotations().unwrap(), annotations);
    document
        .set_annotation_print(0, &bookmark_id, false)
        .unwrap();
    let printed = lopdf::Document::load_mem(&document.to_pdf().unwrap()).unwrap();
    let printed_page = printed
        .get_dictionary(*printed.get_pages().get(&1).unwrap())
        .unwrap();
    let links = printed_page.get(b"Annots").unwrap().as_array().unwrap();
    assert_eq!(links.len(), 2);
    let bookmark_link = printed
        .get_dictionary(links[1].as_reference().unwrap())
        .unwrap();
    assert_eq!(bookmark_link.get(b"F").unwrap().as_i64().unwrap(), 0);
    let before = document.to_bytes().unwrap();
    assert!(document
        .add_bookmark_link_annotation(0, "missing", [1.0, 1.0, 2.0, 2.0])
        .is_err());
    assert!(document
        .add_goto_link_annotation(
            0,
            DestinationInfo {
                page_id: "missing".into(),
                kind: "Fit".into(),
                left: None,
                top: None,
                right: None,
                bottom: None,
                zoom: None
            },
            [1.0, 1.0, 2.0, 2.0]
        )
        .is_err());
    assert!(document
        .add_goto_link_annotation(
            0,
            DestinationInfo {
                page_id: target_page_id,
                kind: "Fit".into(),
                left: None,
                top: None,
                right: None,
                bottom: None,
                zoom: None
            },
            [1.0, 1.0, 0.0, 2.0]
        )
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    assert_ne!(goto_id, bookmark_id);
}

#[test]
fn annotation_visible_and_print_flags_control_preview_and_pdf() {
    let mut document = OfdDocument::new();
    document.add_blank_page(30.0, 20.0).unwrap();
    let id = document
        .add_path_annotation(
            0,
            "M 0 0 L 10 0 L 10 5 L 0 5 C",
            [2.0, 3.0, 10.0, 5.0],
            PathStyle {
                fill: true,
                stroke: false,
                fill_color: Some([255, 0, 0]),
                ..PathStyle::default()
            },
        )
        .unwrap();
    let shown_svg = document.page_svg(0).unwrap();
    let shown_pdf = document.to_pdf().unwrap();
    assert!(shown_svg.contains("data-ofd-annotation"));
    let mut removed = document.clone();
    removed.remove_annotation(0, &id).unwrap();
    let plain_pdf = removed.to_pdf().unwrap();
    assert_ne!(shown_pdf, plain_pdf);

    document.set_annotation_print(0, &id, false).unwrap();
    assert_eq!(document.page_svg(0).unwrap(), shown_svg);
    assert_eq!(document.to_pdf().unwrap(), plain_pdf);
    document.set_annotation_visible(0, &id, false).unwrap();
    assert!(!document
        .page_svg(0)
        .unwrap()
        .contains("data-ofd-annotation"));
    assert_eq!(document.to_pdf().unwrap(), plain_pdf);
    assert_eq!(document.annotations().unwrap().len(), 1);
    document.set_annotation_visible(0, &id, true).unwrap();
    document.set_annotation_print(0, &id, true).unwrap();
    assert_eq!(document.page_svg(0).unwrap(), shown_svg);
    assert_eq!(document.to_pdf().unwrap(), shown_pdf);

    let source = document.annotations().unwrap()[0].source_path.clone();
    let before = document.entry(&source).unwrap().unwrap().to_vec();
    assert!(document
        .set_annotation_visible(0, "missing", false)
        .is_err());
    assert!(document.set_annotation_print(1, &id, false).is_err());
    assert_eq!(document.entry(&source).unwrap().unwrap(), before);
    let malformed =
        std::str::from_utf8(&before)
            .unwrap()
            .replacen("Visible=\"true\"", "Visible=\"maybe\"", 1);
    document.set_entry(&source, malformed.into_bytes()).unwrap();
    assert!(document.page_svg(0).is_err());
    let malformed_print =
        std::str::from_utf8(&before)
            .unwrap()
            .replacen("Print=\"true\"", "Print=\"maybe\"", 1);
    document
        .set_entry(&source, malformed_print.into_bytes())
        .unwrap();
    assert!(document.page_svg(0).is_ok());
    assert!(document.to_pdf().is_err());

    let mut signed = OfdDocument::open(
        PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../../ofdrw-sign/src/test/resources/signedFile.ofd"),
    )
    .unwrap();
    assert!(signed.set_annotation_visible(0, "1", false).is_err());
}

