#[test]
fn annotation_creator_and_remark_round_trip_without_losing_appearance() {
    let mut document = OfdDocument::new();
    document.add_blank_page(40.0, 30.0).unwrap();
    let id = document
        .add_highlight_annotation(0, [5.0, 5.0, 20.0, 10.0], [255, 255, 0], 128)
        .unwrap();
    let svg = document.page_svg(0).unwrap();
    document
        .set_annotation_creator(0, &id, "张三 & <团队>")
        .unwrap();
    document
        .set_annotation_subtype(0, &id, Some("审阅 & <校对>"))
        .unwrap();
    document
        .set_annotation_last_mod_date(0, &id, "2024-02-29")
        .unwrap();
    document
        .set_annotation_remark(0, &id, Some("审核 & 通过 <v1>"))
        .unwrap();
    document
        .set_annotation_parameter(0, &id, "分类 & <键>", "甲 & <乙>")
        .unwrap();
    document
        .set_annotation_parameter(0, &id, "状态", "草稿")
        .unwrap();
    let mark = &document.annotations().unwrap()[0];
    assert_eq!(mark.attributes["Creator"], "张三 & <团队>");
    assert_eq!(mark.subtype.as_deref(), Some("审阅 & <校对>"));
    assert_eq!(mark.last_mod_date.as_deref(), Some("2024-02-29"));
    assert_eq!(mark.remark.as_deref(), Some("审核 & 通过 <v1>"));
    assert_eq!(mark.parameters["分类 & <键>"], "甲 & <乙>");
    assert_eq!(mark.parameters["状态"], "草稿");
    assert_eq!(document.page_svg(0).unwrap(), svg);
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(
        reopened.annotations().unwrap(),
        document.annotations().unwrap()
    );
    let before = document.to_bytes().unwrap();
    assert!(document.set_annotation_creator(0, &id, " ").is_err());
    assert!(document
        .set_annotation_last_mod_date(0, &id, "2023-02-29")
        .is_err());
    assert!(document
        .set_annotation_remark(0, "missing", Some("bad"))
        .is_err());
    assert!(document
        .set_annotation_parameter(0, &id, " ", "bad")
        .is_err());
    assert!(document
        .remove_annotation_parameter(0, &id, "missing")
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    document
        .set_annotation_remark(0, &id, Some("更新"))
        .unwrap();
    assert_eq!(
        document.annotations().unwrap()[0].remark.as_deref(),
        Some("更新")
    );
    document.set_annotation_remark(0, &id, None).unwrap();
    assert_eq!(document.annotations().unwrap()[0].remark, None);
    document.set_annotation_subtype(0, &id, None).unwrap();
    assert_eq!(document.annotations().unwrap()[0].subtype, None);
    document
        .set_annotation_parameter(0, &id, "状态", "通过")
        .unwrap();
    assert_eq!(
        document.annotations().unwrap()[0].parameters["状态"],
        "通过"
    );
    document
        .remove_annotation_parameter(0, &id, "分类 & <键>")
        .unwrap();
    let parameters = &document.annotations().unwrap()[0].parameters;
    assert_eq!(parameters.len(), 4);
    assert!(!parameters.contains_key("分类 & <键>"));
    assert_eq!(parameters["状态"], "通过");
}

#[test]
fn validates_annotation_appearance_graphics_and_nested_page_blocks() {
    let mut document = OfdDocument::new();
    document.add_text_page("page", 30.0, 20.0).unwrap();
    document
        .add_text_watermark(0, "mark", [1.0, 1.0, 10.0, 5.0], 4.0)
        .unwrap();
    assert!(document.validate_references().unwrap().is_empty());
    let source = document.annotations().unwrap()[0].source_path.clone();
    let original = std::str::from_utf8(document.entry(&source).unwrap().unwrap())
        .unwrap()
        .to_owned();
    let parsed = roxmltree::Document::parse(&original).unwrap();
    let appearance = parsed
        .descendants()
        .find(|node| node.tag_name().name() == "Appearance")
        .unwrap();
    let boundary = appearance.attribute("Boundary").unwrap();
    let font = parsed
        .descendants()
        .find(|node| node.tag_name().name() == "TextObject")
        .unwrap()
        .attribute("Font")
        .unwrap();
    let mut broken = original.replacen(
        &format!("<ofd:Appearance Boundary=\"{boundary}\""),
        "<ofd:Appearance Boundary=\"0 0 0 0\"",
        1,
    );
    broken = broken.replacen(&format!("Font=\"{font}\""), "Font=\"999999\"", 1);
    broken = broken.replacen(
        "<ofd:TextObject ",
        "<ofd:TextObject DrawParam=\"999998\" ",
        1,
    );
    broken = broken.replacen(
        "</ofd:Appearance>",
        "<ofd:PageBlock><ofd:CompositeObject ID=\"999997\" Boundary=\"0 0 0 2\" ResourceID=\"999996\"/><ofd:PathObject ID=\"999995\" Boundary=\"0 0 2 2\"/></ofd:PageBlock></ofd:Appearance>",
        1,
    );
    document.set_entry(&source, broken.into_bytes()).unwrap();
    let issues = document.validate_references().unwrap();
    for (code, reference) in [
        ("invalid_annotation_boundary", "Appearance"),
        ("invalid_boundary", "CompositeObject"),
        ("missing_font", "999999"),
        ("draw_param_reference", "999998"),
        ("missing_composite", "999996"),
        ("missing_path_data", "PathObject"),
    ] {
        assert!(
            issues.iter().any(|issue| {
                issue.path == source && issue.code == code && issue.message.contains(reference)
            }),
            "missing {code}: {issues:?}"
        );
    }
}

#[test]
fn reference_validation_checks_annotation_and_appearance_ids() {
    let mut document = OfdDocument::new();
    document.add_text_page("body", 30.0, 20.0).unwrap();
    document
        .add_text_watermark(0, "mark", [1.0, 1.0, 10.0, 5.0], 4.0)
        .unwrap();
    assert!(document.validate_references().unwrap().is_empty());

    let path = document.annotations().unwrap()[0].source_path.clone();
    let original = std::str::from_utf8(document.entry(&path).unwrap().unwrap())
        .unwrap()
        .to_owned();
    let parsed = roxmltree::Document::parse(&original).unwrap();
    let id_of = |name| {
        parsed
            .descendants()
            .find(|node| node.tag_name().name() == name)
            .unwrap()
            .attribute("ID")
            .unwrap()
    };
    let annotation_id = id_of("Annot");
    let appearance_id = id_of("TextObject");
    let page_id = document.page_objects(0).unwrap()[0].id.clone().unwrap();

    for (replacement, code) in [
        ("bad", "invalid_object_id"),
        (page_id.as_str(), "duplicate_object_id"),
        ("999999", "id_exceeds_max"),
    ] {
        let altered = original.replacen(
            &format!("ID=\"{annotation_id}\""),
            &format!("ID=\"{replacement}\""),
            1,
        );
        document.set_entry(&path, altered.into_bytes()).unwrap();
        assert!(document
            .validate_references()
            .unwrap()
            .iter()
            .any(|issue| issue.path == path && issue.code == code));
    }

    let duplicate = original.replacen(
        &format!("ID=\"{appearance_id}\""),
        &format!("ID=\"{annotation_id}\""),
        1,
    );
    document.set_entry(&path, duplicate.into_bytes()).unwrap();
    assert!(document
        .validate_references()
        .unwrap()
        .iter()
        .any(|issue| { issue.path == path && issue.code == "duplicate_object_id" }));

    let missing = original.replacen(&format!(" ID=\"{appearance_id}\""), "", 1);
    assert_ne!(missing, original);
    document.set_entry(&path, missing.into_bytes()).unwrap();
    assert!(document
        .validate_references()
        .unwrap()
        .iter()
        .any(|issue| { issue.path == path && issue.code == "missing_object_id" }));
}

#[test]
fn removes_only_requested_annotation_and_preserves_other_content() {
    let mut document = OfdDocument::new();
    document.add_text_page("body", 210.0, 297.0).unwrap();
    document.add_blank_page(210.0, 297.0).unwrap();
    let first = document
        .add_text_watermark(0, "first mark", [10.0, 20.0, 40.0, 8.0], 4.0)
        .unwrap();
    let second = document
        .add_text_watermark(0, "second mark", [20.0, 30.0, 40.0, 8.0], 4.0)
        .unwrap();
    let annotation_path = document.annotations().unwrap()[0].source_path.clone();
    let before = document.to_bytes().unwrap();
    assert!(document.remove_annotation(1, &first).is_err());
    assert!(document.remove_annotation(0, "").is_err());
    assert!(document.remove_annotation(99, &first).is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    document.remove_annotation(0, &first).unwrap();
    assert!(document.entry(&annotation_path).unwrap().is_some());
    assert_eq!(document.annotations().unwrap()[0].id, second);
    assert!(!document.page_svg(0).unwrap().contains("first mark"));
    assert!(document.page_svg(0).unwrap().contains("second mark"));
    assert!(document.remove_annotation(0, &first).is_err());
    assert!(document.validate_references().unwrap().is_empty());
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.annotations().unwrap().len(), 1);
    assert_eq!(reopened.page_text(0).unwrap(), ["body"]);

    let mut java = OfdDocument::open(fixture("发票示例.ofd")).unwrap();
    let annotations = java.annotations().unwrap();
    java.remove_annotation(0, &annotations[0].id).unwrap();
    assert_eq!(java.annotations().unwrap().len(), 1);
    assert_eq!(java.annotations().unwrap()[0].id, annotations[1].id);
    assert!(java.validate_references().unwrap().is_empty());

    let mut signed = OfdDocument::open(fixture("SESV4SignDoc.ofd")).unwrap();
    let before = signed.to_bytes().unwrap();
    assert!(signed.remove_annotation(0, "1").is_err());
    assert!(signed
        .add_text_watermark(0, "mark", [0.0, 0.0, 10.0, 10.0], 4.0)
        .is_err());
    assert_eq!(signed.to_bytes().unwrap(), before);
}

#[test]
fn appends_uri_click_actions_to_page_objects_and_preserves_them() {
    let mut document = OfdDocument::new();
    document.add_text_page("link", 100.0, 60.0).unwrap();
    let object_id = document.page_objects(0).unwrap()[0].id.clone().unwrap();
    assert!(document
        .page_object_actions(0, &object_id)
        .unwrap()
        .is_empty());
    let before = document.to_bytes().unwrap();
    assert!(document
        .add_page_object_uri_action(0, &object_id, "")
        .is_err());
    assert!(document
        .add_page_object_uri_action(0, "missing", "https://example.org")
        .is_err());
    assert!(document
        .add_page_object_uri_action(99, &object_id, "https://example.org")
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    document
        .add_page_object_uri_action(0, &object_id, "https://example.org/?a=1&b=2")
        .unwrap();
    document
        .add_page_object_uri_action(0, &object_id, "mailto:test@example.org")
        .unwrap();
    let actions = document.page_object_actions(0, &object_id).unwrap();
    assert_eq!(actions.len(), 2);
    assert_eq!(actions[0].event, "CLICK");
    assert_eq!(actions[0].kind, "URI");
    assert_eq!(actions[0].attributes["URI"], "https://example.org/?a=1&b=2");
    assert_eq!(actions[1].attributes["URI"], "mailto:test@example.org");
    assert!(document.validate_references().unwrap().is_empty());
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(
        reopened.page_object_actions(0, &object_id).unwrap(),
        actions
    );
    assert_eq!(reopened.page_text(0).unwrap(), ["link"]);

    let mut java = OfdDocument::open(fixture("helloworld.ofd")).unwrap();
    let java_id = java.page_objects(0).unwrap()[0].id.clone().unwrap();
    java.add_page_object_uri_action(0, &java_id, "https://example.org/java")
        .unwrap();
    assert_eq!(
        java.page_object_actions(0, &java_id).unwrap()[0].kind,
        "URI"
    );

    let mut signed = OfdDocument::open(fixture("SESV4SignDoc.ofd")).unwrap();
    let before = signed.to_bytes().unwrap();
    assert!(signed
        .add_page_object_uri_action(0, "1", "https://example.org")
        .is_err());
    assert_eq!(signed.to_bytes().unwrap(), before);
}

#[test]
fn reads_region_actions_and_appends_to_unprefixed_page() {
    let mut document = OfdDocument::new();
    document.add_text_page("action", 100.0, 60.0).unwrap();
    let page_path = document.pages().unwrap()[0].path.clone();
    let object_id = document.page_objects(0).unwrap()[0].id.clone().unwrap();
    document
        .add_page_object_uri_action(0, &object_id, "https://example.org/first")
        .unwrap();
    let xml = String::from_utf8(document.entry(&page_path).unwrap().unwrap().to_vec()).unwrap();
    let with_region = xml.replacen("<ofd:URI", "<ofd:Region/><ofd:URI", 1);
    assert_ne!(with_region, xml);
    document
        .set_entry(&page_path, with_region.into_bytes())
        .unwrap();
    assert_eq!(
        document.page_object_actions(0, &object_id).unwrap()[0].attributes["URI"],
        "https://example.org/first"
    );
    let unprefixed = String::from_utf8(document.entry(&page_path).unwrap().unwrap().to_vec())
        .unwrap()
        .replace("ofd:", "");
    document
        .set_entry(&page_path, unprefixed.into_bytes())
        .unwrap();
    document
        .add_page_object_uri_action(0, &object_id, "https://example.org/second")
        .unwrap();
    let actions = document.page_object_actions(0, &object_id).unwrap();
    assert_eq!(actions.len(), 2);
    assert_eq!(actions[1].attributes["URI"], "https://example.org/second");
    let xml = String::from_utf8(document.entry(&page_path).unwrap().unwrap().to_vec()).unwrap();
    assert_eq!(xml.matches("<Actions>").count(), 1);

    let mut malformed = document.clone();
    malformed
        .set_entry(
            &page_path,
            xml.replacen(" Event=\"CLICK\"", "", 1).into_bytes(),
        )
        .unwrap();
    assert!(malformed.page_object_actions(0, &object_id).is_err());
    malformed
        .set_entry(
            &page_path,
            xml.replacen("</TextObject>", "<Actions/></TextObject>", 1)
                .into_bytes(),
        )
        .unwrap();
    assert!(malformed.page_object_actions(0, &object_id).is_err());
    assert!(malformed
        .add_page_object_uri_action(0, &object_id, "https://example.org")
        .is_err());
    malformed
        .set_entry(
            &page_path,
            xml.replacen("<URI URI=", "<URI URI=\"extra\"/><URI URI=", 1)
                .into_bytes(),
        )
        .unwrap();
    assert!(malformed.page_object_actions(0, &object_id).is_err());
}

#[test]
fn page_object_actions_ignore_extension_lookalikes() {
    let mut document = OfdDocument::new();
    document.add_text_page("linked", 80.0, 50.0).unwrap();
    let page_path = document.pages().unwrap()[0].path.clone();
    let object_id = document.page_objects(0).unwrap()[0].id.clone().unwrap();
    document
        .add_page_object_uri_action(0, &object_id, "https://example.org/first")
        .unwrap();
    let original = std::str::from_utf8(document.entry(&page_path).unwrap().unwrap()).unwrap();
    let decorated = original
        .replacen(
            "xmlns:ofd=",
            "xmlns:ext=\"urn:example:extension\" xmlns:ofd=",
            1,
        )
        .replacen(
            "<ofd:Actions>",
            "<ext:Actions><ext:Action Event=\"CLICK\"><ext:GotoA AttachID=\"999\"/></ext:Action></ext:Actions>\
             <Actions><Action Event=\"CLICK\"><URI URI=\"https://example.org/fake\"/></Action></Actions>\
             <ofd:Actions><ext:Action Event=\"CLICK\"><ext:URI URI=\"https://example.org/fake\"/></ext:Action>",
            1,
        )
        .replacen(
            "<ofd:URI URI=\"https://example.org/first\"/>",
            "<ext:URI URI=\"https://example.org/fake\"/>\
             <ext:Region><ext:Area Start=\"0 0\"/></ext:Region>\
             <ofd:URI URI=\"https://example.org/first\"/>",
            1,
        );
    assert_ne!(decorated, original);
    document
        .set_entry(&page_path, decorated.into_bytes())
        .unwrap();

    let actions = document.page_object_actions(0, &object_id).unwrap();
    assert_eq!(actions.len(), 1);
    assert_eq!(
        actions[0].attributes.get("URI").map(String::as_str),
        Some("https://example.org/first")
    );
    assert!(actions[0].region.is_none());
    assert!(document.validate_references().unwrap().is_empty());
    let pdf = lopdf::Document::load_mem(&document.to_pdf().unwrap()).unwrap();
    let page = pdf
        .get_dictionary(*pdf.get_pages().get(&1).unwrap())
        .unwrap();
    assert_eq!(page.get(b"Annots").unwrap().as_array().unwrap().len(), 1);

    document
        .add_page_object_uri_action(0, &object_id, "https://example.org/second")
        .unwrap();
    document
        .set_page_object_action_regions(0, &object_id, 0, &[[1.0, 2.0, 8.0, 4.0]])
        .unwrap();
    assert_eq!(
        document.page_object_actions(0, &object_id).unwrap()[0]
            .region
            .as_ref()
            .unwrap()
            .areas
            .len(),
        1
    );
    document
        .remove_page_object_action(0, &object_id, 0)
        .unwrap();
    let actions = document.page_object_actions(0, &object_id).unwrap();
    assert_eq!(actions.len(), 1);
    assert_eq!(
        actions[0].attributes.get("URI").map(String::as_str),
        Some("https://example.org/second")
    );
    let xml = std::str::from_utf8(document.entry(&page_path).unwrap().unwrap()).unwrap();
    assert!(xml.contains("<ext:Actions>"));
    assert!(xml.contains("<Actions>"));
    assert!(xml.contains("<ext:Action Event=\"CLICK\">"));
}

#[test]
fn writes_goto_action_destinations_with_java_compatible_coordinates() {
    let mut document = OfdDocument::new();
    document.add_text_page("click", 100.0, 60.0).unwrap();
    document.add_blank_page(100.0, 60.0).unwrap();
    let object_id = document.page_objects(0).unwrap()[0].id.clone().unwrap();
    let target = document.pages().unwrap()[1].id.clone();
    let destination = ofdrw::DestinationInfo {
        page_id: target.clone(),
        kind: "XYZ".into(),
        left: Some(12.5),
        top: Some(21.0),
        right: None,
        bottom: None,
        zoom: Some(1.5),
    };
    let before = document.to_bytes().unwrap();
    let mut invalid = destination.clone();
    invalid.page_id = "missing".into();
    assert!(document
        .add_page_object_goto_action(0, &object_id, invalid)
        .is_err());
    let mut invalid = destination.clone();
    invalid.kind = "Unknown".into();
    assert!(document
        .add_page_object_goto_action(0, &object_id, invalid)
        .is_err());
    let mut invalid = destination.clone();
    invalid.left = Some(f64::NAN);
    assert!(document
        .add_page_object_goto_action(0, &object_id, invalid)
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    document
        .add_page_object_goto_action(0, &object_id, destination.clone())
        .unwrap();
    let actions = document.page_object_actions(0, &object_id).unwrap();
    assert_eq!(actions[0].kind, "Goto");
    assert_eq!(actions[0].destination, Some(destination.clone()));
    let xml = String::from_utf8(
        document
            .entry(&document.pages().unwrap()[0].path)
            .unwrap()
            .unwrap()
            .to_vec(),
    )
    .unwrap();
    assert!(xml.contains("<ofd:Left>12.5</ofd:Left>"));
    assert!(xml.contains("<ofd:Top>21</ofd:Top>"));
    assert!(xml.contains("<ofd:Zoom>1.5</ofd:Zoom>"));
    assert!(document.validate_references().unwrap().is_empty());
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(
        reopened.page_object_actions(0, &object_id).unwrap(),
        actions
    );

    let mut signed = OfdDocument::open(fixture("SESV4SignDoc.ofd")).unwrap();
    assert!(signed
        .add_page_object_goto_action(0, "1", destination)
        .is_err());
}

#[test]
fn writes_attachment_actions_and_validates_targets() {
    let mut document = OfdDocument::new();
    document.add_blank_page(50.0, 40.0).unwrap();
    document.add_attachment("note & one.txt", b"hello").unwrap();
    let attachment_id = document.attachments().unwrap()[0].id.clone();
    let object_id = document
        .add_path_object(
            0,
            "M 0 0 L 10 0 L 10 10 C",
            [1.0, 1.0, 10.0, 10.0],
            PathStyle::default(),
        )
        .unwrap();
    document
        .add_page_object_attachment_action(0, &object_id, &attachment_id, Some(true))
        .unwrap();
    let annotation_id = document
        .add_attachment_link_annotation(0, &attachment_id, [15.0, 1.0, 10.0, 10.0], Some(false))
        .unwrap();
    let action = &document.page_object_actions(0, &object_id).unwrap()[0];
    assert_eq!(action.kind, "GotoA");
    assert_eq!(action.attributes["AttachID"], attachment_id);
    assert_eq!(action.attributes["NewWindow"], "true");
    let annotation = document
        .annotations()
        .unwrap()
        .into_iter()
        .find(|item| item.id == annotation_id)
        .unwrap();
    assert_eq!(annotation.actions[0].kind, "GotoA");
    assert_eq!(annotation.actions[0].attributes["NewWindow"], "false");
    assert!(document.validate_references().unwrap().is_empty());
    document.rename_attachment(0, "renamed & <linked>").unwrap();
    assert_eq!(document.attachments().unwrap()[0].id, attachment_id);
    assert!(document.validate_references().unwrap().is_empty());
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(
        reopened.page_object_actions(0, &object_id).unwrap()[0],
        *action
    );

    let before = document.to_bytes().unwrap();
    let mut removed = OfdDocument::from_bytes(&before).unwrap();
    removed.remove_attachment(0).unwrap();
    let missing = removed.validate_references().unwrap();
    let annotation_path = removed.annotations().unwrap()[0].source_path.clone();
    let page_path = removed.pages().unwrap()[0].path.clone();
    assert!(missing
        .iter()
        .any(|issue| { issue.code == "attachment_action_reference" && issue.path == page_path }));
    assert!(missing.iter().any(|issue| {
        issue.code == "attachment_action_reference" && issue.path == annotation_path
    }));
    assert!(document
        .add_page_object_attachment_action(0, &object_id, "missing", None)
        .is_err());
    assert!(document
        .add_attachment_link_annotation(0, "missing", [1.0, 1.0, 2.0, 2.0], None)
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);

    let page_path = document.pages().unwrap()[0].path.clone();
    let page_xml =
        String::from_utf8(document.entry(&page_path).unwrap().unwrap().to_vec()).unwrap();
    document
        .set_entry(
            &page_path,
            page_xml
                .replace(
                    &format!("AttachID=\"{attachment_id}\""),
                    "AttachID=\"missing\"",
                )
                .into_bytes(),
        )
        .unwrap();
    assert!(document
        .validate_references()
        .unwrap()
        .iter()
        .any(|issue| issue.code == "attachment_action_reference" && issue.path == page_path));
}

#[test]
fn writes_audio_video_resources_and_playback_actions() {
    let mut document = OfdDocument::new();
    document.add_blank_page(50.0, 40.0).unwrap();
    let audio_id = document
        .add_multimedia_resource(0, "Audio", "MP3", b"audio bytes")
        .unwrap();
    let video_id = document
        .add_multimedia_resource(0, "Video", "MP4", b"video bytes")
        .unwrap();
    let resources = document.page_multimedia_resources(0).unwrap();
    assert_eq!(
        document.document_multimedia_resources(0).unwrap(),
        resources
    );
    assert_eq!(
        document.document_multimedia_data(0, &audio_id).unwrap(),
        b"audio bytes"
    );
    assert!(document.document_multimedia_data(0, "missing").is_err());
    assert!(document.document_multimedia_resources(1).is_err());
    assert!(document.document_multimedia_data(1, &audio_id).is_err());
    assert_eq!(resources.len(), 2);
    assert_eq!(resources[0].id, audio_id);
    assert_eq!(resources[0].media_type.as_deref(), Some("Audio"));
    assert_eq!(resources[0].format.as_deref(), Some("MP3"));
    assert_eq!(resources[0].size, 11);
    assert_eq!(resources[1].id, video_id);
    assert_eq!(
        document.page_multimedia_data(0, &audio_id).unwrap(),
        b"audio bytes"
    );
    assert_eq!(
        document.page_multimedia_data(0, &video_id).unwrap(),
        b"video bytes"
    );
    assert!(document.page_multimedia_data(0, "missing").is_err());
    assert!(document.page_multimedia_resources(1).is_err());
    let object_id = document
        .add_path_object(
            0,
            "M 0 0 L 10 0 L 10 10 C",
            [1.0, 1.0, 10.0, 10.0],
            PathStyle::default(),
        )
        .unwrap();
    let options = ofdrw::SoundActionOptions {
        volume: Some(75),
        repeat: Some(true),
        synchronous: Some(false),
    };
    document
        .add_page_object_sound_action(0, &object_id, &audio_id, options)
        .unwrap();
    document
        .add_page_object_movie_action(0, &object_id, &video_id, Some("Pause"))
        .unwrap();
    document
        .add_sound_link_annotation(0, &audio_id, [15.0, 1.0, 10.0, 10.0], options)
        .unwrap();
    document
        .add_movie_link_annotation(0, &video_id, [28.0, 1.0, 10.0, 10.0], None)
        .unwrap();
    let actions = document.page_object_actions(0, &object_id).unwrap();
    assert_eq!(actions[0].kind, "Sound");
    assert_eq!(actions[0].attributes["Volume"], "75");
    assert_eq!(actions[1].kind, "Movie");
    assert_eq!(actions[1].attributes["Operator"], "Pause");
    assert_eq!(document.annotations().unwrap().len(), 2);
    assert!(document.validate_references().unwrap().is_empty());
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.page_multimedia_resources(0).unwrap(), resources);
    assert_eq!(
        reopened.page_multimedia_data(0, &audio_id).unwrap(),
        b"audio bytes"
    );
    let mut local = reopened.clone();
    let page_path = local.pages().unwrap()[0].path.clone();
    let page_dir = page_path.rsplit_once('/').unwrap().0;
    let page_xml = std::str::from_utf8(local.entry(&page_path).unwrap().unwrap()).unwrap();
    local
        .set_entry(
            &page_path,
            page_xml
                .replace(
                    "<ofd:Content>",
                    "<ofd:PageRes>PageRes.xml</ofd:PageRes><ofd:Content>",
                )
                .into_bytes(),
        )
        .unwrap();
    local
        .set_entry(
            &format!("{page_dir}/PageRes.xml"),
            format!("<ofd:Res xmlns:ofd=\"http://www.ofdspec.org/2016\" BaseLoc=\"Res\"><ofd:MultiMedias><ofd:MultiMedia ID=\"{audio_id}\" Type=\"Audio\" Format=\"WAV\"><ofd:MediaFile>local.wav</ofd:MediaFile></ofd:MultiMedia></ofd:MultiMedias></ofd:Res>").into_bytes(),
        )
        .unwrap();
    local
        .set_entry(
            &format!("{page_dir}/Res/local.wav"),
            b"local audio".to_vec(),
        )
        .unwrap();
    let local_resources = local.page_multimedia_resources(0).unwrap();
    assert_eq!(local_resources.len(), 2);
    assert_eq!(local_resources[0].id, audio_id);
    assert_eq!(local_resources[0].format.as_deref(), Some("WAV"));
    assert_eq!(
        local.page_multimedia_data(0, &audio_id).unwrap(),
        b"local audio"
    );
    assert_eq!(
        local.page_multimedia_data(0, &video_id).unwrap(),
        b"video bytes"
    );
    assert_eq!(local.document_multimedia_resources(0).unwrap(), resources);
    assert_eq!(
        local.document_multimedia_data(0, &audio_id).unwrap(),
        b"audio bytes"
    );
    let local_old_path = local_resources[0].path.clone();
    local
        .replace_page_multimedia_data(0, &audio_id, b"replaced local")
        .unwrap();
    assert_eq!(
        local.page_multimedia_data(0, &audio_id).unwrap(),
        b"replaced local"
    );
    assert_eq!(
        local.document_multimedia_data(0, &audio_id).unwrap(),
        b"audio bytes"
    );
    assert_eq!(
        local.entry(&local_old_path).unwrap().unwrap(),
        b"local audio"
    );
    assert!(local
        .replace_page_multimedia_data(0, "missing", b"bad")
        .is_err());
    assert!(local
        .replace_page_multimedia_data(1, &audio_id, b"bad")
        .is_err());
    let local_reopened = OfdDocument::from_bytes(&local.to_bytes().unwrap()).unwrap();
    assert_eq!(
        local_reopened.page_multimedia_data(0, &audio_id).unwrap(),
        b"replaced local"
    );
    assert_eq!(
        reopened.page_object_actions(0, &object_id).unwrap(),
        actions
    );
    let before = document.to_bytes().unwrap();
    let mut existing = OfdDocument::from_bytes(&before).unwrap();
    let second_audio = existing
        .add_multimedia_resource(0, "Audio", "WAV", b"wave bytes")
        .unwrap();
    existing
        .add_page_object_sound_action(
            0,
            &object_id,
            &second_audio,
            ofdrw::SoundActionOptions::default(),
        )
        .unwrap();
    assert!(existing.validate_references().unwrap().is_empty());
    assert_eq!(
        OfdDocument::from_bytes(&existing.to_bytes().unwrap())
            .unwrap()
            .page_object_actions(0, &object_id)
            .unwrap()
            .len(),
        3
    );
    assert!(document
        .add_page_object_sound_action(0, &object_id, &video_id, options)
        .is_err());
    assert!(document
        .add_page_object_sound_action(
            0,
            &object_id,
            &audio_id,
            ofdrw::SoundActionOptions {
                volume: Some(101),
                ..Default::default()
            },
        )
        .is_err());
    assert!(document
        .add_page_object_movie_action(0, &object_id, &audio_id, Some("Play"))
        .is_err());
    assert!(document
        .add_movie_link_annotation(0, &video_id, [1.0, 1.0, 2.0, 2.0], Some("Bad"))
        .is_err());
    assert!(document
        .add_multimedia_resource(0, "Audio", "../bad", b"bytes")
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);

    let page_path = document.pages().unwrap()[0].path.clone();
    let page_xml =
        String::from_utf8(document.entry(&page_path).unwrap().unwrap().to_vec()).unwrap();
    document
        .set_entry(
            &page_path,
            page_xml
                .replace(
                    &format!("ResourceID=\"{audio_id}\""),
                    "ResourceID=\"missing\"",
                )
                .into_bytes(),
        )
        .unwrap();
    assert!(document
        .validate_references()
        .unwrap()
        .iter()
        .any(|issue| issue.code == "media_action_reference" && issue.path == page_path));
}

#[test]
fn lists_unused_document_multimedia_without_pages() {
    let mut document = OfdDocument::new();
    let id = document
        .add_multimedia_resource(0, "Audio", "WAV", b"unused audio")
        .unwrap();
    assert!(document.pages().unwrap().is_empty());
    assert!(document.page_multimedia_resources(0).is_err());
    let resources = document.document_multimedia_resources(0).unwrap();
    assert_eq!(resources.len(), 1);
    assert_eq!(resources[0].id, id);
    assert_eq!(resources[0].media_type.as_deref(), Some("Audio"));
    assert_eq!(resources[0].size, 12);
    assert_eq!(
        document.document_multimedia_data(0, &id).unwrap(),
        b"unused audio"
    );
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(
        reopened.document_multimedia_resources(0).unwrap(),
        resources
    );
    assert_eq!(
        reopened.document_multimedia_data(0, &id).unwrap(),
        b"unused audio"
    );
}

#[test]
fn creates_standalone_image_multimedia_resource() {
    let mut document = OfdDocument::new();
    document.add_blank_page(10.0, 10.0).unwrap();
    let png = document.page_png(0, 25.4).unwrap();
    let id = document
        .add_multimedia_resource(0, "Image", "pNg", &png)
        .unwrap();
    let resources = document.document_multimedia_resources(0).unwrap();
    assert_eq!(resources.len(), 1);
    assert_eq!(resources[0].id, id);
    assert_eq!(resources[0].media_type.as_deref(), Some("Image"));
    assert_eq!(resources[0].format.as_deref(), Some("PNG"));
    assert!(resources[0].path.ends_with(".png"));
    assert_eq!(document.document_multimedia_data(0, &id).unwrap(), png);
    assert_eq!(document.page_multimedia_resources(0).unwrap(), resources);
    let before = document.to_bytes().unwrap();
    assert!(document
        .add_multimedia_resource(0, "Image", "PNG", b"bad image")
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    let mut reopened = OfdDocument::from_bytes(&before).unwrap();
    assert_eq!(
        reopened.document_multimedia_resources(0).unwrap(),
        resources
    );
    assert_eq!(reopened.page_multimedia_data(0, &id).unwrap(), png);
    assert!(reopened
        .replace_document_multimedia_data(0, &id, b"bad image")
        .is_err());
    assert_eq!(reopened.to_bytes().unwrap(), before);
    reopened
        .replace_document_multimedia_data(0, &id, &png)
        .unwrap();
    assert_eq!(reopened.document_multimedia_data(0, &id).unwrap(), png);
    let resource_path = "Doc_0/DocumentRes.xml";
    let resource_xml =
        std::str::from_utf8(reopened.entry(resource_path).unwrap().unwrap()).unwrap();
    reopened
        .set_entry(
            resource_path,
            resource_xml.replace(" Format=\"PNG\"", "").into_bytes(),
        )
        .unwrap();
    assert!(reopened
        .replace_document_multimedia_data(0, &id, b"bad image")
        .is_err());
    reopened
        .replace_document_multimedia_data(0, &id, &png)
        .unwrap();
    assert_eq!(reopened.document_multimedia_data(0, &id).unwrap(), png);
}

#[test]
fn replaces_document_multimedia_bytes_without_changing_resource_id() {
    let mut document = OfdDocument::new();
    document.add_blank_page(10.0, 10.0).unwrap();
    let audio_id = document
        .add_multimedia_resource(0, "Audio", "MP3", b"first audio")
        .unwrap();
    let video_id = document
        .add_multimedia_resource(0, "Video", "MP4", b"video bytes")
        .unwrap();
    let old_path = document.document_multimedia_resources(0).unwrap()[0]
        .path
        .clone();
    document
        .replace_document_multimedia_data(0, &audio_id, b"second audio")
        .unwrap();
    let resources = document.document_multimedia_resources(0).unwrap();
    assert_eq!(resources[0].id, audio_id);
    assert_ne!(resources[0].path, old_path);
    assert_eq!(document.entry(&old_path).unwrap().unwrap(), b"first audio");
    assert_eq!(
        document.document_multimedia_data(0, &audio_id).unwrap(),
        b"second audio"
    );
    assert_eq!(
        document.document_multimedia_data(0, &video_id).unwrap(),
        b"video bytes"
    );
    let mut reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    reopened
        .replace_document_multimedia_data(0, &audio_id, b"third audio")
        .unwrap();
    assert_eq!(
        reopened.document_multimedia_data(0, &audio_id).unwrap(),
        b"third audio"
    );
    assert_eq!(
        reopened.document_multimedia_data(0, &video_id).unwrap(),
        b"video bytes"
    );
    assert_eq!(
        reopened.page_multimedia_data(0, &audio_id).unwrap(),
        b"third audio"
    );
    reopened
        .replace_page_multimedia_data(0, &video_id, b"new video")
        .unwrap();
    assert_eq!(
        reopened.document_multimedia_data(0, &video_id).unwrap(),
        b"new video"
    );
    let before = reopened.to_bytes().unwrap();
    assert!(reopened
        .replace_document_multimedia_data(0, "missing", b"bad")
        .is_err());
    assert!(reopened
        .replace_document_multimedia_data(0, &audio_id, b"")
        .is_err());
    assert_eq!(reopened.to_bytes().unwrap(), before);
    let key = include_bytes!("fixtures/user-private-key.bin");
    reopened
        .add_digital_signature(key, "2020-04-22 16:22:44")
        .unwrap();
    let signed = reopened.to_bytes().unwrap();
    assert!(reopened
        .replace_document_multimedia_data(0, &audio_id, b"signed change")
        .is_err());
    assert!(reopened
        .replace_page_multimedia_data(0, &audio_id, b"signed page change")
        .is_err());
    assert!(reopened
        .remove_document_multimedia_resource(0, &video_id)
        .is_err());
    assert_eq!(reopened.to_bytes().unwrap(), signed);
}

#[test]
fn replacing_one_media_resource_preserves_shared_payloads() {
    let mut document = OfdDocument::new();
    document.add_blank_page(10.0, 10.0).unwrap();
    let audio_id = document
        .add_multimedia_resource(0, "Audio", "MP3", b"shared bytes")
        .unwrap();
    let video_id = document
        .add_multimedia_resource(0, "Video", "MP4", b"video bytes")
        .unwrap();
    let mut document = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    let resources = document.document_multimedia_resources(0).unwrap();
    let audio_name = resources[0].path.rsplit_once('/').unwrap().1;
    let video_name = resources[1].path.rsplit_once('/').unwrap().1;
    let resource_path = "Doc_0/DocumentRes.xml";
    let xml = std::str::from_utf8(document.entry(resource_path).unwrap().unwrap()).unwrap();
    document
        .set_entry(
            resource_path,
            xml.replace(video_name, audio_name).into_bytes(),
        )
        .unwrap();
    assert_eq!(
        document.document_multimedia_data(0, &video_id).unwrap(),
        b"shared bytes"
    );
    document
        .replace_document_multimedia_data(0, &audio_id, b"new audio")
        .unwrap();
    assert_eq!(
        document.document_multimedia_data(0, &audio_id).unwrap(),
        b"new audio"
    );
    assert_eq!(
        document.document_multimedia_data(0, &video_id).unwrap(),
        b"shared bytes"
    );
}

#[test]
fn removes_only_unreferenced_document_multimedia_resources() {
    let mut document = OfdDocument::new();
    document.add_blank_page(20.0, 20.0).unwrap();
    let audio_id = document
        .add_multimedia_resource(0, "Audio", "MP3", b"audio bytes")
        .unwrap();
    let video_id = document
        .add_multimedia_resource(0, "Video", "MP4", b"video bytes")
        .unwrap();
    let audio_path = document.document_multimedia_resources(0).unwrap()[0]
        .path
        .clone();
    let object_id = document
        .add_path_object(
            0,
            "M 0 0 L 5 0 L 5 5 C",
            [1.0, 1.0, 5.0, 5.0],
            PathStyle::default(),
        )
        .unwrap();
    document
        .add_page_object_sound_action(
            0,
            &object_id,
            &audio_id,
            ofdrw::SoundActionOptions::default(),
        )
        .unwrap();
    let before = document.to_bytes().unwrap();
    assert!(document
        .remove_document_multimedia_resource(0, &audio_id)
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    assert!(document
        .remove_document_multimedia_resource(0, "missing")
        .is_err());
    document
        .remove_page_object_action(0, &object_id, 0)
        .unwrap();
    document
        .remove_document_multimedia_resource(0, &audio_id)
        .unwrap();
    assert_eq!(
        document.entry(&audio_path).unwrap().unwrap(),
        b"audio bytes"
    );
    assert_eq!(document.document_multimedia_resources(0).unwrap().len(), 1);
    assert_eq!(
        document.document_multimedia_resources(0).unwrap()[0].id,
        video_id
    );
    assert!(document.document_multimedia_data(0, &audio_id).is_err());
    assert!(document.validate_references().unwrap().is_empty());
    let mut reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    let mut invalid = reopened.clone();
    let page_path = invalid.pages().unwrap()[0].path.clone();
    let page_xml = std::str::from_utf8(invalid.entry(&page_path).unwrap().unwrap()).unwrap();
    invalid
        .set_entry(
            &page_path,
            page_xml
                .replace(
                    "</ofd:Layer>",
                    "<ofd:ImageObject ID=\"999\" ResourceID=\"missing\" Boundary=\"0 0 1 1\"/></ofd:Layer>",
                )
                .into_bytes(),
        )
        .unwrap();
    let existing_issues = invalid.validate_references().unwrap();
    assert!(!existing_issues.is_empty());
    invalid
        .remove_document_multimedia_resource(0, &video_id)
        .unwrap();
    assert_eq!(invalid.validate_references().unwrap(), existing_issues);
    reopened
        .remove_document_multimedia_resource(0, &video_id)
        .unwrap();
    assert!(reopened
        .document_multimedia_resources(0)
        .unwrap()
        .is_empty());
    let new_id = reopened
        .add_multimedia_resource(0, "Audio", "WAV", b"new bytes")
        .unwrap();
    assert_eq!(
        reopened.document_multimedia_resources(0).unwrap()[0].id,
        new_id
    );
    assert!(reopened.validate_references().unwrap().is_empty());
}

#[test]
fn adds_page_local_multimedia_without_leaking_to_other_pages() {
    let mut document = OfdDocument::new();
    document.add_blank_page(20.0, 20.0).unwrap();
    document.add_blank_page(20.0, 20.0).unwrap();
    let id = document
        .add_page_multimedia_resource(0, "Audio", "WAV", b"page audio")
        .unwrap();
    assert!(document
        .document_multimedia_resources(0)
        .unwrap()
        .is_empty());
    let resources = document.page_multimedia_resources(0).unwrap();
    assert_eq!(resources.len(), 1);
    assert_eq!(resources[0].id, id);
    assert_eq!(resources[0].media_type.as_deref(), Some("Audio"));
    assert_eq!(
        document.page_multimedia_data(0, &id).unwrap(),
        b"page audio"
    );
    assert!(document.page_multimedia_resources(1).unwrap().is_empty());
    assert!(document.page_multimedia_data(1, &id).is_err());
    let before = document.to_bytes().unwrap();
    assert!(document
        .add_page_multimedia_resource(1, "Image", "PNG", b"bad")
        .is_err());
    assert!(document
        .add_page_multimedia_resource(2, "Audio", "WAV", b"bad")
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    let mut reopened = OfdDocument::from_bytes(&before).unwrap();
    assert_eq!(reopened.page_multimedia_resources(0).unwrap(), resources);
    let png = reopened.page_png(1, 25.4).unwrap();
    let image_id = reopened
        .add_page_multimedia_resource(1, "Image", "pNg", &png)
        .unwrap();
    assert_eq!(reopened.page_multimedia_data(1, &image_id).unwrap(), png);
    assert!(reopened.page_multimedia_data(0, &image_id).is_err());
    assert_eq!(
        reopened.page_multimedia_resources(1).unwrap()[0]
            .format
            .as_deref(),
        Some("PNG")
    );
    assert!(reopened.validate_references().unwrap().is_empty());
    let roundtrip = OfdDocument::from_bytes(&reopened.to_bytes().unwrap()).unwrap();
    assert_eq!(roundtrip.page_multimedia_data(1, &image_id).unwrap(), png);
}

#[test]
fn removes_only_unreferenced_unshared_page_multimedia() {
    let mut document = OfdDocument::new();
    document.add_blank_page(20.0, 20.0).unwrap();
    document.add_blank_page(20.0, 20.0).unwrap();
    let document_id = document
        .add_multimedia_resource(0, "Audio", "WAV", b"document audio")
        .unwrap();
    let page_id = document
        .add_page_multimedia_resource(0, "Audio", "WAV", b"page audio")
        .unwrap();
    let page_media_path = document.page_multimedia_resources(0).unwrap()[0]
        .path
        .clone();
    let object_id = document
        .add_path_object(
            0,
            "M 0 0 L 5 0 L 5 5 C",
            [1.0, 1.0, 5.0, 5.0],
            PathStyle::default(),
        )
        .unwrap();
    document
        .add_page_object_sound_action(
            0,
            &object_id,
            &page_id,
            ofdrw::SoundActionOptions::default(),
        )
        .unwrap();
    let before = document.to_bytes().unwrap();
    assert!(document
        .remove_page_multimedia_resource(0, &page_id)
        .is_err());
    assert!(document
        .remove_page_multimedia_resource(0, &document_id)
        .is_err());
    assert!(document
        .remove_page_multimedia_resource(1, &page_id)
        .is_err());
    assert!(document
        .remove_page_multimedia_resource(2, &page_id)
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    document
        .remove_page_object_action(0, &object_id, 0)
        .unwrap();
    document
        .remove_page_multimedia_resource(0, &page_id)
        .unwrap();
    assert_eq!(
        document.entry(&page_media_path).unwrap().unwrap(),
        b"page audio"
    );
    assert!(document.page_multimedia_data(0, &page_id).is_err());
    assert_eq!(
        document.document_multimedia_data(0, &document_id).unwrap(),
        b"document audio"
    );
    assert!(document.validate_references().unwrap().is_empty());
    let mut reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    let new_id = reopened
        .add_page_multimedia_resource(0, "Video", "MP4", b"page video")
        .unwrap();
    assert_eq!(
        reopened.page_multimedia_data(0, &new_id).unwrap(),
        b"page video"
    );
    assert_ne!(new_id, page_id);

    let page_paths = reopened.pages().unwrap();
    let first_page_path = &page_paths[0].path;
    let second_page_path = &page_paths[1].path;
    let first_page_dir = first_page_path.rsplit_once('/').unwrap().0;
    let relative = format!(
        "../{}/RustPageRes_{new_id}.xml",
        first_page_dir.rsplit('/').next().unwrap()
    );
    let second_xml = std::str::from_utf8(reopened.entry(second_page_path).unwrap().unwrap())
        .unwrap()
        .to_owned();
    assert!(second_xml.contains("</ofd:Content>"), "{second_xml}");
    let mut with_bad_reference = reopened.clone();
    with_bad_reference
        .set_entry(
            second_page_path,
            second_xml
                .replace(
                    "</ofd:Content>",
                    "<ofd:Layer ID=\"998\"><ofd:ImageObject ID=\"999\" ResourceID=\"missing\" Boundary=\"0 0 1 1\"/></ofd:Layer></ofd:Content>",
                )
                .into_bytes(),
        )
        .unwrap();
    assert!(
        std::str::from_utf8(with_bad_reference.entry(second_page_path).unwrap().unwrap())
            .unwrap()
            .contains("ResourceID=\"missing\"")
    );
    let existing_issues = with_bad_reference.validate_references().unwrap();
    assert!(!existing_issues.is_empty());
    with_bad_reference
        .remove_page_multimedia_resource(0, &new_id)
        .unwrap();
    assert_eq!(
        with_bad_reference.validate_references().unwrap(),
        existing_issues
    );
    reopened
        .set_entry(
            second_page_path,
            second_xml
                .replacen(
                    "<ofd:Content>",
                    &format!("<ofd:PageRes>{}</ofd:PageRes><ofd:Content>", relative),
                    1,
                )
                .into_bytes(),
        )
        .unwrap();
    let before = reopened.to_bytes().unwrap();
    assert!(reopened
        .remove_page_multimedia_resource(0, &new_id)
        .is_err());
    assert_eq!(reopened.to_bytes().unwrap(), before);

    reopened
        .set_entry(second_page_path, second_xml.into_bytes())
        .unwrap();
    let root = "Doc_0/Document.xml";
    let root_xml = std::str::from_utf8(reopened.entry(root).unwrap().unwrap()).unwrap();
    let shared_resource = format!(
        "Pages/{}/RustPageRes_{new_id}.xml",
        first_page_dir.rsplit('/').next().unwrap()
    );
    reopened
        .set_entry(
            root,
            root_xml
                .replace(
                    "</ofd:CommonData>",
                    &format!(
                        "<ofd:DocumentRes>{shared_resource}</ofd:DocumentRes></ofd:CommonData>"
                    ),
                )
                .into_bytes(),
        )
        .unwrap();
    let before = reopened.to_bytes().unwrap();
    assert!(reopened
        .remove_page_multimedia_resource(0, &new_id)
        .is_err());
    assert_eq!(reopened.to_bytes().unwrap(), before);
}

#[test]
fn replacing_shared_page_resource_isolated_to_selected_page() {
    let mut document = OfdDocument::new();
    document.add_blank_page(10.0, 10.0).unwrap();
    document.add_blank_page(10.0, 10.0).unwrap();
    let id = document
        .add_page_multimedia_resource(0, "Audio", "WAV", b"original")
        .unwrap();
    let pages = document.pages().unwrap();
    let first_dir = pages[0].path.rsplit_once('/').unwrap().0;
    let link = format!(
        "../{}/RustPageRes_{id}.xml",
        first_dir.rsplit('/').next().unwrap()
    );
    let second_page = &pages[1].path;
    let second_xml = std::str::from_utf8(document.entry(second_page).unwrap().unwrap()).unwrap();
    document
        .set_entry(
            second_page,
            second_xml
                .replace(
                    "<ofd:Content>",
                    &format!("<ofd:PageRes>{link}</ofd:PageRes><ofd:Content>"),
                )
                .into_bytes(),
        )
        .unwrap();
    assert_eq!(document.page_multimedia_data(1, &id).unwrap(), b"original");
    let old_resource_path = format!("{first_dir}/RustPageRes_{id}.xml");
    let old_resource_xml = document
        .entry(&old_resource_path)
        .unwrap()
        .unwrap()
        .to_vec();
    let old_payload_path = document.page_multimedia_resources(0).unwrap()[0]
        .path
        .clone();
    document
        .replace_page_multimedia_data(0, &id, b"first only")
        .unwrap();
    assert_eq!(
        document.page_multimedia_data(0, &id).unwrap(),
        b"first only"
    );
    assert_eq!(document.page_multimedia_data(1, &id).unwrap(), b"original");
    assert_eq!(
        document.entry(&old_resource_path).unwrap().unwrap(),
        old_resource_xml
    );
    assert_eq!(
        document.entry(&old_payload_path).unwrap().unwrap(),
        b"original"
    );
    assert!(document.validate_references().unwrap().is_empty());
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(
        reopened.page_multimedia_data(0, &id).unwrap(),
        b"first only"
    );
    assert_eq!(reopened.page_multimedia_data(1, &id).unwrap(), b"original");

    let mut document_shared = OfdDocument::from_bytes(&reopened.to_bytes().unwrap()).unwrap();
    let root = "Doc_0/Document.xml";
    let root_xml = std::str::from_utf8(document_shared.entry(root).unwrap().unwrap()).unwrap();
    document_shared
        .set_entry(
            root,
            root_xml
                .replace(
                    "</ofd:CommonData>",
                    &format!(
                        "<ofd:DocumentRes>Pages/{}/RustPageRes_{id}.xml</ofd:DocumentRes></ofd:CommonData>",
                        first_dir.rsplit('/').next().unwrap()
                    ),
                )
                .into_bytes(),
        )
        .unwrap();
    assert_eq!(
        document_shared.document_multimedia_data(0, &id).unwrap(),
        b"original"
    );
    document_shared
        .replace_page_multimedia_data(1, &id, b"second only")
        .unwrap();
    assert_eq!(
        document_shared.page_multimedia_data(0, &id).unwrap(),
        b"first only"
    );
    assert_eq!(
        document_shared.page_multimedia_data(1, &id).unwrap(),
        b"second only"
    );
    assert_eq!(
        document_shared.document_multimedia_data(0, &id).unwrap(),
        b"original"
    );
}

