#[test]
fn page_multimedia_creation_rejects_invalid_structure_and_path_collision() {
    let mut original = OfdDocument::new();
    original.add_blank_page(10.0, 10.0).unwrap();
    let page_path = original.pages().unwrap()[0].path.clone();
    let mut missing_content = original.clone();
    let page_xml =
        std::str::from_utf8(missing_content.entry(&page_path).unwrap().unwrap()).unwrap();
    let start = page_xml.find("<ofd:Content>").unwrap();
    let end = page_xml.find("</ofd:Content>").unwrap() + "</ofd:Content>".len();
    let mut changed = page_xml.to_owned();
    changed.replace_range(start..end, "");
    missing_content
        .set_entry(&page_path, changed.into_bytes())
        .unwrap();
    let before = missing_content.to_bytes().unwrap();
    assert!(missing_content
        .add_page_multimedia_resource(0, "Audio", "WAV", b"audio")
        .is_err());
    assert_eq!(missing_content.to_bytes().unwrap(), before);

    let doc_path = "Doc_0/Document.xml";
    for replacement in ["bad", "", &usize::MAX.to_string()] {
        let mut invalid_max = original.clone();
        let doc_xml = std::str::from_utf8(invalid_max.entry(doc_path).unwrap().unwrap()).unwrap();
        let max_start = doc_xml.find("<ofd:MaxUnitID>").unwrap() + "<ofd:MaxUnitID>".len();
        let max_end = doc_xml.find("</ofd:MaxUnitID>").unwrap();
        let mut changed = doc_xml.to_owned();
        changed.replace_range(max_start..max_end, replacement);
        invalid_max
            .set_entry(doc_path, changed.into_bytes())
            .unwrap();
        let before = invalid_max.to_bytes().unwrap();
        assert!(invalid_max
            .add_page_multimedia_resource(0, "Audio", "WAV", b"audio")
            .is_err());
        assert_eq!(invalid_max.to_bytes().unwrap(), before);
    }
    let mut missing_max = original.clone();
    let doc_xml = std::str::from_utf8(missing_max.entry(doc_path).unwrap().unwrap()).unwrap();
    let max_start = doc_xml.find("<ofd:MaxUnitID>").unwrap();
    let max_end = doc_xml.find("</ofd:MaxUnitID>").unwrap() + "</ofd:MaxUnitID>".len();
    let mut changed = doc_xml.to_owned();
    changed.replace_range(max_start..max_end, "");
    missing_max
        .set_entry(doc_path, changed.into_bytes())
        .unwrap();
    let before = missing_max.to_bytes().unwrap();
    assert!(missing_max
        .add_page_multimedia_resource(0, "Audio", "WAV", b"audio")
        .is_err());
    assert_eq!(missing_max.to_bytes().unwrap(), before);

    let mut probe = original.clone();
    let id = probe
        .add_page_multimedia_resource(0, "Audio", "WAV", b"audio")
        .unwrap();
    let page_dir = page_path.rsplit_once('/').unwrap().0;
    let collision_path = format!("{page_dir}/RustPageRes_{id}.xml");
    original
        .set_entry(
            &collision_path,
            b"<ofd:Res xmlns:ofd=\"http://www.ofdspec.org/2016\"/>".to_vec(),
        )
        .unwrap();
    let before = original.to_bytes().unwrap();
    assert!(original
        .add_page_multimedia_resource(0, "Audio", "WAV", b"audio")
        .is_err());
    assert_eq!(original.to_bytes().unwrap(), before);
}

#[test]
fn exports_direct_page_object_actions_as_pdf_links() {
    let mut document = OfdDocument::new();
    document.add_blank_page(30.0, 20.0).unwrap();
    document.add_blank_page(40.0, 25.0).unwrap();
    let commands = "M 0 0 L 10 0 L 10 5 L 0 5 C";
    let first = document
        .add_path_object(0, commands, [2.0, 3.0, 10.0, 5.0], PathStyle::default())
        .unwrap();
    let second = document
        .add_path_object(0, commands, [13.0, 3.0, 10.0, 5.0], PathStyle::default())
        .unwrap();
    let hidden = document
        .add_path_object(0, commands, [2.0, 10.0, 10.0, 5.0], PathStyle::default())
        .unwrap();
    let named = document
        .add_path_object(0, commands, [13.0, 10.0, 10.0, 5.0], PathStyle::default())
        .unwrap();
    let target_id = document.pages().unwrap()[1].id.clone();
    document
        .add_bookmark(
            0,
            "next",
            DestinationInfo {
                page_id: target_id.clone(),
                kind: "Fit".into(),
                left: None,
                top: None,
                right: None,
                bottom: None,
                zoom: None,
            },
        )
        .unwrap();
    document
        .add_page_object_uri_action(0, &first, "https://example.com/object")
        .unwrap();
    document
        .add_page_object_goto_action(
            0,
            &second,
            DestinationInfo {
                page_id: target_id,
                kind: "Fit".into(),
                left: None,
                top: None,
                right: None,
                bottom: None,
                zoom: None,
            },
        )
        .unwrap();
    document
        .add_page_object_uri_action(0, &hidden, "https://example.com/hidden")
        .unwrap();
    document.set_page_object_visible(0, &hidden, false).unwrap();
    document
        .add_page_object_bookmark_action(0, &named, "next")
        .unwrap();
    let pdf = lopdf::Document::load_mem(&document.to_pdf().unwrap()).unwrap();
    let pages = pdf.get_pages();
    let page = pdf.get_dictionary(*pages.get(&1).unwrap()).unwrap();
    let links = page.get(b"Annots").unwrap().as_array().unwrap();
    assert_eq!(links.len(), 3);
    let uri = pdf
        .get_dictionary(links[0].as_reference().unwrap())
        .unwrap();
    let uri_action = uri.get(b"A").unwrap().as_dict().unwrap();
    assert_eq!(
        uri_action.get(b"URI").unwrap().as_str().unwrap(),
        b"https://example.com/object"
    );
    let rect = uri.get(b"Rect").unwrap().as_array().unwrap();
    for (actual, expected) in rect.iter().zip([2.0, 12.0, 12.0, 17.0]) {
        assert!((actual.as_float().unwrap() - (expected * 72.0 / 25.4) as f32).abs() < 0.01);
    }
    let goto = pdf
        .get_dictionary(links[1].as_reference().unwrap())
        .unwrap();
    let destination = goto
        .get(b"A")
        .unwrap()
        .as_dict()
        .unwrap()
        .get(b"D")
        .unwrap()
        .as_array()
        .unwrap();
    assert_eq!(
        destination[0].as_reference().unwrap(),
        *pages.get(&2).unwrap()
    );
    assert_eq!(destination[1].as_name().unwrap(), b"Fit");
    let named = pdf
        .get_dictionary(links[2].as_reference().unwrap())
        .unwrap();
    let named_destination = named
        .get(b"A")
        .unwrap()
        .as_dict()
        .unwrap()
        .get(b"D")
        .unwrap()
        .as_array()
        .unwrap();
    assert_eq!(
        named_destination[0].as_reference().unwrap(),
        *pages.get(&2).unwrap()
    );
    assert!(document.validate_references().unwrap().is_empty());
}

#[test]
fn exports_page_object_attachment_actions_as_pdf_file_attachments() {
    let mut document = OfdDocument::new();
    document.add_blank_page(30.0, 20.0).unwrap();
    document
        .add_attachment("linked.txt", b"linked data")
        .unwrap();
    let attachment = document.attachments().unwrap()[0].id.clone();
    let object = document
        .add_path_object(
            0,
            "M 0 0 L 10 0 L 10 5 C",
            [2.0, 3.0, 10.0, 5.0],
            PathStyle::default(),
        )
        .unwrap();
    document
        .add_page_object_attachment_action(0, &object, &attachment, None)
        .unwrap();
    let pdf = document.to_pdf().unwrap();
    let parsed = lopdf::Document::load_mem(&pdf).unwrap();
    let page = parsed
        .get_dictionary(*parsed.get_pages().values().next().unwrap())
        .unwrap();
    let annots = page.get(b"Annots").unwrap().as_array().unwrap();
    assert_eq!(annots.len(), 1);
    let annot = parsed
        .get_dictionary(annots[0].as_reference().unwrap())
        .unwrap();
    assert_eq!(
        annot.get(b"Subtype").unwrap().as_name().unwrap(),
        b"FileAttachment"
    );
    let spec = parsed
        .get_dictionary(annot.get(b"FS").unwrap().as_reference().unwrap())
        .unwrap();
    let stream = parsed
        .dereference(
            spec.get(b"EF")
                .unwrap()
                .as_dict()
                .unwrap()
                .get(b"F")
                .unwrap(),
        )
        .unwrap()
        .1;
    assert_eq!(stream.as_stream().unwrap().content, b"linked data");
    let imported = OfdDocument::from_pdf_bytes(&pdf).unwrap();
    assert_eq!(imported.attachment_data(0).unwrap(), b"linked data");
    assert_eq!(imported.annotations().unwrap()[0].actions[0].kind, "GotoA");
    assert!(imported.validate_references().unwrap().is_empty());
}

#[test]
fn action_regions_roundtrip_and_export_precise_pdf_links() {
    let mut document = OfdDocument::new();
    document.add_blank_page(30.0, 20.0).unwrap();
    let object_id = document
        .add_path_object(
            0,
            "M 0 0 L 20 0 L 20 10 L 0 10 C",
            [2.0, 3.0, 20.0, 10.0],
            PathStyle::default(),
        )
        .unwrap();
    document
        .add_page_object_uri_action(0, &object_id, "https://example.org/region")
        .unwrap();
    let before = document.to_bytes().unwrap();
    assert!(document
        .set_page_object_action_regions(0, &object_id, 0, &[[1.0, 2.0, 0.0, 3.0]])
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    let rectangles = [[3.0, 4.0, 4.0, 2.0], [12.0, 7.0, 3.0, 2.0]];
    document
        .set_page_object_action_regions(0, &object_id, 0, &rectangles)
        .unwrap();
    let action = document
        .page_object_actions(0, &object_id)
        .unwrap()
        .remove(0);
    let region = action.region.unwrap();
    assert_eq!(region.areas.len(), 2);
    assert_eq!(region.areas[0].start, [3.0, 4.0]);
    assert_eq!(region.areas[0].commands[0].kind, "Line");
    assert_eq!(region.areas[0].commands[3].kind, "Close");
    let page_path = document.pages().unwrap()[0].path.clone();
    let xml = std::str::from_utf8(document.entry(&page_path).unwrap().unwrap()).unwrap();
    assert!(xml.contains("<ofd:Region><ofd:Area Start=\"3 4\">"));
    assert!(xml.find("<ofd:Region>").unwrap() < xml.find("<ofd:URI ").unwrap());
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(
        reopened.page_object_actions(0, &object_id).unwrap()[0].region,
        Some(region)
    );
    let pdf = lopdf::Document::load_mem(&reopened.to_pdf().unwrap()).unwrap();
    let page = pdf
        .get_dictionary(*pdf.get_pages().get(&1).unwrap())
        .unwrap();
    let links = page.get(b"Annots").unwrap().as_array().unwrap();
    assert_eq!(links.len(), 1);
    let annotation = pdf
        .get_dictionary(links[0].as_reference().unwrap())
        .unwrap();
    let actual = annotation.get(b"Rect").unwrap().as_array().unwrap();
    for (actual, expected) in actual.iter().zip([3.0, 11.0, 15.0, 16.0]) {
        assert!((actual.as_float().unwrap() - (expected * 72.0 / 25.4) as f32).abs() < 0.01);
    }
    let quads = annotation.get(b"QuadPoints").unwrap().as_array().unwrap();
    assert_eq!(quads.len(), 16);
    for (actual, expected) in quads.iter().zip([
        3.0, 16.0, 7.0, 16.0, 7.0, 14.0, 3.0, 14.0, 12.0, 13.0, 15.0, 13.0, 15.0, 11.0, 12.0, 11.0,
    ]) {
        assert!((actual.as_float().unwrap() - (expected * 72.0 / 25.4) as f32).abs() < 0.01);
    }
    let malformed = xml.replace(
        "<ofd:Line Point1=\"7 4\"/>",
        "<ofd:QuadraticBezier Point1=\"6 4\" Point2=\"7 4\"/>",
    );
    document
        .set_entry(&page_path, malformed.into_bytes())
        .unwrap();
    assert!(document
        .to_pdf()
        .unwrap_err()
        .to_string()
        .contains("nonrectangular Action Region"));
    document
        .set_page_object_action_regions(0, &object_id, 0, &[])
        .unwrap();
    assert!(document.page_object_actions(0, &object_id).unwrap()[0]
        .region
        .is_none());
    let pdf = lopdf::Document::load_mem(&document.to_pdf().unwrap()).unwrap();
    let page = pdf
        .get_dictionary(*pdf.get_pages().get(&1).unwrap())
        .unwrap();
    assert_eq!(page.get(b"Annots").unwrap().as_array().unwrap().len(), 1);

    let mut signed = OfdDocument::open(fixture("SESV4SignDoc.ofd")).unwrap();
    let before = signed.to_bytes().unwrap();
    assert!(signed
        .set_page_object_action_regions(0, "1", 0, &rectangles)
        .is_err());
    assert_eq!(signed.to_bytes().unwrap(), before);
}

#[test]
fn annotation_action_region_controls_pdf_link_rectangle() {
    let mut document = OfdDocument::new();
    document.add_blank_page(30.0, 20.0).unwrap();
    document
        .add_uri_link_annotation(0, "https://example.org", [2.0, 3.0, 10.0, 5.0])
        .unwrap();
    let path = document.annotations().unwrap()[0].source_path.clone();
    let source = std::str::from_utf8(document.entry(&path).unwrap().unwrap()).unwrap();
    let region = "<ofd:Region><ofd:Area Start=\"3 4\"><ofd:Line Point1=\"5 4\"/><ofd:Line Point1=\"5 6\"/><ofd:Line Point1=\"3 6\"/><ofd:Close/></ofd:Area></ofd:Region>";
    let updated = source.replace(
        "<ofd:Action Event=\"CLICK\">",
        &format!("<ofd:Action Event=\"CLICK\">{region}"),
    );
    assert_ne!(source, updated);
    document.set_entry(&path, updated.into_bytes()).unwrap();
    assert_eq!(
        document.annotations().unwrap()[0].actions[0]
            .region
            .as_ref()
            .unwrap()
            .areas
            .len(),
        1
    );
    let pdf = lopdf::Document::load_mem(&document.to_pdf().unwrap()).unwrap();
    let page = pdf
        .get_dictionary(*pdf.get_pages().get(&1).unwrap())
        .unwrap();
    let link = pdf
        .get_dictionary(
            page.get(b"Annots").unwrap().as_array().unwrap()[0]
                .as_reference()
                .unwrap(),
        )
        .unwrap();
    let actual = link.get(b"Rect").unwrap().as_array().unwrap();
    for (actual, expected) in actual.iter().zip([3.0, 14.0, 5.0, 16.0]) {
        assert!((actual.as_float().unwrap() - (expected * 72.0 / 25.4) as f32).abs() < 0.01);
    }
}

#[test]
fn template_graphic_actions_export_on_each_using_page() {
    let mut document = OfdDocument::new();
    document.add_blank_page(30.0, 20.0).unwrap();
    document.add_blank_page(30.0, 20.0).unwrap();
    let template_object = document
        .add_path_object(
            0,
            "M 0 0 L 10 0 L 10 5 L 0 5 C",
            [2.0, 3.0, 10.0, 5.0],
            PathStyle::default(),
        )
        .unwrap();
    document
        .add_page_object_uri_action(0, &template_object, "https://example.org/template")
        .unwrap();
    document
        .set_page_object_action_regions(0, &template_object, 0, &[[3.0, 4.0, 2.0, 2.0]])
        .unwrap();
    let hidden = document
        .add_path_object(
            0,
            "M 0 0 L 5 0 L 5 5 C",
            [15.0, 3.0, 5.0, 5.0],
            PathStyle::default(),
        )
        .unwrap();
    document
        .add_page_object_uri_action(0, &hidden, "https://example.org/hidden")
        .unwrap();
    document.set_page_object_visible(0, &hidden, false).unwrap();
    let template_id = document
        .promote_page_to_template(0, &[1], "Background")
        .unwrap();
    let direct = document
        .add_path_object(
            1,
            "M 0 0 L 4 0 L 4 3 C",
            [20.0, 10.0, 4.0, 3.0],
            PathStyle::default(),
        )
        .unwrap();
    document
        .add_page_object_uri_action(1, &direct, "https://example.org/direct")
        .unwrap();
    assert_eq!(
        document.page_sources(1).unwrap()[0].template_id.as_deref(),
        Some(template_id.as_str())
    );
    assert!(document.page_object_actions(0, &template_object).is_err());
    let template_path = document.page_sources(1).unwrap()[0].path.clone();
    let actions = document
        .page_source_object_actions(1, &template_path, &template_object)
        .unwrap();
    assert_eq!(actions[0].attributes["URI"], "https://example.org/template");
    assert_eq!(
        actions[0].region.as_ref().unwrap().areas[0].start,
        [3.0, 4.0]
    );
    assert!(document
        .page_source_object_actions(1, "OFD.xml", &template_object)
        .is_err());
    assert!(document
        .page_source_object_actions(99, &template_path, &template_object)
        .is_err());
    let direct_path = document.pages().unwrap()[1].path.clone();
    assert_eq!(
        document
            .page_source_object_actions(1, &direct_path, &direct)
            .unwrap()[0]
            .attributes["URI"],
        "https://example.org/direct"
    );
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    let pdf = lopdf::Document::load_mem(&reopened.to_pdf().unwrap()).unwrap();
    for (page_number, expected_links) in [(1, 1), (2, 2)] {
        let page = pdf
            .get_dictionary(*pdf.get_pages().get(&page_number).unwrap())
            .unwrap();
        let links = page.get(b"Annots").unwrap().as_array().unwrap();
        assert_eq!(links.len(), expected_links);
        let first = pdf
            .get_dictionary(links[0].as_reference().unwrap())
            .unwrap();
        let uri = first
            .get(b"A")
            .unwrap()
            .as_dict()
            .unwrap()
            .get(b"URI")
            .unwrap()
            .as_str()
            .unwrap();
        assert_eq!(uri, b"https://example.org/template");
        let rect = first.get(b"Rect").unwrap().as_array().unwrap();
        for (actual, expected) in rect.iter().zip([3.0, 14.0, 5.0, 16.0]) {
            assert!((actual.as_float().unwrap() - (expected * 72.0 / 25.4) as f32).abs() < 0.01);
        }
    }
    assert!(document.validate_references().unwrap().is_empty());
}

#[test]
fn adds_bookmark_action_and_removes_only_selected_action() {
    let mut document = OfdDocument::new();
    document.add_text_page("click", 100.0, 60.0).unwrap();
    let page = document.pages().unwrap()[0].clone();
    let object_id = document.page_objects(0).unwrap()[0].id.clone().unwrap();
    document
        .add_bookmark(
            0,
            "Section & One",
            ofdrw::DestinationInfo {
                page_id: page.id.clone(),
                kind: "XYZ".into(),
                left: Some(10.0),
                top: Some(20.0),
                right: None,
                bottom: None,
                zoom: None,
            },
        )
        .unwrap();
    let before = document.to_bytes().unwrap();
    assert!(document
        .add_page_object_bookmark_action(0, &object_id, "missing")
        .is_err());
    assert!(document
        .add_page_object_bookmark_action(0, &object_id, "")
        .is_err());
    assert!(document
        .remove_page_object_action(0, &object_id, 0)
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    document
        .add_page_object_uri_action(0, &object_id, "https://example.org/one")
        .unwrap();
    document
        .add_page_object_bookmark_action(0, &object_id, "Section & One")
        .unwrap();
    document
        .add_page_object_uri_action(0, &object_id, "https://example.org/two")
        .unwrap();
    let actions = document.page_object_actions(0, &object_id).unwrap();
    assert_eq!(actions.len(), 3);
    assert_eq!(actions[1].bookmark.as_deref(), Some("Section & One"));
    assert_eq!(actions[1].kind, "Goto");
    document
        .remove_page_object_action(0, &object_id, 1)
        .unwrap();
    let remaining = document.page_object_actions(0, &object_id).unwrap();
    assert_eq!(remaining, [actions[0].clone(), actions[2].clone()]);
    assert!(document
        .remove_page_object_action(0, &object_id, 2)
        .is_err());
    document
        .remove_page_object_action(0, &object_id, 0)
        .unwrap();
    assert_eq!(
        document.page_object_actions(0, &object_id).unwrap(),
        [actions[2].clone()]
    );
    document
        .remove_page_object_action(0, &object_id, 0)
        .unwrap();
    assert!(document
        .page_object_actions(0, &object_id)
        .unwrap()
        .is_empty());
    let page_xml = std::str::from_utf8(document.entry(&page.path).unwrap().unwrap()).unwrap();
    assert!(!page_xml.contains("<ofd:Actions>"));
    assert!(document.validate_references().unwrap().is_empty());
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert!(reopened
        .page_object_actions(0, &object_id)
        .unwrap()
        .is_empty());
    assert_eq!(reopened.page_text(0).unwrap(), ["click"]);

    let mut signed = OfdDocument::open(fixture("SESV4SignDoc.ofd")).unwrap();
    let before = signed.to_bytes().unwrap();
    assert!(signed.remove_page_object_action(0, "1", 0).is_err());
    assert_eq!(signed.to_bytes().unwrap(), before);
}

