#[test]
fn writes_gif_images_from_java_fixture_and_rejects_truncated_data() {
    let source = OfdDocument::open(
        PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../../ofdrw-converter/src/test/resources/不规范资源路径.ofd"),
    )
    .unwrap();
    let gif = source.page_image_data(0, 0).unwrap();
    assert!(gif.starts_with(b"GIF"));
    let mut document = OfdDocument::new();
    document.add_image_page(gif, "gif", 30.0, 20.0).unwrap();
    assert_eq!(document.page_image_data(0, 0).unwrap(), gif);
    assert!(document
        .page_svg(0)
        .unwrap()
        .contains("data:image/png;base64,"));
    document
        .add_image_object(0, gif, "GIF", [2.0, 2.0, 10.0, 8.0])
        .unwrap();
    assert_eq!(document.page_image_data(0, 1).unwrap(), gif);
    assert!(document.validate_references().unwrap().is_empty());
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.page_image_data(0, 0).unwrap(), gif);
    let before = document.to_bytes().unwrap();
    assert!(document
        .add_image_object(0, b"GIF89a", "gif", [2.0, 2.0, 10.0, 8.0])
        .is_err());
    assert!(document
        .add_image_page(b"\x89PNG\r\n\x1a\n", "gif", 30.0, 20.0)
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
}

#[test]
fn animated_gif_preview_uses_first_frame_without_changing_original_bytes() {
    let mut gif = Vec::new();
    {
        let mut encoder = image::codecs::gif::GifEncoder::new(&mut gif);
        encoder
            .encode_frame(image::Frame::new(image::RgbaImage::from_pixel(
                2,
                2,
                image::Rgba([255, 0, 0, 255]),
            )))
            .unwrap();
        encoder
            .encode_frame(image::Frame::new(image::RgbaImage::from_pixel(
                2,
                2,
                image::Rgba([0, 0, 255, 255]),
            )))
            .unwrap();
    }
    let mut document = OfdDocument::new();
    document.add_image_page(&gif, "gif", 20.0, 20.0).unwrap();
    assert_eq!(document.page_image_data(0, 0).unwrap(), gif);
    let svg = document.page_svg(0).unwrap();
    assert!(!svg.contains("data:image/gif;base64,"));
    let encoded = svg
        .split_once("data:image/png;base64,")
        .unwrap()
        .1
        .split_once('"')
        .unwrap()
        .0;
    let png = base64::Engine::decode(&base64::engine::general_purpose::STANDARD, encoded).unwrap();
    let pixel = image::load_from_memory(&png)
        .unwrap()
        .to_rgba8()
        .get_pixel(0, 0)
        .0;
    assert_eq!(pixel, [255, 0, 0, 255]);
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.page_image_data(0, 0).unwrap(), gif);
}

#[test]
fn image_writers_decode_png_and_jpeg_before_mutating_package() {
    let invoice = OfdDocument::open(fixture("发票示例.ofd")).unwrap();
    let png = invoice.page_image_data(0, 0).unwrap();
    let mut jpeg = Cursor::new(Vec::new());
    image::DynamicImage::ImageRgb8(image::RgbImage::from_pixel(2, 2, image::Rgb([255, 0, 0])))
        .write_to(&mut jpeg, image::ImageFormat::Jpeg)
        .unwrap();
    let jpeg = jpeg.into_inner();
    let mut document = OfdDocument::new();
    let before = document.to_bytes().unwrap();
    for (format, data) in [
        ("png", b"\x89PNG\r\n\x1a\n".as_slice()),
        ("jpeg", b"\xff\xd8\xff".as_slice()),
    ] {
        assert!(document.add_image_page(data, format, 30.0, 20.0).is_err());
        assert_eq!(document.to_bytes().unwrap(), before);
    }
    document.add_image_page(png, "png", 30.0, 20.0).unwrap();
    document
        .add_image_object(0, &jpeg, "jpeg", [2.0, 2.0, 10.0, 8.0])
        .unwrap();
    assert_eq!(document.page_image_data(0, 0).unwrap(), png);
    assert_eq!(document.page_image_data(0, 1).unwrap(), jpeg);
    let before = document.to_bytes().unwrap();
    assert!(document
        .add_multimedia_resource(0, "Image", "jpeg", b"\xff\xd8\xff")
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    assert!(document.validate_references().unwrap().is_empty());
}

#[test]
fn image_mask_makes_nonwhite_pixels_transparent_and_reports_missing_mask() {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/image-mask.ofd");
    let mut document = OfdDocument::open(path).unwrap();
    assert_eq!(
        document.page_images(0).unwrap()[0].image_mask.as_deref(),
        Some("4")
    );
    assert!(document.validate_references().unwrap().is_empty());
    let svg = document.page_svg(0).unwrap();
    let encoded = svg
        .split_once("data:image/png;base64,")
        .unwrap()
        .1
        .split('"')
        .next()
        .unwrap();
    let embedded =
        base64::Engine::decode(&base64::engine::general_purpose::STANDARD, encoded).unwrap();
    let pixels = image::load_from_memory(&embedded).unwrap().to_rgba8();
    assert_eq!(pixels.get_pixel(0, 0).0[3], 255);
    assert_eq!(pixels.get_pixel(1, 0).0[3], 0);
    let masked =
        resvg::tiny_skia::Pixmap::decode_png(&document.page_png(0, 25.4).unwrap()).unwrap();
    assert_eq!((masked.width(), masked.height()), (2, 1));
    assert!(masked.pixel(0, 0).unwrap().red() > 240);
    assert!(masked.pixel(0, 0).unwrap().blue() < 20);
    assert!(masked.pixel(1, 0).unwrap().red() > 240);
    assert!(masked.pixel(1, 0).unwrap().blue() > 240);
    assert!(lopdf::Document::load_mem(&document.to_pdf().unwrap()).is_ok());

    let page_path = document.pages().unwrap()[0].path.clone();
    let page = String::from_utf8(document.entry(&page_path).unwrap().unwrap().to_vec()).unwrap();
    document
        .set_entry(
            &page_path,
            page.replace("ImageMask=\"4\"", "ImageMask=\"999\"")
                .into_bytes(),
        )
        .unwrap();
    assert!(document
        .validate_references()
        .unwrap()
        .iter()
        .any(|issue| issue.code == "image_mask_reference" && issue.message.contains("999")));
    let unmasked =
        resvg::tiny_skia::Pixmap::decode_png(&document.page_png(0, 25.4).unwrap()).unwrap();
    assert!(unmasked.pixel(1, 0).unwrap().blue() > 240);
    assert!(unmasked.pixel(1, 0).unwrap().red() < 20);

    let mut one_pixel_mask = Vec::new();
    {
        let mut encoder = png::Encoder::new(&mut one_pixel_mask, 1, 1);
        encoder.set_color(png::ColorType::Rgb);
        encoder.set_depth(png::BitDepth::Eight);
        encoder
            .write_header()
            .unwrap()
            .write_image_data(&[0, 0, 0])
            .unwrap();
    }
    document.set_entry(&page_path, page.into_bytes()).unwrap();
    document
        .set_entry("Doc_0/Res/mask.png", one_pixel_mask)
        .unwrap();
    let size_mismatch =
        resvg::tiny_skia::Pixmap::decode_png(&document.page_png(0, 25.4).unwrap()).unwrap();
    assert!(size_mismatch.pixel(1, 0).unwrap().blue() > 240);

    let mut oversized_mask = document
        .entry("Doc_0/Res/mask.png")
        .unwrap()
        .unwrap()
        .to_vec();
    oversized_mask[16..24].copy_from_slice(&[0, 0, 19, 136, 0, 0, 19, 136]);
    let mut crc = !0_u32;
    for byte in oversized_mask[12..29].iter().copied() {
        crc ^= u32::from(byte);
        for _ in 0..8 {
            crc = (crc >> 1) ^ (0xedb8_8320 & (0_u32.wrapping_sub(crc & 1)));
        }
    }
    oversized_mask[29..33].copy_from_slice(&(!crc).to_be_bytes());
    document
        .set_entry("Doc_0/Res/mask.png", oversized_mask)
        .unwrap();
    let oversized = document.page_svg(0);
    assert!(
        matches!(oversized, Err(OfdError::Limit(_))),
        "{oversized:?}"
    );
}

#[test]
fn edits_page_image_mask_atomically() {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/image-mask.ofd");
    let mut document = OfdDocument::open(path).unwrap();
    document.set_page_image_mask(0, "5", None).unwrap();
    assert_eq!(document.page_images(0).unwrap()[0].image_mask, None);
    let unmasked =
        resvg::tiny_skia::Pixmap::decode_png(&document.page_png(0, 25.4).unwrap()).unwrap();
    assert!(unmasked.pixel(1, 0).unwrap().blue() > 240);
    let original_mask = document
        .entry("Doc_0/Res/mask.png")
        .unwrap()
        .unwrap()
        .to_vec();
    let mut wrong_size = Vec::new();
    {
        let mut encoder = png::Encoder::new(&mut wrong_size, 1, 1);
        encoder.set_color(png::ColorType::Rgb);
        encoder.set_depth(png::BitDepth::Eight);
        encoder
            .write_header()
            .unwrap()
            .write_image_data(&[0, 0, 0])
            .unwrap();
    }
    document
        .set_entry("Doc_0/Res/mask.png", wrong_size)
        .unwrap();
    let page_path = document.pages().unwrap()[0].path.clone();
    let before_page = document.entry(&page_path).unwrap().unwrap().to_vec();
    assert!(matches!(
        document.set_page_image_mask(0, "5", Some("4")),
        Err(OfdError::Invalid(message)) if message.contains("dimensions")
    ));
    assert_eq!(document.entry(&page_path).unwrap().unwrap(), before_page);
    document
        .set_entry("Doc_0/Res/mask.png", original_mask)
        .unwrap();
    document.set_page_image_mask(0, "5", Some("4")).unwrap();
    assert_eq!(
        document.page_images(0).unwrap()[0].image_mask.as_deref(),
        Some("4")
    );
    let masked =
        resvg::tiny_skia::Pixmap::decode_png(&document.page_png(0, 25.4).unwrap()).unwrap();
    assert!(masked.pixel(1, 0).unwrap().red() > 240);
    let before = document.to_bytes().unwrap();
    assert!(document.set_page_image_mask(0, "5", Some("999")).is_err());
    assert!(document.set_page_image_mask(0, "5", Some("")).is_err());
    assert!(document.set_page_image_mask(0, "999", Some("4")).is_err());
    assert!(document.set_page_image_mask(1, "5", Some("4")).is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    let reopened = OfdDocument::from_bytes(&before).unwrap();
    assert_eq!(
        reopened.page_images(0).unwrap()[0].image_mask.as_deref(),
        Some("4")
    );
}

#[test]
fn image_substitution_round_trips_and_checks_references() {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/image-mask.ofd");
    let mut document = OfdDocument::open(path).unwrap();
    assert_eq!(document.page_images(0).unwrap()[0].substitution, None);
    document
        .set_page_image_substitution(0, "5", Some("4"))
        .unwrap();
    assert_eq!(
        document.page_images(0).unwrap()[0].substitution.as_deref(),
        Some("4")
    );
    assert!(document.validate_references().unwrap().is_empty());
    let saved = document.to_bytes().unwrap();
    let reopened = OfdDocument::from_bytes(&saved).unwrap();
    assert_eq!(
        reopened.page_images(0).unwrap()[0].substitution.as_deref(),
        Some("4")
    );
    assert!(document
        .set_page_image_substitution(0, "5", Some("999"))
        .is_err());
    assert!(document
        .set_page_image_substitution(0, "5", Some(""))
        .is_err());
    assert!(document
        .set_page_image_substitution(0, "999", Some("4"))
        .is_err());
    assert!(document
        .set_page_image_substitution(1, "5", Some("4"))
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), saved);
    document.set_page_image_substitution(0, "5", None).unwrap();
    assert_eq!(document.page_images(0).unwrap()[0].substitution, None);

    let page_path = document.pages().unwrap()[0].path.clone();
    let page = String::from_utf8(document.entry(&page_path).unwrap().unwrap().to_vec()).unwrap();
    let page = page.replace("ResourceID=\"3\"", "ResourceID=\"3\" Substitution=\"999\"");
    document.set_entry(&page_path, page.into_bytes()).unwrap();
    assert!(document.validate_references().unwrap().iter().any(|issue| {
        issue.code == "image_substitution_reference" && issue.message.contains("999")
    }));
}

#[test]
fn selects_image_substitution_for_svg_png_and_pdf() {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/image-mask.ofd");
    let mut document = OfdDocument::open(path).unwrap();
    document
        .set_page_image_substitution(0, "5", Some("4"))
        .unwrap();
    let options = RenderOptions {
        prefer_image_substitution: true,
    };
    let normal_svg = document.page_svg(0).unwrap();
    let alternate_svg = document.page_svg_with_options(0, options).unwrap();
    assert_ne!(normal_svg, alternate_svg);
    assert_eq!(
        normal_svg,
        document
            .page_svg_with_options(0, RenderOptions::default())
            .unwrap()
    );
    let normal_png = document.page_png(0, 254.0).unwrap();
    let alternate_png = document.page_png_with_options(0, 254.0, options).unwrap();
    assert_ne!(normal_png, alternate_png);
    let normal_pdf = document.to_pdf().unwrap();
    let alternate_pdf = document.to_pdf_with_options(options).unwrap();
    assert!(alternate_pdf.starts_with(b"%PDF-"));
    assert_ne!(normal_pdf, alternate_pdf);

    let page_path = document.pages().unwrap()[0].path.clone();
    let page = String::from_utf8(document.entry(&page_path).unwrap().unwrap().to_vec()).unwrap();
    document
        .set_entry(
            &page_path,
            page.replace("Substitution=\"4\"", "Substitution=\"999\"")
                .into_bytes(),
        )
        .unwrap();
    assert_eq!(
        document.page_svg(0).unwrap(),
        document.page_svg_with_options(0, options).unwrap()
    );
    document.set_page_image_mask(0, "5", None).unwrap();
    let page = String::from_utf8(document.entry(&page_path).unwrap().unwrap().to_vec()).unwrap();
    document
        .set_entry(
            &page_path,
            page.replace("Substitution=\"999\"", "Substitution=\"4\"")
                .into_bytes(),
        )
        .unwrap();
    document
        .set_entry("Doc_0/Res/mask.png", b"not an image".to_vec())
        .unwrap();
    assert_eq!(
        document.page_svg(0).unwrap(),
        document.page_svg_with_options(0, options).unwrap()
    );
}

#[test]
fn composite_substitution_renders_and_validates_media_references() {
    let mut image_data = Cursor::new(Vec::new());
    image::DynamicImage::ImageRgb8(image::RgbImage::from_pixel(2, 2, image::Rgb([0, 255, 0])))
        .write_to(&mut image_data, image::ImageFormat::Png)
        .unwrap();
    let image_data = image_data.into_inner();
    let mut document = OfdDocument::new();
    document.add_blank_page(20.0, 20.0).unwrap();
    let image_id = document
        .add_image_object(0, &image_data, "png", [0.0, 0.0, 20.0, 20.0])
        .unwrap();
    let media_id = document.page_images(0).unwrap()[0].resource_id.clone();
    document.remove_page_object(0, &image_id).unwrap();
    document
        .add_composite_path_object(
            0,
            "M 0 0 L 20 0 L 20 20 L 0 20 C",
            [0.0, 0.0, 20.0, 20.0],
            PathStyle {
                fill: true,
                stroke: false,
                fill_color: Some([255, 0, 0]),
                ..PathStyle::default()
            },
        )
        .unwrap();
    let unit_id = document.page_composite_objects(0).unwrap()[0]
        .resource_id
        .clone();
    let path = format!("Doc_0/CompositeRes_{unit_id}.xml");
    let source = std::str::from_utf8(document.entry(&path).unwrap().unwrap()).unwrap();
    let resource = source.replacen(
        "<ofd:Content>",
        &format!("<ofd:Thumbnail>{media_id}</ofd:Thumbnail><ofd:Substitution>{media_id}</ofd:Substitution><ofd:Content>"),
        1,
    );
    document
        .set_entry(&path, resource.clone().into_bytes())
        .unwrap();
    let units = document.page_composite_units(0).unwrap();
    assert_eq!(units.len(), 1);
    assert_eq!(units[0].id, unit_id);
    assert_eq!((units[0].width, units[0].height), (20.0, 20.0));
    assert_eq!(units[0].thumbnail.as_deref(), Some(media_id.as_str()));
    assert_eq!(units[0].substitution.as_deref(), Some(media_id.as_str()));
    assert!(document.page_composite_units(1).is_err());
    assert!(document.validate_references().unwrap().is_empty());

    let options = RenderOptions {
        prefer_image_substitution: true,
    };
    let original = image::load_from_memory(&document.page_png(0, 25.4).unwrap())
        .unwrap()
        .to_rgb8();
    let replacement =
        image::load_from_memory(&document.page_png_with_options(0, 25.4, options).unwrap())
            .unwrap()
            .to_rgb8();
    let red = original.get_pixel(10, 10);
    let green = replacement.get_pixel(10, 10);
    assert!(red[0] > 220 && red[1] < 35, "{red:?}");
    assert!(green[1] > 220 && green[0] < 35, "{green:?}");
    assert_ne!(
        document.to_pdf().unwrap(),
        document.to_pdf_with_options(options).unwrap()
    );

    document
        .set_entry(
            &path,
            resource
                .replace(
                    &format!("<ofd:Thumbnail>{media_id}</ofd:Thumbnail>"),
                    "<ofd:Thumbnail>998</ofd:Thumbnail>",
                )
                .replace(
                    &format!("<ofd:Substitution>{media_id}</ofd:Substitution>"),
                    "<ofd:Substitution>999</ofd:Substitution>",
                )
                .into_bytes(),
        )
        .unwrap();
    let issues = document.validate_references().unwrap();
    assert!(issues
        .iter()
        .any(|issue| issue.code == "composite_thumbnail_reference"));
    assert!(issues
        .iter()
        .any(|issue| issue.code == "composite_substitution_reference"));
    assert_eq!(
        document.page_png_with_options(0, 25.4, options).unwrap(),
        document.page_png(0, 25.4).unwrap()
    );
}

#[test]
fn empty_composite_content_renders_thumbnail_or_selected_substitution() {
    let png = |color| {
        let mut data = Cursor::new(Vec::new());
        image::DynamicImage::ImageRgb8(image::RgbImage::from_pixel(2, 2, image::Rgb(color)))
            .write_to(&mut data, image::ImageFormat::Png)
            .unwrap();
        data.into_inner()
    };
    let mut document = OfdDocument::new();
    document.add_blank_page(20.0, 20.0).unwrap();
    let mut resources = Vec::new();
    for color in [[0, 255, 0], [255, 0, 0]] {
        let object_id = document
            .add_image_object(0, &png(color), "png", [0.0, 0.0, 20.0, 20.0])
            .unwrap();
        resources.push(
            document
                .page_images(0)
                .unwrap()
                .last()
                .unwrap()
                .resource_id
                .clone(),
        );
        document.remove_page_object(0, &object_id).unwrap();
    }
    document
        .add_composite_path_object(
            0,
            "M 0 0 L 20 0 L 20 20 L 0 20 C",
            [0.0, 0.0, 20.0, 20.0],
            PathStyle {
                fill: true,
                stroke: false,
                ..PathStyle::default()
            },
        )
        .unwrap();
    let unit_id = document.page_composite_objects(0).unwrap()[0]
        .resource_id
        .clone();
    let path = format!("Doc_0/CompositeRes_{unit_id}.xml");
    let source = std::str::from_utf8(document.entry(&path).unwrap().unwrap()).unwrap();
    let start = source.find("<ofd:Content>").unwrap();
    let end = source.find("</ofd:Content>").unwrap() + "</ofd:Content>".len();
    let resource = format!(
        "{}<ofd:Thumbnail>{}</ofd:Thumbnail><ofd:Substitution>{}</ofd:Substitution><ofd:Content/>{}",
        &source[..start], resources[0], resources[1], &source[end..]
    );
    document
        .set_entry(&path, resource.clone().into_bytes())
        .unwrap();
    assert!(document.validate_references().unwrap().is_empty());

    let options = RenderOptions {
        prefer_image_substitution: true,
    };
    let normal = image::load_from_memory(&document.page_png(0, 25.4).unwrap())
        .unwrap()
        .to_rgb8();
    let selected =
        image::load_from_memory(&document.page_png_with_options(0, 25.4, options).unwrap())
            .unwrap()
            .to_rgb8();
    assert_eq!(normal.get_pixel(10, 10).0, [0, 255, 0]);
    assert_eq!(selected.get_pixel(10, 10).0, [255, 0, 0]);
    assert_ne!(
        document.to_pdf().unwrap(),
        document.to_pdf_with_options(options).unwrap()
    );

    document
        .set_entry(
            &path,
            resource
                .replace(
                    &format!("<ofd:Thumbnail>{}</ofd:Thumbnail>", resources[0]),
                    "<ofd:Thumbnail>999</ofd:Thumbnail>",
                )
                .into_bytes(),
        )
        .unwrap();
    assert!(document.page_svg(0).is_err());
    assert!(document.page_svg_with_options(0, options).is_ok());
}

#[test]
fn edits_composite_unit_image_references_atomically() {
    let mut image_data = Cursor::new(Vec::new());
    image::DynamicImage::ImageRgb8(image::RgbImage::from_pixel(2, 2, image::Rgb([0, 255, 0])))
        .write_to(&mut image_data, image::ImageFormat::Png)
        .unwrap();
    let image_bytes = image_data.into_inner();
    let mut document = OfdDocument::new();
    document.add_blank_page(20.0, 20.0).unwrap();
    let image_id = document
        .add_image_object(0, &image_bytes, "png", [0.0, 0.0, 20.0, 20.0])
        .unwrap();
    let media_id = document.page_images(0).unwrap()[0].resource_id.clone();
    document.remove_page_object(0, &image_id).unwrap();
    document
        .add_composite_path_object(
            0,
            "M 0 0 L 20 0 L 20 20 L 0 20 C",
            [0.0, 0.0, 20.0, 20.0],
            PathStyle {
                fill: true,
                stroke: false,
                ..PathStyle::default()
            },
        )
        .unwrap();
    let unit_id = document.page_composite_objects(0).unwrap()[0]
        .resource_id
        .clone();
    let before = document.to_bytes().unwrap();
    assert!(document
        .set_page_composite_unit_images(0, &unit_id, Some("missing"), None)
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    assert!(document
        .set_page_composite_unit_images(0, &unit_id, None, Some("missing"))
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    document
        .set_page_composite_unit_images(0, &unit_id, Some(&media_id), None)
        .unwrap();
    assert_eq!(
        document.page_composite_units(0).unwrap()[0]
            .thumbnail
            .as_deref(),
        Some(media_id.as_str())
    );
    assert_eq!(
        document.page_composite_units(0).unwrap()[0].substitution,
        None
    );
    document
        .set_page_composite_unit_images(0, &unit_id, None, Some(&media_id))
        .unwrap();
    assert_eq!(document.page_composite_units(0).unwrap()[0].thumbnail, None);
    assert_eq!(
        document.page_composite_units(0).unwrap()[0]
            .substitution
            .as_deref(),
        Some(media_id.as_str())
    );
    document
        .set_page_composite_unit_images(0, &unit_id, Some(&media_id), Some(&media_id))
        .unwrap();
    let units = document.page_composite_units(0).unwrap();
    assert_eq!(units[0].thumbnail.as_deref(), Some(media_id.as_str()));
    assert_eq!(units[0].substitution.as_deref(), Some(media_id.as_str()));
    assert!(document.validate_references().unwrap().is_empty());
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.page_composite_units(0).unwrap(), units);
    document
        .set_page_composite_unit_images(0, &unit_id, None, None)
        .unwrap();
    assert_eq!(document.page_composite_units(0).unwrap()[0].thumbnail, None);
    assert_eq!(
        document.page_composite_units(0).unwrap()[0].substitution,
        None
    );
    assert!(document
        .set_page_composite_unit_images(0, "missing", None, None)
        .is_err());
    assert!(document
        .set_page_composite_unit_images(1, &unit_id, None, None)
        .is_err());

    let mut page_local = OfdDocument::new();
    page_local.add_blank_page(20.0, 20.0).unwrap();
    let local_media = page_local
        .add_page_multimedia_resource(0, "Image", "PNG", &image_bytes)
        .unwrap();
    page_local
        .add_composite_path_object(
            0,
            "M 0 0 L 20 0 L 20 20 C",
            [0.0, 0.0, 20.0, 20.0],
            PathStyle::default(),
        )
        .unwrap();
    let local_unit = page_local.page_composite_objects(0).unwrap()[0]
        .resource_id
        .clone();
    let unchanged = page_local.to_bytes().unwrap();
    assert!(page_local
        .set_page_composite_unit_images(0, &local_unit, Some(&local_media), None)
        .is_err());
    assert_eq!(page_local.to_bytes().unwrap(), unchanged);
}

#[test]
fn renders_image_border_and_rejects_invalid_dash_pattern() {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/image-mask.ofd");
    let mut document = OfdDocument::open(path).unwrap();
    let page_path = document.pages().unwrap()[0].path.clone();
    let style = ImageBorderStyle {
        line_width: 0.4,
        horizontal_corner_radius: 0.2,
        vertical_corner_radius: 0.2,
        dash_pattern: vec![1.0, 2.0, 3.0],
        dash_offset: 0.5,
        color: [0, 255, 0],
        color_alpha: 255,
    };
    document
        .set_page_image_border(0, "5", Some(&style))
        .unwrap();
    let info = document.page_images(0).unwrap()[0].border.clone().unwrap();
    assert_eq!(info.line_width, 0.4);
    assert_eq!(info.horizontal_corner_radius, 0.2);
    assert_eq!(info.vertical_corner_radius, 0.2);
    assert_eq!(info.dash_pattern, [1.0, 2.0, 3.0]);
    assert_eq!(info.dash_offset, 0.5);
    assert_eq!(info.color_value.as_deref(), Some("0 255 0"));
    assert_eq!(info.color_alpha, 255);
    assert!(info.color_xml.as_deref().unwrap().contains("BorderColor"));
    let svg = document.page_svg(0).unwrap();
    assert!(svg.contains("stroke=\"#00ff00\""));
    assert!(svg.contains("stroke-width=\"0.4\""));
    assert!(svg.contains("stroke-dasharray=\"1 2 3\""));
    assert!(svg.contains("rx=\"0.1\" ry=\"0.2\""));
    let png = document.page_png(0, 254.0).unwrap();
    let bitmap = resvg::tiny_skia::Pixmap::decode_png(&png).unwrap();
    let edge = bitmap.pixel(0, 4).unwrap();
    assert!(edge.green() > edge.red());
    assert!(document.to_pdf().unwrap().starts_with(b"%PDF-"));

    let before = document.to_bytes().unwrap();
    let mut invalid = style.clone();
    invalid.dash_pattern = vec![1.0, 0.0];
    assert!(document
        .set_page_image_border(0, "5", Some(&invalid))
        .is_err());
    assert!(document
        .set_page_image_border(0, "999", Some(&style))
        .is_err());
    assert!(document
        .set_page_image_border(1, "5", Some(&style))
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    let reopened = OfdDocument::from_bytes(&before).unwrap();
    assert!(reopened.page_svg(0).unwrap().contains("stroke=\"#00ff00\""));

    let page = String::from_utf8(document.entry(&page_path).unwrap().unwrap().to_vec()).unwrap();
    document
        .set_entry(
            &page_path,
            page.replace("DashPattern=\"1 2 3\"", "DashPattern=\"1 0\"")
                .into_bytes(),
        )
        .unwrap();
    assert!(matches!(document.page_svg(0), Err(OfdError::Invalid(_))));
    document.set_page_image_border(0, "5", None).unwrap();
    assert!(document.page_images(0).unwrap()[0].border.is_none());
    assert!(!document.page_svg(0).unwrap().contains("stroke=\"#00ff00\""));
}

#[test]
fn signed_page_rejects_object_attribute_changes_atomically() {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../../ofdrw-sign/src/test/resources/signedFile.ofd");
    let mut document = OfdDocument::open(path).unwrap();
    assert!(!document.signatures().unwrap().is_empty());
    let before = document.to_bytes().unwrap();
    assert!(document.set_page_object_visible(0, "62", false).is_err());
    assert!(document.set_page_object_alpha(0, "62", 128).is_err());
    assert!(document
        .set_page_object_boundary(0, "62", [1.0, 1.0, 10.0, 10.0])
        .is_err());
    assert!(document
        .set_page_object_ctm(0, "62", Some([1.0, 0.0, 0.0, 1.0, 2.0, 3.0]))
        .is_err());
    assert!(document
        .add_path_object(0, "M 0 0 L 5 5", [1.0, 1.0, 5.0, 5.0], PathStyle::default())
        .unwrap_err()
        .to_string()
        .contains("signed"));
    assert!(document
        .add_page_layer(0, "Body", None)
        .unwrap_err()
        .to_string()
        .contains("signed"));
    assert!(document
        .move_page_object_to_layer(0, "62", "60")
        .unwrap_err()
        .to_string()
        .contains("signed"));
    assert!(document
        .move_page_object(0, "62", Some("64"))
        .unwrap_err()
        .to_string()
        .contains("signed"));
    assert!(document
        .remove_page_layer(0, "60")
        .unwrap_err()
        .to_string()
        .contains("signed"));
    assert!(document
        .remove_page_object(0, "62")
        .unwrap_err()
        .to_string()
        .contains("signed"));
    let area = PageArea {
        physical_box: [0.0, 0.0, 210.0, 297.0],
        application_box: None,
        content_box: None,
        bleed_box: None,
    };
    assert!(document
        .set_page_area(0, area)
        .unwrap_err()
        .to_string()
        .contains("signed"));
    assert!(document
        .append_blank_page(0, 10.0, 10.0)
        .unwrap_err()
        .to_string()
        .contains("signed"));
    assert!(document
        .add_attachment_to_document(0, "x.txt", b"x")
        .unwrap_err()
        .to_string()
        .contains("signed"));
    assert!(document
        .add_outline(0, "new", None, None, true)
        .unwrap_err()
        .to_string()
        .contains("signed"));
    let destination = ofdrw::DestinationInfo {
        page_id: document.pages().unwrap()[0].id.clone(),
        kind: "Fit".into(),
        left: None,
        top: None,
        right: None,
        bottom: None,
        zoom: None,
    };
    assert!(document
        .add_bookmark(0, "new", destination)
        .unwrap_err()
        .to_string()
        .contains("signed"));
    let font = std::fs::read(
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/dejavu-sans.ttf"),
    )
    .unwrap();
    assert!(document
        .add_embedded_font_to_document(0, "Test", &font)
        .unwrap_err()
        .to_string()
        .contains("signed"));
    assert_eq!(document.to_bytes().unwrap(), before);
}

#[test]
fn signed_document_rejects_page_reorder_atomically() {
    let mut document = OfdDocument::new();
    document.add_blank_page(100.0, 100.0).unwrap();
    document.add_blank_page(100.0, 100.0).unwrap();
    let key = include_bytes!("fixtures/trust-leaf-private-key.bin");
    document
        .add_digital_signature(key, "2030-01-01 00:00:00")
        .unwrap();
    let before = document.to_bytes().unwrap();
    let mut reopened = OfdDocument::from_bytes(&before).unwrap();
    assert_eq!(reopened.pages().unwrap().len(), 2);
    assert!(reopened
        .move_page(0, 1)
        .unwrap_err()
        .to_string()
        .contains("signed"));
    assert_eq!(reopened.to_bytes().unwrap(), before);
}

#[test]
fn reads_image_border_defaults_and_rejects_invalid_attributes() {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/image-mask.ofd");
    let mut document = OfdDocument::open(path).unwrap();
    let page_path = document.pages().unwrap()[0].path.clone();
    let page = String::from_utf8(document.entry(&page_path).unwrap().unwrap().to_vec()).unwrap();
    let bordered = page.replace(
        "CTM=\"2 0 0 1 0 0\"/>",
        "CTM=\"2 0 0 1 0 0\"><ofd:Border/></ofd:ImageObject>",
    );
    document
        .set_entry(&page_path, bordered.into_bytes())
        .unwrap();
    let info = document.page_images(0).unwrap()[0].border.clone().unwrap();
    assert_eq!(info.line_width, 0.353);
    assert_eq!(info.dash_pattern, []);
    assert_eq!(info.color_alpha, 255);
    assert_eq!(info.color_xml, None);

    let page = String::from_utf8(document.entry(&page_path).unwrap().unwrap().to_vec()).unwrap();
    document
        .set_entry(
            &page_path,
            page.replace("<ofd:Border/>", "<ofd:Border LineWidth=\"-1\"/>")
                .into_bytes(),
        )
        .unwrap();
    assert!(matches!(document.page_images(0), Err(OfdError::Invalid(_))));
    document
        .set_entry(
            &page_path,
            page.replace(
                "<ofd:Border/>",
                "<ofd:Border><ofd:BorderColor ColorSpace=\"88\" Index=\"2\" Alpha=\"128\"><ofd:Pattern/></ofd:BorderColor></ofd:Border>",
            )
            .into_bytes(),
        )
        .unwrap();
    let info = document.page_images(0).unwrap()[0].border.clone().unwrap();
    assert_eq!(info.color_space.as_deref(), Some("88"));
    assert_eq!(info.color_index.as_deref(), Some("2"));
    assert_eq!(info.color_alpha, 128);
    assert!(info.color_xml.unwrap().contains("<ofd:Pattern/>"));
    let page = String::from_utf8(document.entry(&page_path).unwrap().unwrap().to_vec()).unwrap();
    document
        .set_entry(
            &page_path,
            page.replace("Alpha=\"128\"", "Alpha=\"300\"").into_bytes(),
        )
        .unwrap();
    assert!(matches!(document.page_images(0), Err(OfdError::Invalid(_))));
}

#[test]
fn image_border_ignores_foreign_border_color() {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/image-mask.ofd");
    let mut document = OfdDocument::open(path).unwrap();
    let style = ImageBorderStyle {
        color: [0, 255, 0],
        ..ImageBorderStyle::default()
    };
    document
        .set_page_image_border(0, "5", Some(&style))
        .unwrap();
    let page_path = document.pages().unwrap()[0].path.clone();
    let page = std::str::from_utf8(document.entry(&page_path).unwrap().unwrap()).unwrap();
    let page = page.replacen(
        "<ofd:BorderColor ",
        "<x:BorderColor xmlns:x=\"urn:other\" Alpha=\"300\" Value=\"255 0 0\"/><ofd:BorderColor ",
        1,
    );
    document.set_entry(&page_path, page.into_bytes()).unwrap();
    let border = document.page_images(0).unwrap()[0].border.clone().unwrap();
    assert_eq!(border.color_value.as_deref(), Some("0 255 0"));
    assert!(document.page_svg(0).unwrap().contains("stroke=\"#00ff00\""));
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.page_images(0).unwrap()[0].border, Some(border));
}

#[test]
fn reads_and_renders_image_border_inside_composite_resource() {
    let source = OfdDocument::open(
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/image-mask.ofd"),
    )
    .unwrap();
    let png = source.page_image_data(0, 0).unwrap();
    let mut document = OfdDocument::new();
    document.add_blank_page(10.0, 10.0).unwrap();
    document
        .add_composite_image_object(0, png, "png", [1.0, 1.0, 5.0, 5.0])
        .unwrap();
    let image = &document.page_composite_images(0).unwrap()[0];
    let resource_id = image.resource_id.clone();
    let composite_id = document.page_composite_objects(0).unwrap()[0]
        .resource_id
        .clone();
    let path = format!("Doc_0/CompositeRes_{composite_id}.xml");
    let xml = String::from_utf8(document.entry(&path).unwrap().unwrap().to_vec()).unwrap();
    let needle = format!("ResourceID=\"{resource_id}\"/>");
    let replacement = format!("ResourceID=\"{resource_id}\"><ofd:Border LineWidth=\"0.5\"><ofd:BorderColor Value=\"0 255 0\"/></ofd:Border></ofd:ImageObject>");
    assert!(xml.contains(&needle));
    document
        .set_entry(&path, xml.replace(&needle, &replacement).into_bytes())
        .unwrap();
    let border = document.page_composite_images(0).unwrap()[0]
        .border
        .clone()
        .unwrap();
    assert_eq!(border.line_width, 0.5);
    assert_eq!(border.color_value.as_deref(), Some("0 255 0"));
    assert!(document.page_svg(0).unwrap().contains("stroke=\"#00ff00\""));
}

