#[test]
fn parses_nested_outline_and_bookmark_goto() {
    let mut document = OfdDocument::new();
    let path = "Doc_0/Document.xml";
    let xml = std::str::from_utf8(document.entry(path).unwrap().unwrap()).unwrap();
    let addition = "<ofd:Bookmarks><ofd:Bookmark Name=\"Start\"><ofd:Dest Type=\"XYZ\" PageID=\"1\"/></ofd:Bookmark></ofd:Bookmarks>\
      <ofd:Outlines><ofd:OutlineElem Title=\"Parent\" Count=\"1\" Expanded=\"false\">\
      <ofd:OutlineElem Title=\"Child\"><ofd:Actions><ofd:Goto><ofd:Bookmark Name=\"Start\"/>\
      </ofd:Goto></ofd:Actions></ofd:OutlineElem></ofd:OutlineElem></ofd:Outlines>";
    let changed = xml.replace("</ofd:Document>", &format!("{addition}</ofd:Document>"));
    document.set_entry(path, changed.into_bytes()).unwrap();
    assert_eq!(document.bookmarks().unwrap()[0].name, "Start");
    let outlines = document.outlines().unwrap();
    assert_eq!(outlines.len(), 2);
    assert_eq!(outlines[0].count, Some(1));
    assert!(!outlines[0].expanded);
    assert_eq!(outlines[1].depth, 1);
    assert_eq!(outlines[1].parent_index, Some(0));
    assert_eq!(outlines[1].bookmark_name.as_deref(), Some("Start"));
    assert_eq!(outlines[0].destination, None);
}

#[test]
fn writes_nested_outlines_and_preserves_them_after_page_addition() {
    let mut document = OfdDocument::new();
    document.add_text_page("first", 210.0, 297.0).unwrap();
    document.add_text_page("second", 210.0, 297.0).unwrap();
    let pages = document.pages().unwrap();
    let first = ofdrw::DestinationInfo {
        page_id: pages[0].id.clone(),
        kind: "XYZ".into(),
        left: Some(10.0),
        top: Some(20.0),
        right: None,
        bottom: None,
        zoom: Some(1.0),
    };
    let second = ofdrw::DestinationInfo {
        page_id: pages[1].id.clone(),
        ..first.clone()
    };
    assert_eq!(
        document
            .add_outline(0, "Parent & Rust", None, Some(first.clone()), true)
            .unwrap(),
        0
    );
    assert_eq!(
        document
            .add_outline(0, "Other", None, Some(second), false)
            .unwrap(),
        1
    );
    assert_eq!(
        document
            .add_outline(0, "Child", Some(0), None, true)
            .unwrap(),
        1
    );
    assert_eq!(
        document
            .add_outline(0, "Child 2", Some(0), Some(first), false)
            .unwrap(),
        2
    );
    let outlines = document.outlines().unwrap();
    assert_eq!(
        outlines
            .iter()
            .map(|item| item.title.as_str())
            .collect::<Vec<_>>(),
        vec!["Parent & Rust", "Child", "Child 2", "Other"]
    );
    assert_eq!(outlines[1].parent_index, Some(0));
    assert_eq!(outlines[2].parent_index, Some(0));
    assert_eq!(
        outlines[2].destination.as_ref().unwrap().page_id,
        pages[0].id
    );
    assert!(!outlines[3].expanded);
    document.add_text_page("third", 210.0, 297.0).unwrap();
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.outlines().unwrap(), outlines);
    assert_eq!(reopened.page_text(2).unwrap(), vec!["third"]);
}

#[test]
fn edits_outline_title_and_expanded_state_without_changing_children_or_action() {
    let mut document = OfdDocument::new();
    document.add_blank_page(40.0, 30.0).unwrap();
    let page_id = document.pages().unwrap()[0].id.clone();
    document
        .add_outline(
            0,
            "Parent",
            None,
            Some(ofdrw::DestinationInfo {
                page_id,
                kind: "Fit".into(),
                left: None,
                top: None,
                right: None,
                bottom: None,
                zoom: None,
            }),
            true,
        )
        .unwrap();
    document
        .add_outline(0, "Child", Some(0), None, true)
        .unwrap();
    let original = document.outlines().unwrap();
    document.set_outline_title(0, "章节 & 一\tA").unwrap();
    document.set_outline_expanded(0, false).unwrap();
    let edited = document.outlines().unwrap();
    assert_eq!(edited[0].title, "章节 & 一\tA");
    assert!(!edited[0].expanded);
    assert_eq!(edited[0].destination, original[0].destination);
    assert_eq!(edited[1], original[1]);
    let before = document.to_bytes().unwrap();
    assert!(document.set_outline_title(0, "bad\0title").is_err());
    assert!(document.set_outline_title(0, " ").is_err());
    assert!(document.set_outline_expanded(2, true).is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    let reopened = OfdDocument::from_bytes(&before).unwrap();
    assert_eq!(reopened.outlines().unwrap(), edited);
}

#[test]
fn retargets_outline_goto_and_preserves_other_actions_and_children() {
    let mut document = OfdDocument::new();
    document.add_blank_page(40.0, 30.0).unwrap();
    document.add_blank_page(40.0, 30.0).unwrap();
    let pages = document.pages().unwrap();
    let destination = |page_id: String| ofdrw::DestinationInfo {
        page_id,
        kind: "Fit".into(),
        left: None,
        top: None,
        right: None,
        bottom: None,
        zoom: None,
    };
    document
        .add_outline(
            0,
            "Parent",
            None,
            Some(destination(pages[0].id.clone())),
            true,
        )
        .unwrap();
    document
        .add_outline(0, "Child", Some(0), None, true)
        .unwrap();
    let root = "Doc_0/Document.xml";
    let source = std::str::from_utf8(document.entry(root).unwrap().unwrap()).unwrap();
    let updated = source.replacen(
        "</ofd:Actions>",
        "<ofd:Action Event=\"CLICK\"><ofd:URI URI=\"https://example.org\"/></ofd:Action></ofd:Actions>",
        1,
    );
    document.set_entry(root, updated.into_bytes()).unwrap();
    document
        .set_outline_destination(0, &destination(pages[1].id.clone()))
        .unwrap();
    let outlines = document.outlines().unwrap();
    assert_eq!(
        outlines[0].destination.as_ref().unwrap().page_id,
        pages[1].id
    );
    assert_eq!(outlines[1].title, "Child");
    let xml = std::str::from_utf8(document.entry(root).unwrap().unwrap()).unwrap();
    assert!(xml.contains("https://example.org"));
    let before = document.to_bytes().unwrap();
    assert!(document
        .set_outline_destination(0, &destination("missing".into()))
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    let second_body = document.append_document_body().unwrap();
    for _ in 0..5 {
        document.append_blank_page(second_body, 40.0, 30.0).unwrap();
    }
    let other_body_page = document.pages().unwrap().last().unwrap().id.clone();
    assert!(!pages.iter().any(|page| page.id == other_body_page));
    let before_cross_body = document.to_bytes().unwrap();
    assert!(document
        .set_outline_destination(0, &destination(other_body_page))
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before_cross_body);
    assert_eq!(
        OfdDocument::from_bytes(&before_cross_body)
            .unwrap()
            .outlines()
            .unwrap(),
        outlines
    );
}

#[test]
fn retargets_outline_to_existing_bookmark_without_changing_children() {
    let mut document = OfdDocument::new();
    document.add_blank_page(40.0, 30.0).unwrap();
    let page_id = document.pages().unwrap()[0].id.clone();
    let destination = ofdrw::DestinationInfo {
        page_id,
        kind: "Fit".into(),
        left: None,
        top: None,
        right: None,
        bottom: None,
        zoom: None,
    };
    document
        .add_bookmark(0, "索引 & A", destination.clone())
        .unwrap();
    document
        .add_outline(0, "Parent", None, Some(destination.clone()), true)
        .unwrap();
    document
        .add_outline(0, "Child", Some(0), None, true)
        .unwrap();
    document.set_outline_bookmark(0, "索引 & A").unwrap();
    let outlines = document.outlines().unwrap();
    assert_eq!(outlines[0].bookmark_name.as_deref(), Some("索引 & A"));
    assert!(outlines[0].destination.is_none());
    assert_eq!(outlines[1].title, "Child");
    let before = document.to_bytes().unwrap();
    assert!(document.set_outline_bookmark(0, "missing").is_err());
    assert!(document.set_outline_bookmark(0, "bad\0name").is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    let second_body = document.append_document_body().unwrap();
    document.append_blank_page(second_body, 40.0, 30.0).unwrap();
    let other_page = document.pages().unwrap().last().unwrap().id.clone();
    document
        .add_bookmark(
            second_body,
            "Other body",
            ofdrw::DestinationInfo {
                page_id: other_page,
                ..destination.clone()
            },
        )
        .unwrap();
    let before_other = document.to_bytes().unwrap();
    assert!(document.set_outline_bookmark(0, "Other body").is_err());
    assert_eq!(document.to_bytes().unwrap(), before_other);
    document.set_outline_destination(0, &destination).unwrap();
    assert_eq!(document.outlines().unwrap()[0].bookmark_name, None);
    assert_eq!(
        document.outlines().unwrap()[0].destination,
        Some(destination)
    );
}

#[test]
fn removes_outline_subtree_without_changing_siblings_or_other_xml() {
    let mut document = OfdDocument::new();
    document.add_blank_page(210.0, 297.0).unwrap();
    let original_page = document
        .entry("Doc_0/Pages/Page_0/Content.xml")
        .unwrap()
        .unwrap()
        .to_vec();
    document.add_outline(0, "Parent", None, None, true).unwrap();
    document
        .add_outline(0, "Child", Some(0), None, true)
        .unwrap();
    document
        .add_outline(0, "Sibling", None, None, true)
        .unwrap();
    let before = document.to_bytes().unwrap();
    assert!(document.remove_outline(3).is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    document.remove_outline(0).unwrap();
    let outlines = document.outlines().unwrap();
    assert_eq!(outlines.len(), 1);
    assert_eq!(outlines[0].title, "Sibling");
    assert_eq!(
        document
            .entry("Doc_0/Pages/Page_0/Content.xml")
            .unwrap()
            .unwrap(),
        original_page
    );
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.outlines().unwrap(), outlines);
}

