#[test]
fn removes_bookmarks_from_new_and_existing_documents() {
    let mut document = OfdDocument::new();
    document.add_blank_page(210.0, 297.0).unwrap();
    let page_id = document.pages().unwrap()[0].id.clone();
    let destination = ofdrw::DestinationInfo {
        page_id,
        kind: "Fit".into(),
        left: None,
        top: None,
        right: None,
        bottom: None,
        zoom: None,
    };
    document
        .add_bookmark(0, "Keep", destination.clone())
        .unwrap();
    document.add_bookmark(0, "Delete", destination).unwrap();
    let before = document.to_bytes().unwrap();
    assert!(document.remove_bookmark(0, "Missing").is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    document.remove_bookmark(0, "Delete").unwrap();
    document.add_blank_page(210.0, 297.0).unwrap();
    assert_eq!(document.bookmarks().unwrap().len(), 1);
    let mut reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.bookmarks().unwrap()[0].name, "Keep");
    reopened.remove_bookmark(0, "Keep").unwrap();
    assert!(reopened.bookmarks().unwrap().is_empty());
    assert_eq!(
        OfdDocument::from_bytes(&reopened.to_bytes().unwrap())
            .unwrap()
            .pages()
            .unwrap()
            .len(),
        2
    );
}

#[test]
fn refuses_to_remove_bookmark_referenced_by_page_action() {
    let mut document = OfdDocument::new();
    document.add_text_page("click", 100.0, 60.0).unwrap();
    let page_id = document.pages().unwrap()[0].id.clone();
    let object_id = document.page_objects(0).unwrap()[0].id.clone().unwrap();
    document
        .add_bookmark(
            0,
            "Target",
            ofdrw::DestinationInfo {
                page_id,
                kind: "Fit".into(),
                left: None,
                top: None,
                right: None,
                bottom: None,
                zoom: None,
            },
        )
        .unwrap();
    document
        .add_page_object_bookmark_action(0, &object_id, "Target")
        .unwrap();
    let mut broken = document.clone();
    let root = "Doc_0/Document.xml";
    let xml = String::from_utf8(broken.entry(root).unwrap().unwrap().to_vec()).unwrap();
    broken
        .set_entry(
            root,
            xml.replacen("Name=\"Target\"", "Name=\"Other\"", 1)
                .into_bytes(),
        )
        .unwrap();
    assert!(broken.validate_references().unwrap().iter().any(|issue| {
        issue.code == "bookmark_reference" && issue.path == document.pages().unwrap()[0].path
    }));
    let before = document.to_bytes().unwrap();
    assert!(document
        .remove_bookmark(0, "Target")
        .unwrap_err()
        .to_string()
        .contains("still referenced"));
    assert_eq!(document.to_bytes().unwrap(), before);
    document
        .remove_page_object_action(0, &object_id, 0)
        .unwrap();
    document.remove_bookmark(0, "Target").unwrap();
    assert!(document.validate_references().unwrap().is_empty());
}

#[test]
fn bookmark_removal_ignores_existing_missing_reference_in_another_document() {
    let mut document = OfdDocument::new();
    document.add_text_page("first", 100.0, 60.0).unwrap();
    document.append_document_body().unwrap();
    document.append_text_page(1, "second", 100.0, 60.0).unwrap();
    let pages = document.pages().unwrap();
    for (index, page) in pages.iter().enumerate() {
        document
            .add_bookmark(
                index,
                "Target",
                ofdrw::DestinationInfo {
                    page_id: page.id.clone(),
                    kind: "Fit".into(),
                    left: None,
                    top: None,
                    right: None,
                    bottom: None,
                    zoom: None,
                },
            )
            .unwrap();
    }
    let object_id = document.page_objects(1).unwrap()[0].id.clone().unwrap();
    document
        .add_page_object_bookmark_action(1, &object_id, "Target")
        .unwrap();
    let root = document.document_info().unwrap()[1].root.clone();
    let source = String::from_utf8(document.entry(&root).unwrap().unwrap().to_vec()).unwrap();
    document
        .set_entry(
            &root,
            source
                .replacen("Name=\"Target\"", "Name=\"Other\"", 1)
                .into_bytes(),
        )
        .unwrap();
    assert_eq!(
        document
            .validate_references()
            .unwrap()
            .iter()
            .filter(|issue| issue.code == "bookmark_reference")
            .count(),
        1
    );
    document.remove_bookmark(0, "Target").unwrap();
    assert_eq!(
        document
            .validate_references()
            .unwrap()
            .iter()
            .filter(|issue| issue.code == "bookmark_reference")
            .count(),
        1
    );
    assert_eq!(document.bookmarks().unwrap().len(), 1);
    assert_eq!(document.bookmarks().unwrap()[0].document_index, 1);
}

