#[test]
fn page_area_boxes_inherit_and_application_box_clips_output() {
    let mut document = OfdDocument::new();
    document
        .add_path_page(
            "M 0 0 L 100 0 L 100 100 L 0 100 C",
            [0.0, 0.0, 100.0, 100.0],
            100.0,
            100.0,
            true,
            false,
        )
        .unwrap();
    let path = document.pages().unwrap()[0].path.clone();
    let original = std::str::from_utf8(document.entry(&path).unwrap().unwrap()).unwrap();
    let page = original.replace(
        "</ofd:PhysicalBox>",
        "</ofd:PhysicalBox><ofd:ApplicationBox>25 25 50 50</ofd:ApplicationBox><ofd:ContentBox>30 30 40 40</ofd:ContentBox><ofd:BleedBox>-5 -5 110 110</ofd:BleedBox>",
    );
    document.set_entry(&path, page.into_bytes()).unwrap();
    let page = &document.pages().unwrap()[0];
    assert_eq!(page.physical_box, Some([0.0, 0.0, 100.0, 100.0]));
    assert_eq!(page.application_box, Some([25.0, 25.0, 50.0, 50.0]));
    assert_eq!(page.content_box, Some([30.0, 30.0, 40.0, 40.0]));
    assert_eq!(page.bleed_box, Some([-5.0, -5.0, 110.0, 110.0]));
    let svg = document.page_svg(0).unwrap();
    assert!(svg.contains("clip-path=\"url(#ofd-application-clip)\""));
    let png = resvg::tiny_skia::Pixmap::decode_png(&document.page_png(0, 25.4).unwrap()).unwrap();
    assert_eq!(png.width(), 100);
    assert_eq!(png.height(), 100);
    assert_eq!(png.pixel(10, 10).unwrap().red(), 255);
    assert_eq!(png.pixel(50, 50).unwrap().red(), 0);
    assert_eq!(png.pixel(90, 90).unwrap().red(), 255);
    let pdf = lopdf::Document::load_mem(&document.to_pdf().unwrap()).unwrap();
    let has_pdf_clip = pdf.objects.values().any(|object| {
        let lopdf::Object::Stream(stream) = object else {
            return false;
        };
        let mut stream = stream.clone();
        if stream.decompress().is_err() {
            return false;
        }
        lopdf::content::Content::decode(&stream.content).is_ok_and(|content| {
            content
                .operations
                .iter()
                .any(|operation| operation.operator == "W" || operation.operator == "W*")
        })
    });
    assert!(has_pdf_clip);

    let path = document.pages().unwrap()[0].path.clone();
    let page_xml = std::str::from_utf8(document.entry(&path).unwrap().unwrap()).unwrap();
    let page_xml = page_xml.replace(
        "<ofd:Area><ofd:PhysicalBox>0 0 100 100</ofd:PhysicalBox><ofd:ApplicationBox>25 25 50 50</ofd:ApplicationBox><ofd:ContentBox>30 30 40 40</ofd:ContentBox><ofd:BleedBox>-5 -5 110 110</ofd:BleedBox></ofd:Area>",
        "",
    );
    document.set_entry(&path, page_xml.into_bytes()).unwrap();
    let root = "Doc_0/Document.xml";
    let common = std::str::from_utf8(document.entry(root).unwrap().unwrap()).unwrap();
    let common = common.replace(
        "<ofd:PageArea><ofd:PhysicalBox>0 0 210 297</ofd:PhysicalBox></ofd:PageArea>",
        "<ofd:PageArea><ofd:PhysicalBox>0 0 100 100</ofd:PhysicalBox><ofd:ApplicationBox>10 10 80 80</ofd:ApplicationBox><ofd:ContentBox>20 20 60 60</ofd:ContentBox></ofd:PageArea>",
    );
    document.set_entry(root, common.into_bytes()).unwrap();
    let inherited = &document.pages().unwrap()[0];
    assert_eq!(inherited.application_box, Some([10.0, 10.0, 80.0, 80.0]));
    assert_eq!(inherited.content_box, Some([20.0, 20.0, 60.0, 60.0]));
    assert_eq!(inherited.bleed_box, inherited.physical_box);

    let outside = std::str::from_utf8(document.entry(root).unwrap().unwrap())
        .unwrap()
        .replace(
            "<ofd:ApplicationBox>10 10 80 80</ofd:ApplicationBox>",
            "<ofd:ApplicationBox>150 150 20 20</ofd:ApplicationBox>",
        );
    document.set_entry(root, outside.into_bytes()).unwrap();
    let blank = resvg::tiny_skia::Pixmap::decode_png(&document.page_png(0, 25.4).unwrap()).unwrap();
    assert_eq!(blank.pixel(50, 50).unwrap().red(), 255);

    let invalid = std::str::from_utf8(document.entry(root).unwrap().unwrap())
        .unwrap()
        .replace(
            "<ofd:ApplicationBox>150 150 20 20</ofd:ApplicationBox>",
            "<ofd:ApplicationBox>10 10 0 20</ofd:ApplicationBox>",
        );
    document.set_entry(root, invalid.into_bytes()).unwrap();
    assert!(matches!(document.page_svg(0), Err(OfdError::Invalid(_))));
}

#[test]
fn document_page_area_updates_inherited_pages_and_preserves_extensions() {
    let mut document = OfdDocument::new();
    document.add_blank_page(80.0, 40.0).unwrap();
    document.add_blank_page(90.0, 50.0).unwrap();
    let inherited_path = document.pages().unwrap()[0].path.clone();
    let page_xml =
        String::from_utf8(document.entry(&inherited_path).unwrap().unwrap().to_vec()).unwrap();
    let parsed = roxmltree::Document::parse(&page_xml).unwrap();
    let area = parsed
        .root_element()
        .children()
        .find(|node| node.tag_name().name() == "Area")
        .unwrap();
    let mut without_area = page_xml.clone();
    without_area.replace_range(area.range(), "");
    document
        .set_entry(&inherited_path, without_area.into_bytes())
        .unwrap();
    let root = "Doc_0/Document.xml";
    let root_xml = String::from_utf8(document.entry(root).unwrap().unwrap().to_vec()).unwrap();
    document
        .set_entry(
            root,
            root_xml
                .replace(
                    "</ofd:PageArea>",
                    "<ofd:VendorExtension Key=\"keep\"/></ofd:PageArea>",
                )
                .into_bytes(),
        )
        .unwrap();
    let area = PageArea {
        physical_box: [0.0, 0.0, 150.0, 60.0],
        application_box: Some([10.0, 5.0, 130.0, 50.0]),
        content_box: Some([15.0, 10.0, 120.0, 40.0]),
        bleed_box: None,
    };
    assert!(matches!(
        document.set_document_page_area(
            0,
            PageArea {
                physical_box: [0.0, 0.0, -1.0, 60.0],
                ..area
            }
        ),
        Err(OfdError::Invalid(_))
    ));
    assert!(document
        .document_page_area(0)
        .unwrap()
        .unwrap()
        .application_box
        .is_none());
    document.set_document_page_area(0, area).unwrap();
    assert_eq!(document.document_page_area(0).unwrap(), Some(area));
    assert_eq!(
        document.pages().unwrap()[0].physical_box,
        Some(area.physical_box)
    );
    assert_eq!(
        document.pages().unwrap()[0].application_box,
        area.application_box
    );
    assert_eq!(
        document.pages().unwrap()[1].physical_box,
        Some([0.0, 0.0, 90.0, 50.0])
    );
    assert!(
        String::from_utf8_lossy(document.entry(root).unwrap().unwrap())
            .contains("VendorExtension Key=\"keep\"")
    );
    assert!(document.validate_references().unwrap().is_empty());
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.document_page_area(0).unwrap(), Some(area));
}

#[test]
fn document_page_area_adds_missing_element_without_reordering_resources() {
    let mut document = OfdDocument::new();
    let root = "Doc_0/Document.xml";
    let original = String::from_utf8(document.entry(root).unwrap().unwrap().to_vec()).unwrap();
    let parsed = roxmltree::Document::parse(&original).unwrap();
    let area = parsed
        .descendants()
        .find(|node| node.tag_name().name() == "PageArea")
        .unwrap();
    let range = area.range();
    let mut without_area = original;
    without_area.replace_range(range, "");
    document.set_entry(root, without_area.into_bytes()).unwrap();
    assert_eq!(document.document_page_area(0).unwrap(), None);
    let area = PageArea {
        physical_box: [0.0, 0.0, 120.0, 70.0],
        application_box: None,
        content_box: None,
        bleed_box: None,
    };
    document.set_document_page_area(0, area).unwrap();
    let xml = String::from_utf8(document.entry(root).unwrap().unwrap().to_vec()).unwrap();
    assert!(xml.find("<ofd:PageArea>").unwrap() < xml.find("<ofd:PublicRes>").unwrap());
    assert_eq!(document.document_page_area(0).unwrap(), Some(area));

    let self_closing = xml.replace(
        "<ofd:PageArea><ofd:PhysicalBox>0 0 120 70</ofd:PhysicalBox></ofd:PageArea>",
        "<ofd:PageArea/>",
    );
    assert_ne!(self_closing, xml);
    document.set_entry(root, self_closing.into_bytes()).unwrap();
    document.set_document_page_area(0, area).unwrap();
    assert_eq!(document.document_page_area(0).unwrap(), Some(area));
}

#[test]
fn rejects_invalid_present_page_area_boxes_instead_of_using_defaults() {
    let mut document = OfdDocument::new();
    document.add_blank_page(80.0, 40.0).unwrap();
    let root = "Doc_0/Document.xml";
    let root_xml = String::from_utf8(document.entry(root).unwrap().unwrap().to_vec()).unwrap();
    for invalid in ["0 0 0 297", "0 0 NaN 297", "0 0 210"] {
        let changed = root_xml.replace("0 0 210 297", invalid);
        document.set_entry(root, changed.into_bytes()).unwrap();
        assert!(matches!(
            document.document_page_area(0),
            Err(OfdError::Invalid(_))
        ));
        assert!(matches!(document.pages(), Err(OfdError::Invalid(_))));
    }
    document.set_entry(root, root_xml.into_bytes()).unwrap();

    let path = document.pages().unwrap()[0].path.clone();
    let page_xml = String::from_utf8(document.entry(&path).unwrap().unwrap().to_vec()).unwrap();
    let changed = page_xml.replace(
        "</ofd:Area>",
        "<ofd:ApplicationBox>1 2 broken 4</ofd:ApplicationBox></ofd:Area>",
    );
    document.set_entry(&path, changed.into_bytes()).unwrap();
    assert!(matches!(document.pages(), Err(OfdError::Invalid(_))));
    document.set_entry(&path, page_xml.into_bytes()).unwrap();
    assert!(document.pages().is_ok());
}

#[test]
fn rejects_duplicate_page_area_elements_and_boxes() {
    let mut document = OfdDocument::new();
    document.add_blank_page(80.0, 40.0).unwrap();
    let root = "Doc_0/Document.xml";
    let root_xml = String::from_utf8(document.entry(root).unwrap().unwrap().to_vec()).unwrap();
    let duplicate_box = root_xml.replace(
        "</ofd:PageArea>",
        "<ofd:PhysicalBox>0 0 100 100</ofd:PhysicalBox></ofd:PageArea>",
    );
    document
        .set_entry(root, duplicate_box.into_bytes())
        .unwrap();
    assert!(
        matches!(document.pages(), Err(OfdError::Invalid(message)) if message.contains("multiple PhysicalBox"))
    );
    assert!(
        matches!(document.document_page_area(0), Err(OfdError::Invalid(message)) if message.contains("multiple PhysicalBox"))
    );
    assert!(document
        .set_document_page_area(
            0,
            PageArea {
                physical_box: [0.0, 0.0, 100.0, 100.0],
                application_box: None,
                content_box: None,
                bleed_box: None,
            },
        )
        .is_err());

    let duplicate_area = root_xml.replace(
        "</ofd:PageArea>",
        "</ofd:PageArea><ofd:PageArea><ofd:PhysicalBox>0 0 100 100</ofd:PhysicalBox></ofd:PageArea>",
    );
    document
        .set_entry(root, duplicate_area.into_bytes())
        .unwrap();
    assert!(
        matches!(document.pages(), Err(OfdError::Invalid(message)) if message.contains("multiple PageArea"))
    );
    document.set_entry(root, root_xml.into_bytes()).unwrap();

    let path = document.pages().unwrap()[0].path.clone();
    let page_xml = String::from_utf8(document.entry(&path).unwrap().unwrap().to_vec()).unwrap();
    let duplicate_area = page_xml.replace(
        "</ofd:Area>",
        "</ofd:Area><ofd:Area><ofd:PhysicalBox>0 0 100 100</ofd:PhysicalBox></ofd:Area>",
    );
    document
        .set_entry(&path, duplicate_area.into_bytes())
        .unwrap();
    assert!(
        matches!(document.pages(), Err(OfdError::Invalid(message)) if message.contains("multiple Area"))
    );
    document.set_entry(&path, page_xml.into_bytes()).unwrap();
    assert!(document.pages().is_ok());
}

#[test]
fn set_page_area_preserves_extensions_and_round_trips() {
    let mut document = OfdDocument::new();
    document.add_text_page("area", 100.0, 100.0).unwrap();
    let path = document.pages().unwrap()[0].path.clone();
    let original = std::str::from_utf8(document.entry(&path).unwrap().unwrap()).unwrap();
    let extended = original.replace(
        "</ofd:PhysicalBox>",
        "</ofd:PhysicalBox><ext:Keep xmlns:ext=\"urn:example\" token=\"value\"/><ofd:BleedBox>-5 -5 110 110</ofd:BleedBox>",
    );
    document.set_entry(&path, extended.into_bytes()).unwrap();
    let area = PageArea {
        physical_box: [1.0, 2.0, 90.0, 80.0],
        application_box: Some([10.0, 20.0, 60.0, 50.0]),
        content_box: Some([15.0, 25.0, 40.0, 30.0]),
        bleed_box: Some([-5.0, -5.0, 110.0, 110.0]),
    };
    document.set_page_area(0, area).unwrap();
    let page = &document.pages().unwrap()[0];
    assert_eq!(page.physical_box, Some(area.physical_box));
    assert_eq!(page.application_box, area.application_box);
    assert_eq!(page.content_box, area.content_box);
    assert_eq!(page.bleed_box, area.bleed_box);
    let changed = std::str::from_utf8(document.entry(&path).unwrap().unwrap()).unwrap();
    assert!(changed.contains("<ext:Keep xmlns:ext=\"urn:example\" token=\"value\"/>"));
    assert!(
        changed.find("<ofd:ApplicationBox>").unwrap() < changed.find("<ofd:ContentBox>").unwrap()
    );
    assert!(changed.find("<ofd:ContentBox>").unwrap() < changed.find("<ofd:BleedBox>").unwrap());
    assert!(changed.contains("<ofd:TextObject"));
    assert!(document
        .page_svg(0)
        .unwrap()
        .contains("ofd-application-clip"));

    let bytes = document.to_bytes().unwrap();
    let mut loaded = OfdDocument::from_bytes(&bytes).unwrap();
    assert_eq!(
        loaded.pages().unwrap()[0].application_box,
        area.application_box
    );
    loaded
        .set_page_area(
            0,
            PageArea {
                application_box: None,
                content_box: None,
                bleed_box: None,
                ..area
            },
        )
        .unwrap();
    let page = &loaded.pages().unwrap()[0];
    assert_eq!(page.application_box, None);
    assert_eq!(page.content_box, None);
    assert_eq!(page.bleed_box, Some(area.physical_box));
    assert!(!loaded.page_svg(0).unwrap().contains("ofd-application-clip"));
    assert!(std::str::from_utf8(loaded.entry(&path).unwrap().unwrap())
        .unwrap()
        .contains("<ext:Keep"));
}

#[test]
fn set_page_area_adds_missing_area_and_rejects_invalid_dimensions() {
    let mut document = OfdDocument::new();
    document.add_text_page("area", 100.0, 100.0).unwrap();
    let path = document.pages().unwrap()[0].path.clone();
    let original = std::str::from_utf8(document.entry(&path).unwrap().unwrap()).unwrap();
    let no_area = original.replace(
        "<ofd:Area><ofd:PhysicalBox>0 0 100 100</ofd:PhysicalBox></ofd:Area>",
        "",
    );
    document.set_entry(&path, no_area.into_bytes()).unwrap();
    let area = PageArea {
        physical_box: [0.0, 0.0, 50.0, 60.0],
        application_box: None,
        content_box: None,
        bleed_box: None,
    };
    document.set_page_area(0, area).unwrap();
    let page_xml = std::str::from_utf8(document.entry(&path).unwrap().unwrap()).unwrap();
    assert!(page_xml.find("<ofd:Area>").unwrap() < page_xml.find("<ofd:Content>").unwrap());
    assert_eq!(
        document.pages().unwrap()[0].physical_box,
        Some(area.physical_box)
    );

    let before = document.entry(&path).unwrap().unwrap().to_vec();
    for invalid in [
        PageArea {
            physical_box: [0.0, 0.0, 0.0, 60.0],
            ..area
        },
        PageArea {
            application_box: Some([f64::NAN, 0.0, 10.0, 10.0]),
            ..area
        },
    ] {
        assert!(matches!(
            document.set_page_area(0, invalid),
            Err(OfdError::Invalid(_))
        ));
        assert_eq!(document.entry(&path).unwrap().unwrap(), before);
    }
    assert!(matches!(
        document.set_page_area(1, area),
        Err(OfdError::PageIndex { .. })
    ));

    let self_closing = std::str::from_utf8(document.entry(&path).unwrap().unwrap())
        .unwrap()
        .replace(
            "<ofd:Area><ofd:PhysicalBox>0 0 50 60</ofd:PhysicalBox></ofd:Area>",
            "<ofd:Area/>",
        );
    document
        .set_entry(&path, self_closing.into_bytes())
        .unwrap();
    document.set_page_area(0, area).unwrap();
    assert_eq!(
        document.pages().unwrap()[0].physical_box,
        Some(area.physical_box)
    );
}

#[test]
fn rasterizes_vector_page_to_png_at_requested_resolution() {
    let mut document = OfdDocument::new();
    document
        .add_path_page(
            "M 0 0 L 10 0 L 10 10 L 0 10 C",
            [2.0, 2.0, 10.0, 10.0],
            20.0,
            20.0,
            true,
            false,
        )
        .unwrap();
    let png = document.page_png(0, 25.4).unwrap();
    assert!(png.starts_with(b"\x89PNG\r\n\x1a\n"));
    let image = resvg::tiny_skia::Pixmap::decode_png(&png).unwrap();
    assert_eq!((image.width(), image.height()), (20, 20));
    let doubled =
        resvg::tiny_skia::Pixmap::decode_png(&document.page_png(0, 50.8).unwrap()).unwrap();
    assert_eq!((doubled.width(), doubled.height()), (40, 40));
    assert_eq!(image.pixel(0, 0).unwrap().red(), 255);
    assert_eq!(image.pixel(7, 7).unwrap().red(), 0);
    assert!(document.page_png(0, 0.0).is_err());
    assert!(document.page_png(0, f64::NAN).is_err());
    assert!(matches!(
        document.page_png(1, 96.0),
        Err(OfdError::PageIndex { .. })
    ));
}

