#[test]
fn exports_multi_page_vector_pdf_with_physical_page_sizes() {
    let mut document = OfdDocument::new();
    document
        .add_path_page(
            "M 0 0 L 10 0 L 10 10 C",
            [2.0, 2.0, 10.0, 10.0],
            20.0,
            30.0,
            true,
            false,
        )
        .unwrap();
    document.add_text_page("second page", 40.0, 50.0).unwrap();
    let bytes = document.to_pdf().unwrap();
    assert!(bytes.starts_with(b"%PDF-"));
    let parsed = lopdf::Document::load_mem(&bytes).unwrap();
    let pages = parsed.get_pages();
    assert_eq!(pages.len(), 2);
    assert!(parsed
        .objects
        .values()
        .any(|object| object.as_dict().is_ok_and(|dict| dict.has(b"ToUnicode"))));
    for (index, expected_width) in [(1, 20.0_f32), (2, 40.0)] {
        let page = parsed.get_dictionary(*pages.get(&index).unwrap()).unwrap();
        let media_box = page.get(b"MediaBox").unwrap().as_array().unwrap();
        let width_pt = media_box[2].as_float().unwrap();
        assert!((width_pt - expected_width * 72.0 / 25.4).abs() < 0.1);
        assert!(!parsed
            .get_page_content(*pages.get(&index).unwrap())
            .unwrap()
            .is_empty());
    }
    assert!(OfdDocument::new().to_pdf().is_err());
}

#[test]
fn exports_ofd_attachments_as_sorted_pdf_embedded_files() {
    let mut document = OfdDocument::new();
    document.add_blank_page(40.0, 30.0).unwrap();
    document.add_attachment("报告.txt", b"first").unwrap();
    document.add_attachment("a.txt", b"middle").unwrap();
    document.add_attachment("报告.txt", b"last").unwrap();
    document
        .set_attachment_metadata(
            0,
            AttachmentMetadata {
                format: Some("text/plain".into()),
                creation_date: Some("2024-02-29T12:30:59".into()),
                mod_date: Some("2024-03-01T08:00:00".into()),
                usage: Some("Data".into()),
                ..AttachmentMetadata::default()
            },
        )
        .unwrap();
    let target = document.attachments().unwrap()[0].id.clone();
    document
        .add_attachment_link_annotation(0, &target, [2.0, 3.0, 10.0, 8.0], None)
        .unwrap();
    let bytes = document.to_pdf().unwrap();
    assert!(bytes.starts_with(b"%PDF-2.0"));
    let parsed = lopdf::Document::load_mem(&bytes).unwrap();
    let associated = parsed
        .catalog()
        .unwrap()
        .get(b"AF")
        .unwrap()
        .as_array()
        .unwrap();
    assert_eq!(associated.len(), 1);
    let associated_spec = parsed
        .get_dictionary(associated[0].as_reference().unwrap())
        .unwrap();
    assert_eq!(
        associated_spec
            .get(b"AFRelationship")
            .unwrap()
            .as_name()
            .unwrap(),
        b"Data"
    );
    let page_id = *parsed.get_pages().values().next().unwrap();
    let page = parsed.get_dictionary(page_id).unwrap();
    let annots = page.get(b"Annots").unwrap().as_array().unwrap();
    assert_eq!(annots.len(), 1);
    let annotation = parsed.dereference(&annots[0]).unwrap().1.as_dict().unwrap();
    assert_eq!(
        annotation.get(b"Subtype").unwrap().as_name().unwrap(),
        b"FileAttachment"
    );
    let linked_spec = annotation.get(b"FS").unwrap().as_reference().unwrap();
    let linked_ef = parsed
        .get_dictionary(linked_spec)
        .unwrap()
        .get(b"EF")
        .unwrap()
        .as_dict()
        .unwrap();
    let linked_file = parsed.dereference(linked_ef.get(b"F").unwrap()).unwrap().1;
    assert_eq!(linked_file.as_stream().unwrap().content, b"first");
    let names = parsed
        .catalog()
        .unwrap()
        .get(b"Names")
        .unwrap()
        .as_dict()
        .unwrap();
    let tree = names.get(b"EmbeddedFiles").unwrap().as_dict().unwrap();
    let entries = tree.get(b"Names").unwrap().as_array().unwrap();
    assert_eq!(entries.len(), 6);
    let keys: Vec<_> = entries
        .chunks_exact(2)
        .map(|pair| pair[0].as_str().unwrap().to_vec())
        .collect();
    assert!(keys.windows(2).all(|pair| pair[0] < pair[1]));
    let first_file = entries
        .chunks_exact(2)
        .map(|pair| parsed.dereference(&pair[1]).unwrap().1.as_dict().unwrap())
        .find_map(|spec| {
            let ef = spec.get(b"EF").ok()?.as_dict().ok()?;
            let stream = parsed
                .dereference(ef.get(b"F").ok()?)
                .ok()?
                .1
                .as_stream()
                .ok()?;
            (stream.content == b"first").then_some(stream)
        })
        .unwrap();
    let params = first_file.dict.get(b"Params").unwrap().as_dict().unwrap();
    assert!(params
        .get(b"CreationDate")
        .unwrap()
        .as_str()
        .unwrap()
        .starts_with(b"D:20240229123059"));
    assert!(params
        .get(b"ModDate")
        .unwrap()
        .as_str()
        .unwrap()
        .starts_with(b"D:20240301080000"));
    let imported = OfdDocument::from_pdf_bytes(&bytes).unwrap();
    assert_eq!(
        imported
            .attachments()
            .unwrap()
            .iter()
            .map(|item| item.name.as_str())
            .collect::<Vec<_>>(),
        ["a.txt", "报告.txt", "报告.txt"]
    );
    assert_eq!(imported.attachment_data(0).unwrap(), b"middle");
    assert_eq!(imported.attachment_data(1).unwrap(), b"first");
    assert_eq!(imported.attachment_data(2).unwrap(), b"last");
    let metadata = &imported.attachments().unwrap()[1];
    assert_eq!(metadata.format.as_deref(), Some("text/plain"));
    assert_eq!(
        metadata.creation_date.as_deref(),
        Some("2024-02-29T12:30:59")
    );
    assert_eq!(metadata.mod_date.as_deref(), Some("2024-03-01T08:00:00"));
    assert_eq!(metadata.usage, "Data");
    let linked = imported.annotations().unwrap();
    assert_eq!(linked.len(), 1);
    assert_eq!(linked[0].actions[0].kind, "GotoA");
    assert_eq!(linked[0].actions[0].attributes["AttachID"], metadata.id);
    assert!(imported.validate_references().unwrap().is_empty());

    let mut invalid = lopdf::Document::load_mem(&bytes).unwrap();
    let file = invalid
        .catalog()
        .unwrap()
        .get(b"Names")
        .unwrap()
        .as_dict()
        .unwrap()
        .get(b"EmbeddedFiles")
        .unwrap()
        .as_dict()
        .unwrap()
        .get(b"Names")
        .unwrap()
        .as_array()
        .unwrap()[1]
        .as_reference()
        .unwrap();
    let file = invalid
        .get_object(file)
        .unwrap()
        .as_dict()
        .unwrap()
        .get(b"EF")
        .unwrap()
        .as_dict()
        .unwrap()
        .get(b"F")
        .unwrap()
        .as_reference()
        .unwrap();
    invalid
        .get_object_mut(file)
        .unwrap()
        .as_stream_mut()
        .unwrap()
        .dict
        .set("Params", lopdf::dictionary! {"Size" => 999});
    let mut corrupt = Vec::new();
    invalid.save_to(&mut corrupt).unwrap();
    assert!(matches!(
        OfdDocument::from_pdf_bytes(&corrupt),
        Err(OfdError::Invalid(message)) if message.contains("Size does not match")
    ));
}

#[test]
fn exports_pdf_associated_file_with_mime_fallback() {
    let mut document = OfdDocument::new();
    document.add_blank_page(20.0, 20.0).unwrap();
    document.add_attachment("source.bin", b"payload").unwrap();
    document
        .set_attachment_metadata(
            0,
            AttachmentMetadata {
                usage: Some("Source".into()),
                ..AttachmentMetadata::default()
            },
        )
        .unwrap();
    let bytes = document.to_pdf().unwrap();
    assert!(bytes.starts_with(b"%PDF-2.0"));
    let pdf = lopdf::Document::load_mem(&bytes).unwrap();
    let spec = pdf
        .catalog()
        .unwrap()
        .get(b"AF")
        .unwrap()
        .as_array()
        .unwrap()[0]
        .as_reference()
        .unwrap();
    let spec = pdf.get_dictionary(spec).unwrap();
    assert_eq!(
        spec.get(b"AFRelationship").unwrap().as_name().unwrap(),
        b"Source"
    );
    let file = pdf
        .dereference(
            spec.get(b"EF")
                .unwrap()
                .as_dict()
                .unwrap()
                .get(b"F")
                .unwrap(),
        )
        .unwrap()
        .1;
    assert_eq!(
        file.as_stream()
            .unwrap()
            .dict
            .get(b"Subtype")
            .unwrap()
            .as_name()
            .unwrap(),
        b"application/octet-stream"
    );
    let imported = OfdDocument::from_pdf_bytes(&bytes).unwrap();
    assert_eq!(imported.attachments().unwrap()[0].usage, "Source");
    assert_eq!(imported.attachment_data(0).unwrap(), b"payload");
}

#[test]
fn exports_java_ofd_attachment_to_pdf_without_losing_payload() {
    let document = OfdDocument::open(fixture("AddAttachment.ofd")).unwrap();
    let originals = document.attachments().unwrap();
    assert!(!originals.is_empty());
    let payloads = (0..originals.len())
        .map(|index| document.attachment_data(index).unwrap().to_vec())
        .collect::<Vec<_>>();
    let pdf = document.to_pdf().unwrap();
    let parsed = lopdf::Document::load_mem(&pdf).unwrap();
    assert!(parsed.catalog().unwrap().has(b"Names"));
    let imported = OfdDocument::from_pdf_bytes(&pdf).unwrap();
    let names = imported.attachments().unwrap();
    assert_eq!(names.len(), originals.len());
    for (index, original) in originals.iter().enumerate() {
        assert_eq!(names[index].name, original.name);
        assert_eq!(imported.attachment_data(index).unwrap(), payloads[index]);
    }
    assert!(imported.validate_references().unwrap().is_empty());
}

