    assert!(svg.contains("gradientTransform=\"matrix("));
    let image = resvg::tiny_skia::Pixmap::decode_png(&document.page_png(0, 25.4).unwrap()).unwrap();
    let horizontal = image.pixel(19, 15).unwrap();
    let vertical = image.pixel(15, 19).unwrap();
