#[test]
fn inherited_draw_param_ignores_extension_color_lookalikes() {
    let mut document = OfdDocument::new();
    document
        .add_path_page(
            "M 0 0 L 20 0 L 20 20 L 0 20 C",
            [0.0, 0.0, 20.0, 20.0],
            20.0,
            20.0,
            true,
            false,
        )
        .unwrap();
    let id = document.page_paths(0).unwrap()[0].id.clone().unwrap();
    let base = document
        .add_document_draw_param(
            0,
            &DrawParamStyle {
                fill: Some(SolidPaintStyle {
                    color: [255, 0, 0],
                    alpha: 255,
                }),
                ..DrawParamStyle::default()
            },
        )
        .unwrap();
    let derived = document
        .add_document_draw_param(
            0,
            &DrawParamStyle {
                relative: Some(base.clone()),
                ..DrawParamStyle::default()
            },
        )
        .unwrap();
    document
        .set_page_object_draw_param(0, &id, Some(&derived))
        .unwrap();
    let expected = document.page_svg(0).unwrap();
    assert!(expected.contains("fill=\"#ff0000\""));
    let path = "Doc_0/PublicRes.xml";
    let source = std::str::from_utf8(document.entry(path).unwrap().unwrap()).unwrap();
    let parsed = roxmltree::Document::parse(source).unwrap();
    let target = parsed
        .descendants()
        .find(|node| {
            node.is_element()
                && node.tag_name().name() == "DrawParam"
                && node.attribute("ID") == Some(derived.as_str())
        })
        .unwrap();
    let markup = &source[target.range()];
    let extension = "<x:FillColor xmlns:x=\"urn:example:extension\" Value=\"0 0 255\"/>";
    let replacement = if let Some(stripped) = markup.strip_suffix("/>") {
        format!("{stripped}>{extension}</ofd:DrawParam>")
    } else {
        let closing = markup.rfind("</ofd:DrawParam>").unwrap();
        format!("{}{extension}{}", &markup[..closing], &markup[closing..])
    };
    document
        .set_entry(path, source.replace(markup, &replacement).into_bytes())
        .unwrap();
    assert_eq!(document.page_svg(0).unwrap(), expected);
    let page_path = document.pages().unwrap()[0].path.clone();
    let page = std::str::from_utf8(document.entry(&page_path).unwrap().unwrap()).unwrap();
    assert!(page.contains("<ofd:AbbreviatedData>"));
    document
        .set_entry(
            &page_path,
            page.replacen(
                "<ofd:AbbreviatedData>",
                &format!("{extension}<ofd:AbbreviatedData>"),
                1,
            )
            .into_bytes(),
        )
        .unwrap();
    assert_eq!(document.page_svg(0).unwrap(), expected);
    assert_eq!(
        document.page_object_paints(0).unwrap()[0]
            .effective_fill_draw_param
            .as_deref(),
        Some(base.as_str())
    );
}

