#[test]
fn text_deltas_control_svg_positions_and_reject_invalid_encoding() {
    let mut document = OfdDocument::new();
    document.add_text_page("ABC", 40.0, 20.0).unwrap();
    let path = document.pages().unwrap()[0].path.clone();
    let original = std::str::from_utf8(document.entry(&path).unwrap().unwrap())
        .unwrap()
        .to_owned();
    let changed = without_first_text_code_delta_x(&original).replace(
        "<ofd:TextCode X=\"0\" Y=\"5\">ABC</ofd:TextCode>",
        "<ofd:TextCode X=\"0\" Y=\"5\" DeltaX=\"g 2 4\" DeltaY=\"1 2\">ABC</ofd:TextCode>",
    );
    assert_ne!(changed, original);
    document
        .set_entry(&path, changed.clone().into_bytes())
        .unwrap();
    let svg = document.page_svg(0).unwrap();
    assert!(svg.contains("<text x=\"0 4 8\" y=\"5 6 8\""));
    assert!(document.page_png(0, 25.4).unwrap().starts_with(b"\x89PNG"));
    assert!(document.to_pdf().unwrap().starts_with(b"%PDF-"));

    document
        .set_entry(&path, changed.replace("g 2 4", "g bad 4").into_bytes())
        .unwrap();
    assert!(matches!(document.page_svg(0), Err(OfdError::Invalid(_))));
    assert!(document.page_png(0, 25.4).is_err());
    assert!(document.to_pdf().is_err());
}

#[test]
fn omitted_text_deltas_keep_glyphs_at_the_same_origin() {
    let mut document = OfdDocument::new();
    document.add_text_page("ABC", 40.0, 20.0).unwrap();
    let path = document.pages().unwrap()[0].path.clone();
    let source = std::str::from_utf8(document.entry(&path).unwrap().unwrap()).unwrap();
    let written_delta = document.page_text_objects(0).unwrap()[0].codes[0]
        .delta_x
        .clone()
        .unwrap();
    assert_eq!(written_delta.split_whitespace().count(), 2);
    let normal = document.page_svg(0).unwrap();
    assert!(!normal.contains("<text x=\"0 0 0\""));

    let without_delta = without_first_text_code_delta_x(source);
    document
        .set_entry(&path, without_delta.into_bytes())
        .unwrap();
    let overlapping = document.page_svg(0).unwrap();
    assert!(overlapping.contains("<text x=\"0 0 0\" y=\"5 5 5\""));
    assert_eq!(document.page_text(0).unwrap(), ["ABC"]);
}

#[test]
fn validation_reports_invalid_text_positions_before_rendering() {
    let mut document = OfdDocument::new();
    document.add_text_page("ABC", 40.0, 20.0).unwrap();
    let path = document.pages().unwrap()[0].path.clone();
    let original = std::str::from_utf8(document.entry(&path).unwrap().unwrap())
        .unwrap()
        .to_owned();
    let delta = document.page_text_objects(0).unwrap()[0].codes[0]
        .delta_x
        .clone()
        .unwrap();

    for invalid in [
        original.replace(&format!("DeltaX=\"{delta}\""), "DeltaX=\"g bad 2\""),
        original.replace("Size=\"5\"", "Size=\"0\""),
        original.replace("X=\"0\"", "X=\"NaN\""),
    ] {
        document.set_entry(&path, invalid.into_bytes()).unwrap();
        let issues = document.validate_references().unwrap();
        assert!(
            issues
                .iter()
                .any(|issue| { issue.path == path && issue.code == "invalid_text_position" }),
            "{issues:?}"
        );
        assert!(document.page_svg(0).is_err());
    }
    document.set_entry(&path, original.into_bytes()).unwrap();
    assert!(document.validate_references().unwrap().is_empty());
}

#[test]
fn validation_requires_first_text_code_coordinates_and_content() {
    let mut document = OfdDocument::new();
    document.add_text_page("AB", 30.0, 20.0).unwrap();
    let path = document.pages().unwrap()[0].path.clone();
    let original = std::str::from_utf8(document.entry(&path).unwrap().unwrap())
        .unwrap()
        .to_owned();
    let start = original.find("<ofd:TextCode").unwrap();
    let end = start + original[start..].find("</ofd:TextCode>").unwrap() + "</ofd:TextCode>".len();
    let mut no_code = original.clone();
    no_code.replace_range(start..end, "");
    for invalid in [
        original.replace(" X=\"0\"", ""),
        original.replace(" Y=\"5\"", ""),
        no_code,
    ] {
        document.set_entry(&path, invalid.into_bytes()).unwrap();
        assert!(document
            .validate_references()
            .unwrap()
            .iter()
            .any(|issue| issue.path == path && issue.code == "invalid_text_position"));
    }
    document.set_entry(&path, original.into_bytes()).unwrap();
    assert!(document.validate_references().unwrap().is_empty());
}

#[test]
fn validation_checks_text_positions_in_template_composite_and_annotation() {
    let check = |mut document: OfdDocument, path: String, issue_path: String| {
        let original = std::str::from_utf8(document.entry(&path).unwrap().unwrap())
            .unwrap()
            .to_owned();
        let start = original.find("DeltaX=\"").unwrap();
        let end = start + 8 + original[start + 8..].find('"').unwrap() + 1;
        let mut invalid = original;
        invalid.replace_range(start..end, "DeltaX=\"bad\"");
        document.set_entry(&path, invalid.into_bytes()).unwrap();
        let issues = document.validate_references().unwrap();
        assert!(
            issues
                .iter()
                .any(|issue| { issue.path == issue_path && issue.code == "invalid_text_position" }),
            "{path}: {issues:?}"
        );
    };

    let mut template = OfdDocument::new();
    template.add_text_page("AB", 30.0, 20.0).unwrap();
    template
        .promote_page_to_template(0, &[], "Background")
        .unwrap();
    let template_path = template.page_sources(0).unwrap()[0].path.clone();
    check(template, template_path.clone(), template_path);

    let mut composite = OfdDocument::new();
    composite.add_blank_page(30.0, 20.0).unwrap();
    composite
        .add_composite_text_object(0, "AB", [2.0, 2.0, 20.0, 8.0], 5.0, None)
        .unwrap();
    let composite_path = composite
        .entry_names()
        .find(|name| {
            composite.entry(name).ok().flatten().is_some_and(|bytes| {
                bytes
                    .windows(b"<ofd:CompositeGraphicUnit".len())
                    .any(|window| window == b"<ofd:CompositeGraphicUnit")
            })
        })
        .unwrap()
        .to_owned();
    let page_path = composite.pages().unwrap()[0].path.clone();
    check(composite, composite_path, page_path);

    let mut annotated = OfdDocument::new();
    annotated.add_blank_page(30.0, 20.0).unwrap();
    annotated
        .add_text_watermark(0, "AB", [0.0, 0.0, 30.0, 20.0], 5.0)
        .unwrap();
    let annotation_path = annotated.annotations().unwrap()[0].source_path.clone();
    check(annotated, annotation_path.clone(), annotation_path);
}

#[test]
fn validation_reports_invalid_text_typography_and_glyph_mapping() {
    let mut document = OfdDocument::new();
    document.add_text_page("AB", 30.0, 20.0).unwrap();
    let path = document.pages().unwrap()[0].path.clone();
    let original = std::str::from_utf8(document.entry(&path).unwrap().unwrap())
        .unwrap()
        .to_owned();
    for attribute in [
        "ReadDirection=\"45\"",
        "CharDirection=\"45\"",
        "HScale=\"0\"",
        "Weight=\"950\"",
        "Italic=\"yes\"",
    ] {
        let modified = original.replace(" Size=\"5\"", &format!(" Size=\"5\" {attribute}"));
        document.set_entry(&path, modified.into_bytes()).unwrap();
        assert!(
            document
                .validate_references()
                .unwrap()
                .iter()
                .any(|issue| issue.path == path && issue.code == "invalid_text_typography"),
            "{attribute}"
        );
    }
    let mapping = "<ofd:CGTransform CodePosition=\"1\" CodeCount=\"2\" GlyphCount=\"1\"><ofd:Glyphs>1</ofd:Glyphs></ofd:CGTransform>";
    let modified = original.replace("</ofd:TextObject>", &format!("{mapping}</ofd:TextObject>"));
    document.set_entry(&path, modified.into_bytes()).unwrap();
    let issues = document.validate_references().unwrap();
    assert!(issues
        .iter()
        .any(|issue| issue.path == path && issue.code == "invalid_cg_transform"));
    document.set_entry(&path, original.into_bytes()).unwrap();
    assert!(document.validate_references().unwrap().is_empty());
}

#[test]
fn text_writers_emit_positions_for_multiple_characters() {
    let mut document = OfdDocument::new();
    document.add_blank_page(80.0, 50.0).unwrap();
    document
        .add_text_object(0, "ABC", [10.0, 10.0, 30.0, 8.0], 5.0, None)
        .unwrap();
    document
        .add_composite_text_object(0, "ABC", [10.0, 20.0, 30.0, 8.0], 5.0, None)
        .unwrap();
    document
        .add_text_watermark(0, "ABC", [0.0, 0.0, 80.0, 50.0], 5.0)
        .unwrap();
    document.add_text_page("ABC", 80.0, 50.0).unwrap();

    let page_text = document.page_text_objects(0).unwrap();
    assert_eq!(
        page_text[0].codes[0]
            .delta_x
            .as_deref()
            .unwrap()
            .split_whitespace()
            .count(),
        2
    );
    assert_eq!(
        document.page_text_objects(1).unwrap()[0].codes[0]
            .delta_x
            .as_deref()
            .unwrap()
            .split_whitespace()
            .count(),
        2
    );
    let archive = document.to_bytes().unwrap();
    let reopened = OfdDocument::from_bytes(&archive).unwrap();
    assert!(reopened.validate_references().unwrap().is_empty());
    let xml = reopened
        .entry_names()
        .filter_map(|name| reopened.entry(name).ok().flatten())
        .filter_map(|bytes| std::str::from_utf8(bytes).ok())
        .collect::<Vec<_>>()
        .join("\n");
    assert!(xml.matches("<ofd:TextCode X=\"0\" Y=\"5\" DeltaX=").count() >= 4);
    assert!(reopened.page_png(0, 25.4).unwrap().starts_with(b"\x89PNG"));
}

#[test]
fn pattern_text_writers_emit_positions() {
    let mut document = OfdDocument::new();
    document.add_blank_page(40.0, 40.0).unwrap();
    let object_id = document
        .add_path_object(
            0,
            "M 0 0 L 20 0 L 20 20 C",
            [0.0, 0.0, 20.0, 20.0],
            PathStyle::default(),
        )
        .unwrap();
    let pattern = PatternStyle {
        width: 10.0,
        height: 10.0,
        x_step: None,
        y_step: None,
        reflect: PatternReflectMethod::Normal,
        relative_to: PatternRelativeTo::Object,
        ctm: None,
        alpha: None,
        thumbnail: None,
        cells: vec![PatternCell::Text {
            text: "AB".into(),
            boundary: [0.0, 0.0, 10.0, 10.0],
            size: 5.0,
            font_id: None,
        }],
    };
    document
        .set_page_object_pattern_fill(0, &object_id, &pattern)
        .unwrap();
    let page = document.pages().unwrap()[0].path.clone();
    let xml = std::str::from_utf8(document.entry(&page).unwrap().unwrap()).unwrap();
    assert!(xml.contains("<ofd:TextCode X=\"0\" Y=\"5\" DeltaX="));
    document
        .add_document_draw_param(
            0,
            &DrawParamStyle {
                fill_pattern: Some(pattern),
                ..DrawParamStyle::default()
            },
        )
        .unwrap();
    assert!(document
        .entry_names()
        .filter_map(|name| document.entry(name).ok().flatten())
        .filter_map(|bytes| std::str::from_utf8(bytes).ok())
        .any(|xml| xml.contains("<ofd:DrawParam")
            && xml.contains("<ofd:TextCode X=\"0\" Y=\"5\" DeltaX=")));
    assert!(document.validate_references().unwrap().is_empty());
}

#[test]
fn svg_preview_rejects_invalid_geometry_and_path_commands() {
    let mut document = OfdDocument::new();
    document.add_text_page("page", 210.0, 297.0).unwrap();
    let path = "Doc_0/Pages/Page_0/Content.xml";
    let original = std::str::from_utf8(document.entry(path).unwrap().unwrap())
        .unwrap()
        .to_owned();
    document
        .set_entry(
            path,
            original.replace("0 0 210 297", "0 0 0 297").into_bytes(),
        )
        .unwrap();
    assert!(matches!(document.page_svg(0), Err(OfdError::Invalid(_))));
    document
        .set_entry(
            path,
            original
                .replace("Font=\"1\"", "Font=\"1\" CTM=\"bad\"")
                .into_bytes(),
        )
        .unwrap();
    assert!(matches!(document.page_svg(0), Err(OfdError::Invalid(_))));
    document.set_entry(path, original.into_bytes()).unwrap();
    document
        .add_path_page("M 1 2", [0.0, 0.0, 10.0, 10.0], 210.0, 297.0, false, true)
        .unwrap();
    let path = document.pages().unwrap()[1].path.clone();
    let xml = std::str::from_utf8(document.entry(&path).unwrap().unwrap()).unwrap();
    document
        .set_entry(&path, xml.replace("M 1 2", "CM 1 2").into_bytes())
        .unwrap();
    assert!(matches!(document.page_svg(1), Err(OfdError::Invalid(_))));
}

#[test]
fn inserts_bookmark_into_existing_document_without_list_or_with_empty_list() {
    let source = OfdDocument::open(fixture("helloworld.ofd")).unwrap();
    let bytes = source.to_bytes().unwrap();
    let destination = ofdrw::DestinationInfo {
        page_id: source.pages().unwrap()[0].id.clone(),
        kind: "Fit".into(),
        left: None,
        top: None,
        right: None,
        bottom: None,
        zoom: None,
    };
    let mut without_list = OfdDocument::from_bytes(&bytes).unwrap();
    without_list
        .add_bookmark(0, "No list", destination.clone())
        .unwrap();
    assert_eq!(without_list.bookmarks().unwrap()[0].name, "No list");

    let mut empty_list = OfdDocument::from_bytes(&bytes).unwrap();
    let path = "Doc_0/Document.xml";
    let xml = std::str::from_utf8(empty_list.entry(path).unwrap().unwrap()).unwrap();
    let closing = "</ofd:Document>";
    assert!(xml.contains(closing));
    empty_list
        .set_entry(
            path,
            xml.replace(closing, &format!("<ofd:Bookmarks/>{closing}"))
                .into_bytes(),
        )
        .unwrap();
    empty_list
        .add_bookmark(0, "Empty list", destination)
        .unwrap();
    let reopened = OfdDocument::from_bytes(&empty_list.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.bookmarks().unwrap()[0].name, "Empty list");
}

#[test]
fn reads_signature_description_and_opaque_data() {
    let document = OfdDocument::open(fixture("SESV4SignDoc.ofd")).unwrap();
    let signatures = document.signatures().unwrap();
    assert_eq!(signatures.len(), 1);
    let signature = &signatures[0];
    assert_eq!(signature.document_index, 0);
    assert_eq!(signature.id, "1");
    assert_eq!(signature.signature_type.as_deref(), Some("Seal"));
    assert_eq!(signature.provider_name.as_deref(), Some("ofdrw-sign"));
    assert_eq!(signature.check_method.as_deref(), Some("SM3"));
    assert_eq!(signature.references.len(), 5);
    assert_eq!(signature.references[0].path, "OFD.xml");
    assert_eq!(signature.stamps.len(), 1);
    assert_eq!(signature.stamps[0].page_ref, "1");
    assert_eq!(signature.stamps[0].boundary, Some([50.0, 50.0, 40.0, 40.0]));
    assert_eq!(document.signed_value_data(0).unwrap().len(), 17_726);
    assert_eq!(document.seal_data(0).unwrap().len(), 17_011);
    let checks = document.check_signature_references(0).unwrap();
    assert_eq!(checks.len(), 5);
    assert!(checks.iter().all(|check| check.valid));
    assert!(document.signed_value_data(1).is_err());
    assert!(document.seal_data(1).is_err());
    assert!(OfdDocument::open(fixture("helloworld.ofd"))
        .unwrap()
        .signatures()
        .unwrap()
        .is_empty());
}

#[test]
fn detects_modified_signed_file_and_supports_sha256() {
    let mut document = OfdDocument::open(fixture("SESV4SignDoc.ofd")).unwrap();
    let path = "Doc_0/PublicRes.xml";
    let mut changed = document.entry(path).unwrap().unwrap().to_vec();
    changed.push(b'\n');
    document.set_entry(path, changed).unwrap();
    let checks = document.check_signature_references(0).unwrap();
    assert_eq!(checks.iter().filter(|check| !check.valid).count(), 1);
    assert_eq!(checks[1].path, path);
    assert!(!checks[1].valid);

    let description_path = "Doc_0/Signs/Sign_0/Signature.xml";
    let description = b"<Signature><SignedValue>SignedValue.dat</SignedValue><SignedInfo>\
        <References CheckMethod=\"SHA256\"><Reference FileRef=\"/OFD.xml\">\
        <CheckValue>lFG5JS5zARjZ IPBZPFrHpVkVmuLs2lMsq6IipRoA0f4=</CheckValue>\
        </Reference></References></SignedInfo></Signature>";
    document
        .set_entry(description_path, description.to_vec())
        .unwrap();
    assert!(document.check_signature_references(0).unwrap()[0].valid);
    let unsupported = String::from_utf8(description.to_vec())
        .unwrap()
        .replace("SHA256", "MD5");
    document
        .set_entry(description_path, unsupported.into_bytes())
        .unwrap();
    assert!(matches!(
        document.check_signature_references(0),
        Err(OfdError::Invalid(_))
    ));
}

#[test]
fn checks_sm3_signature_reference_with_xml_base64_whitespace() {
    let mut document = OfdDocument::open(fixture("SESV4SignDoc.ofd")).unwrap();
    let signature = document.signatures().unwrap().remove(0);
    let first = &signature.references[0].check_value;
    let wrapped = format!("{}\n\t{}", &first[..20], &first[20..]);
    let source = std::str::from_utf8(document.entry(&signature.path).unwrap().unwrap()).unwrap();
    let modified = source.replacen(first, &wrapped, 1);
    assert_ne!(modified, source);
    document
        .set_entry(&signature.path, modified.as_bytes().to_vec())
        .unwrap();
    let checks = document.check_signature_references(0).unwrap();
    assert!(checks.iter().all(|check| check.valid));
    assert_eq!(checks[0].expected, wrapped);

    let malformed = modified.replacen(&wrapped, "?", 1);
    document
        .set_entry(&signature.path, malformed.into_bytes())
        .unwrap();
    let checks = document.check_signature_references(0).unwrap();
    assert!(!checks[0].valid);
    assert!(checks.iter().skip(1).all(|check| check.valid));
}

#[test]
fn checks_signature_reference_split_across_xml_text_nodes() {
    let mut document = OfdDocument::open(fixture("SESV4SignDoc.ofd")).unwrap();
    let signature = document.signatures().unwrap().remove(0);
    let value = &signature.references[0].check_value;
    let markup = format!(
        "{}<![CDATA[{}]]><!-- digest -->{}",
        &value[..10],
        &value[10..25],
        &value[25..]
    );
    let source = std::str::from_utf8(document.entry(&signature.path).unwrap().unwrap()).unwrap();
    assert!(source.contains("SignedValue.dat"));
    let modified = source.replacen(value, &markup, 1).replacen(
        "SignedValue.dat",
        "Signed<!-- path -->Value.dat",
        1,
    );
    assert_ne!(modified, source);
    document
        .set_entry(&signature.path, modified.into_bytes())
        .unwrap();
    let reopened_signature = document.signatures().unwrap().remove(0);
    assert_eq!(reopened_signature.references[0].check_value, *value);
    assert_eq!(
        reopened_signature.signed_value_path,
        signature.signed_value_path
    );
    assert_eq!(document.signed_value_data(0).unwrap().len(), 17_726);
    assert!(document.check_signature_references(0).unwrap()[0].valid);
}

