#[test]
fn reads_resource_paths_split_across_xml_text_nodes() {
    let mut document = OfdDocument::new();
    document.add_blank_page(80.0, 60.0).unwrap();
    let root = "Doc_0/Document.xml";
    let source = std::str::from_utf8(document.entry(root).unwrap().unwrap()).unwrap();
    let modified = source.replacen("PublicRes.xml", "Public<!-- split -->Res.xml", 1);
    assert_ne!(modified, source);
    document.set_entry(root, modified.into_bytes()).unwrap();
    let public_path = "Doc_0/PublicRes.xml";
    let resources = std::str::from_utf8(document.entry(public_path).unwrap().unwrap()).unwrap();
    let modified = resources.replace(
        "</ofd:Fonts>",
        "<ofd:Font ID=\"2\" FontName=\"Public\"/></ofd:Fonts>",
    );
    assert_ne!(modified, resources);
    document
        .set_entry(public_path, modified.into_bytes())
        .unwrap();
    assert!(document
        .fonts()
        .unwrap()
        .iter()
        .any(|font| font.font_name == "Public"));

    let page_path = document.pages().unwrap()[0].path.clone();
    let page = std::str::from_utf8(document.entry(&page_path).unwrap().unwrap()).unwrap();
    let modified = page.replace(
        "</ofd:Page>",
        "<ofd:PageRes>Page<!-- split -->Res.xml</ofd:PageRes></ofd:Page>",
    );
    assert_ne!(modified, page);
    document
        .set_entry(&page_path, modified.into_bytes())
        .unwrap();
    let page_res_path = format!("{}/PageRes.xml", page_path.rsplit_once('/').unwrap().0);
    document.set_entry(&page_res_path, b"<ofd:Res xmlns:ofd=\"http://www.ofdspec.org/2016\"><ofd:Fonts><ofd:Font ID=\"3\" FontName=\"Page\"/></ofd:Fonts></ofd:Res>".to_vec()).unwrap();
    let fonts = document.page_fonts(0).unwrap();
    assert_eq!(fonts[0].font_name, "Page");
    assert!(fonts.iter().any(|font| font.font_name == "Public"));
}

