#[test]
fn reserves_signature_ids_from_split_max_sign_id() {
    let key = include_bytes!("fixtures/user-private-key.bin");
    let mut document = OfdDocument::new();
    document.add_text_page("signed", 40.0, 30.0).unwrap();
    document
        .add_digital_signature(key, "2030-01-01 00:00:00")
        .unwrap();
    let index = "Doc_0/Signs/Signatures.xml";
    let xml = std::str::from_utf8(document.entry(index).unwrap().unwrap()).unwrap();
    let changed = xml.replacen(
        "<ofd:MaxSignId>s001</ofd:MaxSignId>",
        "<ofd:MaxSignId>s0<!-- split -->10</ofd:MaxSignId>",
        1,
    );
    assert_ne!(changed, xml);
    document.set_entry(index, changed.into_bytes()).unwrap();
    document
        .add_digital_signature(key, "2030-01-02 00:00:00")
        .unwrap();
    let signatures = document.signatures().unwrap();
    assert_eq!(signatures.len(), 2);
    assert_eq!(signatures[1].id, "s011");
    assert!(document
        .check_signature_references(0)
        .unwrap()
        .iter()
        .all(|check| check.valid));
    assert!(document
        .check_signature_references(1)
        .unwrap()
        .iter()
        .all(|check| check.valid));
}

