#[test]
fn edits_attachments_through_split_list_link() {
    let mut source = OfdDocument::new();
    source.add_attachment("first.txt", b"original").unwrap();
    let root = "Doc_0/Document.xml";
    let xml = std::str::from_utf8(source.entry(root).unwrap().unwrap()).unwrap();
    let path = xml
        .split("<ofd:Attachments>")
        .nth(1)
        .unwrap()
        .split("</ofd:Attachments>")
        .next()
        .unwrap();
    let split = format!("{}<!-- split -->{}", &path[..3], &path[3..]);
    let changed = xml.replacen(
        &format!("<ofd:Attachments>{path}</ofd:Attachments>"),
        &format!("<ofd:Attachments>{split}</ofd:Attachments>"),
        1,
    );
    source.set_entry(root, changed.into_bytes()).unwrap();
    assert_eq!(source.attachments().unwrap().len(), 1);

    let mut renamed = source.clone();
    renamed.rename_attachment(0, "renamed.txt").unwrap();
    assert_eq!(renamed.attachments().unwrap()[0].name, "renamed.txt");

    let mut replaced = source.clone();
    replaced.replace_attachment_data(0, b"replacement").unwrap();
    assert_eq!(replaced.attachment_data(0).unwrap(), b"replacement");

    let mut metadata = source.clone();
    metadata
        .set_attachment_metadata(
            0,
            AttachmentMetadata {
                format: Some("text/plain".into()),
                ..AttachmentMetadata::default()
            },
        )
        .unwrap();
    assert_eq!(
        metadata.attachments().unwrap()[0].format.as_deref(),
        Some("text/plain")
    );

    let mut removed = source;
    removed.remove_attachment(0).unwrap();
    assert!(removed.attachments().unwrap().is_empty());
}

#[test]
fn edits_extensions_through_split_links() {
    let mut source = OfdDocument::new();
    source
        .set_entry("Doc_0/Ext/data.bin", b"extension data".to_vec())
        .unwrap();
    let extension = |name: &str| ExtensionInfo {
        document_index: 0,
        app_name: name.into(),
        company: None,
        app_version: None,
        date: None,
        ref_id: None,
        properties: Vec::new(),
        extend_data_paths: vec!["Doc_0/Ext/data.bin".into()],
        data_xml: Vec::new(),
    };
    source.add_document_extension(&extension("first")).unwrap();
    let root = "Doc_0/Document.xml";
    let xml = std::str::from_utf8(source.entry(root).unwrap().unwrap()).unwrap();
    let xml = xml.replace(
        "<ofd:Extensions>Extensions_1.xml</ofd:Extensions>",
        "<ofd:Extensions>Ext<!-- split -->ensions_1.xml</ofd:Extensions>",
    );
    assert!(xml.contains("Ext<!-- split -->ensions_1.xml"));
    source.set_entry(root, xml.into_bytes()).unwrap();
    let list_path = "Doc_0/Extensions_1.xml";
    let xml = std::str::from_utf8(source.entry(list_path).unwrap().unwrap()).unwrap();
    let xml = xml.replace(
        "<ofd:ExtendData>/Doc_0/Ext/data.bin</ofd:ExtendData>",
        "<ofd:ExtendData>/Doc_0/<!-- split -->Ext/data.bin</ofd:ExtendData>",
    );
    assert!(xml.contains("/Doc_0/<!-- split -->Ext/data.bin"));
    source.set_entry(list_path, xml.into_bytes()).unwrap();
    assert_eq!(source.extensions().unwrap()[0].app_name, "first");

    let mut updated = source.clone();
    updated
        .update_document_extension(0, &extension("updated"))
        .unwrap();
    assert_eq!(updated.extensions().unwrap()[0].app_name, "updated");

    let mut appended = source.clone();
    appended
        .add_document_extension(&extension("second"))
        .unwrap();
    assert_eq!(appended.extensions().unwrap().len(), 2);

    let mut removed = source;
    removed.remove_document_extension(0).unwrap();
    assert!(removed.extensions().unwrap().is_empty());
}

#[test]
fn edits_custom_tags_through_split_links() {
    let mut source = OfdDocument::new();
    source
        .set_entry("Doc_0/Tags/schema.xsd", b"schema".to_vec())
        .unwrap();
    source
        .add_custom_tag_to_document(0, "first", None, Some("Doc_0/Tags/schema.xsd"), b"<First/>")
        .unwrap();
    let root = "Doc_0/Document.xml";
    let xml = std::str::from_utf8(source.entry(root).unwrap().unwrap()).unwrap();
    let xml = xml.replace(
        "<ofd:CustomTags>CustomTags_1.xml</ofd:CustomTags>",
        "<ofd:CustomTags>Custom<![CDATA[Tags_1]]>.xml</ofd:CustomTags>",
    );
    assert!(xml.contains("Custom<![CDATA[Tags_1]]>.xml"));
    source.set_entry(root, xml.into_bytes()).unwrap();
    let list_path = "Doc_0/CustomTags_1.xml";
    let xml = std::str::from_utf8(source.entry(list_path).unwrap().unwrap()).unwrap();
    let xml = xml
        .replace(
            "<ofd:SchemaLoc>/Doc_0/Tags/schema.xsd</ofd:SchemaLoc>",
            "<ofd:SchemaLoc>/Doc_0/Tags/<!-- split -->schema.xsd</ofd:SchemaLoc>",
        )
        .replace(
            "<ofd:FileLoc>/Doc_0/Tags/CustomTag_1.xml</ofd:FileLoc>",
            "<ofd:FileLoc>/Doc_0/Tags/<!-- split -->CustomTag_1.xml</ofd:FileLoc>",
        );
    assert!(xml.contains("/Doc_0/Tags/<!-- split -->schema.xsd"));
    assert!(xml.contains("/Doc_0/Tags/<!-- split -->CustomTag_1.xml"));
    source.set_entry(list_path, xml.into_bytes()).unwrap();
    assert_eq!(source.custom_tags().unwrap()[0].type_id, "first");

    let mut updated = source.clone();
    updated.update_custom_tag(0, "updated", None, None).unwrap();
    assert_eq!(updated.custom_tags().unwrap()[0].type_id, "updated");

    let mut replaced = source.clone();
    replaced.replace_custom_tag_data(0, b"<New/>").unwrap();
    assert_eq!(replaced.custom_tag_data(0).unwrap(), b"<New/>");

    let mut appended = source.clone();
    appended
        .add_custom_tag_to_document(0, "second", None, None, b"<Second/>")
        .unwrap();
    assert_eq!(appended.custom_tags().unwrap().len(), 2);

    let mut removed = source;
    removed.remove_custom_tag(0).unwrap();
    assert!(removed.custom_tags().unwrap().is_empty());
}

#[test]
fn reads_and_replaces_multimedia_through_split_media_file() {
    let mut created = OfdDocument::new();
    created.add_blank_page(10.0, 10.0).unwrap();
    let png = created.page_png(0, 25.4).unwrap();
    let id = created
        .add_multimedia_resource(0, "Image", "PNG", &png)
        .unwrap();
    let mut document = OfdDocument::from_bytes(&created.to_bytes().unwrap()).unwrap();
    let resource_path = "Doc_0/DocumentRes.xml";
    let xml = std::str::from_utf8(document.entry(resource_path).unwrap().unwrap()).unwrap();
    let location = xml
        .split("<ofd:MediaFile>")
        .nth(1)
        .unwrap()
        .split("</ofd:MediaFile>")
        .next()
        .unwrap();
    let split = format!("{}<!-- split -->{}", &location[..2], &location[2..]);
    let changed = xml.replacen(
        &format!("<ofd:MediaFile>{location}</ofd:MediaFile>"),
        &format!("<ofd:MediaFile>{split}</ofd:MediaFile>"),
        1,
    );
    assert!(changed.contains(&split));
    document
        .set_entry(resource_path, changed.into_bytes())
        .unwrap();

    let resources = document.document_multimedia_resources(0).unwrap();
    assert_eq!(resources.len(), 1);
    assert_eq!(resources[0].id, id);
    assert_eq!(document.document_multimedia_data(0, &id).unwrap(), png);
    assert_eq!(document.page_multimedia_data(0, &id).unwrap(), png);
    document
        .replace_document_multimedia_data(0, &id, &png)
        .unwrap();
    assert_eq!(document.document_multimedia_data(0, &id).unwrap(), png);
    assert_eq!(document.document_multimedia_resources(0).unwrap().len(), 1);
}

#[test]
fn replaces_shared_page_media_through_split_page_res_link() {
    let mut document = OfdDocument::new();
    document.add_blank_page(10.0, 10.0).unwrap();
    document.add_blank_page(10.0, 10.0).unwrap();
    let id = document
        .add_page_multimedia_resource(0, "Audio", "WAV", b"original")
        .unwrap();
    let pages = document.pages().unwrap();
    let first_dir = pages[0].path.rsplit_once('/').unwrap().0;
    let link = format!(
        "../{}/RustPageRes_{id}.xml",
        first_dir.rsplit('/').next().unwrap()
    );
    let second_path = &pages[1].path;
    let xml = std::str::from_utf8(document.entry(second_path).unwrap().unwrap()).unwrap();
    let xml = xml.replace(
        "<ofd:Content>",
        &format!("<ofd:PageRes>{link}</ofd:PageRes><ofd:Content>"),
    );
    document.set_entry(second_path, xml.into_bytes()).unwrap();
    let first_path = &pages[0].path;
    let xml = std::str::from_utf8(document.entry(first_path).unwrap().unwrap()).unwrap();
    let unsplit = format!("<ofd:PageRes>RustPageRes_{id}.xml</ofd:PageRes>");
    let split = format!("<ofd:PageRes>Rust<!-- split -->PageRes_{id}.xml</ofd:PageRes>");
    let changed = xml.replacen(&unsplit, &split, 1);
    assert!(changed.contains(&split));
    document
        .set_entry(first_path, changed.into_bytes())
        .unwrap();
    assert_eq!(document.page_multimedia_data(0, &id).unwrap(), b"original");
    document
        .replace_page_multimedia_data(0, &id, b"changed")
        .unwrap();
    assert_eq!(document.page_multimedia_data(0, &id).unwrap(), b"changed");
    assert_eq!(document.page_multimedia_data(1, &id).unwrap(), b"original");
    assert!(document.validate_references().unwrap().is_empty());
}

