#[test]
fn import_and_snapshot_do_not_rewrite_foreign_namespace_path_lookalikes() {
    for xml in [
        "<x:Refs xmlns:x=\"urn:other\"><x:FileLoc>/Doc_0/Payload.bin</x:FileLoc></x:Refs>",
        "<ofd:Refs xmlns:ofd=\"http://www.ofdspec.org/2016\" xmlns:x=\"urn:other\" x:FileLoc=\"/Doc_0/Payload.bin\"/>",
        "<x:TextObject xmlns:x=\"urn:other\"><x:FileLoc>/Doc_0/Payload.bin</x:FileLoc></x:TextObject>",
    ] {
        let mut source = OfdDocument::new();
        source
            .set_entry("Doc_0/Payload.bin", b"payload".to_vec())
            .unwrap();
        source
            .set_entry("Doc_0/Foreign.xml", xml.as_bytes().to_vec())
            .unwrap();
        let mut target = OfdDocument::new();
        let before_target = target.to_bytes().unwrap();
        assert!(target.append_document_body_from(&source, 0).is_err(), "{xml}");
        assert_eq!(target.to_bytes().unwrap(), before_target);
        let before_source = source.to_bytes().unwrap();
        assert!(source.add_version_snapshot(0, "foreign", None).is_err(), "{xml}");
        assert_eq!(source.to_bytes().unwrap(), before_source);
    }

    let mut source = OfdDocument::new();
    let literal = b"<x:Refs xmlns:x=\"urn:other\"><x:FileLoc>/external/value.xml</x:FileLoc><x:Ref x:FileLoc=\"/external/value.bin\"/></x:Refs>";
    source
        .set_entry("Doc_0/Foreign.xml", literal.to_vec())
        .unwrap();
    let mut target = OfdDocument::new();
    assert_eq!(target.append_document_body_from(&source, 0).unwrap(), 1);
    assert_eq!(
        target.entry("Imported_0/Doc_0/Foreign.xml").unwrap(),
        Some(literal.as_slice())
    );
    source.add_version_snapshot(0, "foreign", None).unwrap();
    assert_eq!(
        source
            .entry("Versions/foreign/Snapshot/Doc_0/Foreign.xml")
            .unwrap(),
        Some(literal.as_slice())
    );
}

#[test]
fn extracts_version_with_split_file_path() {
    let mut document = OfdDocument::new();
    document.add_text_page("archived", 40.0, 30.0).unwrap();
    let version = document
        .add_version_snapshot(0, "split-file", None)
        .unwrap();
    let path = &version.description_path;
    let xml = std::str::from_utf8(document.entry(path).unwrap().unwrap()).unwrap();
    let location = xml
        .split("<ofd:File ID=\"f1\">")
        .nth(1)
        .unwrap()
        .split("</ofd:File>")
        .next()
        .unwrap();
    let split = format!("{}<!-- split -->{}", &location[..3], &location[3..]);
    let changed = xml.replacen(
        &format!("<ofd:File ID=\"f1\">{location}</ofd:File>"),
        &format!("<ofd:File ID=\"f1\">{split}</ofd:File>"),
        1,
    );
    assert!(changed.contains(&split));
    document.set_entry(path, changed.into_bytes()).unwrap();
    assert_eq!(
        document.versions().unwrap()[0].files[0].path,
        version.files[0].path
    );
    let extracted = document.extract_version_snapshot(0).unwrap();
    assert_eq!(extracted.page_text(0).unwrap(), ["archived"]);
    assert!(extracted.validate_references().unwrap().is_empty());
}

#[test]
fn reads_and_updates_split_annotation_remark_and_parameter() {
    let mut document = OfdDocument::new();
    document.add_blank_page(40.0, 30.0).unwrap();
    let id = document
        .add_highlight_annotation(0, [5.0, 5.0, 20.0, 10.0], [255, 255, 0], 128)
        .unwrap();
    document
        .set_annotation_remark(0, &id, Some("reviewed"))
        .unwrap();
    document
        .set_annotation_parameter(0, &id, "status", "draft")
        .unwrap();
    let source_path = document.annotations().unwrap()[0].source_path.clone();
    let xml = std::str::from_utf8(document.entry(&source_path).unwrap().unwrap()).unwrap();
    let changed = xml
        .replace(
            "<ofd:Remark>reviewed</ofd:Remark>",
            "<ofd:Remark>rev<!-- split -->iewed</ofd:Remark>",
        )
        .replace(
            "<ofd:Parameter Name=\"status\">draft</ofd:Parameter>",
            "<ofd:Parameter Name=\"status\">dr<![CDATA[af]]>t</ofd:Parameter>",
        );
    assert!(changed.contains("rev<!-- split -->iewed"));
    assert!(changed.contains("dr<![CDATA[af]]>t"));
    document
        .set_entry(&source_path, changed.into_bytes())
        .unwrap();
    let annotation = &document.annotations().unwrap()[0];
    assert_eq!(annotation.remark.as_deref(), Some("reviewed"));
    assert_eq!(annotation.parameters["status"], "draft");
    document
        .set_annotation_remark(0, &id, Some("updated"))
        .unwrap();
    document
        .set_annotation_parameter(0, &id, "status", "done")
        .unwrap();
    let annotation = &document.annotations().unwrap()[0];
    assert_eq!(annotation.remark.as_deref(), Some("updated"));
    assert_eq!(annotation.parameters["status"], "done");
    assert!(document.validate_references().unwrap().is_empty());
}

#[test]
fn renders_split_composite_substitution_resource_id() {
    let mut image_data = Cursor::new(Vec::new());
    image::DynamicImage::ImageRgb8(image::RgbImage::from_pixel(2, 2, image::Rgb([0, 255, 0])))
        .write_to(&mut image_data, image::ImageFormat::Png)
        .unwrap();
    let mut document = OfdDocument::new();
    for _ in 0..10 {
        document.add_blank_page(20.0, 20.0).unwrap();
    }
    let image_id = document
        .add_image_object(0, &image_data.into_inner(), "png", [0.0, 0.0, 20.0, 20.0])
        .unwrap();
    let media_id = document.page_images(0).unwrap()[0].resource_id.clone();
    assert!(media_id.len() > 1);
    document.remove_page_object(0, &image_id).unwrap();
    document
        .add_composite_path_object(
            0,
            "M 0 0 L 20 0 L 20 20 L 0 20 C",
            [0.0, 0.0, 20.0, 20.0],
            PathStyle {
                fill: true,
                stroke: false,
                fill_color: Some([255, 0, 0]),
                ..PathStyle::default()
            },
        )
        .unwrap();
    let unit_id = &document.page_composite_objects(0).unwrap()[0].resource_id;
    let resource_path = format!("Doc_0/CompositeRes_{unit_id}.xml");
    let xml = std::str::from_utf8(document.entry(&resource_path).unwrap().unwrap()).unwrap();
    let split = format!("{}<!-- split -->{}", &media_id[..1], &media_id[1..]);
    let changed = xml.replacen(
        "<ofd:Content>",
        &format!("<ofd:Substitution>{split}</ofd:Substitution><ofd:Content>"),
        1,
    );
    assert!(changed.contains(&split));
    document
        .set_entry(&resource_path, changed.into_bytes())
        .unwrap();
    assert!(document.validate_references().unwrap().is_empty());
    let options = RenderOptions {
        prefer_image_substitution: true,
    };
    let image = image::load_from_memory(&document.page_png_with_options(0, 25.4, options).unwrap())
        .unwrap()
        .to_rgb8();
    let green = image.get_pixel(10, 10);
    assert!(green[1] > 220 && green[0] < 35, "{green:?}");
}

