#[test]
fn reports_missing_signed_file_without_losing_other_digest_results() {
    let original = OfdDocument::open(fixture("SESV4SignDoc.ofd")).unwrap();
    for missing_path in [
        "Doc_0/PublicRes.xml",
        "Doc_0/Signs/Sign_0/Seal.esl",
        "Doc_0/Signs/Sign_0/SignedValue.dat",
    ] {
        let mut source = zip::ZipArchive::new(Cursor::new(original.to_bytes().unwrap())).unwrap();
        let mut output = zip::ZipWriter::new(Cursor::new(Vec::new()));
        for index in 0..source.len() {
            let mut entry = source.by_index(index).unwrap();
            if entry.is_dir() || entry.name() == missing_path {
                continue;
            }
            output
                .start_file(entry.name(), zip::write::SimpleFileOptions::default())
                .unwrap();
            std::io::copy(&mut entry, &mut output).unwrap();
        }
        let bytes = output.finish().unwrap().into_inner();
        let document = OfdDocument::from_bytes(&bytes).unwrap();
        let checks = document.check_signature_references(0).unwrap();
        assert_eq!(checks.len(), 5);
        if missing_path.ends_with("SignedValue.dat") {
            assert!(checks.iter().all(|check| check.valid));
            assert!(document.signed_value_data(0).is_err());
        } else {
            assert!(checks
                .iter()
                .filter(|check| check.path != missing_path)
                .all(|check| check.valid));
            let missing = checks
                .iter()
                .find(|check| check.path == missing_path)
                .unwrap();
            assert!(!missing.valid);
            assert!(missing.actual.is_empty());
            assert!(!missing.expected.is_empty());
        }
        let issues = document.validate_references().unwrap();
        assert!(issues.iter().any(|issue| {
            issue.code == "signature_reference" && issue.message.contains(missing_path)
        }));
        if missing_path.ends_with("Seal.esl") {
            assert_eq!(document.check_signature_seal_match(0).unwrap(), Some(false));
            let report = document
                .verify_signature_with_direct_trust_anchor(
                    0,
                    &[],
                    include_bytes!("fixtures/root-cert.der"),
                    1_600_000_000,
                    "1234567812345678",
                )
                .unwrap();
            assert_eq!(report.seal_match, Some(false));
            assert!(!report.references_valid);
            assert!(!report.all_valid);
        }
    }
}

#[test]
fn rejects_broken_signature_entries() {
    let mut document = OfdDocument::open(fixture("SESV4SignDoc.ofd")).unwrap();
    let index_path = "Doc_0/Signs/Signatures.xml";
    let original = document.entry(index_path).unwrap().unwrap().to_vec();
    document
        .set_entry(index_path, b"<Wrong/>".to_vec())
        .unwrap();
    assert!(matches!(document.signatures(), Err(OfdError::Invalid(_))));
    document
        .set_entry(
            index_path,
            b"<Signatures><Signature ID=\"1\"/></Signatures>".to_vec(),
        )
        .unwrap();
    assert!(matches!(document.signatures(), Err(OfdError::Invalid(_))));
    document.set_entry(index_path, original).unwrap();
    let description_path = "Doc_0/Signs/Sign_0/Signature.xml";
    document
        .set_entry(description_path, b"<Signature/>".to_vec())
        .unwrap();
    assert!(matches!(document.signatures(), Err(OfdError::Invalid(_))));
    document
        .set_entry(
            description_path,
            b"<Signature><SignedValue>SignedValue.dat</SignedValue></Signature>".to_vec(),
        )
        .unwrap();
    assert!(matches!(document.signatures(), Err(OfdError::Invalid(_))));
    document
        .set_entry(description_path, b"<Wrong/>".to_vec())
        .unwrap();
    assert!(matches!(document.signatures(), Err(OfdError::Invalid(_))));
    document
        .set_entry(
            description_path,
            b"<Signature><SignedValue>SignedValue.dat</SignedValue><SignedInfo>\
              <References CheckMethod=\"SM3\"><Reference FileRef=\"/OFD.xml\"/>\
              </References></SignedInfo></Signature>"
                .to_vec(),
        )
        .unwrap();
    assert!(matches!(document.signatures(), Err(OfdError::Invalid(_))));
}

#[test]
fn resolves_relative_signature_paths() {
    let mut document = OfdDocument::open(fixture("SESV4SignDoc.ofd")).unwrap();
    for (path, absolute, relative) in [
        (
            "OFD.xml",
            "/Doc_0/Signs/Signatures.xml",
            "Doc_0/Signs/Signatures.xml",
        ),
        (
            "Doc_0/Signs/Signatures.xml",
            "/Doc_0/Signs/Sign_0/Signature.xml",
            "Sign_0/Signature.xml",
        ),
        (
            "Doc_0/Signs/Sign_0/Signature.xml",
            "/Doc_0/Signs/Sign_0/SignedValue.dat",
            "SignedValue.dat",
        ),
    ] {
        let xml = std::str::from_utf8(document.entry(path).unwrap().unwrap()).unwrap();
        document
            .set_entry(path, xml.replace(absolute, relative).into_bytes())
            .unwrap();
    }
    let signature = &document.signatures().unwrap()[0];
    assert_eq!(
        signature.signed_value_path,
        "Doc_0/Signs/Sign_0/SignedValue.dat"
    );
    assert_eq!(document.signed_value_data(0).unwrap().len(), 17_726);
    assert!(!document.check_signature_references(0).unwrap()[0].valid);
}

