#[test]
fn duplicate_page_object_rejects_stale_max_id_on_another_page() {
    let mut document = OfdDocument::new();
    document.add_text_page("first", 40.0, 30.0).unwrap();
    document.add_text_page("second", 40.0, 30.0).unwrap();
    let first = document.page_text_objects(0).unwrap()[0]
        .id
        .clone()
        .unwrap();
    let second = document.page_text_objects(1).unwrap()[0]
        .id
        .clone()
        .unwrap();
    let root = "Doc_0/Document.xml";
    let source = std::str::from_utf8(document.entry(root).unwrap().unwrap())
        .unwrap()
        .to_owned();
    let start = source.find("<ofd:MaxUnitID>").unwrap() + "<ofd:MaxUnitID>".len();
    let end = source[start..].find('<').unwrap() + start;
    let mut changed = source;
    changed.replace_range(
        start..end,
        &(second.parse::<usize>().unwrap() - 1).to_string(),
    );
    document.set_entry(root, changed.into_bytes()).unwrap();
    let before = document.to_bytes().unwrap();
    assert!(document.duplicate_page_object(0, &first).is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
}

#[test]
fn groups_page_objects_into_nested_blocks_without_changing_appearance() {
    let mut document = OfdDocument::new();
    document.add_text_page("grouped", 40.0, 30.0).unwrap();
    let first = document.page_objects(0).unwrap()[0].id.clone().unwrap();
    let second = document
        .add_path_object(0, "M 0 0 L 3 3", [1.0, 1.0, 4.0, 4.0], PathStyle::default())
        .unwrap();
    let third = document
        .add_path_object(0, "M 0 0 L 2 2", [3.0, 3.0, 3.0, 3.0], PathStyle::default())
        .unwrap();
    let page = document.pages().unwrap()[0].path.clone();
    let before_page = document.entry(&page).unwrap().unwrap().to_vec();
    let before_ids: Vec<_> = document
        .page_objects(0)
        .unwrap()
        .into_iter()
        .map(|object| object.id)
        .collect();
    let before_svg = document.page_svg(0).unwrap();
    let before_png = document.page_png(0, 25.4).unwrap();
    let before_document = document
        .entry("Doc_0/Document.xml")
        .unwrap()
        .unwrap()
        .to_vec();

    document.group_page_objects(0, &first, &second).unwrap();
    document.group_page_objects(0, &first, &first).unwrap();
    let xml = std::str::from_utf8(document.entry(&page).unwrap().unwrap()).unwrap();
    let parsed = roxmltree::Document::parse(xml).unwrap();
    let depth = |id: &str| {
        parsed
            .descendants()
            .find(|node| node.attribute("ID") == Some(id))
            .unwrap()
            .ancestors()
            .filter(|node| node.tag_name().name() == "PageBlock")
            .count()
    };
    assert_eq!(depth(&first), 2);
    assert_eq!(depth(&second), 1);
    assert_eq!(depth(&third), 0);
    assert_eq!(
        document
            .page_objects(0)
            .unwrap()
            .into_iter()
            .map(|object| object.id)
            .collect::<Vec<_>>(),
        before_ids
    );
    assert_eq!(document.page_text(0).unwrap(), ["grouped"]);
    assert_eq!(document.page_svg(0).unwrap(), before_svg);
    assert_eq!(document.page_png(0, 25.4).unwrap(), before_png);
    assert_eq!(
        document.entry("Doc_0/Document.xml").unwrap().unwrap(),
        before_document
    );
    assert!(document.validate_references().unwrap().is_empty());

    let snapshot = document.entry(&page).unwrap().unwrap().to_vec();
    for (first_id, last_id) in [
        (first.as_str(), third.as_str()),
        (third.as_str(), second.as_str()),
        ("missing", second.as_str()),
        ("", second.as_str()),
    ] {
        assert!(document.group_page_objects(0, first_id, last_id).is_err());
        assert_eq!(document.entry(&page).unwrap().unwrap(), snapshot);
    }
    assert!(document.ungroup_page_objects(0, &third).is_err());
    assert!(document.ungroup_page_objects(0, "missing").is_err());
    assert_eq!(document.entry(&page).unwrap().unwrap(), snapshot);
    let mut attributed = document.clone();
    let with_attribute = std::str::from_utf8(&snapshot).unwrap().replacen(
        "<ofd:PageBlock>",
        "<ofd:PageBlock Ext=\"keep\">",
        1,
    );
    attributed
        .set_entry(&page, with_attribute.into_bytes())
        .unwrap();
    assert!(attributed.ungroup_page_objects(0, &second).is_err());
    let mut scoped = document.clone();
    let with_namespace = std::str::from_utf8(&snapshot).unwrap().replacen(
        "<ofd:PageBlock>",
        "<ofd:PageBlock xmlns:x=\"urn:x\">",
        1,
    );
    scoped
        .set_entry(&page, with_namespace.into_bytes())
        .unwrap();
    assert!(scoped.ungroup_page_objects(0, &second).is_err());
    let mut extended = document.clone();
    let with_extension = std::str::from_utf8(&snapshot)
        .unwrap()
        .replacen(
            "<ofd:Page xmlns:ofd=",
            "<ofd:Page xmlns:x=\"urn:example:extension\" xmlns:ofd=",
            1,
        )
        .replacen(
            "<ofd:PageBlock>",
            "<ofd:PageBlock><x:TextObject Boundary=\"0 0 1 1\"/>",
            1,
        );
    extended
        .set_entry(&page, with_extension.into_bytes())
        .unwrap();
    let before = extended.entry(&page).unwrap().unwrap().to_vec();
    assert!(extended.ungroup_page_objects(0, &second).is_err());
    assert_eq!(extended.entry(&page).unwrap().unwrap(), before);
    document.ungroup_page_objects(0, &first).unwrap();
    document.ungroup_page_objects(0, &second).unwrap();
    assert_eq!(document.entry(&page).unwrap().unwrap(), before_page);
    assert!(document.validate_references().unwrap().is_empty());
    let mut signed = OfdDocument::open(
        PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../../ofdrw-sign/src/test/resources/signedFile.ofd"),
    )
    .unwrap();
    assert!(signed.group_page_objects(0, "62", "62").is_err());
    assert!(signed.ungroup_page_objects(0, "62").is_err());
}

