#[test]
fn attachment_references_use_unique_archive_case_for_reading_and_editing() {
    let mut created = OfdDocument::new();
    created.add_text_page("attachment", 30.0, 20.0).unwrap();
    created.add_attachment("note.txt", b"original").unwrap();
    let mut document = OfdDocument::from_bytes(&created.to_bytes().unwrap()).unwrap();
    let attachment = document.attachments().unwrap().remove(0);
    let root = "Doc_0/Document.xml";
    let original = std::str::from_utf8(document.entry(root).unwrap().unwrap()).unwrap();
    let changed = original.replace(">Attachments.xml<", ">ATTACHMENTS.XML<");
    assert_ne!(changed, original);
    document.set_entry(root, changed.into_bytes()).unwrap();
    let list_path = "Doc_0/Attachments.xml";
    let original = std::str::from_utf8(document.entry(list_path).unwrap().unwrap()).unwrap();
    let changed = original.replace(&attachment.path, &attachment.path.to_ascii_uppercase());
    assert_ne!(changed, original);
    document.set_entry(list_path, changed.into_bytes()).unwrap();

    assert_eq!(document.attachments().unwrap()[0].path, attachment.path);
    assert_eq!(document.attachment_data(0).unwrap(), b"original");
    assert!(document.validate_references().unwrap().is_empty());
    document.rename_attachment(0, "renamed.txt").unwrap();
    assert_eq!(document.attachments().unwrap()[0].name, "renamed.txt");
    assert!(document.entry("Doc_0/ATTACHMENTS.XML").unwrap().is_none());

    let mut ambiguous = document.clone();
    let list_bytes = document.entry(list_path).unwrap().unwrap().to_vec();
    ambiguous
        .set_entry("doc_0/attachments.xml", list_bytes)
        .unwrap();
    assert!(matches!(
        ambiguous.attachments(),
        Err(OfdError::Invalid(message)) if message.contains("ambiguous entry reference")
    ));

    document
        .set_entry(&attachment.path.to_ascii_lowercase(), b"other".to_vec())
        .unwrap();
    assert!(matches!(
        document.attachments(),
        Err(OfdError::Invalid(message)) if message.contains("ambiguous entry reference")
    ));
}

#[test]
fn attachment_metadata_round_trips_and_survives_new_attachment() {
    let metadata = AttachmentMetadata {
        format: Some("text/plain & notes".into()),
        creation_date: Some("2024-02-29T12:30:59".into()),
        mod_date: Some("2024-03-01T08:00:00".into()),
        visible: false,
        usage: Some("source & <record>".into()),
    };
    let mut document = OfdDocument::new();
    document.add_attachment("first", b"one").unwrap();
    let before = document.to_bytes().unwrap();
    let mut invalid = metadata.clone();
    invalid.creation_date = Some("2023-02-29T12:30:59".into());
    assert!(document.set_attachment_metadata(0, invalid).is_err());
    assert!(document
        .set_attachment_metadata(1, metadata.clone())
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    document
        .set_attachment_metadata(0, metadata.clone())
        .unwrap();
    document.add_attachment("second", b"two").unwrap();
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    let attachments = reopened.attachments().unwrap();
    assert_eq!(attachments[0].format.as_deref(), metadata.format.as_deref());
    assert_eq!(
        attachments[0].creation_date.as_deref(),
        metadata.creation_date.as_deref()
    );
    assert_eq!(
        attachments[0].mod_date.as_deref(),
        metadata.mod_date.as_deref()
    );
    assert!(!attachments[0].visible);
    assert_eq!(attachments[0].usage, "source & <record>");
    assert_eq!(attachments[1].usage, "none");
    assert_eq!(reopened.attachment_data(0).unwrap(), b"one");
    let mut existing = OfdDocument::open(fixture("AddAttachment.ofd")).unwrap();
    existing.set_attachment_metadata(0, metadata).unwrap();
    let reopened = OfdDocument::from_bytes(&existing.to_bytes().unwrap()).unwrap();
    assert_eq!(
        reopened.attachments().unwrap()[0].usage,
        "source & <record>"
    );
    assert_eq!(reopened.attachment_data(0).unwrap().len(), 36_494);
}

#[test]
fn attachment_operations_ignore_extension_namespace_lookalikes() {
    let mut created = OfdDocument::new();
    created.add_attachment("original", b"old").unwrap();
    let mut document = OfdDocument::from_bytes(&created.to_bytes().unwrap()).unwrap();
    let root_path = "Doc_0/Document.xml";
    let root = std::str::from_utf8(document.entry(root_path).unwrap().unwrap()).unwrap();
    assert!(root.contains("<ofd:Attachments>"));
    document
        .set_entry(
            root_path,
            root.replace(
                "<ofd:Attachments>",
                "<x:Attachments xmlns:x=\"urn:example:extension\">missing</x:Attachments><ofd:Attachments>",
            )
            .into_bytes(),
        )
        .unwrap();
    let path = "Doc_0/Attachments.xml";
    let source = std::str::from_utf8(document.entry(path).unwrap().unwrap()).unwrap();
    let extension = "<x:Attachment xmlns:x=\"urn:example:extension\" ID=\"999\" Name=\"keep\"><x:FileLoc>missing</x:FileLoc></x:Attachment>";
    let extension_file = "<x:FileLoc xmlns:x=\"urn:example:extension\">keep-this</x:FileLoc>";
    assert!(source.contains("<ofd:Attachment "));
    assert!(source.contains("<ofd:FileLoc>"));
    document
        .set_entry(
            path,
            source
                .replacen(
                    "<ofd:Attachment ",
                    &format!("{extension}<ofd:Attachment "),
                    1,
                )
                .replacen(
                    "<ofd:FileLoc>",
                    &format!("{extension_file}<ofd:FileLoc>"),
                    1,
                )
                .into_bytes(),
        )
        .unwrap();
    assert_eq!(document.attachments().unwrap().len(), 1);
    assert_eq!(document.attachment_data(0).unwrap(), b"old");
    assert!(document.validate_references().unwrap().is_empty());

    document.rename_attachment(0, "renamed").unwrap();
    document.replace_attachment_data(0, b"new").unwrap();
    document
        .set_attachment_metadata(
            0,
            AttachmentMetadata {
                format: Some("TXT".into()),
                ..AttachmentMetadata::default()
            },
        )
        .unwrap();
    assert_eq!(document.attachments().unwrap()[0].name, "renamed");
    assert_eq!(
        document.attachments().unwrap()[0].format.as_deref(),
        Some("TXT")
    );
    assert_eq!(document.attachment_data(0).unwrap(), b"new");
    assert!(std::str::from_utf8(document.entry(path).unwrap().unwrap())
        .unwrap()
        .contains(extension_file));
    document.remove_attachment(0).unwrap();
    assert!(document.attachments().unwrap().is_empty());
    assert!(std::str::from_utf8(document.entry(path).unwrap().unwrap())
        .unwrap()
        .contains(extension));
    document
        .add_attachment_to_document(0, "added", b"payload")
        .unwrap();
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.attachments().unwrap().len(), 1);
    assert_eq!(reopened.attachment_data(0).unwrap(), b"payload");
    assert!(std::str::from_utf8(reopened.entry(path).unwrap().unwrap())
        .unwrap()
        .contains(extension));
}

#[test]
fn replaces_attachment_bytes_and_size_without_touching_old_entry() {
    let mut document = OfdDocument::new();
    document.add_attachment("first", b"one").unwrap();
    document
        .set_attachment_metadata(
            0,
            AttachmentMetadata {
                format: Some("text/plain".into()),
                ..AttachmentMetadata::default()
            },
        )
        .unwrap();
    let original = document.attachments().unwrap()[0].clone();
    let before = document.to_bytes().unwrap();
    assert!(document.replace_attachment_data(1, b"bad").is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    document.replace_attachment_data(0, b"replacement").unwrap();
    let replaced = document.attachments().unwrap()[0].clone();
    assert_eq!(replaced.id, original.id);
    assert_eq!(replaced.format, original.format);
    assert_eq!(replaced.size, 11);
    assert_ne!(replaced.path, original.path);
    assert_eq!(
        document.entry(&original.path).unwrap(),
        Some(b"one".as_slice())
    );
    assert_eq!(document.attachment_data(0).unwrap(), b"replacement");
    let list = roxmltree::Document::parse(
        std::str::from_utf8(document.entry("Doc_0/Attachments.xml").unwrap().unwrap()).unwrap(),
    )
    .unwrap();
    let declared = list
        .descendants()
        .find(|node| node.tag_name().name() == "Attachment")
        .unwrap()
        .attribute("Size")
        .unwrap()
        .parse::<f64>()
        .unwrap();
    assert!((declared - 11.0 / 1024.0).abs() < 1e-12);
    let before_rename = document.to_bytes().unwrap();
    assert!(document.rename_attachment(0, " ").is_err());
    assert!(document.rename_attachment(1, "missing").is_err());
    assert_eq!(document.to_bytes().unwrap(), before_rename);
    document
        .rename_attachment(0, "新名称 & <附件>.txt")
        .unwrap();
    let renamed = document.attachments().unwrap()[0].clone();
    assert_eq!(renamed.name, "新名称 & <附件>.txt");
    assert_eq!(renamed.id, replaced.id);
    assert_eq!(renamed.path, replaced.path);
    document.add_attachment("second", b"two").unwrap();
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.attachments().unwrap()[0], renamed);
    assert_eq!(reopened.attachment_data(0).unwrap(), b"replacement");
    assert_eq!(reopened.attachment_data(1).unwrap(), b"two");
    let mut existing = OfdDocument::open(fixture("AddAttachment.ofd")).unwrap();
    let prior = existing.attachments().unwrap()[0].clone();
    existing.replace_attachment_data(0, b"new").unwrap();
    existing.rename_attachment(0, "renamed & <Java>").unwrap();
    assert_eq!(existing.entry(&prior.path).unwrap().unwrap().len(), 36_494);
    assert_eq!(existing.attachment_data(0).unwrap(), b"new");
    assert_eq!(existing.attachments().unwrap()[0].size, 3);
    assert_eq!(existing.attachments().unwrap()[0].name, "renamed & <Java>");
}

#[test]
fn attachment_writers_avoid_case_insensitive_package_path_collisions() {
    let mut reusable = OfdDocument::new();
    reusable.add_attachment("first", b"one").unwrap();
    let old_path = reusable.attachments().unwrap()[0].path.clone();
    reusable.remove_attachment(0).unwrap();
    reusable.add_attachment("second", b"two").unwrap();
    assert_ne!(reusable.attachments().unwrap()[0].path, old_path);
    assert_eq!(reusable.attachment_data(0).unwrap(), b"two");

    let mut document = OfdDocument::new();
    document
        .set_entry("doc_0/res/attachment_0", b"reserved".to_vec())
        .unwrap();
    let before = document.to_bytes().unwrap();
    assert!(document.add_attachment("first", b"one").is_err());
    assert_eq!(document.to_bytes().unwrap(), before);

    let mut document = OfdDocument::new();
    document
        .set_entry("doc_0/attachments.xml", b"<reserved/>".to_vec())
        .unwrap();
    let before = document.to_bytes().unwrap();
    assert!(document.add_attachment("first", b"one").is_err());
    assert_eq!(document.to_bytes().unwrap(), before);

    let mut document = OfdDocument::new();
    document.add_attachment("first", b"one").unwrap();
    document
        .set_entry("doc_0/res/attachmentreplacement_0_1", b"reserved".to_vec())
        .unwrap();
    document.replace_attachment_data(0, b"replacement").unwrap();
    assert_eq!(document.attachment_data(0).unwrap(), b"replacement");
    assert_eq!(
        document.attachments().unwrap()[0].path,
        "Doc_0/Res/AttachmentReplacement_0_2"
    );
    assert_eq!(
        document
            .entry("doc_0/res/attachmentreplacement_0_1")
            .unwrap(),
        Some(b"reserved".as_slice())
    );
    assert!(document.validate_references().unwrap().is_empty());
}

