#[test]
fn removes_attachment_without_discarding_payload_or_reusing_its_path() {
    let mut document = OfdDocument::new();
    document.add_attachment("first", b"one").unwrap();
    document.add_attachment("second", b"two").unwrap();
    let first_path = document.attachments().unwrap()[0].path.clone();
    let second_path = document.attachments().unwrap()[1].path.clone();
    assert!(document.remove_attachment(2).is_err());
    document.remove_attachment(0).unwrap();
    assert_eq!(
        document.entry(&first_path).unwrap(),
        Some(b"one".as_slice())
    );
    assert_eq!(document.attachment_data(0).unwrap(), b"two");
    document.add_attachment("third", b"three").unwrap();
    let attachments = document.attachments().unwrap();
    assert_eq!(attachments.len(), 2);
    assert_eq!(attachments[0].path, second_path);
    assert_ne!(attachments[1].path, first_path);
    assert_ne!(attachments[1].path, second_path);
    assert_eq!(document.attachment_data(1).unwrap(), b"three");
    assert!(document.validate_references().unwrap().is_empty());
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.attachments().unwrap(), attachments);
}

