#[test]
fn shared_signed_attachment_list_rejects_all_attachment_edits() {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../../ofdrw-sign/src/test/resources/signedFile.ofd");
    let mut document = OfdDocument::open(path).unwrap();
    let copied_root = document
        .entry("Doc_0/Document.xml")
        .unwrap()
        .unwrap()
        .to_vec();
    document
        .set_entry("Doc_0/DocumentCopy.xml", copied_root)
        .unwrap();
    let ofd = std::str::from_utf8(document.entry("OFD.xml").unwrap().unwrap())
        .unwrap()
        .replace(
            "</ofd:OFD>",
            "<ofd:DocBody><ofd:DocRoot>Doc_0/DocumentCopy.xml</ofd:DocRoot></ofd:DocBody></ofd:OFD>",
        );
    document.set_entry("OFD.xml", ofd.into_bytes()).unwrap();
    assert_eq!(document.attachments().unwrap().len(), 2);
    let before = document.to_bytes().unwrap();

    let errors = [
        document.rename_attachment(1, "changed").unwrap_err(),
        document.replace_attachment_data(1, b"changed").unwrap_err(),
        document
            .set_attachment_metadata(1, AttachmentMetadata::default())
            .unwrap_err(),
        document.remove_attachment(1).unwrap_err(),
        document
            .add_attachment_to_document(1, "new", b"new")
            .unwrap_err(),
    ];
    for error in errors {
        assert!(error.to_string().contains("signed"), "{error}");
    }
    assert_eq!(document.to_bytes().unwrap(), before);
}

