fn signed_multimedia_resource_is_protected_even_without_shared_document_link() {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../../ofdrw-sign/src/test/resources/signedFile.ofd");
    let mut document = OfdDocument::open(path).unwrap();
    let original_root = document
        .entry("Doc_0/Document.xml")
        .unwrap()
        .unwrap()
        .to_vec();
    document
        .set_entry("Doc_0/DocumentCopy.xml", original_root.clone())
        .unwrap();
    let modified_root = std::str::from_utf8(&original_root)
        .unwrap()
        .replace("<ofd:DocumentRes>DocumentRes.xml</ofd:DocumentRes>", "");
    document
        .set_entry("Doc_0/Document.xml", modified_root.into_bytes())
        .unwrap();
    let ofd = std::str::from_utf8(document.entry("OFD.xml").unwrap().unwrap())
        .unwrap()
        .replace(
            "</ofd:OFD>",
            "<ofd:DocBody><ofd:DocRoot>Doc_0/DocumentCopy.xml</ofd:DocRoot></ofd:DocBody></ofd:OFD>",
        );
    document.set_entry("OFD.xml", ofd.into_bytes()).unwrap();
    let media = document.document_multimedia_data(1, "80").unwrap().to_vec();
    let before = document.to_bytes().unwrap();

    let replace_error = document
        .replace_document_multimedia_data(1, "80", &media)
        .unwrap_err();
    assert!(
        replace_error.to_string().contains("Doc_0/DocumentRes.xml"),
        "{replace_error}"
    );
    let remove_error = document
        .remove_document_multimedia_resource(1, "80")
        .unwrap_err();
    assert!(
        remove_error.to_string().contains("Doc_0/DocumentRes.xml"),
        "{remove_error}"
    );
    assert_eq!(document.to_bytes().unwrap(), before);
}

