#[test]
fn shared_signed_annotation_files_reject_add_edit_and_remove() {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../../ofdrw-sign/src/test/resources/signedFile.ofd");
    let mut document = OfdDocument::open(path).unwrap();
    let copied_page = document
        .entry("Doc_0/Pages/Page_0/Content.xml")
        .unwrap()
        .unwrap()
        .to_vec();
    document
        .set_entry("Doc_0/Pages/Page_Copy/Content.xml", copied_page)
        .unwrap();
    let copied_root = std::str::from_utf8(document.entry("Doc_0/Document.xml").unwrap().unwrap())
        .unwrap()
        .replace("Pages/Page_0/Content.xml", "Pages/Page_Copy/Content.xml");
    document
        .set_entry("Doc_0/DocumentCopy.xml", copied_root.into_bytes())
        .unwrap();
    let ofd = std::str::from_utf8(document.entry("OFD.xml").unwrap().unwrap())
        .unwrap()
        .replace(
            "</ofd:OFD>",
            "<ofd:DocBody><ofd:DocRoot>Doc_0/DocumentCopy.xml</ofd:DocRoot></ofd:DocBody></ofd:OFD>",
        );
    document.set_entry("OFD.xml", ofd.into_bytes()).unwrap();
    let annotation = document
        .annotations()
        .unwrap()
        .into_iter()
        .find(|annotation| annotation.document_index == 1)
        .unwrap();
    let before = document.to_bytes().unwrap();

    let add_error = document
        .add_path_annotation(1, "M 0 0 L 1 1", [0.0, 0.0, 2.0, 2.0], PathStyle::default())
        .unwrap_err();
    assert!(
        add_error
            .to_string()
            .contains("Doc_0/Annots/Annotations.xml"),
        "{add_error}"
    );
    let edit_error = document
        .set_annotation_visible(1, &annotation.id, false)
        .unwrap_err();
    assert!(
        edit_error
            .to_string()
            .contains("Doc_0/Annots/Page_0/Annotation.xml"),
        "{edit_error}"
    );
    let remove_error = document.remove_annotation(1, &annotation.id).unwrap_err();
    assert!(
        remove_error
            .to_string()
            .contains("Doc_0/Annots/Page_0/Annotation.xml"),
        "{remove_error}"
    );
    let object_edit_error = document
        .update_annotation_object(
            1,
            &annotation.id,
            "missing",
            &ofdrw::AnnotationObjectUpdate {
                alpha: Some(128),
                ..Default::default()
            },
        )
        .unwrap_err();
    assert!(object_edit_error
        .to_string()
        .contains("Doc_0/Annots/Page_0/Annotation.xml"));
    let object_remove_error = document
        .remove_annotation_object(1, &annotation.id, "missing")
        .unwrap_err();
    assert!(object_remove_error
        .to_string()
        .contains("Doc_0/Annots/Page_0/Annotation.xml"));
    assert_eq!(document.to_bytes().unwrap(), before);
}

