#[test]
fn removes_attachment_by_global_index_from_second_document() {
    let mut document = OfdDocument::new();
    document.add_attachment("shared name", b"first").unwrap();
    let copies: Vec<_> = document
        .entry_names()
        .filter(|path| path.starts_with("Doc_0/"))
        .map(|path| {
            let bytes = document.entry(path).unwrap().unwrap();
            let bytes = if path.ends_with(".xml") {
                std::str::from_utf8(bytes)
                    .unwrap()
                    .replace("Doc_0/", "Doc_1/")
                    .into_bytes()
            } else {
                bytes.to_vec()
            };
            (path.replacen("Doc_0/", "Doc_1/", 1), bytes)
        })
        .collect();
    for (path, bytes) in copies {
        document.set_entry(&path, bytes).unwrap();
    }
    let ofd = std::str::from_utf8(document.entry("OFD.xml").unwrap().unwrap())
        .unwrap()
        .replace(
            "</ofd:OFD>",
            "<ofd:DocBody><ofd:DocRoot>Doc_1/Document.xml</ofd:DocRoot></ofd:DocBody></ofd:OFD>",
        );
    document.set_entry("OFD.xml", ofd.into_bytes()).unwrap();
    assert_eq!(document.attachments().unwrap().len(), 2);
    let second_path = document.attachments().unwrap()[1].path.clone();
    document.remove_attachment(1).unwrap();
    let attachments = document.attachments().unwrap();
    assert_eq!(attachments.len(), 1);
    assert_eq!(attachments[0].document_index, 0);
    assert_eq!(document.attachment_data(0).unwrap(), b"first");
    assert_eq!(
        document.entry(&second_path).unwrap(),
        Some(b"first".as_slice())
    );
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.attachments().unwrap(), attachments);
}

#[test]
fn appends_attachment_to_existing_java_list_without_losing_original() {
    let mut document = OfdDocument::open(fixture("AddAttachment.ofd")).unwrap();
    let original_file = document.attachment_data(0).unwrap().to_vec();
    document
        .add_attachment_to_document(0, "Rust & ofd:note", b"attachment bytes")
        .unwrap();
    let attachments = document.attachments().unwrap();
    assert_eq!(attachments.len(), 2);
    assert_eq!(attachments[0].name, "Gao");
    assert_eq!(attachments[1].name, "Rust & ofd:note");
    assert_eq!(document.attachment_data(0).unwrap(), original_file);
    assert_eq!(document.attachment_data(1).unwrap(), b"attachment bytes");
    let list = document.entry("Doc_0/Attachments.xml").unwrap().unwrap();
    assert!(String::from_utf8_lossy(list).contains("Name=\"Gao\""));
    assert!(document.validate_references().unwrap().is_empty());
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.attachments().unwrap().len(), 2);
    assert_eq!(reopened.attachment_data(1).unwrap(), b"attachment bytes");
}

#[test]
fn creates_attachment_list_in_existing_document_and_rejects_collisions_atomically() {
    let mut document = OfdDocument::open(fixture("helloworld.ofd")).unwrap();
    let original = document.to_bytes().unwrap();
    for (index, name) in [(1, "note"), (0, " ")] {
        assert!(document
            .add_attachment_to_document(index, name, b"data")
            .is_err());
        assert_eq!(document.to_bytes().unwrap(), original);
    }
    for path in ["Doc_0/Attachments_5.xml", "Doc_0/Res/Attachment_5"] {
        let mut occupied = document.clone();
        let data = if path.ends_with(".xml") {
            b"<occupied/>".as_slice()
        } else {
            b"occupied".as_slice()
        };
        occupied.set_entry(path, data.to_vec()).unwrap();
        let before = occupied.to_bytes().unwrap();
        assert!(occupied
            .add_attachment_to_document(0, "report.txt", b"report")
            .is_err());
        assert_eq!(occupied.to_bytes().unwrap(), before);
    }
    document
        .add_attachment_to_document(0, "report.txt", b"report")
        .unwrap();
    assert_eq!(document.attachments().unwrap()[0].name, "report.txt");
    assert_eq!(document.attachment_data(0).unwrap(), b"report");
    assert!(document.validate_references().unwrap().is_empty());
    let reopened = OfdDocument::from_bytes(&document.to_bytes().unwrap()).unwrap();
    assert_eq!(reopened.attachment_data(0).unwrap(), b"report");
}

#[test]
fn appends_attachment_to_empty_unprefixed_list_and_rejects_bad_list() {
    let mut document = OfdDocument::open(fixture("AddAttachment.ofd")).unwrap();
    document
        .set_entry("Doc_0/Attachments.xml", b"<Attachments/>".to_vec())
        .unwrap();
    document
        .add_attachment_to_document(0, "ofd:note & test", b"new data")
        .unwrap();
    let list =
        std::str::from_utf8(document.entry("Doc_0/Attachments.xml").unwrap().unwrap()).unwrap();
    assert!(list.contains("<Attachment "));
    assert!(list.contains("Name=\"ofd:note &amp; test\""));
    assert_eq!(document.attachment_data(0).unwrap(), b"new data");
    assert!(document.validate_references().unwrap().is_empty());

    let mut bad = OfdDocument::open(fixture("AddAttachment.ofd")).unwrap();
    bad.set_entry("Doc_0/Attachments.xml", b"<Wrong/>".to_vec())
        .unwrap();
    let before = bad.to_bytes().unwrap();
    assert!(bad.add_attachment_to_document(0, "note", b"data").is_err());
    assert_eq!(bad.to_bytes().unwrap(), before);

    let mut empty = OfdDocument::open(fixture("AddAttachment.ofd")).unwrap();
    let source = std::str::from_utf8(empty.entry("Doc_0/Document.xml").unwrap().unwrap())
        .unwrap()
        .replace(
            "<ofd:Attachments>/Doc_0/Attachments.xml</ofd:Attachments>",
            "<ofd:Attachments/>",
        );
    empty
        .set_entry("Doc_0/Document.xml", source.into_bytes())
        .unwrap();
    let before = empty.to_bytes().unwrap();
    assert!(empty
        .add_attachment_to_document(0, "note", b"data")
        .is_err());
    assert_eq!(empty.to_bytes().unwrap(), before);
}

#[test]
fn saves_atomically_and_reopens() {
    let directory = tempfile::tempdir().unwrap();
    let path = directory.path().join("written.ofd");
    let document = OfdDocument::open(fixture("helloworld.ofd")).unwrap();
    document.save(&path).unwrap();
    let reopened = OfdDocument::open(path).unwrap();
    assert_eq!(
        reopened.page_text(0).unwrap(),
        document.page_text(0).unwrap()
    );
    assert!(reopened.attachments().unwrap().is_empty());
}

