#[test]
fn colored_shaped_text_commits_paint_and_glyph_mapping_together() {
    let font = include_bytes!("fixtures/dejavu-serif.ttf");
    let mut document = OfdDocument::new();
    let font_id = document.add_embedded_font("DejaVu Serif", font).unwrap();
    document.add_blank_page(40.0, 20.0).unwrap();
    let before = document.to_bytes().unwrap();
    assert!(document
        .add_colored_shaped_text_object(
            0,
            "AfiB",
            [5.0, 5.0, 30.0, 10.0],
            6.0,
            "missing",
            ofdrw::ColoredShapedTextOptions {
                color: [255, 0, 0],
                language: None,
            },
        )
        .is_err());
    assert_eq!(document.to_bytes().unwrap(), before);
    let id = document
        .add_colored_shaped_text_object(
            0,
            "AfiB",
            [5.0, 5.0, 30.0, 10.0],
            6.0,
            &font_id.to_string(),
            ofdrw::ColoredShapedTextOptions {
                color: [255, 0, 0],
                language: None,
            },
        )
        .unwrap();
    let page = document.pages().unwrap()[0].path.clone();
    let xml = String::from_utf8(document.entry(&page).unwrap().unwrap().to_vec()).unwrap();
    assert_eq!(
        document.page_text_objects(0).unwrap()[0].id.as_deref(),
        Some(id.as_str())
    );
    assert!(xml.contains("<ofd:FillColor Value=\"255 0 0\" Alpha=\"255\"/>"));
    assert!(xml.contains("GlyphCount=\"1\""));
    assert_eq!(document.page_text(0).unwrap(), ["AfiB"]);
}
